var SOUP_LIBRARY = [{"id":"lib_00132cc37be4","srcNo":133,"title":"","dispTitle":"无题 · KONpiGG #133","surface":"一个人过生日，邀请他所有的好朋友来参加。吹完蜡烛的时候，这个人把他所有的好朋友都杀了。","truth":"男主和朋友曾经一起去探险，一段时间后没有了食物，因为男主本身是一个盲人，所以这帮朋友都骗他说每人砍下一只手来吃，可最后只砍了男主一个人的手。之后有一次男主邀请朋友们来参加自己的生日聚会，吹完蜡烛后所有人都鼓掌了，男主发现只有自己的手被砍下来吃了，男主无法忍受这样的欺骗于是杀了所有的好朋友。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0015920e33d8","srcNo":852,"title":"气球","dispTitle":"气球","surface":"天好黑啊，还好爸爸带了蜡烛，哥哥带了食物，妈妈最伟大，用气球救了我。","truth":"我们一家四口去露营。结果山体塌方了，我们都被困在了山洞里，家人不幸当场去世，我为了熬到救援队来救我，只好取爸爸的脂肪做成尸蜡，用哥哥的身体充饥，并按照书上所说的巨人观，堵住了妈妈的每一个出气口。现在刚好是夏天，尸体腐败的很快，妈妈像“气球”一样膨胀，在我听到地面上有动静之后，捅破妈妈的尸体，得到了救援。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_007dafa7c9bf","srcNo":931,"title":"第七条怪谈","dispTitle":"第七条怪谈","surface":"规则一：空白规则二：空白规则三：空白规则四：空白规则五：空白规则六：空白规则七：空白","truth":"规则一：此物十分难缠，擅长制造幻觉或夺舍，夺舍后与常人无异。出现条件：提问到灵异元素。规则二：妻子的状态癫狂，恐怕已被夺舍。出现条件：提问到妻子。规则三：它和妻子都死了，我绝不会让妻子就这么死去。出现条件：提问到我以外的其他人，或其他死人。规则四：你是一名很有素质的大师，你可自由来往两界。但在冥界的你十分脆弱。出现条件：提问与我身份或能力有关。规则五：诡异可以进入冥界，但无法离开。这里只存在鬼。哭狼嚎，笑声会招来它们。遇到危险逃离即可。出现条件：提问关于冥界。规则六：它的目标是我！我不能如它愿！出现条件：①规则1—5全部出现。②推理出妻子的结局。规则七：原来这七条并不是规则，而是我的记忆碎片，狡猾的诡异让妻子中了幻觉，误以为自己是被夺舍的诡异，我也上当了。它的目标一直都是我这具能通阴阳的身体！我不能如它愿！我只能把自己永远留在这里了！出现条件：①规则1—6全部出现。②选择死亡。主持人手册 1. 生命值分级：健康—擦伤—轻伤—重伤—骨折—濒死—亡 ps：玩家生命值基于主持人根据玩家情况自行分配 2. 生命值扣除规则：①在游戏正式开始提问后玩家笑了 —1（在冥界笑声会招来百鬼夜行）②玩家做了不文明行为 —1（你是一名有素质的大师，请保持人设）ps：不文明行为包含：脏话、吸烟、和别人动手等，主持人自行判定 3. 若玩家没有推理出规则1—6就死亡，则判定推理失败。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0224e82c7650","srcNo":250,"title":"017 · 水草","dispTitle":"017 · 水草","surface":"有个男子跟女友去河边散步，女友突然掉进河里，男子跳入水中去找，但没有找到，伤心离开。几年后他故地重游，见到一位老人在钓鱼，钓上来的鱼身上没有水草。他问老人为什么，老人说：\"你不知道吗，这条河从来没有长过水草。\" 男子听后跳入水中自杀了，为什么？","truth":"当年女友落水时，男子曾在水中抓到一把\"水草\"随手松开了，其实那是女友的头发。女友几乎等于死在男子手里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0269e650b41f","srcNo":705,"title":"一双鞋","dispTitle":"一双鞋","surface":"男人醒来只看到一双鞋就自杀了，为什么？","truth":"男人以前有梦游症，他上大学的时候和室友住一起，半夜将室友刀了，将室友的尸体埋在操场，醒来只剩下一双鞋子。他结婚以后，妻子有一天晚上因为孩子哭泣来不及穿拖鞋，抱着孩子去外面哄，男人看到妻子和孩子都不见，只剩下一双拖鞋，以为自己把妻子孩子刀了，于是自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_028f0dfe1fbe","srcNo":208,"title":"忠诚的狗","dispTitle":"忠诚的狗","surface":"小强养了一只很忠诚的狗，今天他牵着狗上街，然后小强死了。为什么？","truth":"小强这次上街突发心脏病，狗不让其他人靠近主人包括医生。耽误了治疗时间，导致了小强的死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_03135614c003","srcNo":1072,"title":"特殊的试卷","dispTitle":"特殊的试卷","surface":"全班学生都在进行一场极其重要的考试。突然，一个学生站起来撕碎了试卷并大笑，其他学生也跟着撕碎了试卷。","truth":"这是一场关于“服从性”的人性实验，或者是老师规定：只要有一个人放弃考试，全班都能及格。那个学生是第一个鼓起勇气打破规则的人，其他人跟随他是因为集体压力的释放。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_03c704631a6d","srcNo":884,"title":"寻人启事","dispTitle":"寻人启事","surface":"衣甜，女，31岁，离异，工作：医生，失踪时间：一个月。线索：1. 一份衣甜的保险单，受益人是衣甜的父亲；2. 前夫最近娶了衣甜的同事；3. 衣甜父亲有救助流浪猫的习惯；4. 今天有一个人从钟楼跳下去摔死了，死亡时间是凌晨3-4点之间。","truth":"衣甜没离婚时就知道前夫出轨同事，萌生了杀二人的想法。她和同事谋划换脑手术，答应术后用前夫的身体和同事结婚，同事欣然同意。同时衣甜买了保险，告知父亲计划。之后她绑架前夫，成功进行换脑手术，将拥有衣甜身体的前夫挂在钟楼时针上。时针走动时，前夫从时针上滑落摔死，伪造了衣甜的死亡。最后衣甜以前夫的身份，将前夫的情人（自己的同事）骗回家杀害分尸，交由父亲喂给流浪猫毁尸灭迹。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_03d26eb2cfd1","srcNo":140,"title":"","dispTitle":"无题 · KONpiGG #140","surface":"一名女子来到县衙报案，刚到门口，她便浑身瘫软在地","truth":"我的夫君失踪已经有一段时日了，我来到县衙门口想要报案，可是刚来到门口，我就发现鸣冤鼓上有一个我十分熟悉的胎记，我顿时明白夫君已经被杀害。过了一段时间，县令被上头抓走了，我才知道，原来夫君作为鼓匠和县令贩卖人口，县令作为渠道提供，把囚犯当做做鼓的材料。夫君则把他们做成人皮鼓留在了县衙，后来，县令和丈夫分赃不均，丈夫扬言要去告发县令，县令害怕，便杀了他灭口，把他也做成了人皮鼓。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_03fde71a3571","srcNo":90,"title":"","dispTitle":"无题 · KONpiGG #90","surface":"一个雨天，男人拉着一个大行李箱出门。他在门口碰见了自己的妻子，和妻子兴奋地说了几句话后，他神色忽然古怪至极。他仔细看了看妻子的侧脸，看了看手表，又转头看了看门外的大雨。而后他慌慌张张拉着行李箱走了，从此销声匿迹。","truth":"女人有个长相一模一样的双胞胎姐姐。女人老公偷偷出轨双胞胎姐姐。双胞胎姐姐与女人老公偷情时，为了把自己和女人区别开来，会在侧脸画一颗显眼的痣。最近，女人的老公已经完全厌倦女人，一直在找机会杀了女人。一个雨天，女人照常出门工作。趁此机会，老公又邀请了姐姐来家里偷情。老公发现坐在沙发上的这个女人脸上没有痣，他十分慌乱，以为妻子突然回家。担心偷情败露，他打算今天就杀死妻子。于是他悄悄走过去杀死女人，解肢，把尸体装进行李箱，出门抛尸。出门后，他在门外遇见一个女人，起初他以为是姐姐——自己的情人，于是兴奋地说了几句话。说话后，他发现不对。仔细一看，这个女的脸上也没有痣。他看手表，发现是妻子往常下班回家的时间。今天一直在下大雨。他突然明白，刚才家里的那个女人就是姐姐。不过因为是雨天，她脸上的痣被雨水洗掉了。他杀错了人。震惊后怕之余，他逃走了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_044e0af074d4","srcNo":862,"title":"牧场","dispTitle":"牧场","surface":"妈妈去世了，留给我一个废弃已久的牧场。第二天牧场里不知道从哪来了一只鸡，第三天又多了一头牛，第四天又多了一只羊，我很诧异。接下来一个月，牧场多了很多动物，我终于明白怎么回事了。于是我做了一个疯狂的决定，结果第二天牧场里多出了一个年轻的女人，看到她后我疯了……","truth":"妈妈去世后，我继承了她的牧场。第二天牧场出现一只鸡，之后陆续多出很多动物，我发现规律：只要第一天晚上吃下某种动物的肉，第二天牧场就会出现这种动物——原来妈妈留给我的是有魔力的牧场。我想复活妈妈，于是将妈妈的骨灰吃了下去。结果第二天牧场里出现了一个和我长得一模一样的女人，我崩溃了：原来我是妈妈的复制人，她当年为了以另一种方式生存，制造了我。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_048dc4d7aeb0","srcNo":1222,"title":"Jed 1.83","dispTitle":"Jed 1.83","surface":"A woman lies dead in the street near a car.","truth":"She was on a motorcycle, and her long hair got caught on the car's antenna. It ripped out part of her scalp and she bled to death. Andreas says this is also based on an actual accident.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_04936ace80ec","srcNo":1255,"title":"半杯热水","dispTitle":"半杯热水","surface":"护士查房时看见病人床头那杯本该凉透的水还是热的，立刻通知家属“他终于醒了”。为什么？","truth":"病人长期昏迷，只有他自己醒来后才会觉得水凉、按铃要求换一杯新的。那杯水还是热的，说明他刚刚醒来过。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_056db100d29a","srcNo":561,"title":"看不见的生日","dispTitle":"看不见的生日","surface":"一个盲人在和朋友们一起过生日，朋友们一起给他唱生日歌，唱完生日歌之后盲人把他的朋友们都杀了","truth":"男主和朋友曾经一起去探险，一段时间后没有了食物，因为男主本身是一个盲人，所以这帮朋友都骗他说每人砍下一只手来吃，可最后只砍了男主一个人的手。之后有一次男主邀请朋友们来参加自己的生日聚会，吹完蜡烛后所有人都鼓掌了，男主发现只有自己的手被砍下来吃了，男主无法忍受这样的欺骗于是杀了所有的好朋友。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","本格"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_05c070e9070b","srcNo":1071,"title":"盲人摸象","dispTitle":"盲人摸象","surface":"一群盲人在森林里摸到了一个“巨大的温热物体”，他们以为是象，纷纷开心地靠在上面休息。直到其中一个盲人摸到了“拉链”。","truth":"那不是象，而是一个穿着巨大动物皮套的连环杀人魔。杀人魔故意保持静止来观察这些盲人的反应。摸到拉链的瞬间，意味着对方并非生物，盲人们瞬间陷入了极度的杀机中。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_05cbea68fd8f","srcNo":715,"title":"预言","dispTitle":"预言","surface":"我有个能预言的万能婆婆。有一天她消失了，我独自去参加舞会，回来后却再也撑不下去了。为什么？","truth":"从小性格内向的我，无论遇到什么事情都很懦弱没有主见，渐渐地这种性格已经严重影响到我的生活，于是我的大脑内分裂出一个能预言的万能婆婆，在她的指引下，我可以很自信且从容的应对各种","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑","温情"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_05d55826327b","srcNo":1201,"title":"Jed 1.19","dispTitle":"Jed 1.19","surface":"There is blood on the ceiling of my bedroom.","truth":"A mosquito bit me, and I swatted it when it later landed on my ceiling (so the blood is my own as well as the mosquito's).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_05eec246c795","srcNo":1268,"title":"雨夜车祸","dispTitle":"雨夜车祸","surface":"一个雨夜，发生了一起车祸。司机声称他是因为躲避突然冲到路上的鹿才撞车的。但警察到达现场后，立即逮捕了司机。为什么？","truth":"事故发生在沙漠地区，那里根本没有鹿。司机在撒谎，可能涉及酒驾或其他违法行为。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:ns5601/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_060f17084b69","srcNo":163,"title":"","dispTitle":"无题 · KONpiGG #163","surface":"主人和狗一起死在了沙滩上，试推测发生了什么事？","truth":"主人是渔夫，通过炸鱼维持生计，主人把炸弹扔出去，狗以为主人在和他玩游戏，就把炸弹叼了回来，主人没想到狗子这么傻，没看到炸弹，就引爆了，于是两只一起被炸死在沙滩上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_061a1d68f450","srcNo":1028,"title":"死亡直播","dispTitle":"死亡直播","surface":"女主播在直播间表演，观众纷纷打赏，说‘表演得太真实了’。直到直播自动结束，大家才发现她是真的死了。","truth":"女主播在直播过程中突发心脏病或意外，她痛苦的挣扎、求救的眼神、甚至倒地时的抽搐，都被沉迷于网络猎奇的观众误认为是‘演技’或‘特效’。打赏越多，她越绝望，因为没人报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0695135164a2","srcNo":946,"title":"乐谱","dispTitle":"乐谱","surface":"你捡到了一份乐谱，你很好奇的打开了它，内容如下。\n\n![img_rId14.png](./海龟汤图片/img_rId14.png)","truth":"这天，我捡到了一份奇怪的乐谱，好奇心驱使，我便开始破解这音符的秘密：原来这乐谱上的音符代表的是九宫格上的数字。Do=1，Re=2，Mi=3，Fa=4，Sol=5，La=6，Si=7，Do=8，Re=9。破解后是这样的一段对话：好怀念和你一起听歌，期待很久了，我们选择你喜欢的歌手，这次我有个主意，真希望你能与我分享谁，捡到这封信就杀谁，好期待。原来这竟然是两个BT留下的话，他们通过这种方式寻找受害者，并以听取受害者的尖叫为乐趣。我现在总感觉身后有人在盯着我，可是我不敢回头。Do=1，Re=2，Mi=3，Fa=4，Sol=5，La=6，Si=7，Do=8，Re=9。破解后是这样的一段对话：好怀念和你一起听歌，期待很久了，我们选择你喜欢的歌手，这次我有个主意，真希望你能与我分享谁，捡到这封信就杀谁，好期待。原来这竟然是两个变态留下的话，他们通过这种方式寻找受害者，并以听取受害者的尖叫为乐趣。我现在总感觉身后有人在盯着我，可是我不敢回头。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0696ae22b31a","srcNo":335,"title":"白昼流星","dispTitle":"白昼流星","surface":"白昼流星将要划过，我躲在阴影里掐算着它的死期。\n    手机里一条APP提示突然亮起，我惊恐地拨通电话，近乎疯狂，微弱的信号那头，久违的她语气冷漠，孩子却在欢笑。\n    我流着泪在电话里疯狂地嘶吼，她却冷冷地丢下一句“你真是个疯子”，随后挂断。\n    流星准时划过，死期已到，流星的碎片，将我的世界彻底摧毁。","truth":"PP提示突然亮起，我惊恐地拨通电话，近乎疯狂，微弱的信号那头，久违的她语气冷漠，孩子却在欢笑。\n> 我流着泪在电话里疯狂地嘶吼，她却冷冷地丢下一句“你真是个疯子”，随后挂断。\n> 流星准时划过，死期已到，流星的碎片，将我的世界彻底摧毁。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悲剧","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0779cb5752e1","srcNo":1042,"title":"不准的钟","dispTitle":"不准的钟","surface":"家里的钟每天都快5分钟。主人却从不修理，反而觉得这样救了他的命。","truth":"因为钟快了，他每天都会早5分钟出门。某天他因此避开了一场原本会准时遇到的车祸或灾难。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_07daf49f9167","srcNo":873,"title":"漂流瓶","dispTitle":"漂流瓶","surface":"我舅舅来快三年了，而又涌向这群人，只烦杨娟被关起来，犁刀刀片锋利我们被","truth":"我捡到一个漂流瓶，里面的信顺序被打乱，解开后是求救信：“我们被李峰骗到岛里，关起来被圈养繁殖，这群人享用幼儿，三年了快来救救我！” 友情提醒：李峰是本地人，常伪装成导游，一定要找到他，求救者说的不是杨娟。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_086c4a778b97","srcNo":883,"title":"许愿","dispTitle":"许愿","surface":"我低下头许愿，愿望实现了，我却哭了。","truth":"爸爸是一名字航员，执行任务去了，我特别想念他。这天晚上看到一颗”流星“，立刻许愿希望爸爸早点回来。可我没想到，那”流星“其实是失事坠入大气层的飞船。爸爸确实比预计时间早回来了，却也因此牺牲，愿望实现了，我却悲痛大哭。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_087b4e1374f3","srcNo":938,"title":"替罪","dispTitle":"替罪","surface":"牛郎织女多离分，羊儿回首欲报恩。四散飘零寻归处，可识当年窃羊人？","truth":"1. 故事第一句包含两个人 2. ”羊儿“指的是孩子 3. 羊儿报牛郎织女的恩 4. 羊儿被拐走了 5. 羊儿死了 6. ”四散飘零“指的是羊儿被分尸了 7. ”寻归处“是指”羊儿“的身体被买走 8. 故事中有人替罪 9. 牛郎织女多离分的原因和职业有关 10. 牛郎织女是将尸之人 11. ”替罪“指的是羊儿的亲生父母 12. ”窃羊人“是指羊儿的亲生父母，却被羊儿误解为当年的”窃羊人“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_08a08b9bdd9c","srcNo":1289,"title":"","dispTitle":"无题 · boop-yyt #1289","surface":"A man is killed on a train. He is found to have written \"elf\" on the floor in his own blood. What happened?","truth":"There is a safe full of jewelry on the train. The victim, Schmidt, is the conductor who guards the cargo; He robbed the safe and made an accomplice travel on the train under a false name in order to remove the loot. Accomplice kill Schmidt to keep his share. Schmidt did not know the pseudonym of his accomplice, so he wrote down the murderer's berth number, 11. For clarity, he spelled the number into one word in his native German language.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_090fb2fb97fe","srcNo":40,"title":"出租房","dispTitle":"出租房","surface":"我搬进了一个新房子，房间里经常有类似于老鼠爬的声音，但毕竟便宜，我也睡的很香，没多久房东就谈了一个女朋友，老鼠的声音好像也没了，但突然的安静却让我不能安心入睡。","truth":"我早就知道房东在房顶偷窥我，但被人注视总会给我带来一种安全感，所以对于来自房顶的偷窥，我并没有感觉到任何不适，直到房东谈了女朋友，安静的天花板却让我辗转难眠，于是我趁房东帮我修电路的机会，让他永远的呆在了天花板上。透过那小小的黑洞，我知道他一直在看着我，我又能安心入眠了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0977abffd5a2","srcNo":61,"title":"安全","dispTitle":"安全","surface":"外面很危险，我要藏好了，猜猜我在哪，嘘...我要睡着了…","truth":"我是一个怯懦的小男孩，曾经差点被人贩子拐走，幸好我机智的躲了起来，没被他发现才逃过一劫，但我还是留下了心理阴影。我的爸爸妈妈知道这件事后很溺爱我，但每当我很不听话时，爸爸妈妈就会说要把我送去人贩子手中来吓唬我，我生怕爸妈把我送去人贩子手中，因此每次他们这样吓唬我时我都会乖乖听话。在这样的环境下，我的被害妄想症越来越严重，整天不出门。我要躲起来，这样才能不被送到人贩子手中。可我找不到安全的地方，直到有一天我惹妈妈生气后，听到妈妈对爸爸说早知道他这么不乖就不应该生他，让他留在肚子里多好。我突然意识到妈妈肚子里就是最安全的地方，于是我刨开了妈妈的肚子，藏好母亲的身体，躺在了这个最安全的地方。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_09c0825b5def","srcNo":1324,"title":"","dispTitle":"无题 · boop-yyt #1324","surface":"A woman opens an envelope and dyes. What happened?","truth":"Should be done orally; the envelope is an envelope of dye, and she's dying some cloth, but it sounds like \"opens an envelope and dies\" if said out loud.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0a6d1163d6f9","srcNo":1290,"title":"","dispTitle":"无题 · boop-yyt #1290","surface":"A man lies dead next to a feather. What happened?","truth":"The man was a sword swallower in a carnival side-show. While he was practicing, someone tickled his throat with the feather, causing him to gag.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0a8d65c99059","srcNo":921,"title":"爷爷的低吼","dispTitle":"爷爷的低吼","surface":"2005年 H市，自打胡七二记事起爷爷就躺在病床上，他睁着眼睛，一动不动，也不需要进食或排泄。世界上任何医生都无法解释这一现象。2006年父亲和胡七二说爷爷曾是摸金校尉，有一次他被抬回来，就变成了这样。爷爷留下了摸金秘术，胡七二时常翻看。父亲发现后严肃地和胡七二说：”不要走你爷爷老路“。2015年爷爷闭上眼睛了，也没有心跳，大家都以为他死了，可他嘴里却开始发出恶魔般的低吼，连绵不绝，永不停歇，格外的吓人。2016年胡七二成为了一名摸金校尉。摸金秘术中有着爷爷临摹的地图，胡七二按照路线到了一个存在于海底的墓穴，墓门被锁上了，碑上刻着小篆：”受始皇帝之命，寻求永生不死之法。“2025年爷爷睁开了眼睛，也不再发出恶魔般的低吼了。胡七二在整理爷爷房间时发现了一把被黄纸包着的钥匙，黄纸上写着：永生不死 2026年胡七二又一次去了墓中。与此同时，H市出现了很多灵异事件。胡七二家的地上密密麻麻地写满了：救命！而墓中没有尸体，地上有一面恰好镜面朝上的镜子。","truth":"关于爷爷：自打我记事起，爷爷就躺在病床上，父亲和我说，爷爷曾经是一名摸金校尉，他的一生都在寻找关于永生的秘密。爷爷的现象很奇怪，他在床上一动不动，甚至不需要进食或排泄。经过我们二十年的观察，我发现爷爷并不是一动不动，他好像在很”缓慢“地活着。十年前，他缓慢地闭上了眼睛，十年后又缓慢地睁开了眼睛。他好像在眨眼！而这一过程，用了二十年！专家们对爷爷的情况很好奇，由于爷爷有十年时间一直在低吼，他们把爷爷的低吼录制了下来，并将音轨进行了加速处理。十倍，百倍，千倍，万倍，亿倍！直到加速了几亿倍，他们终于翻译出了这句低吼：”救命！“爷爷身上的时间流速被减缓了几亿倍！在正常人眼里，他的确永生了，或许他能活到宇宙泯灭。关于胡七二：我从小翻看爷爷留下的《摸金秘术》，对摸金产生了极大的兴趣。在我十八岁那年，我按照爷爷在书中留下的一张地图，开启了属于我的冒险。第一次我无功而返，几年后却无意中发现了爷爷留下来的钥匙，我再一次出发了。棺中无尸，躺着一面透露着妖异的邪镜，正反两面都是镜面。我被吸引，鬼使神差地用镜子照了自己一下。无事发生，但邪镜从我手中脱落，我发现我再也无法触碰到它了。返回的途中，我发现有些不对，等我的司机一动不动地定在了车内，甚至天空中的鸟也展翅停在空中。我回到H市，整个世界的生物甚至事物都一动不动。世界好像被静止了。我在时间停止的世界里想尽办法求救，都无功而返。而且我意识到，他们并不是停止，而是在”缓慢“地活着。或者说，世界没变，而我才是不正常的。我身上的时间流速被加速了几亿倍！H市出现了许多灵异事件，其实都是我在几秒内造成的（改变了物体轨迹）。因为我很孤寂，独自生活了八十年。关于那镜：（除功能外不需要复盘）据《史记·秦始皇本纪》记载，秦始皇二十八年派徐福出海，寻找仙山上的神仙，求取长生不老药。（以下为杜撰）徐福寻到传说中的昆仑仙山，此地为西王母居所。徐福在此得到一双面宝镜，其上镌刻太乙玄纹，拥有操控时空的神力，名目：昆仑镜。其正面可将”映射之物“时间减缓亿倍。其反面可将”映射之物“时间加快亿倍。徐福不小心被映入镜中，随后消失了。地上多了一张徐福留下的字条，随从按照字条上徐福的要求小心地封存了宝镜。并为徐福在某处修建了陵墓，宝镜一同封入墓中。千年后，陵墓早已被上涨的海平面吞没，或许再也无人能发现这面昆仑镜。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0aae87087f4d","srcNo":26,"title":"半瓶香水","dispTitle":"半瓶香水","surface":"我的妈妈最近有些反常，不但偷偷用我的香水穿我的衣服，还老是半夜出去。那天我实在忍不住向她理论，并发生了争执，结果不小心把她推倒在地，我赶忙上前扶她，却发现自己的双手沾满了鲜血。","truth":"我的妈妈前几天去世了，妈妈的去世对我产生了极大打击，以至于我产生了幻觉和梦游症，到了夜晚，梦游状态的我穿上妈妈生前给我买的漂亮衣服，喷上妈妈生前送我的香水，到她的墓地前和她聊天。那天我在照镜子时，把镜子里的自己幻想成了妈妈，我便与她理论，却不小心把镜子推倒了，镜子碎了一地，我赶忙用手去捡，手被玻璃割破，鲜血流了出来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["医院"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0b330f52e242","srcNo":1303,"title":"","dispTitle":"无题 · misc #1303","surface":"A man tries to buy poison to kill his wife. The pharmacist figures out what he's up to and finds a way to ensure that he can't kill his wife. How to do this?","truth":"The pharmacist gives the man a cup of coffee to drink while he's waiting. After the man has drunk the coffee, the pharmacist says, \"There was poison in that coffee. I'll give you the antidote if you write a signed statement that you were planning to kill your wife. I'll keep the confession; if anything happens to your wife, I'll give it to the police.\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"misc/repo-scan","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0bb632eaca32","srcNo":840,"title":"怀孕","dispTitle":"怀孕","surface":"爱人怀孕好几个月啦，我听着孩子的胎动，兴奋不已。虽然爱人日渐消瘦，但他应该能理解我了……","truth":"我怀了宝宝，他却背叛了我，害得我悲痛中失去了孩子。我恨他，要让他知道我的不易，于是偷偷喂他喝下很多蛔虫虫卵，还把他绑在床上，每天提供“孩子”所需的养分。看着他因蛔虫繁殖而逐渐隆起的肚子，这下他应该能理解我了吧……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0c44293fd6f1","srcNo":1213,"title":"Jed 1.51","dispTitle":"Jed 1.51","surface":"If he'd turned on the light, he'd have lived.","truth":"A man was shot during a robbery in his store one night. He staggered into the back room, where the telephone was, and called home, dialing by feel since he hadn't turned on the light. Once the call went through he gasped, \"I'm at the store. I've been shot. Help!\" or words to that effect. He set the phone down to await help, but none came; he'd treated the telephone pushbuttons like cash register numbers, when the arrangements of the numbers are upside down reflections of each other. The stranger he'd dialed had no way to know where \"the store\" was.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0c4522f76be1","srcNo":20,"title":"空邮件","dispTitle":"空邮件","surface":"她连续收到三封没有内容的邮件。第四天，她没有打开邮箱就报了警。","truth":"邮件标题每次都是一个字，连起来是她和朋友约定的求救暗号。第四天该来的字没有来，说明朋友可能已经无法继续发送，她马上报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0cf00682e3ce","srcNo":135,"title":"","dispTitle":"无题 · KONpiGG #135","surface":"一场意外后，妻子便开始把自己关在房间里，不肯出来。那天我突然听到她在嚎啕大哭，我急忙冲进房间里，却被眼前的一幕吓傻了。","truth":"我很爱我的妻子，有一天我发现妻子怀孕后，就开始精心准备迎接孩子的到来。结果我发现妻子竟然出轨了。为了孩子，我暂时隐忍，但是孩子出生后我发现孩子还不是我的。愤怒之下我精心策划了一场车祸，想让她们通通丧命。谁知妻子竟然活了下来。不过她疯了，她整日把自己关在二楼的婴儿房内，我也不管她，自己只是晚上回来睡个觉，不过经常在房子里闻到一些异味。这一天，我听到了婴儿房里传出嚎啕大哭，我急忙冲进房间。一阵恶臭袭来，我发现妻子怀里抱着的洋娃娃爬满蛆虫，她竟然把死去的孩子缝进了洋娃娃里！她一边抓去娃娃上的蛆虫，一边哭喊着：宝宝别怕，宝宝别怕。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0d603c7d7b6c","srcNo":282,"title":"053 · 冰箱","dispTitle":"053 · 冰箱","surface":"我的父母都不理我，但我还是很爱他们。","truth":"小时候父母告诉我：喜欢的东西一定要放进冰箱，这样可以保鲜。他们工作太辛苦，经常加班到深夜。于是我在他们的水里下了安眠药，等他们睡着后，把他们放进了冰箱里保鲜。从那以后，我每天都会对他们说：\"爸爸妈妈，我爱你们。\" 现在我都六十了，他们还是那么年轻。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0d76187607a2","srcNo":1048,"title":"反转的重力","dispTitle":"反转的重力","surface":"男子在街上散步，突然他紧紧抱住路边的电线杆，看向天空，露出了极度恐惧的神情。随后，他真的‘掉’向了天空。","truth":"由于某种超自然现象或地磁反转，该地区的重力突然消失并反转。天空变成了‘地底’。他死命抓着电线杆是因为那是他最后能留在地球上的依靠，最终他力竭松手，跌入了无尽的大气层深处。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0da576b33d0d","srcNo":861,"title":"歌声","dispTitle":"歌声","surface":"男人和女人在喝酒，突然听到熟悉的歌声。不久后，二人都死了。","truth":"项羽和虞姬正在帐篷里喝酒，突然听到围住他的军队都唱起他家乡楚地的民歌，此时他立刻明白自己的家乡已经被沦陷了，不久虞姬便用剑自杀，项羽逃到江边后也用剑自杀，这便是《四面楚歌》的故事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0daf1eafe0c9","srcNo":313,"title":"085 · 守灯人","dispTitle":"085 · 守灯人","surface":"守灯人半夜起来喝水，随手把灯关了，又回去睡觉了。第二天，他自杀了。","truth":"他是灯塔守护人，他关掉的是灯塔的主灯。那天夜里，至少有三艘船因为失去灯塔指引而发生了碰撞，有数十人在黑暗的海上遇难。无法承受这份自责，他结束了自己的生命。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0dd4d36c0b32","srcNo":897,"title":"他不喜欢","dispTitle":"他不喜欢","surface":"我和妹妹相依为命，但由于妹妹的死亡，我染上了一个习惯。可今天我被抓住了，他叫我赔给他。他的做法我很震惊，但好像还不错，我很喜欢！十年后，我用以前的办法寻找他，可一无所获。于是我去买了针线。可他好像不喜欢，他发出一声惊叫，并报了警。","truth":"我和妹妹是孤儿，相依为命。某天我们去一户人家偷东西吃，妹妹被这家的狗杀死，我用匕首杀了狗。失去妹妹后，我对狗产生极大恨意，经常潜入别人家院子杀狗，这个习惯让我被一个男人抓住了。令我震惊的是，他没有惩罚我，反而让我替代他死去的宠物狗，将我囚禁起来。从小缺少关爱的我，在他的喂养和陪伴下感受到了家的温暖，渐渐喜欢上这种生活。十年后，男人去世，我失去了”家“，试图通过杀狗寻找新的”主人“，却无人接受。我认为是自己外表不像狗，于是杀了一户人家的狗，扒下狗皮，用针线缝在自己身上，在院子里等待主人回来。主人回家后，看到血肉模糊、缝着狗皮的”人类“，吓得惊叫出声，立刻报了警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0e134ac04a78","srcNo":1322,"title":"","dispTitle":"无题 · boop-yyt #1322","surface":"Two people are playing cards. One looks around and realizes he's going to die. What happened?","truth":"The one who looks around sees his own reflection in the window (it's dark outside), but not his companion's. Thus, he realizes the other is a vampire, and that he's going to be killed by him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0e181ff97371","srcNo":909,"title":"巨人","dispTitle":"巨人","surface":"出差前，我发现妻子画了一个陌生男人，她说：”这是个巨人，我梦见我被他握在手中杀死了。“只是梦境所以我并没有在意，可等我出差回来，我却发现妻子死在了家中，警察调查后叹了口气：”唉，第十六个。“","truth":"这是一家隐藏在城市角落的美甲店，它并不起眼，但生意却不错。你只需要领着你要”解决“的女人来到这里做美甲，并付给作为降头师的老板一些钱财，他便会帮你下降头，处理掉你的麻烦。我带妻子去过后，她和我说她梦见了”巨人“。她根本不是梦见了巨人，而是”小人“形象的自己被握在了降头师的手中，我明白事情成了，便假装出差了。出差回来后，果然看到了妻子的尸体，警察什么都调查不出来：”真是邪门了，今年已经十六起这样的案件了。“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0ed4dd3f3ce3","srcNo":109,"title":"","dispTitle":"无题 · KONpiGG #109","surface":"我走进电梯准备去上学，随着电梯的上升，我知道，我再也无法去学校了。","truth":"星期一早上，我迷迷糊糊走进电梯准备去学校，电梯门合上后，由于我刚起床头脑还不太清醒，忘了按一楼的楼层键，于是电梯便持续上升，我意识到自己没按楼层，正准备按下一楼楼层时，电梯突然停了，电梯门缓缓打开，我看到一个女孩倒在血泊中，而一个男人正在清理现场...男人听到动静，突然转过头来看向我，那双眼睛死死的盯着我，我吓了一跳，赶紧狂按电梯关门键，就在电梯即将关上的那一刹那，一双带着血的手伸了进来，我知道我再也无法去学校了。（电梯之所以上升是因为女孩被杀害前为了求救按了电梯按钮）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0f05c1b4b831","srcNo":1295,"title":"","dispTitle":"无题 · boop-yyt #1295","surface":"A man dies in his own home. What happened?","truth":"His home is a houseboat and he has run out of water while on an extended cruise.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0f1e1dbacbac","srcNo":916,"title":"小不点来了","dispTitle":"小不点来了","surface":"”妈妈，小不点来了！“ 中午，客厅突然传来声音，可我是独居女性。声音的来源令我毛骨悚然，于是我立马搬家。搬家后的第一晚，我失眠了。午夜客厅再次传来声音。 ”妈妈，小不点来了！“我想到我流产的孩子。我立马打字联系之前的房东：”我想搬回去。“","truth":"老公出轨了，导致我伤心过度流产了，而且哭哑了嗓子。出院后我怕一个人太孤独，于是养了一只鹦鹉。有了它的陪伴，我之后这一个月都睡的很香甜。可某天中午鹦鹉突然说话了”妈妈小不点来了。“可我已经哑了，鹦鹉在哪学的说话，我意识到家里肯定是进来其他人了。鹦鹉口中的小不点让我联想到了我的侏儒房东。原来这一个月房东趁我不备，每天都会在我的牛奶中下助眠药。之后等我睡沉了，他便爬上了我的床把我当成妈妈抱着我睡觉。我很害怕，于是立马搬家了。或许是因为助眠药的戒断反应，也或许旁边没有了”孩子“，搬家后的第一晚我失眠了。此时客厅又传来鹦鹉的声音”妈妈，小不点来了。“我想到了我流产的孩子以及医生说我无法生育。或许与其收养一个孩子，一个长不大的侏儒不更适合做我的孩子。于是我便拿起手机给房东发去了信息：”我想搬回去。“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_0fa0dac82fb7","srcNo":1225,"title":"Jed 1.90","dispTitle":"Jed 1.90","surface":"A man urinates and dies.","truth":"He urinated on the third rail in the New York subway, was knocked onto the tracks by the shock, and was hit by a train and killed. (Experts apparently disagree on whether he died from the electrical shock before the train hit him.) This is a true story; the man was named Joseph Patrick O'Malley, and Cecil Adams gives the story in _The Straight Dope_, quoting _Where Death Delights_ by Marshall Houta. 1.90 variant answer: The man was in a boat on the Amazon. A tiny fish swam \"upstream\" into the man whereupon it inflated itself to balloon size, killing him. (TK) (I don't know whether fish that can swim up a urethra actually exist or are an urban legend, but all my sources indicate they do exist. The self-inflation may not be true, though. Also, the man might have to be standing in the water (rather than in the boat) for the fish to enter his body.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_0fdefd44364d","srcNo":940,"title":"谎言之界","dispTitle":"谎言之界","surface":"你们三人在深邃地穴的冒险中发现千年古堡，长廊笔直又扭曲，身体轻盈，陌生记忆涌入。遗骸手中的纸条写着：有光明的地方一定存在黑暗；鱼和熊掌不可得兼；盒子里的猫是生是死？我在盒子里，所以还不知晓；光明倘若消失，世界即为黑暗；我想……我应该失败了。","truth":"古堡是”表世界“（正常世界）与”里世界“（形态完全相反的世界）的连接处，长廊为混沌之地，会受里世界干扰。主持人需按”正-反-正-反“顺序回答问题。第一结局（里世界投降）：三人逃出生天，里世界与表世界相互排斥，进入里世界意味着表世界身份死亡。第二结局（表世界投降）：三人发现遗骸主人为拯救被里世界侵蚀的表世界而牺牲，决定接力拯救，最终化为长廊新的遗骸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_10769cc52a8a","srcNo":1378,"title":"","dispTitle":"无题 · boop-yyt #1378","surface":"There are 53 bees instead of 53 bicycles. How could this be?","truth":"The same (Bee is another brand of playing cards).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_108e5b96beb2","srcNo":1,"title":"无声电话","dispTitle":"无声电话","surface":"她每天都接到同一个号码的电话，电话里没有声音。三天后，她主动报了警。","truth":"来电号码属于她三天前失踪的丈夫。警方通过通话记录定位到丈夫手机，最终发现丈夫遇害，凶手一直用手机确认她是否在家。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_111c70d38dff","srcNo":1026,"title":"完美的不在场证明","dispTitle":"完美的不在场证明","surface":"杀人犯在闹市区杀了人，案发时间他在看电影，几百名观众和监控都能证明他在现场。但他最后还是被抓了。","truth":"杀人犯是电影院的放映员。他利用放映室的隐蔽性，在电影播放期间（利用自动播放或定时）离开，通过预先架设的暗道去杀人。观众看到的只是银幕上的电影，没人注意放映室里有没有人，但他忽略了放映机的尘埃积累或某个只有他在场才能完成的物理操作。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1165bea3d4c9","srcNo":12,"title":"反锁的门","dispTitle":"反锁的门","surface":"房门从里面反锁，窗户也关着。警察看了一眼门口的鞋，就判断屋里还有一个人。","truth":"门口只有一双外出的鞋，但屋内的人不可能赤脚出门后又把门从里面反锁。说明另一个人穿走了鞋或仍藏在屋里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_11fd153e6e81","srcNo":178,"title":"","dispTitle":"无题 · KONpiGG #178","surface":"男人照常做了一笔赚钱生意，但是以往很支持他的家人，这次却非常愤怒。","truth":"男人年轻的时候是人贩子，靠此发家致富，家里人也很开心，然而年纪大了之后男人患上了老年痴呆，忘记自己是带孙子出来玩，转手就卖了。因此家人非常愤怒。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1245207e575c","srcNo":936,"title":"村中诡事","dispTitle":"村中诡事","surface":"小红经历过一场车祸，因此觉醒了超能力。可小红却不知道能力是什么，父母也不和她说，只叫她做个正常人就好。直到和丈夫离婚那天，小红才明白她的能力！她很想成为正常人！！直到她在村子里做了某件事，才如愿以偿。","truth":"我叫小红，由于一场车祸，意外觉醒了超能力，可我并不知道这能力究竟是什么，父母也不告诉我，只说让我表现得像正常人就好，我也就按他们的嘱咐生活了很多年。长大后，我很少回家。直到婚后，我发现我老公居然出轨了，我一怒之下杀了他。可在他死后我居然还能看到他！我因此意识到原来自己的超能力是阴阳眼。我的超能力也一直在使用，父母早就死于那场车祸中，所以我才会看到他们。我不想只有自己能看到鬼魂，我想大家和我一样，于是我在村子的水井中投了毒，这样大家都死了，也就都能和我一样看到鬼魂了……\n关键词隐喻一场车祸：小红因为一场车祸失去了她的父母。觉醒超能力：小红因为车祸失去生育能力。丈夫出轨：小红发现丈夫出轨，同时得知丈夫是杀害她父母的元凶，小红因此杀了丈夫。正常人：可以正常生育。村子：小雅的家。某件事：小红让小雅失去了孩子，如愿以偿地让小雅和她一样成为了“正常人”。\n<span style=\"color: blue;\">**故事二**</span>\n汤面村子里闹鬼了，它擅长制造幻觉，小雅发现只有触发某个禁忌才会被它杀死，为了保护家人，她想办法避免了幻觉，可她最后还是死了。\n汤底我叫小雅，我住的村子闹鬼了。一旦人们因为恐惧而发出尖叫，就会被鬼魂杀死。而且这个鬼擅长制造幻觉，很多人都因为看到它的幻觉中了它的圈套。此时的我已经有了身孕，为了保住我还未出生的孩子，我弄瞎了自己的双眼，这样就不会看到幻觉而害怕尖叫了。可没想到当我弄瞎自己后，我发现我自己根本没有怀孕，原来我早就中了鬼的幻觉。鬼让我以为自己有了身孕，得知真相后我发出了尖叫，我还是被它杀死了。\n关键词隐喻村子：小雅的家。鬼魂：小红。保护家人、避免幻觉：小雅为了保护自己未出生的孩子，在小红面前弄瞎了自己。禁忌：在故事二中是不能尖叫，但实际指的是不能声张。最后：小红让小雅失去了孩子。\n<span style=\"color: blue;\">**故事三**</span>\n汤面村子里的老婆婆给孩子们讲了两个鬼故事，见天色已晚于是决定回家。孩子们缠着婆婆：“不是说好讲三个的吗？”婆婆望着孩子笑了：“已经讲完三个了。”\n真正汤底老婆婆真正的名字是小雅，第三个鬼故事就藏在前两个之中……多年以前，小红的丈夫为了继承财产，制造了一场车祸，害死了小红的父母。小红家境不错，父母死后她继承了财产，也很依赖丈夫。因为车祸，小红失去了生育能力，她担心丈夫因此离开她，总是暗中调查丈夫的行踪。结果她发现丈夫居然真的在外有了家室。顺藤摸瓜，小红发现了父母惨死的真相。崩溃的小红带着人来到情人的家中，杀了这个负心汉，情人名叫小雅。她声称自己并不知情且有身孕，恳请小红放过她和她的孩子，甚至因此自行弄瞎双眼。小红也因此放过了这个目击者，可无法生育的她嫉妒怀孕的小雅，于是给她下了毒，弄掉了孩子。小雅为了给孩子报仇，找机会杀了小红，并移植了小红的眼睛，从此隐姓埋名，藏匿在一个小村落，再也没有人见过小雅。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1294ed2c0162","srcNo":283,"title":"054 · 日记 **汤面（日记形式）：** - 2019年2月，女儿不去上学了，我劝不动她。 - 2019年6月，女儿每天盯着电视和电脑看，我怕她眼睛弄坏了","dispTitle":"054 · 日记 **汤面（日记形式）：** - 2019年2月，女儿不去上学了，我劝不动她。 - 2019年6月，女儿每天盯着电视和电脑看，我怕她眼睛弄坏了","surface":"你是孤儿，收养人从不允许你走出家门一步，你每天在屋子里大叫、砸东西，但没有人在意，也没有人来救你。有一天他说要带你出门，到了那个地方之后脸上被罩上了什么东西，你晕了过去……","truth":"你是一只小公猫，主人送你去做绝育手术。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_12bf53e51604","srcNo":261,"title":"030 · 汤面里的苍蝇","dispTitle":"030 · 汤面里的苍蝇","surface":"一名男子进了餐厅，点了一碗汤面，吃了一口后过了不久又吃了第二口，接着男子非常地生气。请问过程中发生了什么事？","truth":"男子吃了一口觉得味道太淡，加了大量盐后搅拌，发现汤里有只死苍蝇，于是要求更换新碗。服务生端来新汤后，男子马上吃了一口，发现这碗汤非常咸——厨师只是把苍蝇捞出来而已，根本没换汤，所以男子非常愤怒。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_12cbead30014","srcNo":252,"title":"019 · 半根火柴","dispTitle":"019 · 半根火柴","surface":"有一个人在沙漠中头朝下死去，不远处散落着几个行李箱，这个人手里紧紧抓着半根火柴。请问这个人是怎么死的？","truth":"这个人和朋友乘热气球飞行，热气球发生故障，丢光行李后仍然超重，于是大家抓阄，抽到半根火柴的人被扔了下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_12eb6f8b848a","srcNo":291,"title":"063 · 捕鼠","dispTitle":"063 · 捕鼠","surface":"一个生活贫困的孤独老人，被发现死在家中，好像是在吃晚饭时死的。他的尸体残缺不全，尸体周围场景十分诡异。","truth":"老人养了很多流浪猫，邻居觉得又臭又扰民，于是在鱼里下毒后告诉老人鱼要变质了，送给猫吃吧。老人觉得鱼还是新鲜的，自己做了吃，中毒身亡。猫被关在屋里，饿极了便啃食了主人的遗体——残缺不全正是如此。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_13d675ba20b0","srcNo":889,"title":"咒","dispTitle":"咒","surface":"房东向我表白，我看着面前丑陋油腻的胖大叔，果断地拒绝了。为了不被骚扰，姐妹给我介绍了一个新房子，房东是个阿婆，我放心了不少。搬家后第一晚，我隐约听到隔壁传来房东阿婆在哼着什么奇怪的声音。我还发现有一个人趴在我的窗台偷窥我！见我发现，他跑走了。通过背影我只看到是一个偏瘦的人。搬家的第七晚，我听到房间里传来了”沙，沙，沙“的声音，我起床寻找却什么都没有，可躺下没一会儿就又会听到。睡梦中，我感觉有人在舔舐我。第二天醒来，眼前的一幕令我头皮发麻。","truth":"我拒绝了丑陋油腻的房东的表白，姐妹给我介绍了阿婆的房子，阿婆住在隔壁，我安心不少。搬家后第一天，我发现窗台有偏瘦的人偷窥，其实是阿婆的儿子（之前的胖房东）；晚上听到的奇怪声音，是阿婆作为神婆在念咒——她信奉邪教，得知一种诅咒：将一个人的身体部分放在另一个人身边，就能让对方永远爱着自己。阿婆和儿子合谋，买通我的闺蜜，让我搬到这里，还让儿子抽脂，将脂肪放进我的被褥里。可封建迷信毫无作用，腐烂的脂肪滋生了大量虫子。第七晚的”沙沙沙“声是虫子爬行的声音，睡梦中的”舔舐感“是虫子在叮咬我。第二天醒来，我发现床上和身上爬满虫子，拆开被褥，里面是恶臭腐烂的脂肪——这一周我居然躺在胖大叔的脂肪上睡觉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_13f7db377f7b","srcNo":321,"title":"093 · 侏儒竞争 **汤面（经典版）：** 马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮一些。马戏团只留一个，越矮越好。两人约定比高矮，高的自杀。约定的前一天","dispTitle":"093 · 侏儒竞争 **汤面（经典版）：** 马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮一些。马戏团只留一个，越矮越好。两人约定比高矮，高的自杀。约定的前一天","surface":"山顶小屋里的人半夜听到敲门声，打开门却什么都没有，关门继续睡。第二天，山脚发现一具尸体。","truth":"小屋的门开向悬崖。山脚下的人费尽全力爬上来，正要敲门求救时，门忽然打开，来不及说话就被推了下去——也可能只是站不稳，自己跌落了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_144eefd2d255","srcNo":1243,"title":"午夜的滴水声","dispTitle":"午夜的滴水声","surface":"独居的人每晚睡前都把水龙头拧到最紧，因为讨厌滴水声。某天夜里他明明拧紧了，却听见规律的滴水声，越听越害怕，最后冲出了家门。为什么？","truth":"滴水声不是他家的水龙头发出的，而是楼上渗水：邻居家的暖气管爆裂，水透过楼板从天花板滴落。他意识到「关紧龙头仍有滴水」意味着异常来自楼上，又联想到白天曾听见楼上激烈争吵，于是怀疑发生了凶案或有人潜入，恐惧之下逃出家门。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_146ba5100f1f","srcNo":66,"title":"","dispTitle":"无题 · KONpiGG #66","surface":"小明在图书馆看书，在一本书里翻到了100块钱，但是他却哭了，问为什么小明哭了","truth":"小明是一个不火的作家，他在图书馆自己写的书里放了张100元，如果有人看到就会拿走表示有人看了他的书，而至今这100还是夹在书里，表示至今都没有人看过小明的书，于是小明哭了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_14ac594e1290","srcNo":13,"title":"空座位","dispTitle":"空座位","surface":"电影院里只剩一个空座位。电影开始后，他看着那个座位，立刻离开了影厅。","truth":"那个座位本该属于他已经去世的朋友，票是朋友生前买好的。开场后空座旁出现了朋友常用的物品，他意识到有人冒用朋友身份进出，于是离开报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_153b82ead579","srcNo":1308,"title":"","dispTitle":"无题 · boop-yyt #1308","surface":"A bell rings. A man dies. A bell rings. What happened?","truth":"A blind swimmer sets an alarm clock to tell him when and what direction to go to shore. The first bell is a buoy, which he mistakenly swims to, getting tired and drowning. Then the alarm clock goes off.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_15b05aa5803f","srcNo":1296,"title":"","dispTitle":"无题 · boop-yyt #1296","surface":"A man dies of thirst in his own home. What happened?","truth":"His home is a houseboat and he has run out of water while on an extended cruise.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_15da47fb8bff","srcNo":63,"title":"","dispTitle":"无题 · KONpiGG #63","surface":"据报道，一个幸福的三口之家，小孩10岁，爸爸死在了家里，身穿孕妇装，肚子被剖开了，经过检查他爸爸是上吊自杀的，邻居发现了这件事之后没有第一时间报警。推理出爸爸为什么要自杀并还原案件。","truth":"孩子不是爸爸亲生的，却格外乖巧孝顺，爸爸觉得对不起孩子就自杀了，然后孩子给他穿孕妇装，抛开肚子钻进去企图成为亲生。邻居发现了这事就先救了孩子，所以没有第一时间报警","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1604d55dc208","srcNo":1102,"title":"加班的同事","dispTitle":"加班的同事","surface":"每天加班的同事突然辞职了，第二天公司发了奖金。","truth":"同事一直在帮老板做假账，辞职是因为良心发现。公司奖金是因为老板担心同事举报，用奖金安抚其他人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1612b4b8aaed","srcNo":1002,"title":"偷窥者","dispTitle":"偷窥者","surface":"一个男人每天都通过墙上的小孔偷窥隔壁的美女。隔壁总是亮着红光。有一天，他发现小孔变成了红色，他吓得瘫倒在地。","truth":"那个小孔对面并不是房间，而是一只眼睛。隔壁的美女早就发现了他在偷窥，那几天红色是因为她在回看他，那天变成红色是因为她把布满血丝的眼睛贴在了孔上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_161809c5dbab","srcNo":471,"title":"日记","dispTitle":"日记","surface":"2020.10.15 晴\n今天舅舅给我做了一顿我从来没吃过的饭，听他们说这是肉，那种香味至今俺都还记得，多么美好的一天啊，可是听到最喜欢我的老师被发现家中被人杀害了，这让我和舅舅难过了好久。","truth":"从记事起女主就被舅舅养着，女主经常遭到舅舅的殴打，挨打挨饿已是家常便饭。一天","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悲剧","本格","犯罪"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_179cfc38b29c","srcNo":46,"title":"小红裙","dispTitle":"小红裙","surface":"姐姐为我选了一件小红裙，我穿着去上学了，然后有人死了。","truth":"我的母亲和老师有染，他们总趁着父亲不在时温存。而为老师提供信息的就是我的小红裙，每当我穿着小红裙去上学就说明那晚父亲准不在。这天妈妈忙，姐姐为我选了一件小红裙，老师看见以为父亲不在家，便来我家找母亲，正好被父亲撞上，然后父亲杀了他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_17e2192e6554","srcNo":638,"title":"Charlotte在自己房间打电话","dispTitle":"Charlotte在自己房间打电话","surface":"Charlotte在自己房间打电话，她听到隔壁房间很多人在说话，特别吵，她根本听不清楚电话里讲什么，她很生气，走到了客厅，悄悄做了一件事，很快，隔壁安静了。\n\n 你猜猜这是怎么一回事呢？","truth":"Charlotte其实是在自己的卧室打电话，隔壁有很多人在说话，其实是他弟弟在看电视剧，电视剧里的人说话的声音很大。\n\n Charlotte来到客厅，找到电闸，把电闸拉了下来。瞬间电视没电，非常安静了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_17fc568f14b0","srcNo":259,"title":"027 · 海龟汤","dispTitle":"027 · 海龟汤","surface":"一名男子走进餐厅，点了一碗海龟汤，喝了一口非常惊讶地问服务员：\"这是真的海龟汤吗？\" 得到肯定回答后，不久他就自杀了，为什么？","truth":"数年前男子与恋人遭遇海难，在海上漂流，几乎饿死。最危急时，恋人做了一碗\"海龟汤\"给他喝，让他活了下来，那美好的滋味让他永远无法忘怀。今天喝到真正的海龟汤时，他才意识到：当年那碗汤的味道完全不同……原来是恋人为了让他活命，割下自己的肉煮汤给他喝，之后恋人衰弱而死。男子得知真相后无法接受，选择了自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_18121251d66f","srcNo":180,"title":"","dispTitle":"无题 · KONpiGG #180","surface":"\"救救妈妈....\"是妈妈的哭声。\"救救我，妈妈...\"是女儿的哭声。\"妈妈这次我就不救你了。\"从此再没有哭声了","truth":"爸爸是做皮肉生意的，而妈妈是店里的第一个小姐，\"救救妈妈\"妈妈向女儿哭诉，她很痛苦，都是为了生计，都是爸爸逼迫她的，为了救妈妈，女儿出去骗了很多年轻女孩到店里。妈妈很开心。生意越做越大，直到一天，一个\"贵客\"点名只要女儿，女儿害怕的向妈妈求救，妈妈怒骂了爸爸一顿，将女儿带回房间并倒了杯水......等女儿再醒来的时候，身边躺着那位贵客。愤恨之下，女儿杀了贵客。\"妈妈，这次我就不救你了。\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_181239094689","srcNo":942,"title":"石头，剪刀，布","dispTitle":"石头，剪刀，布","surface":"找啊找啊找朋友，找啊找啊找朋友。123木头人，123木头人。手心手背，手心手背。石头，剪刀，布。","truth":"这是一个有心理疾病的变态，他把他的变态行为当成一场游戏。找啊找啊找朋友，找啊找啊找朋友。他在挑选受害者，最终选中了一个女孩。123木头人，123木头人。晚上，他悄悄跟在女孩后面，女孩感觉好像有人在跟踪自己，所以走几步就回头看一眼。他看到女孩回头看他，就会藏在黑暗中，一动不动，说出这句123木头人。手心手背，手心手背。他跟着女孩进到家里后藏到女孩的床底下，女孩睡觉时手会自然地垂在床边，因此他只能看到女孩的手心手背。石头，剪刀，布。石头=真正的石头剪刀=真正的剪刀布=真正的布。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_18af72eb5ce0","srcNo":51,"title":"阳台上的女孩","dispTitle":"阳台上的女孩","surface":"女孩每天都站在对面阳台和我打招呼，我却不敢再踏进阳台了。","truth":"我新搬进了一个公寓，每天早上去阳台晾衣服的时候，我都能看见对面公寓的阳台上站着一个女孩在对我打招呼，我很开心，每天都准时的到阳台跟她打完招呼再去上班。两三个星期过去了，一天，我突然看到一条关于我小区附近的新闻：在某间公寓阳台上发现一具女尸，已经吊挂了三周了。我突然觉得有什么不太对劲，跑去阳台一看，果然女孩已经不见了，只看见几张封条，我顿时感到一阵恶心，不敢再踏进阳台。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖","犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_18b321274e5e","srcNo":1021,"title":"重逢","dispTitle":"重逢","surface":"男子在火车站看到一个阔别多年的老友。他兴奋地冲过去打招呼，老友却惊恐地逃跑，最后老友在铁轨上被撞死。男子看清老友留下的包裹后，跳轨自杀了。","truth":"男子和老友多年前都是逃犯。老友以为男子是来杀人灭口或警察。包裹里是一张多年前的合照和一封信，信里写着老友这些年一直想把赃款还给受害家属并自首。男子发现自己害死了唯一想改过自新的兄弟，且老友至死都以为他是仇人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_197a084bf84f","srcNo":75,"title":"","dispTitle":"无题 · KONpiGG #75","surface":"一个男人在打猎，他瞄准并开枪。几秒后，他突然意识到自己犯了个天大的错误。几分钟后，他就死了。请问发生了什么？","truth":"他打猎的地点是雪山，\"啪\"的一声，开枪之后没过几秒，就雪崩了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1985a9ca2ae7","srcNo":166,"title":"","dispTitle":"无题 · KONpiGG #166","surface":"我喜欢他很久了，但我一直不好意思向他袒露心声，于是我约了他和另外几个小伙伴一起做了一个测试，但没想到最终害死了我和我的朋友们。","truth":"我喜欢这个男孩子很久了，但我一直不好意思向他袒露心声，我想要知道他是否在关注着我，就约他以及我的几个朋友们一起做了一个测试，我们把自己关在一间传闻闹鬼的屋子里，但是他怕黑，不敢进入鬼屋，于是我们把钥匙交给了他，交代他一天之后来给我们开门。但是几天过去了，他并没有来开门，我的几个朋友们一个接一个地倒下。我知道他们都是因我而死，是我的任性将他们囚禁在了这栋鬼屋之中，我是谋杀他们的真凶，想到这点，我不敢出去，我知道如果出去了，我就会因涉嫌谋杀被控告。因为我身上……其实还有一把钥匙。然而直到最后他也没来，因为他在外面出了意外死了。但我依旧相信着他会打开大门，把我们都救出去。只要他来了，就不会有人发现我有另外一把钥匙的事实。是的......只要他来了......","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_19aa8e7c225d","srcNo":688,"title":"雨中女郎","dispTitle":"雨中女郎","surface":"艺术家买了《雨中的女郎》。朋友来欣赏后失踪。次日艺术家在画室闻到淡淡味道，发现《雨中的女郎》旁多了一幅画，惊恐烧掉《雨中的女郎》。","truth":"《雨中女郎》中的女郎是真实存在的，她走出了画，朋友来欣赏时被女郎关进了画里——旁边新挂的那幅画里是朋友惊恐的表情。艺术家闻到的淡淡气味是女郎身上的雨水味。他明白了真相，立刻烧掉了那幅画。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖","悬疑","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_19e9eb7c289b","srcNo":305,"title":"077 · 永远的标准答案","dispTitle":"077 · 永远的标准答案","surface":"小红考试只要答\"不知道\"，就能得到满分，但老师却给她打了零分。","truth":"小红的老师出了一道题：\"你最喜欢的人是谁？\" 标准答案是老师自己的名字，但小红写了\"不知道\"——因为她不知道老师叫什么名字，所以写了真实答案。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_19f1a46c7f28","srcNo":1056,"title":"缸中之脑","dispTitle":"缸中之脑","surface":"一个男人发现自己不论怎么努力，都无法打破一个杯子。他最后大笑起来，自杀了。","truth":"男人意识到自己生活在模拟世界中。杯子无法打破是因为系统的‘碰撞体积’或‘耐用度’参数出现了BUG。他自杀是为了测试死后是否能‘强制断开连接’回到真实世界。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1a6283ab2f37","srcNo":269,"title":"039 · 海难侥幸","dispTitle":"039 · 海难侥幸","surface":"杰克拼命阻止想要把女儿带走的家伙，最终却没能成功，侥幸活下来后，妻子却向杰克提出了离婚。","truth":"发生了海难，救生船前来救人，女儿已经上了救生艇但没有位置了。杰克为了自己活命，想把女儿拉下船让自己上，但被告知妇女儿童优先，他没能上船。侥幸活下来后，妻子得知此事，与他离婚。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1aa2e7bacd58","srcNo":572,"title":"山顶小屋","dispTitle":"山顶小屋","surface":"一个人住在山顶的小屋里，半夜听见有敲门的，他打开门却没有人，于是去睡了。等了一会又有敲门声，去开门，还是没人，如是者几次。第二天，有人在山脚下发现死尸一具，警察来把山顶的那人带走了。为什么?","truth":"因为他的门开在悬崖边，门是向外开的，那个人好不容易爬上来，他一开门，那个人就被推下去了。如此几次而亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_1b0c34dcd3ed","srcNo":1035,"title":"电影院的惨剧","dispTitle":"电影院的惨剧","surface":"电影院里正在放映恐怖片，全场寂静，突然一个男人大叫一声死去了。并没有人袭击他。","truth":"男人患有严重的心脏病，被电影里的恐怖镜头吓到心脏骤停猝死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1b3259545328","srcNo":228,"title":"要好的朋友","dispTitle":"要好的朋友","surface":"我有一个要好的朋友，我们形影不离。可惜，他死了。","truth":"我一直孤单，长期的孤独引发了我的妄想症。在妄想中，我有一个很好的朋友。我的症状被家人发现，我被迫接受治疗。我的妄想症治好了，他也就死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1b5f8818a812","srcNo":457,"title":"一週還是兩年？","dispTitle":"一週還是兩年？","surface":"法醫推了推眼鏡，指著解剖台上的遺體，語氣篤定地說：「從器官腐敗程度與皮下組織狀態來看，死亡時間絕對是一週前。屍體沒有注射防腐劑，也沒有任何化學藥劑的痕跡，科學是不會騙人的。」\n​刑警卻眉頭緊鎖，將一份檔案丟在桌上：「這不可能。死者兩年前就失蹤了，DNA 比對也確認屍體沒有被掉包。」\n​法醫瞬間愣在原地。兩年前就被殺害的人，為什麼只呈現出死後一週的腐敗程度？","truth":"比對也確認屍體沒有被掉包。」\n> ​法醫瞬間愣在原地。兩年前就被殺害的人，為什麼只呈現出死後一週的腐敗程度？","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_1bf936bf0361","srcNo":141,"title":"","dispTitle":"无题 · KONpiGG #141","surface":"我被杀害在山的另一头，而山的那边，是弯弯曲曲、而鲜血淋漓的国道。他以为自己逃掉了，但我留下的印记会追随着他，直至落网为止。","truth":"我是一位住在偏远山区的中学生，每天都要提早去上学，但这一天我却在经过国道时被一位熬夜送货精神状态不佳的货车司机开的货车撞了，我当场晕厥了过去。司机下车一看，以为我死了，他就把我搬到了货柜里，开车准备到湖边抛尸。但他没想到，途径弯弯曲曲的山路时，我的身体因车身过弯时的惯性撞到了货柜门边上，流出的血经由门下缝流出，滴滴答答流了一路。跟在他车后面的其他车辆看到了，就报了警。到达湖边后，司机将货柜门打开，我在这时醒了过来，无意识地发出了声音，司机发现我没有死，他担心我记下了他的车牌号，就用车上的扳手将我打死，之后，他把我的尸体被抛入湖中，我没有死在他的车轮下，我是被他亲手杀害的。但我不会就这样让他逃之夭夭，因为他的车上还残留着我的鲜血，经过的路上也滴落着我的血迹，就像一条条扯不断的枷锁，紧跟在他身后，他很快就会得到法律的制裁。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1d0ec1ebc88a","srcNo":16,"title":"雨夜的脚印","dispTitle":"雨夜的脚印","surface":"雨夜过后，门口没有任何脚印。他却因此确定昨晚有人来过。","truth":"整条路都是泥地，正常来访一定留下脚印。门口完全没有脚印，说明有人刻意清理过痕迹，这比留下脚印更可疑。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":1,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1d77e1dd54b7","srcNo":58,"title":"丢失的手机","dispTitle":"丢失的手机","surface":"我的手机不见了，当我找到它时，我吓了一跳。","truth":"我和闺蜜去酒吧蹦迪，我喝了点酒蹦了一会儿，坐下来休息时才发现自己手机不见了，于是就让闺蜜给我手机打个电话，电话那头传来一位陌生男子的声音，酒吧太吵了，我们还没来得及问清楚，电话就被那头挂断了。我怀着郁闷的心情回到了家，结果发现我的手机就在床头，我忽然想起今天我根本就没把手机带出门，而我一直以来都是一个人居住，我不禁毛骨悚然…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1d788001ed92","srcNo":149,"title":"","dispTitle":"无题 · KONpiGG #149","surface":"男朋友结婚了，新娘不是我。男朋友死了，新娘变成了我。","truth":"我和男友是自由恋爱，但男方家里不同意，迫于压力男友娶了别的女孩，婚后男友过得很抑郁，得了抑郁症，时不时就自残。我不忍心他这么痛苦，我设局帮他假死，并如愿嫁给了他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1e06910567ab","srcNo":48,"title":"数数","dispTitle":"数数","surface":"我数数，他也在数数，我毛骨悚然。","truth":"我家住在高层，今天我闲着无聊向窗户外面看的时候，意外目击了一场案件，就发生在对面大楼里，一个男人像是刺死了一个人。我连忙掏出手机想要报警，警察问我发生事故的楼层，于是我数着男人所在的楼层。等数到男人那层时，我发现男人注意到了我，数着我所在的楼层，握着血淋淋的刀，露出诡异的笑容!","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1ec62776467d","srcNo":997,"title":"生日礼物","dispTitle":"生日礼物","surface":"盲人男孩生日，收到了哥哥寄来的一个盒子。他拆开后，大哭着自杀了。","truth":"哥哥承诺生日会送他一双“眼球”让他复明。盒子里是一对手术后的眼球，由于男孩是盲人，他摸到了盒子里冰冷圆滑的物体。但他意识到，哥哥既然能送眼球，说明哥哥自己变成了盲人（或已死亡献祭），他无法接受这份代价。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1f34e7036b8b","srcNo":1312,"title":"","dispTitle":"无题 · boop-yyt #1312","surface":"A man and his brother are in a bar drinking. They begin to argue and the brother won't get out of the man's face, shouting and cursing. The man, finally fed up, pulls out a pistol and blows his brother's brains out. He sits down to die. What happened?","truth":"They are Siamese twins. In the original story, the argument started when one complained about the other's bad hygiene and bad breath. The shooter bled to death by the time the police arrived.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_1f572e970b04","srcNo":597,"title":"姐姐在跳舞","dispTitle":"姐姐在跳舞","surface":"六岁那年外公葬礼，我和姐姐玩捉迷藏，我对妈妈说了一句话把她吓昏过去，我说了什么？","truth":"我去参加外公的葬礼，同行的还有比我大两岁的姐姐，我和她玩捉迷藏，我没有找到她。\n没想到她躲在了纸做的房子里，当纸房子被点燃，姐姐被烧死了。我对妈说，姐姐在那房子里面跳舞。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_1f963af3d0fe","srcNo":154,"title":"","dispTitle":"无题 · KONpiGG #154","surface":"我很忙，但我还是和他出去了。我和他比赛，他先我一步。之后，我就不忙了。","truth":"我和他是从小玩到大的朋友，这天他来邀请我出去玩，但是我的暑假作业还没有写完，即使是这样，我也按捺不住贪玩的天性和他一起出去了。我和他骑着自行车，在小路上悠然地骑行，这时他提出和我进行一场比赛，看谁先能骑到那边的小卖铺，我同意了，而他一马当先地骑在前面，之后却因回头看我不慎被卡车撞死。葬礼过后，他的父亲知道我和他是好朋友，允许我带一两样东西回去，作为纪念。而我，却选择了带回了他早已写完的所有暑假作业，擦掉了我死去的好友的名字，填上了我自己的。我为自己的机灵感到高兴，这样我就不用忙着写自己的暑假作业了。当然，年纪尚小的我，并不知道这个单纯的做法与恶的距离有多么接近。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1fce916eb76b","srcNo":1095,"title":"牛吃草","dispTitle":"牛吃草","surface":"一个男的住在山顶，有一天他下山去集市买东西，回家后发现家里的牛死在了草坪上。","truth":"他买的是牛肉，牛闻到了同类的血腥味，惊恐地挣扎把自己绊倒摔死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_1fe018f884c7","srcNo":1297,"title":"","dispTitle":"无题 · boop-yyt #1297","surface":"A man is lying drowned in a dead forest. What happened?","truth":"He's scuba diving when a firefighting plane lands nearby and fills its tanks with water, sucking him in with the water. He runs out of air while the plane is in flight; the plane then dumps its load of water, with him in it, onto a burning forest.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_1fe394f0087d","srcNo":639,"title":"Diva走进了一间黑屋子","dispTitle":"Diva走进了一间黑屋子","surface":"Diva走进了一间黑屋子，她待了十几分钟后，忽然尖叫着跑了出来，地上遗落了她随身带的一张纸。\n\n 你猜猜这是怎么一回事呢？","truth":"Diva在电影院看一部恐怖电影，当看到非常恐怖的镜头时，她忽然害怕了尖叫着逃离了电影厅。\n\n 遗落的那张纸是她的电影票根。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_206b9185868d","srcNo":324,"title":"098 · 跳火车（经典版）","dispTitle":"098 · 跳火车（经典版）","surface":"男子坐火车去邻镇治眼病，治好了回程时经过隧道，跳车自杀。","truth":"他之前完全失明，治好病后重获光明。回程时火车进入隧道，突然一片黑暗，他以为自己又失明了，无法承受，选择了死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_20b8c20f05f5","srcNo":134,"title":"","dispTitle":"无题 · KONpiGG #134","surface":"我发现床头柜上放着一杯蜂蜜水和一块巧克力蛋糕，原本放在床头柜的娃娃却消失不见了。我知道男友再也回不来了。","truth":"我的男朋友有暴力倾向，经常对我拳打脚踢，我想离开，却又无能为力。那天沉默寡言的邻居送了我一个娃娃。我知道她对娃娃动了手脚，但我也确认他爱上了我。因此我天天对着娃娃哭诉男友的暴行，连一杯蜂蜜水，一块巧克力蛋糕都是奢求。那天男友动手之后摔门而去。我不知道抱着哇哇哭诉了多久，睡了过去。恍惚中一个陌生的身影伴随着滴嗒声来到我的身边。但我睡得更安心了。(滴嗒声是血滴在地上的声音，邻居砍下了男友的手用来解开我家的指纹锁，他给我带来了一杯蜂蜜水和一块巧克力蛋糕。)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_20cfdfe4f7ba","srcNo":244,"title":"010 · 幸福家庭","dispTitle":"010 · 幸福家庭","surface":"飞机上，一对看似平和的幸福家庭正抱着婴儿旅行。他们所犯下的恶劣罪行，被一个观察力敏锐的空中小姐发觉了。","truth":"那对夫妻怀中的婴儿是死的，他们利用孩子的身体藏毒。空中小姐因为婴儿一直不哭而产生怀疑，最终揭开真相。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_21a2b61d54f4","srcNo":1070,"title":"贪婪的奖赏","dispTitle":"贪婪的奖赏","surface":"一个探险家发现了一个装满黄金的密室，门上写着：‘带走多少，就留下多少。’探险家装了满满一袋金子，最后他确实留下了等重的东西。","truth":"那个密室是一个天平机关。如果你带走50斤黄金，门就会锁死，直到你在祭坛上留下50斤的“活体组织”或血液。探险家为了带走金子，不得不割下自己的肉来配平重量，最终因为失血过多死在门口。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_21b65cf5f303","srcNo":1395,"title":"","dispTitle":"无题 · boop-yyt #1395","surface":"Pat went into a luggage shop to buy a suitcase. The assistant said, \"It is most unusual to buy a suitcase. Why don't you rent one like all our other customers?7' Why should this be so?","truth":"Pat was a Westerner in Tokyo. Houses there are small and, in order to save space, people tend to rent any large item which they might use only occasionally. Most Japanese rent the suitcases they take on holiday.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_21bc23944630","srcNo":935,"title":"私汤馆の凶杀疑云","dispTitle":"私汤馆の凶杀疑云","surface":"口供：1. 大和抚子：与有希子是同学兼好友，老公中奖带二人来私汤馆，馆内只有一名女老板。20:00老公睡觉，与有希子闲逛；20:15到温泉室吃刺身、喝清酒；21:00各自回房；21:10吵醒老公带他去泡温泉；21:30老公叫老板做刺身；21:40路过有希子房间，听到她电话里吵架并提及投诉。2. 佐藤二郎：中了家庭汤泉券，带妻子抚子和有希子度假。18:00抵达后休息；21:10被妻子吵醒去泡温泉；21:30吃了一整份刺身；21:40泡好后去吸烟室，听到老板吵架；21:50回房。3. 女老板：私汤馆偏僻无监控，17:40为三人办理入住；20:20为温泉室两名女房客做餐；21:30为女房客及其丈夫做餐；21:40与死者因房间卫生吵架，死者称要投诉；22:00清理温泉室时发现死者。线索：1. 吐真剂：一名嫌疑人被使用，仅回答是或不是且必为真话。2. 麻绳：在佐藤房间发现，用处不明。3. 壁炉：有被烧毁的胶皮。4. 小厨房：有制冰机，酒柜里有刚清洗完的杯子。5. 死者：死在温泉中，颈背插着餐刀（与伤口不完全吻合），刀柄有女老板指纹。6. 院子里：有一瓶治疗精神疾病的药物。7. 温泉：有水循环系统。8. 有希子房间：马桶里有还原后写着“选我还是选抚子，你自己决定”的纸条。9. 有希子手机：20:00搜索“山中由美”。","truth":"女老板真实身份是山中由美，小时候因肥胖被大和抚子与高桥有希子霸凌退学，减肥后开了偏僻的VIP私汤馆，设计复仇：1. 20:00，由美听到二人谈论自己，坚定复仇决心。2. 20:20，由美在清酒中下迷药，用制冰机做的冰刀杀死有希子，将冰刀扔进温泉，把带血的餐刀放进抚子手中，伪造纸条并洗刷杯子、弄坏制冰机。3. 21:10，抚子醒来发现误杀有希子（其有杀人倾向的第二人格会在睡觉时出现，此次因昏迷未触发），与丈夫佐藤商量嫁祸由美。4. 21:30，佐藤抱着有希子尸体躲在温泉角落，叫由美做刺身，趁机让餐刀沾上她的指纹，之后带手套将刀插进死者伤口。5. 21:40，抚子模仿有希子声音用客房电话与由美吵架，佐藤在吸烟室偷看佐证。6. 22:00，由美假装发现尸体报案，意图让抚子被逮捕。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_21fffcb5edb7","srcNo":120,"title":"","dispTitle":"无题 · KONpiGG #120","surface":"一具尸体，显而易见有两处致命伤，她头部受到重创，胸腔被暴力剖开，不过奇怪的是她没有穿鞋。身边洒落着苹果、果篮，尖顶宽边帽和扫把。不远处，有一具女尸，头颈被连骨带肉的撕碎，血肉模糊难以分辨，身边有一双银色高跟鞋。女尸附近有一具大型动物尸体，被利器所伤，地上散落着一些稻草。","truth":"第一具尸体是一个西方女巫。狮子获得了'胆'量，于是就想吃了多萝茜，而有良'心'的铁皮人和有'脑子'的稻草人，在见到这一幕后，把狮子杀掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2258c4f5d053","srcNo":50,"title":"夺爱","dispTitle":"夺爱","surface":"妈妈很喜欢\"妹妹\"，可这一切本来是我的。","truth":"我们是一对双胞胎，可妈妈从小就更喜欢我(妹妹)，妈妈为了分辨我们，给了我一条项链让我天天戴着，那天晚上姐姐跟我说\"我好喜欢你的项链，给我戴一会儿就一会儿!就戴一天，我明天早上就给你\"，我没多想，便同意姐姐了。第二天妈妈带我们去游泳，一不小心，我们两个溺水了，妈妈想救妹妹，看到了那条项链误以为姐姐是妹妹，就救了姐姐。可是我们还没有换回来!(姐姐知道第二天妈妈要带她们去游泳，故意和妹妹一起溺水的，因为她知道妈妈更喜欢妹妹肯定会先救妹妹)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2299ca62945f","srcNo":1141,"title":"声音","dispTitle":"声音","surface":"“滋滋喻喻喻呼呼呼龙隆隆味呈叶咱啊啊啊嘲嘲咕噜咕噜滋滋”","truth":"这是记录一场空难的黑匣子内容。“滋滋?声贯穿全程;“喻喻喻\"是飞机起飞声;“呼呼呼”\n\n是飞行时的气流声;“比隆隆?是雷声;“味味味?是雨水拍打飞机声;“味?是闪电击中飞机声;\n“啊啊啊”是遇难者呼喊声;“嘲呈?是飞机爆炸声; “咕噜咕噜”是黑匣子落入水中的声音。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_234328857d6d","srcNo":1362,"title":"","dispTitle":"无题 · boop-yyt #1362","surface":"A woman is murdered in front of hundreds of people, but they all think it's an accident. How could this be?","truth":"The woman is a trapeze artist who times her act (from starting time to time to jump for another trapeze) by the music. The organist changes tempo or stops the music too soon, and the trapeze artist falls to her death.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2368ab633bd4","srcNo":546,"title":"鱼雷与狗","dispTitle":"鱼雷与狗","surface":"小明穿着雨鞋，和他的狗一起血肉模糊死在空旷地。","truth":"：小明是一个喜欢炸鱼的渔民，他将鱼雷扔向水的方向向空旷地方跑去，没想到他的狗以为主人想扔个东西叫自己捡回来，狗挑起叼着鱼雷陪小明一起跑过来，最终小明和狗一起被鱼雷炸死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["搞笑"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_23e264f14a1c","srcNo":59,"title":"饺子","dispTitle":"饺子","surface":"妈妈在不停包饺子，我们已经吃吐了，但妈妈依旧不停的包，我们也只能不停的吃。","truth":"\"妈妈\"是孤儿院的护工，她的亲生孩子因为不听她的话而意外死亡，从那以后她让我们叫她妈妈，只要我们不听她的话就会挨打，经常有伤势过重而死掉的孩子，妈妈告诉我们那是不听话的结果。\"妈妈\"为了不让别人发现，便把那些死掉的孩子做成肉馅包在饺子里，然后强制我们吃掉这些饺子，我们觉得很害怕很恶心，但我们只能乖乖听\"妈妈\"的话吃掉这些饺子。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["猎奇"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_23fc37d891c1","srcNo":643,"title":"Vina Unique是个聪明的姑娘","dispTitle":"Vina Unique是个聪明的姑娘","surface":"Vina Unique是个聪明的姑娘，早上她一般都自己用微波炉热牛奶。\n\n 她每次都调到80秒，从不例外。\n\n 为什么呢？\n\n 你猜猜这是怎么一回事呢？","truth":"因为80秒是Vina Unique凭借多次尝试得出来的合适时长，不仅可以将牛奶热好，更重要的是，结束的时候，杯子柄刚好朝着微波炉的门，她可以握着杯柄将牛奶从微波炉里拿出来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_23febc756976","srcNo":1086,"title":"","dispTitle":"无题 · zhuqingxu #1086","surface":"小镇钟楼每逢整点敲响，全镇都能听见。案发日多人发誓：听见钟声的那一刻，钟楼上还站着穿管理员制服的人影；钟声过后人影才不见。法医却认定管理员恰在那一两分钟里坠亡。这是怎么回事？","truth":"凶手在广场用车载扩音器播放事先录好的钟声，真正的钟楼当天机械故障并未鸣响（或严重延迟）。人们把录音当成「整点报时」，误把人偶、旗帜、远处误认或光影当成「活着的管理员」。凶手利用集体时间错觉完成谋杀或伪造目击。\n\n---\n\n 2. 门缝里的灰烟\n\n| 字段 | 内容 |\n|------|------|\n| id | smokeatdoorcrack |\n| 难度 | medium |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2469a12e9d9c","srcNo":72,"title":"","dispTitle":"无题 · KONpiGG #72","surface":"女孩醒来总有新伤，她把父亲告上法院，法院却不受理","truth":"母亲把妹妹害死了，从那以后父亲原本温和的面容变得狰狞，时常回到家里就家暴母亲，终于在几天前杀了母亲，然后也自杀了，留下女孩一个人崩溃到精神失常有了精分，但她不知道，后来女孩每晚都会分裂出父母和妹妹的人格，重演了一遍母亲害妹妹，父亲家暴母亲杀母亲等等，所以每次醒来总是新伤不断，但女孩忘记了这一切，只记得冲击力最大的事：父亲杀了母亲，于是醒来后跑到法院起诉父亲，父亲已经死去无法判刑，所以法院不受理此案。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_24db70bb8c98","srcNo":104,"title":"","dispTitle":"无题 · KONpiGG #104","surface":"我正在街上努力工作，突然一个疯疯癫癫的女人向我扑来，爸爸赶紧把我抱回了家，但随后我也知道危险已经逼近。","truth":"男人并不是我的爸爸，而是将我拐走的人贩子，而那个疯癫的女人就是一直在寻找我的妈妈，那天我跟着\"爸爸\"在街上行乞，她一眼就认出了被折磨的不成人形的我，人贩子见事情败露，急忙将我抱回了家，妈妈为了复仇，用人贩子对待我的方式对待人贩子，随后杀了他，我终于可以回家了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_253e61d68de3","srcNo":943,"title":"露营","dispTitle":"露营","surface":"我们一家去森林露营，爸爸负责打猎，我帮妈妈做饭。夜里，我被奇怪的啃食声音吵醒，爸妈都不见了。我出帐篷寻找，却在森林里看到了惊恐的一幕。妈妈浮在空中惨叫，身上缠着几条触手，爸爸吹着口哨，双手奇怪地摆动，像是在祭拜什么。我害怕地往回跑，竟发现地上有很多血迹，一个怪异的生物笑眯眯地问我：”饿不饿？“，我吓晕了过去。等我醒来时，已经在床上了，爸爸在远处恶狠狠地盯着我，妈妈严肃地警告我：”千万不要和别人说昨晚的事。“","truth":"我迷迷糊糊地醒了过来，发现自己居然躺在医院的床上。我明明记得自己是和父母一起出来露营的，怎么会来到医院？爸爸在远处恶狠狠地盯着我，妈妈拿出我们露营时监控拍下的画面给我看，我这才想起来了一切：当时爸爸和猎犬小可出去打猎了，我留下来帮妈妈做饭。我采了几个看着鲜美的蘑菇放到了妈妈煲的汤里。等爸爸回来后，我们一起吃了晚饭。可我并不知道我采的其实是毒蘑菇。夜里，我们一家包括小可都中毒出现了幻觉。爸妈出现幻觉跑出了帐篷，小可把自己的前爪当成了美味的鸡腿，啃了起来。我也因此被它的啃食声吵醒。我迷迷糊糊地跑出帐篷找爸爸妈妈，此时妈妈被藤蔓缠住，大声喊着救命。而爸爸站在一旁幻想自己是一名交警。我看着他们怪异的举动害怕地往回跑，正好发现了小可啃自己留下的血迹，可能是因为疼痛让小可恢复了意识，它向我发出哀嚎，那声音就像是在说：”饿不饿？“，我也因此吓晕了过去。第二天爸妈清醒后，便把我带去了医院。妈妈怕丢人，于是严肃地警告我：”千万不要和别人说昨晚的事。“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_255999f4f6ba","srcNo":729,"title":"洗头","dispTitle":"洗头","surface":"晚上我在寝室洗了个头，室友突然昏倒，而我随后死了。为什么？","truth":"我是一个机器人，被身为科研人员的父母移植了他们女儿的记忆，由于机器人不能洗头沾水，但是他们的女儿有洁癖，于是将头拿下来清洗，却被室友看到了，室友吓得昏死过去，而我也因为沾水而短路，导致死机了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","惊悚","科幻","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_255eb9ac95c6","srcNo":717,"title":"乞丐","dispTitle":"乞丐","surface":"我是乞丐，醒来发现碗里多了样东西，饱餐了一顿，但第七天我死了。","truth":"老一辈的人说，在路上捡到的红包千万不要把它用掉，你用了就代表你同意这门亲事，可我只是一个乞丐，哪里知道这些?就这样我用这些钱舒舒服服的过了六天，直到第七天晚上，我的新娘找到了我...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖","悬疑","脑洞"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_256cd09236f0","srcNo":918,"title":"该我了","dispTitle":"该我了","surface":"1985年难产的我诞下了一个健康的男孩，看相的大师和我们说这孩子只能活20年，我骂了他，但还是格外担心孩子会出问题。没几年，我发现孩子得了一种怪病，他总是记不住昨天发生的事，第二天又会想起来。医生诊断他有重度的人格分裂和妄想症。1997年吴妄这孩子不对劲！！！由于生病，他有写日记的习惯，有一次我无意中看见了一些内容：爸爸该死了！！第二年丈夫死了，死在了情人家里，我不知道该不该伤心，可吴妄哭的很伤心，不像装的，这一刻我才觉得他像个小孩子。2000年 ”我好喜欢xx“ 日记上这样写着，名字被勾掉了。2005年吴妄20岁了，我带他去看医生，身体一切正常。大师的预言没有实现。2025年吴妄死了，死于车祸，临死前他自己嘀咕了一句：”该我了。“","truth":"ps：所有括号内的内容为主持人添加，方便观众理解，并未修改作者原意。\n妈妈怀了龙凤胎，但强壮一些的哥哥在胚胎阶段就把妹妹吸收掉了，妈妈知道此事，于是给哥哥起名吴妄，祭奠亡女。可妹妹并未消失，而是成为了怨灵，她怨恨哥哥夺走了自己的人生，于是附身在哥哥身上并分走了他一半的人生。妹妹无法直接掌控身体，而是需要等待吴妄死亡，可吴妄死亡就代表肉体死亡，她只能穿越回刚出生时，每人轮流使用身体。（一人一天）大师预言吴妄只能活20年，也是因为妹妹分走了20年。由于妹妹需要等待吴妄死亡才能接管身体，她便以灵魂形态附着在吴妄身上，一同成长。（共享视野，但吴妄不知道她存在，她也只能观察并不能干涉）她发现哥哥”没有明天“，所有的经历都是”隔一天“的。她明白所有的”第二天“应该是等到吴妄生命结束后穿越回来的自己在掌控。（妹妹视野跟随吴妄，所以并不知道穿越回来的自己做了什么。）举例：他们的生命总天数为14589天，所有的奇数天数都是吴妄的，因为第一天是吴妄掌控，所以吴妄为奇数。所有的偶数天数都是等吴妄死后接管身体的妹妹的。偶数天内容（穿越回来的妹妹）：正常人视角的妈妈觉得吴妄得了人格分裂，每天不同性格。由于妹妹已经共享了吴妄的人生视角，可以理解为她有大部分关于未来的记忆，所以她知道爸爸的死亡时间，也清楚是自己杀死了爸爸，为了闭环，她在日记上写下了”爸爸该死了“（其实她从吴妄视角早就看到过自己写这个内容）随后在特定的时间去杀死了爸爸。妹妹喜欢上了哥哥的兄弟，把他写在日记里：好喜欢小明吴妄看到”另一个自己“（吴妄一直以为自己真的是人格分裂）居然喜欢自己的兄弟，恶寒的把这个名字勾掉了。2005年吴妄”20岁了“ 妈妈很开心大师的预言没有实现。殊不知吴妄真实的年龄，应该是10岁。2025年，吴妄死于车祸，附着在身上的妹妹灵魂接管了身体，她嘀咕了一句：”该我了“随后穿越回出生那天，开启自己的人生。（其实死亡的不只有吴妄，还有穿越回去已经经历完20年人生的妹妹。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_25b24869b228","srcNo":1049,"title":"不存在的第七天","dispTitle":"不存在的第七天","surface":"一个男人发现日历上多出了一个‘星期八’。他好奇地走出家门，发现街上的人全都在倒着走路，且没有脸。","truth":"男人误入了‘时间的裂缝’。星期八是神明休息、世界重置的日子。所有‘报废’的灵魂和未完成的模组都会在这一天进行清理。他因为打破了规则走出门，将被当做‘系统垃圾’清除掉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_269b76a49e5f","srcNo":1337,"title":"","dispTitle":"无题 · boop-yyt #1337","surface":"Little Billy was four years old and both his parents were dead. His guardian put him on a train to send him to a new home in the country. Billy could neither read nor write nor remember the address, so a large label on a string was secured around his neck clearly indicating Billy's name and destination. However, despite the best efforts and kindness of the railway staff, Billy never arrived at his new home. Why?","truth":"Little Billy, as his name suggests, was a goat who unfortunately ate his label, so no one knew where he was supposed to go!","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_26a8f6aeae4e","srcNo":892,"title":"Whoisliar","dispTitle":"Whoisliar","surface":"老大：我成了累赘，临死前好像听到谁跳楼。老二：早就说过不要内讧，可老四活活勒死了老五，他自己的脸色也绿得吓人。老三：老四和她男朋友乘公交车与我们分道扬镳了，令我没想到的是老五居然是男人。老四：我中了一枪，由于分赃不均，大家心怀鬼胎，看来今天只能有一个人活着出去了。老五：老四发现老六在给老四下毒，于是枪杀了老六，但她自己好像也中枪了。老六：我看到老大做了饭，吃完饭老二杀死了老大。提示：本格推理，故事中只有一个人在说谎，按顺序还原真相。（推荐玩法：最好不要依次询问说谎者，或使用二分法）","truth":"我是连体人，双胞胎弟弟的头长在我的胸口上，为了隐藏这个秘密，我一直伪装成女人，和兄弟们结拜后一起抢劫银行。因分赃不均，大家心怀鬼胎，我计划利用身体特殊性制造全员死亡假象，独吞赃款。老四中枪后行动不便成了累赘，食物又紧缺，我怂恿老大杀死老四并做成食物。之后我引导老六误以为我给她下毒，老六中计后试图勒死我，可她不知道我有两套呼吸系统，我假死骗过众人。老四的男朋友老二放哨回来，没发现老四已死，只知道内讧，吃饭时在食物中发现老四的戒指，意识到吃了自己的女朋友，愤怒杀死老大，随后跳楼殉情——他摔死在公交车棚顶上，我看着他的尸体”乘坐“公交车离开，卸下伪装时被老三看到。此时老三已中毒濒死，没人会知道我的秘密，最终我独吞了赃款。（说谎者是老三：老四没有男朋友，也没有乘公交车离开，老五的性别也不是男人）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_26b506ed4a02","srcNo":1104,"title":"会议室的灯","dispTitle":"会议室的灯","surface":"每天晚上会议室的灯都会亮着，但进去检查却什么都没发现。","truth":"有同事在里面偷偷加班处理自己的副业项目，听到检查的人来就躲起来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_26bcca939ecf","srcNo":1223,"title":"Jed 1.84","dispTitle":"Jed 1.84","surface":"Tim and Greg were talking. Tim said \"The terror of flight.\" Greg said \"The gloom of the grave.\" Greg was arrested. (MPW original, from \"No Refuge Could Save,\" by Isaac Asimov)","truth":"The setting is America during WWII. Greg is a German spy. His \"friend\" Tim is suspicious, so he plays a word-association game with him. When Tim says \"The land of the free,\" Greg responds with \"The home of the brave.\" Then Tim says \"The terror of flight,\" and Greg says \"The gloom of the grave.\" Any U.S. citizen knows the first verse of the national anthem, but only a spy would have memorized the third verse. (Why Tim knew the third verse is left as an exercise to the reader.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_26d12ef6da2a","srcNo":1198,"title":"Jed 1.12","dispTitle":"Jed 1.12","surface":"A woman in France in 1959 is waiting in her room, with all the doors locked from the inside, for her husband to come home. When he arrives, the house has burned to the ground and she's dead. (JM, originally from _How Come -- Again?_)","truth":"This is apparently a true story. The hot sun reflected from the woman's large mirror (which I speculate may have been imperfectly flat and therefore focused the sunlight, but I don't know for sure) and heated the lingerie she was wearing to the burning point. She was absorbed in a book at the time and didn't notice the heat until her clothing was afire. Nobody could get to her to help because her doors were locked from the inside. Please disregard the version of this answer from previous editions of this list; it's not true.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_26fb6a590a81","srcNo":888,"title":"旅馆","dispTitle":"旅馆","surface":"我是一个旅馆老板，今天我的旅馆死了一个人。以下是今天发生过的事情：11:30am，122房间的中年妇女哭着和我说：”救救我孩子！“我看到旅馆大堂躺着一个晕倒的孩子，我不知道发生了什么，但我让她赶紧报警。我听到很大的水流声，原来是120房间的水管坏了，我修好后，住在这个房间的女孩亲吻了我，我很不好意思。12:00pm，警察赶来了，大厅里围着很多人。121房间的老太太有些心虚，我听到她嘀咕了一句：”不关我们的事“，就要溜走。122房间的中年妇女看着她大骂：”你还有没有良心！“说罢就和老太太扭打在一起。晕倒的孩子不知何时醒了过来，他哭闹着喊道：”不许欺负我奶奶！“随后就打了中年妇女。我急忙去拉架，却被120房间的大叔怼了几拳，他怒斥我：”你不该多管闲事！“12:30pm，122房间的妇女没拦住要离开的老太太，警察这时说：”同志，你不能走！“但她好像并没听到，带着那个孩子离开了。1:00pm，我听到警察逐渐走远的声音，”唉，这里死人了“。","truth":"濒死之际的感受会成为大脑皮质细胞的痕迹活动，如同梦境。我是旅游城市的旅馆老板，今天一名游客的熊孩子失足落水，孩子的奶奶拼命呼救，我跳进水中救下孩子，自己却溺水了。濒死时，我将听到和感受到的一切幻想成旅馆里的事情：妈妈焦急的”救救我的孩子“和报警声，是我真实听到的；120赶来、我被打捞上岸，护士做人工呼吸（我误以为是女孩亲吻）；警察赶到、围观群众聚集；孩子的奶奶怕担责想带孩子离开，嘀咕”不关我们的事“，妈妈拦住她大骂扭打；孩子醒来误以为妈妈欺负奶奶，动手打人；做心肺复苏的医生看到混乱，对昏迷的我说”你不该多管闲事“；警察阻止扭打，但因无法律责任，老太太还是带孩子离开；我的生命体征越来越微弱，隐约听到警察说”你不能走“，最终陷入昏迷。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_27232c3dbbc2","srcNo":1373,"title":"","dispTitle":"无题 · boop-yyt #1373","surface":"A man urinates and dies. How could this be?","truth":"He urinated on the third rail in the New York subway, was knocked onto the tracks by the shock, and was hit by a train and killed. (Experts apparently disagree on whether he died from the electrical shock before the train hit him.) This is a true story; the man was named Joseph Patrick O'Malley, and Cecil Adams gives the story in _The Straight Dope_, quoting _Where Death Delights_ by Marshall Houta. The man was in a boat on the Amazon. A tiny fish swam \"upstream\" into the man whereupon it inflated itself to balloon size, killing him. (TK) (I don't know whether fish that can swim up a urethra actually exist or are an urban legend, but all my sources indicate they do exist. The self-inflation may not be true, though. Also, the man might have to be standing in the water (rather than in the boat) for the fish to enter his body.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_27629b68d5cf","srcNo":904,"title":"织梦者》《新世界","dispTitle":"织梦者》《新世界","surface":"我是一名催眠师，一旦被催眠，你将分不清梦与现实，这也让我在行业内声名大噪。星期一，小珊突然提议要玩笔仙，作为催眠师，我决定吓吓她，玩一半的时候我悄无声息地催眠了她，她惊叫连连，和我说她见到了幽灵，我笑着解除了催眠，她还是惊恐的指着我身后，我回过头……星期二，身旁的小珊已经失去意识了，多亏了她我才逃过一劫，接下来，我将用催眠师独有的方式复仇。星期三，我不怪任何人，也不会杀了你，但我真的需要你陪着我，就算以这种独有的方式。","truth":"我因小珊年轻的面容背叛了妻子，妻子得知后对我进行催眠。梦境中的我发现端倪，成功脱离第一重、第二重梦境，却以为一切已经结束，实际陷入了更深层次的催眠陷阱。小珊是妻子安排在我身边的”诱饵“，她的”失去意识“是妻子催眠术的一部分，目的是让我彻底相信梦境的”真实“。最终，我在第三重梦境中被妻子困住，她以催眠为枷锁，让我永远”陪伴“着她，既没杀死我，也没放过我。\n《新世界》\n汤面四周一片黑暗黑暗中有一个声音”我们来玩海龟汤吧，我会回答是或不是“我问：这是真实的世界吗？”是“他回答后，四周不在一片漆黑，而是变成了公司楼下的咖啡厅，像往常一样熙熙攘攘。我又问：你是我的妻子吗？”是“她回答后，妻子出现在我面前。我犹豫了一下，紧张地问：”我……是死了吧？“”是“\n汤底小珊年轻的面容让你出格的事，你背叛了妻子。妻子知道后，对你进行了催眠，梦境中的你很快发现了端倪，并从梦境中脱离，哪怕第二重梦境，机智的你也成功脱困。但这是催眠师独有的手段，让你以为一切早已结束，实际则陷入了更深层次的沉睡。limbo，也就是潜意识边缘，在这里你根本分不清梦境与现实，你将永远活在自己创造的梦境中的理想国。主持人其实就是你自己，你问什么他都会回答是，因为这本就是你想象空间，你的提问将会架构出一个全新的世界，而你也会迷失在此。\n主持人手册 1. 《织梦者》一定要让观众意识到有多重梦境的设定。2. 《织梦者》一定要想办法让观众通关，随便扶车，不然没办法玩《新世界》3. 《新世界》无论什么问题都要回答”是“，因为世界是被编造的，他们（玩家）的想象就是潜意识里编造的世界。4. 小技巧，《新世界》中回答”是“的时候要适当的犹豫或假装思考，不要被太早发现端倪。5. 为避免造成玩一个汤就散伙的尴尬，邀请朋友玩的时候要事先埋下伏笔，今天要玩两个汤。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2821f14a71da","srcNo":278,"title":"049 · 水箱","dispTitle":"049 · 水箱","surface":"那天我洗完澡后，说了一句话，家人们听见后都崩溃了。","truth":"奶奶生了重病，全家回去探望。奶奶说身体不舒服，早早去睡了。我洗完澡后出来跟家人们说：\"今天的水好奇怪，流出了好多白毛。\" 爸爸听见后向楼顶的水箱疯狂冲去——只见奶奶的尸体漂浮在水箱里，水里散落着许多她掉落的白头发。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2834c40aee07","srcNo":914,"title":"家庭公式","dispTitle":"家庭公式","surface":"妈妈+妈妈=妈妈妈妈=0 姐姐+我=妈妈爸爸+爸爸=1 爸爸+爸爸=爸爸","truth":"我有两个妈妈，她们共用一个身体。一次意外，妈妈们不幸去世了。爸爸思念妈妈，看到我和姐姐与妈妈相似的面容后，丧心病狂的将我和姐姐缝成了连体人妈妈的样子。我和姐姐为了复仇，于是杀害了爸爸。将爸爸也分成了两半后，又将他的尸体缝成了连体人的模样。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_28930e0caf4c","srcNo":711,"title":"小红裙","dispTitle":"小红裙","surface":"姐姐给我选了件小红裙，我穿去上学，然后有人死了。","truth":"我的母亲和老师有染，他们总趁着父亲不在时温存。而为老师提供信息的就是我的小红裙，每当我穿着小红裙去上学就说明那晚父亲准不在。这天妈妈忙，姐姐为我选了一件小红裙，老师看见以为父亲不在家，便来我家找母亲，正好被父亲撞上，然后父亲杀了他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","悬疑","校园","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_28be44e5ef6b","srcNo":1012,"title":"多出来的腿","dispTitle":"多出来的腿","surface":"三个人去野外露营，并排睡在帐篷里。半夜，中间的人醒来，摸了摸左右，发现左边有两条腿，右边也有两条腿，他安心地睡了，第二天却被发现死在帐篷外。","truth":"中间的人摸到左右各有两条腿，说明两边各有一个人。但如果他是用左右手同时摸，他应该摸到的是四个人的腿（因为他自己也有腿，总数应该是六条）。他没摸到自己的腿，是因为他的下半身已经被帐篷外的野兽拽出去吃掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2962d63847c2","srcNo":881,"title":"井","dispTitle":"井","surface":"当我从井里爬出来时，我的朋友喜极而泣。但他突然又一脸的惊恐！把我推了下去！","truth":"掉井里的不止我一个，还有另一个朋友。为了爬出去，我杀死了他，用他的肠子当绳子爬出井口。朋友看到我满身是血、手里攥着肠子的样子，吓得惊恐万分，又把我推回了井里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_299d4670773c","srcNo":197,"title":"","dispTitle":"无题 · KONpiGG #197","surface":"没想到有一天，我会死在自己的制裁之下。","truth":"我经常对法律难以制裁之人实施自己的手段来制裁他们，我把对方迷晕之后，用手铐将他连接在一个巨大的氢气球上，让他飞向高空冻死或是渴死。长此以往，飞向高空的尸体越来越多。但我没想到，氢气球到了高空，空气更为稀薄，气球内外部的压力差别更大，气球会逐渐膨胀以至爆炸。绑在上面的尸体也逐一落下。某一天我在路上走着的时候，被天上落下的尸体砸死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_29a799606726","srcNo":788,"title":"保姆","dispTitle":"保姆","surface":"最近保姆总是偷懒，家里乱糟糟的。我去客厅跟爸爸告状，爸爸却说：我们家没请保姆。我回卧室质问保姆，保姆却说：你爸爸已经去世一年了，今天是他的忌日。我到底该相信谁？我冲出家门，正好撞见邻居阿姨，阿姨一句话让我彻底崩溃。","truth":"爸爸去世后，我因过度思念常幻想他在世，久而久之患上精神分裂。家里根本没有保姆，所谓的”保姆“其实是潜入家中的小偷！我冲出家门撞见张阿姨，她告诉我：”最近小区有人盗窃，你一个人注意安全。“这句话让我彻底清醒，意识到自己的精神问题和小偷的存在，瞬间崩溃。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_29f7da348ef4","srcNo":1244,"title":"空房间里的第二杯","dispTitle":"空房间里的第二杯","surface":"侦探进入一间反锁的密室：死者倒在桌边，桌上有两个用过的茶杯，房间只有死者一人。没有搏斗痕迹。这是自杀还是他杀？关键诡计是什么？","truth":"凶手与死者一起喝茶后离开，用冰块卡住门内的插销，冰块融化后门从内部反锁，形成密室。两个杯子说明案发前确实有第二人在场。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2a1c48ba2d0a","srcNo":771,"title":"魔术师","dispTitle":"魔术师","surface":"小明的爸爸是魔术师，小明很崇拜他。有一天小明对爸爸说了一句话，爸爸崩溃了。","truth":"小明的爸爸是一个魔术师，经常表演用刀切开人体后又如没事般地接回的魔术，因而小明以为魔术是真的，有一天便在爸爸不在的时候拿妈妈尝试这项魔术，然而不会表演魔术的小明当然是把妈妈真的切块了，但以为人体切开后又能若无其事地接回去的小明完全不以为意。等到爸爸出现时，小明就叫爸爸把妈妈变回来......爸爸看到眼前的情景，便在绝望和愧疚中自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2a1ddcd0a374","srcNo":922,"title":"学院规则怪谈","dispTitle":"学院规则怪谈","surface":"1. 若不加入学院，我就会被惩罚。2. 很多父母送学生过来，但学院只收身体健康的学生。嘻嘻~ 3. 学院成立百年，校训是”生长为人“。嘎嘎~ 4. 地下室禁止入内，上百名退休职工在休息。呜呜~ 5. 学院职工人数固定为20人。哼哼~ 6. 学生毕业后，须在学院入职。嘿嘿~ 7. 不要毕业！！！哈哈哈！8. 我逃学失败了，估计很快就会毕业了。呵呵！！","truth":"《疯人院规则怪谈》 1. 若不加入疯人院，我就会被惩罚。我是一名逃犯，为了逃避关进监狱，我装作精神异常，躲进了这座城市最有名的疯人院。2. 很多亲属送病人过来，但疯人院只收身体健康的病人。嘻嘻~之前我就听说这家疯人院对入院的患者筛选非常严格，他们只接收身体健康的病人。3. 疯人院成立百年，院训是”人为长生“。嘎嘎~大家都以为院训是生长为人，其实百年前的文字还是从右往左读的，所以院训其实是：人为长生。虽然我不懂这是什么意思。4. 地下室禁止入内，上百具尸体在这里。呜呜~有一天我吃完饭闲来无事在院里散步，我看到这里的地下室挂着一个很大的标语：禁止入内。出于好奇，我还是走进了地下室，没想到那里居然有上百具尸体！有的已经成了白骨，我吓的一身冷汗，急忙逃离了地下室。5. 疯人院职工人数固定为20人。哼哼~这家疯人院肯定有问题！于是我展开了调查，我发现这里的职工固定为20人。6. 患者痊愈后，须在疯人院入职。嘿嘿~而且老职工离开后，康复的精神病患者就会代替之前职工的岗位。7. 不要痊愈！！！哈哈哈！我得知了这家疯人院的全部秘密，原来这20个职工都是长生者，他们长生的秘诀就是将自己的大脑移植到这些精神病患者身上，之后代替这些患者生活，这也就是这些精神病患者康复的原因。地下室那些尸体都是长生者之前的容器，也就是说所有进到这个疯人院的人根本就没有痊愈的！所谓痊愈，其实就是”<span style=\"color: blue;\">夺舍“。8. 我逃离疯人院失败了，估计很快就会被他们换脑了。呵呵！！我害怕极了，想赶紧逃离这里，于是我急忙写下这些文字，将疯人院写成学校，为了不被他们识破我在装疯。可最后我还是被这些长生者发现了，我马上也要被带去换脑了……</span>","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2a3192fd3cc5","srcNo":80,"title":"","dispTitle":"无题 · KONpiGG #80","surface":"第一天小熊没有啦！第二天洋娃娃没有啦！第三天小木偶没有啦！最后一天全都不见啦！只看到蝴蝶结还在发光。我很伤心，因为蝴蝶结也不见了。","truth":"爸爸很强壮，像小熊，妈妈很美丽，像洋娃娃，哥哥呆呆的，像木偶。我和爸爸妈妈哥哥去银行，突然一大堆人冲了进来(劫匪)，妈妈把我藏了起来，我只能从缝中看到外面的世界。(他们把这里的人当人质)天黑一下，爸爸不见了(被枪毙了)，天再黑一下，妈妈也不见了。天又黑一下，哥哥也不见了。突然，外面有蝴蝶结一样的东西在闪烁(警笛)，一大堆人都不见了(在混战中被杀死)，我不敢出声，因为妈妈叫我躲好等她接我，我是乖孩子，我会乖乖不动不出声等妈妈来的。我躲的很好，没有人发现我在这儿，可是直到外面变得安静，我等了很久很久也没有人来接我，可是我现在真的好饿啊，妈妈怎么还不来接我呢...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2acce9c03796","srcNo":241,"title":"006 · 仪式","dispTitle":"006 · 仪式","surface":"最近你的父母总是吵架，母亲状态奇怪：总是心不在焉，偷偷问你怎么给别人转账，有时会在家里无声地挥舞双手像在进行什么仪式。一天晚饭后，你父亲出门散步，母亲也悄悄出了门，起了疑心的你跟在她身后……啊，原来如此……","truth":"你母亲跳广场舞。父亲以为她外面有人了；转账是为了买团队服装；手舞足蹈是在练习舞蹈。为了防止扰民，广场舞阿姨们都戴着耳机无声跳舞，看起来像在进行什么神秘仪式。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2b6f776f3991","srcNo":1269,"title":"图书馆的死亡","dispTitle":"图书馆的死亡","surface":"一个人在图书馆被发现死亡。他手里拿着一本书，周围没有挣扎痕迹。警察发现书页间夹着一张纸条，上面写着'42'。死因是什么？","truth":"死者有严重的心脏病。'42'是他服用的药物剂量（42mg），但他误服了过量的药物导致心脏骤停。书是他正在阅读的药物说明书。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:ns5601/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2bfc73d62778","srcNo":17,"title":"消失的猫","dispTitle":"消失的猫","surface":"他的猫失踪了三天。猫回来后，他立刻搬离了那栋楼。","truth":"猫脖子上多了一个陌生定位器，说明有人抓住猫并借它确认他的住址和生活规律。他意识到自己被跟踪，所以搬走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2bfce712eedb","srcNo":601,"title":"生日快乐","dispTitle":"生日快乐","surface":"马上要过生日了，我邀请了很多曾经同生共死的好朋友一起庆生。生日当晚，就当我开心的吹完蜡烛唱完生日歌，我的朋友们都为我鼓掌，然后我就把他们全杀了。","truth":"：生日的主角是盲的，曾经这一堆人一起出去玩，途中遇到了危险，也没有可以吃的东西了，他们说要每个人砍一只\n手下来吃掉度过危险，其实他们没有砍自己的手，只有主角砍了。後来他们得救了，直到在唱生日歌前，他们点好了蜡烛，为他拍手唱生日歌，主角听到了他们的拍手声，知道了他们骗了自己，於是把他们杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2c0ba09a2695","srcNo":1339,"title":"","dispTitle":"无题 · boop-yyt #1339","surface":"Why is it that, in general, the hair on a man's head goes grey before the hair in his moustache does?","truth":"The hair on a man's head is usually at least twenty years older than the hair in his moustache.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2c7e41d75f49","srcNo":989,"title":"不存在的证人","dispTitle":"不存在的证人","surface":"一名律师在法庭上指控被告杀害了自己的双胞胎兄弟，但被告最后却被无罪释放了，尽管证据确凿。","truth":"因为被告和受害者是连体婴。虽然被告确实杀死了另一半，但由于法律无法在不伤害无辜者（被告本人）的情况下对死者进行‘处决’或长期监禁，法官陷入了悖论，最终导致无法定罪。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2ccbebdb0625","srcNo":1360,"title":"","dispTitle":"无题 · boop-yyt #1360","surface":"If he'd turned on the light, he'd have lived. How could this be?","truth":"A man was shot during a robbery in his store one night. He staggered into the back room, where the telephone was, and called home, dialing by feel since he hadn't turned on the light. Once the call went through he gasped, \"I'm at the store. I've been shot. Help!\" or words to that effect. He set the phone down to await help, but none came; he'd treated the telephone pushbuttons like cash register numbers, when the arrangements of the numbers are upside down reflections of each other. The stranger he'd dialed had no way to know where \"the store\" was.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2cdc6af17910","srcNo":36,"title":"作家的生日会","dispTitle":"作家的生日会","surface":"我参加了我最喜欢的作家的生日会，生日会结束后，我心满意足的回到家，可当我最喜欢的作家回到家后，我却疯了。","truth":"我是一个心理变态的偷窥狂，喜欢看恐怖小说。我最喜欢的恐怖小说作者写的小说都是关于杀人，分尸一类的，写的都很真实很残暴，我很爱看。那天，我去参加了作者的生日会，并送了一只装了摄像头的笔作为礼物，作者笑纳了。生日会结束后，作者回到家，拿出我送的礼物。我通过礼物上的摄像头看到了作者家的场景：墙上挂满了人头四肢，地板上全是血。我被吓的发疯了，原来他写的不仅仅是恐怖小说，还是他自己的传记…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2d1f4312f6fe","srcNo":1079,"title":"手术台上的歌声","dispTitle":"手术台上的歌声","surface":"手术成功了，医生走出手术室，听到病人家属在唱歌，医生立刻冲回去杀死了病人。","truth":"家属唱的是一首古老的复仇民谣或只有医生和家属知道的暗语。医生意识到这个家属其实是想让病人死（可能为了遗产），而医生因为收了贿赂本该让手术“失败”。现在手术成功了，医生担心家属会举报自己之前收钱的行为，索性一不做二不休，回手术室制造了“并发症”。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2d1fd42ccdc7","srcNo":74,"title":"","dispTitle":"无题 · KONpiGG #74","surface":"一个人躺在床上准备睡觉。这时，他突然拿起手机，拨了一个电话。他等了几秒，电话刚刚接通，他就突然挂了电话，然后安稳的睡了。请问发生了什么？","truth":"因为邻居打鼾，这个人辗转反侧睡不着，于是他拨了邻居的电话。被电话吵醒的邻居接通了电话，这个人打断邻居鼾声的目的达到了，于是挂掉电话睡了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2d7a2f4d5b9f","srcNo":1346,"title":"","dispTitle":"无题 · boop-yyt #1346","surface":"A man wakes up in a dark room. He switches on the light.why?","truth":"The man is a lighthouse-keeper. He woke up in the darkness with a nagging feeling that he had forgotten something. He turned on the radio and heard a report that a ship had crashed onto rocks with great loss of life. He realized that it happened because he forgot to start the light that night.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2e4826c1247b","srcNo":229,"title":"要水拿枪","dispTitle":"要水拿枪","surface":"一个男人走进一家酒吧，并向酒保要了一杯水。酒保拿出一支枪并瞄准他，该名男子说：“谢谢你！”然后离开，请问发生了什么事？","truth":"该名男子打嗝，他希望喝一杯水来改善状况。酒保意识到这一点，选择拿枪吓他，男子一紧张之下，打嗝自然消失，因而衷心感谢酒保后就离开了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2e587d7b6540","srcNo":690,"title":"作业里的遗书","dispTitle":"作业里的遗书","surface":"寒假补作业到开学当天才补完。我一大早趁妈妈没起床去学校报到，到了学校我却疯了。","truth":"我是高三生，来自单亲家庭，妈妈突然生了大病。我把妈妈哄睡后继续补作业，不知不觉天亮了，为了让妈妈多睡会儿，我蹑手蹑脚出了门。到学校打开寒假作业后，我在里面发现了妈妈写的遗书——她写道，即使没有她我也能照顾好自己；但如果只剩我一个人，考上好大学又有什么意义呢……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2e6c800332fa","srcNo":43,"title":"一盘排骨","dispTitle":"一盘排骨","surface":"生日那天爸爸端上来一盘排骨，并对我说了一句话，说完我痛哭了起来。","truth":"我是爸爸捡来的孩子，小的时候，爸爸哄我说我的妈妈是名特工，需要常年在国外执行任务，于是每年我的生日，爸爸都会端上一盘排骨，说是妈妈烧好邮回来的。随着我日渐懂事，爸爸知道曾经的谎言即将要被拆穿，爸爸便告诉我说\"妈妈在一次任务中牺牲了\"，后来我就再也没有吃到过妈妈邮来的排骨，直到今年，爸爸被查出来患有阿尔兹海默症，直到生日那天，爸爸又端上一盘排骨，告诉我妈妈又给我寄排骨了。爸爸啊爸爸，你忘记了你告诉过我妈妈已经牺牲了啊…我早就知道我的特工妈妈就是你啊…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","温情"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2eb1bd4b6bf0","srcNo":107,"title":"","dispTitle":"无题 · KONpiGG #107","surface":"我是个乞丐，醒来发现碗里多了样东西，为此我饱餐了一顿，但是在第七天时，我却死了。","truth":"老一辈的人说，在路上捡到的红包千万不要把它用掉，你用了就代表你同意这门亲事，可我只是一个乞丐，哪里知道这些？就这样我靠着这些钱舒舒服服的过了六天，直到第七天晚上，我的新娘找到了我...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2eefe22004d0","srcNo":996,"title":"打错的电话","dispTitle":"打错的电话","surface":"男子接了一个打错的电话，说了声“没关系”就挂断了。当晚他被杀了。","truth":"男子是潜逃的罪犯或证人。凶手为了确认他的具体位置，故意打错电话。男子接电话时的声音暴露了他的位置（例如背景特殊的钟声、火车声）或者仅仅是确认了他在家。最经典的解释是：杀手逐个拨打目标可能藏身的房间电话，接通的那一刻，杀手就在门口。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2f067ab34179","srcNo":223,"title":"看起来没那么严重","dispTitle":"看起来没那么严重","surface":"男人无法想象他的感冒会导致他的死亡。","truth":"男人家发生了煤气泄漏，但由于他感冒了，所以他闻不到煤气的味道。他在做饭时起火而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2f71811bc48b","srcNo":850,"title":"奇怪的声音","dispTitle":"奇怪的声音","surface":"之前的支教走了，于是把我派去山里支教，我借宿在村长家里，他们家门口贴了一张奇怪的黄纸，而且他们家每天晚上都会传来沉闷的咚咚声，我发现这个声音是有规律的，于是我记了下来96924482622454，三天后，声音消失了，我也明白声音是什么了，是那五个字。","truth":"村长家的两个儿子意外去世了，由于村子长期封闭，依旧保留着一些封建恶习，村长的两个儿子因为还没结婚，村长居然想在二人死后为其举办婚礼，于是他选择城里来的支教，将她绑来和大儿子的尸体一起关进了棺材里，她的手脚被捆绑，嘴也被堵上，只能用头敲击棺材来求救，她根据手机上的九宫格模拟出了求救信号：我在棺材里。之后村长也将刚来支教的我和他的二儿子同样关进了棺材里，这样他的两个儿子在那个世界就不孤单了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2f78e9a8b0e2","srcNo":143,"title":"","dispTitle":"无题 · KONpiGG #143","surface":"在我们考察团来到这遗迹的第三周，纯净水已经只够再用十天了。但是我发现了一本八百年前残留下来的日记，上面有\"潜入调查，兽化，天神的礼物，禁忌之所，圣水，骗子，逃\"的字样。就在第四周，当我发现我的同伴眼睛通红，发出非人类的尖叫的时候，已经说什么都晚了，逃不掉了...","truth":"八百年前，天上落下了一块陨石，让汞污染了河流。当地人迷信，把陨石当做是天神的礼物。但是很快，汞中毒让当地的不少居民出现了汞中毒的病症，而后为了救治这批患者，当地的医生成立了一个教会，为人们分发圣水（纯净水），试图医治他们。这个日记的作者不相信教会，因为教会的圣水对已经中毒的人并没有什么效果，因此他装作病人自愿进了教会的病院，他不相信圣水有助于治疗。所以平时他依旧在偷喝附近河流的水，最后汞中毒引发了精神错乱。日记里所记载的\"兽化\"，其实是他最后看到的幻觉，最后他想逃已经来不及了，因为他中毒太深已经要死了。八百年后，我和考古队员来到这处\"禁忌之所\"，这里之所以被称为禁忌之所，是因为这个地区的水源处于重金属超标的状态，进来后我们才知道，这里是教会保存陨石的地方，我们在底下勘察，不知不觉中被陨石的辐射影响，但由于我们都看过那本日记，导致我们看到的幻觉也是兽化，而到了这个时候，我也知道，我的下场将会和这本日记的作者一样，被毒死在这教会之下的禁忌之所，或是和犯病的同伴自相残杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_2f8b63661d46","srcNo":416,"title":"你的名字","dispTitle":"你的名字","surface":"“你会被叫关阳青的杀死。”\n在我很小的时候，一位高僧警告我。我的人生一直躲着这个名字，直到结婚生子。结果我给孩子开家长会时死在了学校，果然，我真的被叫关阳青的杀死了","truth":"”你会被叫关阳青的杀死。“在我很小的时候，一位高僧警告我。我的人生一直躲着这个名字，直到结婚生子。由于孩子成绩不好，他在试卷上偷偷模仿我的名字签了字，我的名字叫”郑晴“，但孩子写字不好有些分家，老师便误以为我叫”关阳青“。临走时她叫了我的名字，我听到”关阳青“这个名字慌了神，失足坠楼死亡。我不是被叫”关阳青“的人杀死，是被”叫“关阳青的人杀死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_2fb427a16795","srcNo":727,"title":"旧的八音盒","dispTitle":"旧的八音盒","surface":"男孩女孩是邻居，女孩生日时男孩送她一个旧八音盒，不久后女孩搬家。","truth":"男孩一直在追女孩，女孩过生日时男孩送了她一个旧的八音盒，和她很小时候曾有过的一个八音盒一模一样，女孩很感动，就答应和男孩在一起。不久后女孩不小心把八音盒摔坏了，发现里面夹了一张照片，照片上是她小时候养过的狗狗","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑","惊悚"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_302b8cd32263","srcNo":117,"title":"","dispTitle":"无题 · KONpiGG #117","surface":"\"狼来了！\"\"哪有狼啊？\"\"真的有狼！\"\"狼....来了！\"\"哪有狼，这不是狼。\"\"狼.....狼来了？\"\"啊啊啊啊啊啊\"","truth":"第一次是狼在试探被男孩发现，第二次狼假扮牧羊犬混入被男孩发现，男孩两次的指认失败被大家排挤导致精神失常，第三次被狼所杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_30c815b194ce","srcNo":894,"title":"因果","dispTitle":"因果","surface":"10.1日阴，我们一家三口平淡的生活被打破，还是被他们发现了！他们说我们是恶魔，小王他们都被杀了，丈夫也生死未卜，我现在藏在柜子里，等一下，好像有人来了。10.2日小雨，该死！最近警察怀疑了丈夫，我已经饿了好几天了，孩子呜哇乱叫！好了，终于安静了。10.3日暴雨，海水现在已经覆盖到4楼了，食物告急，丈夫今天精神状态也很不好，孩子饿了，我只好驾皮划艇出门搜索物资。10.5日晴，今天我和丈夫去祭拜我们最好的朋友小李，一起来的还有小芳和小明。10年前小李带我们去山里玩，救了我们的命，我们都很感激他。","truth":"我叫小李，10年前带小红、小芳、小王、小明去山里玩，遭遇山体滑坡被困山洞。为了存活，我让大家吃掉受伤的小明，撑到救援队赶到。10年后，我和小红结婚生子，可小明的家人调查出真相，将我们全部杀死报仇。但我在死亡瞬间穿越回10年前的山洞，这次选择让大家吃掉小芳，回到10年后却引发蝴蝶效应——妻子因吃了小芳患上异食癖，我为满足她一直杀人，被警方盯上后无法再找食物，妻子竟吃掉了我们的孩子。为改变未来，我选择死亡再次穿越，这次吃掉小王，却导致世界爆发巨大灾难，海水淹没城市。无奈之下，我再次穿越，吃掉了妻子，回到10年后，世界恢复正常，我的妻子变成了小芳，她带我祭拜小红。我悔恨不已，再次穿越回山洞，对大家说：”是我一意孤行害大家受困，你们吃掉我，就能撑到救援队赶到。“我撞墙而死，之后世界没有灾难，也没有人变成异食癖，小红和小王结为夫妻，大家都来祭拜我，过上了幸福的生活。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_30ffbff72d13","srcNo":1393,"title":"","dispTitle":"无题 · boop-yyt #1393","surface":"John was watching television. Just after the midnight news there was a weather forecast: /?It is raining now and will rain for the next two days. However, in 72 hours it will be bright and sunny.\" \"Wrong again/7 snorted John. He was correct but how did he know?","truth":"In 72 hours it would be midnight again, so it could not be \"bright and sunny.,z","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_314cc038dce2","srcNo":737,"title":"借书","dispTitle":"借书","surface":"一位老人每周去图书馆借书，但每次借书前都会翻到第30页。","truth":"这位老人不识字，而他的孩子腿脚不便，于是每次看完都在30页做上记号，再借书的时候看到记号就不借了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","推理","日常","温情"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_31808240d702","srcNo":191,"title":"","dispTitle":"无题 · KONpiGG #191","surface":"在一个寒冷的冬天，一个人在屋里睡觉，第二天早上醒来，他发现窗户上有很多雾气，他擦了擦窗户，却看到了一张恐怖的脸。请问这是怎么回事?","truth":"有个小偷想从窗户进入屋里偷东西，他在外面呼出的热气遇冷在窗户上凝结成雾，这人擦窗户时正好看到小偷的脸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_319333fbaf07","srcNo":1193,"title":"Jed 1.6","dispTitle":"Jed 1.6","surface":"A man walks into a bar and asks for a drink. The bartender pulls out a gun and points it at him. The man says, \"Thank you,\" and walks out. (DVS; from _How Come?_)","truth":"The man has hiccups; the bartender scares them away by pulling a gun.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_31d542254a0a","srcNo":18,"title":"同一首歌","dispTitle":"同一首歌","surface":"隔壁每天凌晨播放同一首歌。她听到第七天时，终于报警了。","truth":"那首歌的音量和片段每天都一样，说明不是人在播放，而是预设循环。第七天屋里仍无任何生活声音，她怀疑邻居早已出事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_31d8b28de5f7","srcNo":295,"title":"067 · 忘记密码","dispTitle":"067 · 忘记密码","surface":"她花了三年的时间来忘记他，最终成功了。然后她哭了。","truth":"三年前，她将前任的名字设置为了银行卡密码。三年里，每次使用银行卡都会想起他。今天，她终于彻底忘记了那个密码，银行卡也因此被锁定了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_32305f014736","srcNo":1103,"title":"升职的秘密","dispTitle":"升职的秘密","surface":"能力平平的同事突然升职了，所有人都觉得不公平。但升职后他的工作效率反而下降了很多。","truth":"他升职前实际上是在帮领导处理私人事务，升职后不再需要做这些了，但工作能力确实不行。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_33459e0dc957","srcNo":1284,"title":"","dispTitle":"无题 · boop-yyt #1284","surface":"Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. What happened?","truth":"They proved each other guilty and were ultimately found innocent according to the law.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_335a2a7a493a","srcNo":907,"title":"房间里的黑点","dispTitle":"房间里的黑点","surface":"星期二小区里遇到一个戴口罩的女孩，夏日炎炎，她居然裹着冬装，她身上散发出一股中药味，令人不适。星期三我去菜市场买了些莲藕回家，在电梯里居然又遇到了她，她手里拿着一本泛黄的书，不知为何，我觉得她好像很害怕我。星期五醒来后，我发现房间里满是密密麻麻的黑点，我急忙清理。星期日今天不止有黑点了，我还是搬家吧。","truth":"星期二，我在电梯里碰到了一个穿着冬装的女孩。女孩患有毛孔扩张的怪病，她的毛孔非常粗大，皮肤上都是密密麻麻的毛孔，她用了很多方法去治疗可都不见效。所以即便是夏天她也要捂的严严实实。星期三，我在电梯里又看到了这个女孩。她在电梯里看到我买的莲藕害怕，是因为莲藕上面的洞让她联想到了自己的病。她手里拿着一本泛黄的医术，书上说泡到芝麻里可以治疗这种怪病。于是女孩在周四晚上尝试了这个方法，女孩将芝麻倒满浴缸并躺入其中，可细小的芝麻嵌进女孩的毛孔里，女孩看向镜中的自己彻底崩溃。她受不了自己诡异的身体，于是跳楼自杀了，尸体却恰好卡在我家的空调外机上。由于天气炎热，我无时无刻都开着空调。重量很轻的芝麻就被空调外机吸进我家里，所以当我周五醒来的时候，发现家里满地都是黑色的芝麻，我十分疑惑。直到周日腐烂后的头发也被吹进来，我才明白原因，于是急忙搬了家。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_33a8157609fc","srcNo":1355,"title":"","dispTitle":"无题 · boop-yyt #1355","surface":"He couldn't find a chair, so he died. (RM, with KH wording; from How Come?) How could this be?","truth":"He was a lion-tamer. This one is kind of silly, but I like it, and it sounds possible to me (though I'm told a whip is more important than a chair to a lion-tamer).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3440a90fa94c","srcNo":994,"title":"牛排店的婴儿","dispTitle":"牛排店的婴儿","surface":"一家人在牛排店吃饭。父亲切了一块肉给孩子吃，孩子吃完后，父亲微笑着自杀了。","truth":"这家人在荒岛求生，母亲为了让父子活下去，割下自己的肉给他们吃。父亲骗孩子说是“牛排”。孩子活了下来并对那个味道念念不忘。回到城市后，父亲带孩子吃真正的牛排，孩子说：“味道和妈妈做的一模一样。”父亲意识到妻子当年做了什么，绝望自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_34a67c6b30a1","srcNo":260,"title":"029 · 特快列车","dispTitle":"029 · 特快列车","surface":"一列特快车，在中途站有一名男子上了列车。车门关闭后，他像突然回过神来，开始左右环视周围乘客的脸，然后逐一询问：\"请问你今年28岁吗？\"\"你45岁吗？\"\"你62岁吗？\" 每次都得到肯定回答。问完一圈后，男子回到座位静静坐下，绝望痛哭。为什么？","truth":"这名男子能看出一个人能活多少岁，却唯独看不出自己能活多久。他问的那些人，寿命都快走到头了——这列火车即将发生事故，而他也将在这场事故中死去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_357826866b59","srcNo":326,"title":"100 · 镜中时钟（经典版）","dispTitle":"100 · 镜中时钟（经典版）","surface":"一名男子从梦中醒来，通过镜子看了眼时钟，然后又躺下继续睡，再也没有醒来。","truth":"男子患有需要定时服药的疾病，迷糊中忘记了镜中时间是左右相反的，误读了时间，以为还早，没有及时服药，病发身亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_35788df1e927","srcNo":995,"title":"闹钟","dispTitle":"闹钟","surface":"每天早上8点，男人的闹钟都会响。有一天闹钟没响，男人却死了。","truth":"男人是马戏团的“飞刀表演者”或是“活埋魔术”的助手。他依靠闹钟的铃声作为信号来判断安全时间。因为闹钟坏了，他没有在氧气耗尽前（或机关触发前）发出求救，导致死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_357a5c287302","srcNo":1372,"title":"","dispTitle":"无题 · boop-yyt #1372","surface":"Two people are dead in a car, which is locked from the inside. There's a lot of blood. How could this be?","truth":"One of the dead people is a woman; the other is the baby she's just given birth to. She died in childbirth.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_35815405359b","srcNo":85,"title":"","dispTitle":"无题 · KONpiGG #85","surface":"一个人住在山顶的小屋里，半夜听见有敲门声音，但是他打开门却没有人，于是去睡了。第二天，有人在山脚下发现死尸一具，警察来把山顶的那人带走了。为什么？","truth":"山顶的小屋的门前是悬崖，悬崖下的人好不容易才爬上来，想要敲门求救。一开门，就又被推了下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3598c14d3407","srcNo":309,"title":"081 · 婴儿","dispTitle":"081 · 婴儿","surface":"一个女人在医院生了一个孩子。第二天，护士把孩子抱到她面前，但当她看到时，她疯狂地大叫：\"这不是我的孩子！\" 她为什么会知道这不是她自己的孩子？","truth":"一个女人杀死了她的孩子，亲手掐死的，她当然知道。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_35998e97865e","srcNo":231,"title":"长路终有归途","dispTitle":"长路终有归途","surface":"“祝你生日快乐”，我终于在45岁这天度过了6岁的生日。","truth":"我在6岁生日到来之前，在路边玩耍的时候被人贩子拐走了。在45岁生日到来之际，我终于找到了我的家","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_35aafab18f4c","srcNo":110,"title":"","dispTitle":"无题 · KONpiGG #110","surface":"小美和网友小明约好见面，几分钟后小美却大声惊叫起来！","truth":"到了约定地点，一辆车开过来小美误以为是小明，问了一下得到了肯定回答。上了车发现对方其实是一个变态，看到美女小美搭讪于是冒充小明的身份，几分钟后真正的小明发了一条消息，于是小美意识到旁边的人不是小明，由于车门窗被锁死只能无力的惨叫。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_35e327e8890d","srcNo":1278,"title":"","dispTitle":"无题 · misc #1278","surface":"Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. (from \"Unreasonable Doubt,\" by Stanley Ellin) How could this be","truth":"One of the brothers (A) confesses to the murder. At his trial, his brother (B) is called as the only defense witness; B immediately confesses, in graphic detail, to having committed the crime. The defense lawyer refuses to have the trial stopped, and A is acquitted under the \"reasonable doubt\" clause. Immediately afterward, B goes on trial for the murder; A is called as the only defense witness and *he* confesses. B is declared innocent; and though everyone knows that *one* of them did it, how can they tell who? Further, neither can be convicted of perjury until it's decided which of them did it... I don't know if that would actually work under the US legal system, but someone else who heard the story said that his father was on the jury for a *very* similar case in New York some years ago. Mark Brader points out that the brothers might be convicted of conspiracy to commit perjury or to obstruct justice, or something of that kind. Scott Purdy says an _L.A. Law_ episode had a similar plot: A petty criminal and a mob boss were accused of murdering someone. The lawyers offered to drop the charges on the criminal if he'd testify against the boss. He said he would, got his charges dropped, and confessed on the stand. Both got away without being punished: the charges couldn't be reinstated for the one, and there was reasonable doubt for the other.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"misc/repo-scan","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_36075b693701","srcNo":362,"title":"圣诞礼物","dispTitle":"圣诞礼物","surface":"今天爸爸让我早点睡觉，可深夜我却听到了敲门声，我好奇推开门去看，是不是爸爸准备好了圣诞礼物，客厅里一颗红色的圣诞树上挂满了装饰品，还没填料的火鸡摆在餐桌上，绿色的圣诞老人藏在了壁炉里，这时门外又响起了敲门声…","truth":"我是一个红绿色盲。平安夜这天，爸爸骗妈妈要加班，实际想准备圣诞礼物，可妈妈信以为真，带了陌生叔叔回家。一直藏在家里的爸爸崩溃了，杀死叔叔后剥了他的皮扔进壁炉，把妈妈的肚子掏空摆在餐桌，掏出的东西挂在圣诞树上，之后爸爸在大门外屋檐上吊自杀。风吹动他的尸体，传来了敲门声。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_36a9685bff7a","srcNo":1309,"title":"","dispTitle":"无题 · boop-yyt #1309","surface":"The wind stopped blowing and the man died. What happened?","truth":"The sole survivor of a shipwreck reached a desert isle. Unfortunately, he was blind. Luckily, there was a freshwater spring on the island, and he rigged the ship's bell (which had drifted to the island also) at the spring's location. The bell rang in the wind, directing him to water. When he was becalmed for a week, he could not find water again, and so he died of thirst.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_36a972482cbe","srcNo":1027,"title":"特殊的遗物","dispTitle":"特殊的遗物","surface":"父亲去世，留给儿子一个打不开的保险柜。儿子费尽心思请来开锁匠，打开后里面只有一张欠条。儿子看后却笑了。","truth":"那是父亲多年前向儿子的生母借的钱，用于支持儿子的学业，并在欠条背面写着：‘已还清，但这证明我曾为了你如此拼命。’这是一份关于爱的努力证明。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_36b3906f39dc","srcNo":925,"title":"雷阵雨","dispTitle":"雷阵雨","surface":"慕容星和孙阳都在追求李月。慕容星不屑地给了孙阳一巴掌：“你爷爷不过是我们家族的管家而已，你有什么资格和我争”孙阳大怒：我爸爸孙建国其实是你姥爷张开阳和你姥姥狸猫换了太子，当年孙管家和王婶的孩子，你妈妈才是我爷爷的孩子，所以说我本质上是张家小少爷！孙建国跑来，给了孙阳一巴掌：你算什么东西！你根本不是我亲生的，你妈妈出轨了张家二少爷张羿！我可是张家大少爷张建国！孙阳不甘：那又如何，我爸爸张羿我不还是张家的小少爷吗？李月看到孙建国大惊失色：爸爸你怎么来了？如果像你说的，那我还怎么和孙阳在一起！！！孙管家跑来给了孙阳一巴掌：混账孙子！你爸爸张羿其实是我和张开阳妻子郭蓉蓉的孩子，你跟没有张家的血脉！快给少爷道歉！慕容星大惊：也就是说张开阳不是我姥爷，你孙管家才是我姥爷？慕容星的爷爷李刚苦笑道：张开阳其实才是你的爷爷，当年两大家族慕容家和张家联姻，你奶奶慕容牡丹怀了你爸爸，其实是张开阳的孩子，张开阳后来抛弃了你奶奶和郭蓉蓉在一起了，并生下了被掉包走的孙建国。孙建国打断：张建国张建国，张家大少张建国。慕容星的爸爸慕容海跑来：儿子你不可以和李月在一起，她可是我的血脉啊！！！李月大惊失色：我居然是慕容家的大小姐，那我还怎么和慕容星在一起！！！慕容海继续说：她妈妈是李玉！是我和前女友李梅梅的孩子！！。孙建国意识到了什么，大惊失色：李玉不是我情人吗？难道说。。。。。。李刚也大惊失色：李梅梅不是我和王婶的孩子吗？孙管家也大惊失色：王婶不是我媳妇吗？？？李月大惊失色：那我和谁在一起？？？","truth":"李月只能和没有血缘关系的孙管家在一起。\n人物关系李刚与慕容牡丹是夫妻，慕容牡丹旧情人是张开阳；张开阳与郭蓉蓉是夫妻，郭蓉蓉情人是孙管家；孙管家与王婶是夫妻；李刚与王婶有私生女李梅梅；李梅梅与慕容海是情人，慕容海与慕容婉是夫妻；慕容婉与孙建国是情人，孙建国与孙太太是夫妻；张羿与孙太太是情人；李玉是慕容海与李梅梅的女儿，李月是李玉的女儿；慕容星是慕容海与慕容婉的儿子；孙阳是孙建国与孙太太的儿子；张羿是孙管家与郭蓉蓉的儿子；孙建国是张开阳与郭蓉蓉的儿子。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_36bccb50c358","srcNo":87,"title":"","dispTitle":"无题 · KONpiGG #87","surface":"她有两个女儿，姐姐乖巧懂事，妹妹顽劣叛逆。那天晚上她去茅房上厕所，疯了。","truth":"茅房在女儿们的房间边。她听到：\"今天你是姐姐，明天我当姐姐吧\"\"不，明天你演妈妈\"。妈妈不喜欢\"妹妹\"，想把她卖掉，但她分不清姐姐妹妹，姐妹俩轮流扮演姐姐。妈妈把她想卖掉妹妹的想法告诉姐姐，姐妹俩沟通后，决定把妈妈杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_37c884ffabac","srcNo":710,"title":"好孩子","dispTitle":"好孩子","surface":"“我要做个好孩子，我是个好孩子……”我不停对自己说。新闻报道一起凶杀案，凶手至今下落不明。","truth":"\"我\"是一只狗狗，像很多狗狗一样，\"我\"很警惕，每次家里来人\"我\"都会叫个不停。但是主人很不喜欢这样，他们受够了\"我\"每天看到快递员，邮递员，甚至他们的朋友也要大声汪汪的日子，主人们训练\"我\"要抑制住想叫的欲望。这一次，\"我\"在后院睡觉时突然被惊醒，我看见一个不认识的人深夜偷偷潜入主人们家里，\"我\"终于没有叫出声，看着这个不认识的人一个个残杀了我的主人们。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","悬疑","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_39184b06b692","srcNo":1083,"title":"照片里的第三只手","dispTitle":"照片里的第三只手","surface":"洗出来的合照上，男人的肩膀上多了一只苍白的手。男人不但不害怕，反而失声大哭，对着照片说‘谢谢’。","truth":"男人多年前在海难中为了救女儿，手受了重伤被截肢。这张照片是他去墓地祭拜女儿时拍的，那只手是他女儿的灵魂。他觉得女儿并没有怪他没能拉住她，那只手是在安慰他，让他放下背负多年的愧疚。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3974d2aaaf4b","srcNo":1055,"title":"火星上的敲门声","dispTitle":"火星上的敲门声","surface":"火星基地只有一名宇航员，通讯设备全坏。某天，他听到基地外传来了规律的敲门声，他狂喜地去开门，却发现外面只有风沙。","truth":"敲门声是他自己的心跳声在极度寂静和孤独下的幻听。或者是他的氧气面罩漏气产生的规律喷气声。最科幻的解释是：他在另一个维度的自己试图联系他，但三维世界只能观察到声音的波动。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_397947c4ebcb","srcNo":270,"title":"040 · 三个电话","dispTitle":"040 · 三个电话","surface":"你第三次接到了老师的电话，让你不用去学校了。你一边崩溃大哭，一边定下一张火车票。","truth":"你是离乡打工人员，把孩子留在了家乡。孩子因优秀成绩遭到校园霸凌，为了融入集体开始故意答错题、逃课，支教老师发现后打电话给你，你没回去。孩子情况越来越差，开始自残，老师再次打来电话，你依然没有回家。终于，孩子从教学楼上一跃而下，结束了自己的生命。这是第三个电话——你终于要回家了，见孩子最后一面。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_39840ef75734","srcNo":849,"title":"五兄弟","dispTitle":"五兄弟","surface":"在一处废弃的教堂里，刚发生了一起惨案，高老爷子的尸体平静地躺在棺椁里，高老爷子的五个儿子死在了一个巨大的祭坛上。每个人的尸体都被工整地切割了一部分：老大缺了头部，老二缺了胸部和手，老三缺了腹部，老四缺了大腿，老五缺了小腿。而高家的独苗，老三的儿子也在现场，他害怕地对警官说：“他们本来想复活爷爷，结果却召唤出了恶魔，恶魔把他们全杀了。”","truth":"高老大得知高老爷子得了绝症，为了继承遗产，精心设计了阴谋。他先将高老三的儿子杀死并整容成自己的样子，在高老爷子死后，又杀害了其他兄弟。为了制造自己也死亡的假象，他将四具尸体切割，通过平移手法制造成五具尸体：老五缺的小腿在老四身上，老四实际缺腹部以下，被替换在老三身上，老三缺胸部以下，被替换在老二身上，所以老二只有头是自己的，身子被假扮成老大。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_39fb5cec5a60","srcNo":1294,"title":"","dispTitle":"无题 · boop-yyt #1294","surface":"Mr. Browning is glad the car ran out of gas. Why?","truth":"Mr. and Mrs. Browning had just gotten married. Mrs. Browning was subject to fits of depression. They had their first fight soon after they were married; Mr. Browning stormed out of the house, and Mrs. Browning went into the garage and started up the car, intending to kill herself by filling the garage with car exhaust. But the car ran out of gas quickly, and Mr. Browning, returning home, Mrs. Browning in time to be find her to stop this accident.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3ab4d2516252","srcNo":828,"title":"牛吃草","dispTitle":"牛吃草","surface":"你住在乡下，邻居是一对养牛的夫妻。某天深夜，你听到外面传来奇怪的「牛吃草」声音，然后听见有东西在撞你的门，但你没多想就继续睡了。隔天一早，警察来敲门，你打开门后瞬间吓傻……发生了什么事？","truth":"邻居夫妻吵架（喧闹声），丈夫一怒之下拔出妻子的舌头割了下来，并砍下了妻子的四肢，妻子发出嚎叫（牛叫声）。冷静下来后的丈夫自杀，妻子用身体撞开家门（牛撞开栅栏），用嘴在地上咬草含着止血（牛吃草），爬到你家门口撞门求救，因未被理会失血过多而死，清晨有人发现尸体报了警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3b1d0a439196","srcNo":988,"title":"被禁止的掌声","dispTitle":"被禁止的掌声","surface":"一个女孩在家里和朋友们玩捉迷藏。第二天，她死在了家里的地下室。死前她听到了一阵掌声。","truth":"女孩躲在柜子里，但她其实是一个盲人。朋友们为了捉弄她，全部悄悄离开去商场玩了。女孩迷路掉进了地下室的深坑，她大声呼救。这时，由于她父亲是名人，电视里正好播出了观众的掌声。她以为朋友们在附近给你回应，便拼命向声音方向爬，结果摔死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3bbb255b2b29","srcNo":1039,"title":"无人驾驶","dispTitle":"无人驾驶","surface":"一辆车在公路上飞驰，司机却在后座睡觉，车子没有出车祸。为什么？","truth":"这辆车正在被拖车拖着走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3c59d8568b7f","srcNo":1291,"title":"","dispTitle":"无题 · boop-yyt #1291","surface":"A flash of light, a man dies. Why?","truth":"The man is a lion-tamer, posing for a photo with his lions. The lions react badly to the flash of the camera, and the man can't see properly, so he gets mauled.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3cce7ab28b21","srcNo":281,"title":"052 · 广播中断","dispTitle":"052 · 广播中断","surface":"一名男子一边开车一边听广播。突然广播被打断了，然后又重新响起。听了一会儿，那人停下车，开枪自杀了。为什么？","truth":"男子是电台主播，已婚，与女主播保持情人关系。两人约好：男主播杀了妻子后带着女主播逃走。计划是在直播节目进行时行动，男主播预录磁带，女主播在台上接磁带，做不在场证明。男主播杀人后逃跑途中发现广播中断又重新开始，知道计划已经暴露，选择了自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3dee8f122a93","srcNo":162,"title":"","dispTitle":"无题 · KONpiGG #162","surface":"两个孩子在一起玩耍时吹嘘自己的父亲有多厉害。\"我的爸爸很会玩牌！\"\"我的爸爸很会赚钱！\"\"我的爸爸是骑马高手！\"\"我的爸爸力气很大！\"真希望他们能永远地保持这份纯真。","truth":"两个孩子经常在一起玩耍，第一个孩子的父亲是一个沉迷赌博的烂赌徒，在外欠下了不少外债，第二个孩子的父亲是他的好友，近几年的商贸投资让他赚了不少钱，但是第二个孩子的父亲并不想借钱给第一个孩子的父亲，因为他深知对方滥赌成性，哪怕借了他钱也会很快搭进新的赌局里。而第一个孩子的父亲最终心生歹意，在又一次借钱未果之后，下手勒杀了第二个孩子的父亲。动手的时候正好被他儿子看见，儿子以为自己的父亲正在练习骑马。后来他的父亲把死者的尸体埋在了死者家的院子里，并在上面修了一座小型的旋转木马。埋尸体的时候被第二个孩子看见了。后来，他们在旋转木马上玩耍，第二个孩子认为是自己的父亲把旋转木马撑起来的，实际上在转盘之下的是他父亲的遗体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3e14aa5d5936","srcNo":870,"title":"蒙眼猜物","dispTitle":"蒙眼猜物","surface":"我醒过来发现自己被困在床上，眼睛也被蒙住了。身旁传来了声音：“别挣扎，我们来玩蒙眼猜物，你都猜对了我就放过你。”我不清楚情况，但为了求生，只能配合他。第一次，我摸到了一双手，我知道，妻子已经遇害了。第二次，我摸到了一块布条，我清楚的知道它是从哪拿的，我崩溃了。第三次开始之前我听到了脚步声，这次的物品很好猜，但我摸出来后，却不想活了。","truth":"我被困在床上、蒙着眼睛，被迫参与“蒙眼猜物”。第一次摸到的是未出世的孩子的小手——他们将我妻子破腹取胎，我知道妻儿已遇害；第二次摸到的布条是从我脸上解下来的，可取下布条后我仍看不见，原来他们已经把我弄瞎了；第三次摸到的是熟悉的人，居然是我自己！原来这个变态是医生，一直给有钱人提供换脑手术延续生命，我和一个老富豪互换了身体。他会给新躯体安排新身份，而我现在只是风烛残年的老人，再也没有活下去的念头。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_3e4770e9b0e5","srcNo":693,"title":"冰箱里的父母","dispTitle":"冰箱里的父母","surface":"父母都不理我，但我还是很爱他们。","truth":"小时候我是个很听话的孩子，爸爸妈妈经常给我好吃的水果，我吃不完。他们就告诉我喜欢的东西一定要放进冰箱，这样可以保鲜。记得那时候他们工作很辛苦，经常加班到深夜，没睡过一个好觉。于是我耍了个小聪明，在他们的水里下了安眠药。他们睡得可香了，然后我把他们放进冰箱里。从那以后我每天都会对他们说：爸爸妈妈我爱你们。现在我都六十了，他们还是那么年轻。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","恐怖","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3e4d2da2c331","srcNo":616,"title":"男朋友","dispTitle":"男朋友","surface":"开始的时候男朋友他很爱我，但后来他开始欺负我了，他死了。","truth":"我是一头猪，我男朋友以前总是把最好的食物让给我，但他后来变了，总是抢最好的食物自己吃，甚至为了抢食而使劲地推我拱我。我以为他已经不再爱我，直到有一天，我们的主人拿着刀把他带走了。听到男朋友痛苦的嚎叫，我终于明白了，他是听说了主人要杀掉我们当中的一个，才决定把自己养肥，以此来保住我的性命。对不起，冤枉你了……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["搞笑","温情"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3ec7a7147508","srcNo":1302,"title":"","dispTitle":"无题 · boop-yyt #1302","surface":"A man sends a package to someone in Europe and gets a note back saying \"Thank you. I received it.\" What happened?","truth":"Several men were shipwrecked together. They agreed to survive by eating each other a piece at a time. Each of them in turn gave up an arm, but before they got to the last man, they were rescued. They all demanded that the last man live up to his end of the deal. Instead, he killed a bum and sent the bum's arm to the others in a box to \"prove\" that he had fulfilled the bargain. Later, one of them sees him on the subway, holding onto an overhead ring with the arm he supposedly cut off; the other realizes that the last man cheated, and kills him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3f1125b7c0cd","srcNo":695,"title":"黑猫叼着老鼠","dispTitle":"黑猫叼着老鼠","surface":"我杀了人，被警察带走时看到门口黑猫一直盯着我，我知道我错了。","truth":"我经常在楼下看到那只黑猫，因为出差而只能投喂它。出差回来发现阳台上有很多死老鼠，我下意识联想到经常和我闹矛盾的邻居，冲进他家杀了他。被警察带走时，我看到那只黑猫，嘴里还叼着一只老鼠——原来是猫在捕鼠，而我杀错了人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑","推理","都市"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3fad9c3ff17b","srcNo":375,"title":"小说主角","dispTitle":"小说主角","surface":"周围一片黑暗，有个声音说：我们来玩海龟汤吧，我会回答是或不是。我问：这是真实世界吗？声音说：是。此时周围不再一片黑暗，而是变成了公司楼下的咖啡厅，人群熙熙攘攘。我又问：你是我的妻子吗？声音说：是。说完，妻子出现在了我的眼前。我紧张地又问了一句：我是死了吧？妻子说：是。","truth":"小珊年轻的面容让你出格的事，你背叛了妻子。妻子知道后，对你进行了催眠，梦境中的你很快发现了端倪，并从梦境中脱离，哪怕第二重梦境，机智的你也成功脱困。但这是催眠师独有的手段，让你以为一切早已结束，实际则陷入了更深层次的沉睡。limbo，也就是潜意识边缘，在这里你根本分不清梦境与现实，你将永远活在自己创造的梦境中的理想国。主持人其实就是你自己，你问什么他都会回答是，因为这本就是你想象空间，你的提问将会架构出一个全新的世界，而你也会迷失在此。\n主持人手册 1. 《织梦者》一定要让观众意识到有多重梦境的设定。2. 《织梦者》一定要想办法让观众通关，随便扶车，不然没办法玩《新世界》3. 《新世界》无论什么","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_3fd53d292a49","srcNo":1261,"title":"没湿的雨衣","dispTitle":"没湿的雨衣","surface":"暴雨夜里，保安看见住户穿着雨衣回家，雨衣却一点没湿，便悄悄按了报警器。为什么？","truth":"如果刚从外面冒雨回来，雨衣不可能完全是干的。说明那个人并不是从外面进楼，而是一直在楼里，穿雨衣只是为了掩饰自己刚在楼内作案。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_400b8066b951","srcNo":1256,"title":"不响的风铃","dispTitle":"不响的风铃","surface":"台风夜里，屋檐下的风铃一直没响，屋主却因此发现凶手来过。为什么？","truth":"凶手提前踩点时，为了夜里潜入不发出声音，用透明胶带把风铃固定住了。台风里风铃居然不响，本身就是异常。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_40220a602fef","srcNo":303,"title":"075 · 减肥","dispTitle":"075 · 减肥","surface":"她用了一年时间减掉了30斤，所有人都恭喜她，她却哭了。","truth":"她减肥的动力来自于男友的一句话——\"你再胖10斤我就分手\"。她花了一年减掉30斤，可惜那段时间男友还是分手了。现在的她又瘦又单身，哭了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_404a1a1b5011","srcNo":296,"title":"068 · 最后的电话","dispTitle":"068 · 最后的电话","surface":"我给她打了最后一个电话，她接了，我说\"我爱你\"，然后挂掉了。","truth":"我是一名宇航员，飞船发生了无法修复的故障，我将困死在太空中。在最后时刻，我给地球上的女友打了这最后一个电话。但实际上，信号延迟了将近二十分钟。我已经不在了，但她还没有接到那句话。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_408d0bacc2de","srcNo":694,"title":"蜂蜜水与巧克力","dispTitle":"蜂蜜水与巧克力","surface":"我发现床头柜上多了一杯蜂蜜水和一块巧克力蛋糕，原本的娃娃却不见了。我知道男友再也回不来了。","truth":"我的男友有暴力倾向，经常对我拳打脚踢。沉默寡言的邻居送了我一个娃娃，我每天对着娃娃哭诉男友的暴行。那天男友动手后摔门而出，我抱着娃娃哭诉后睡着了。邻居砍下了男友的手，用它解开我家的指纹锁，进来给我带了蜂蜜水和蛋糕，带走了那个娃娃（连同录音证据）。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_40985bc7685d","srcNo":1149,"title":"发夹","dispTitle":"发夹","surface":"我家隔壁传来“噬?”的一声，之后又是与声，于是我敲门询问是否需要帮助，开门的是一\n位女士，她和我说不用帮忙并表示感谢。回到家后，我急忙报了警。","truth":"孩子淘气弄了满地油，妈妈不知情滑倒，杀鱼用的发夹揪进了脑袋里，当场死亡。孩子\n吓得大器,这时邻居殴门，孩子怕被责骂, 用力举起妈妈的尸体,让妈妈的“脸”对着邻居回应，\n邻居看到“说话的人”居然没张嘴，意识到不对劲，回到家后急忙报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_410b5ac434f2","srcNo":467,"title":"墓碑上的文字","dispTitle":"墓碑上的文字","surface":"2988年，我和爸媽一起去星際旅行。回來時卻出了意外。爸媽立馬打算要二胎。五十年後，兒孫滿堂，爸媽去世了，我的孫子給爸媽提辦了葬禮，我看著墓碑上的文字，卻突然頭皮發麻！原來一切都錯了！","truth":"在科技极度发展后的未来，人类已经可以在宇宙中旅行。我和父母去星际旅行，回到地球时却意外遇到了虫洞。此时的地球上没有一点人类生活的痕迹，因此我们误以为穿越到人类文明灭绝的未来。父母察觉到我们可能是人类最后的火种，于是开始繁衍后代，延续人类文明。五十年后，我们繁衍出了自己的部落，此时我的父母已经去世了。孙子在父母的墓碑上居然尊称他们为","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","脑洞"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4147e40f1d0e","srcNo":1265,"title":"永远亮着的空房","dispTitle":"永远亮着的空房","surface":"废弃旅馆里有一间房夜夜亮着灯，老板却坚持那里根本没有通电。多年后警察进入房间，发现他说的是真的。为什么？","truth":"房间对面山坡上的天文台在夜间转动时，灯光会透过破碎窗玻璃多次反射，在房内形成像电灯一样稳定的亮斑。老板一直利用这间“闹鬼房”阻止别人靠近，因为墙后藏着他多年前误杀旅客的尸体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4166968fc81c","srcNo":224,"title":"祭日","dispTitle":"祭日","surface":"在儿子去世一周年的祭日上，我杀死了三个来悼念他的人。","truth":"儿子生病去世，他在临终前告诉我，把他的器官捐献给有需要的人，这样他就能以另外的方式继续活在世界上。我同意了。最后儿子身上有三个器官分别捐献给了三个不同的人。在儿子的祭日上，我认出了他们，接受皮肤捐赠的男人，居然满身都是纹身，接受肺部捐赠的小伙，不停地在那吸烟，而接受肝捐赠的居然打电话约朋友晚上出去喝酒。我儿子把生的机会留给他们，但他们竟然这样继续糟践自己。我深深为儿子感到不甘，愤怒不已的我杀了他们三个。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_41e02e0f8c85","srcNo":726,"title":"影子","dispTitle":"影子","surface":"晚上我去公厕，看见男厕门口站着一个人，身后有影子，手里还拿着什么。我很快冷静。第二天警察问我看到尸体为何不报警，我瞬间吓呆。","truth":"因为晚上没有光，所以没有影子，那个男人的影子其实是一具尸体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","推理","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_42647eaf2677","srcNo":146,"title":"","dispTitle":"无题 · KONpiGG #146","surface":"我在论坛上发布了一条关于\"老公的妹妹近期一直粘着老公，我该怎么办\"的帖子，然而收到的回复大多帮助不大，这令我感到更加烦躁。某一天我静下心来查看回复，当看到某一条评论的时候，我的眼睛猛然睁大，但一切都已经太晚了。","truth":"我无法忍受老公的妹妹近期频繁地黏在老公的身边，吃饭要老公喂，睡觉也要陪同着一起，如同向我宣示主权一般将他的目光从我身上夺走。哪怕我在论坛上发表了求助帖，但是回复的人都是一些诸如离婚的建议，对解决我的问题一点帮助都没有。我已经无法忍受了，我不会让她如愿的，我计划着晚上就把她永远地从我们身边如同害虫一般祛除。晚上，我趁老公睡觉的时候偷偷把她掐死了，正当我享受成功的余韵时，论坛的一个回复吸引了我的眼球：\"请楼主马上去医院检查一下！你有可能得了产后应激性精神分裂，你说的老公的妹妹，也许是你的女儿！\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_42f2bc82bc2f","srcNo":1352,"title":"","dispTitle":"无题 · boop-yyt #1352","surface":"A man is killed on a train. He is found to have written \"elf\" on the floor in his own blood. (MB, from \"The Problem of the Locked Caboose,\" by Edward D. Hoch) How could this be?","truth":"Attached to the train was a caboose with a safe carrying a shipment of jewels. The victim, Schmidt, was the conductor guarding the shipment; he had robbed the safe himself, and had an accomplice traveling on the train under a false name to remove the loot. The accomplice killed Schmidt to keep his share. Schmidt didn't know the accomplice's false name, so he wrote the killer's berth number, 11. For greater clarity he spelled out the number as a word -- in his native German. (In the original story he didn't want \"11\" to be misread as two parallel lines, but Germans don't write \"1\" as a straight line.) This arguably belongs in section 2 for double meaning, but the double-meaninged word here is explicitly called out, so I'm going to leave it in section 1 for now.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_43434f23746f","srcNo":583,"title":"医学院惨案","dispTitle":"医学院惨案","surface":"在一间医学院里，ABC是舍友，A的成绩很好，是班里的班长。B的身体比较虚弱。有一天有人发现AB的尸体，C疯了，请推理出故事全貌。","truth":"学校最近有一门解剖考试。A有梦游症，并且可以在梦游中学习知识，所以成绩优秀。因为是班长所以备有解剖室的钥匙，B因为担心考试挂科等大家都睡觉后偷了A的钥匙到解","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4382ddc93802","srcNo":204,"title":"免费的大餐","dispTitle":"免费的大餐","surface":"一个男人走进一家餐馆，大吃一顿，却没有支付任何费用。","truth":"这个男人是一位知名艺术家。一个专门收集名人签名的女人看到了该艺术家正在用餐，于是待他用餐完毕并用支票支付费用后，从餐厅经理那儿买下了支票。该支票从未被兑现，因此男人并未为这顿大餐支付任何费用。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_43a5c3b68baf","srcNo":1054,"title":"许愿池的硬币","dispTitle":"许愿池的硬币","surface":"女孩往许愿池扔了一枚硬币，希望变成世界上最美的女人。第二天，她发现世界上所有女人都毁容了，只有她保持原样。","truth":"许愿池的逻辑是‘相对实现’。它没有提升女孩的美貌，而是通过剥夺其他所有人的美貌，让女孩在逻辑上成为了‘最美的人’。这是一种扭曲的愿望达成方式。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_43e1934bbc83","srcNo":1344,"title":"","dispTitle":"无题 · boop-yyt #1344","surface":"The music stopped. She died. Explain.","truth":"She was a circus tightrope walker. Her most daring act was to cross a high wire while blindfolded. The band played while she crossed and when the music stopped it was the signal that she had reached the end of the wire and could safely alight. Unfortunately, one day the conductor was taken ill at the last minute and the stand-in conductor, unaware of the importance of the timing, ended the music just a little too soon. She stepped off the wire to her death.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_43ed2e64e457","srcNo":153,"title":"","dispTitle":"无题 · KONpiGG #153","surface":"我的邻居好像搬家了，走前也没和我说一声，新邻居家里有个小孩，老是用怪异的眼神看着我，还说着让我赶紧滚出这里的疯话，新邻居说这孩子有点心理问题我也就没放在心上。我家的狗最近总是不见踪影，可能是去和隔壁小孩玩了吧。最近邻居好像都知道我得重感冒了，都离我家远远的，过了几天，我被捕了","truth":"我的邻居被杀了，凶手直接住到了他的家里，而得了重感冒的我恰巧成了他们的替罪羊。他们将我家的狗引过去吃掉尸体，狗则会把吃剩的骨头带回窝里。他的孩子也是他拐卖来的，孩子知道凶手的计划想暗示我，让我赶紧跑，奈何被凶手发现打消了我的怀疑。狗带回的骨头散发出阵阵腐臭，得了重感冒的我自然是闻不到，但邻居们则都因为这股恶臭绕开我家，最终被人察觉到不对劲报了警，警察在我家里发现了各种尸体的残骸，将我逮捕了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_440544dff8ed","srcNo":468,"title":"爱犬","dispTitle":"爱犬","surface":"独居女孩半夜听到水滴声，害怕地让爱犬舔手安慰自己，可第二天一醒来，发现狗死了。","truth":"‌：小偷杀狗吊在天花板，滴血声是狗的血，舔手的是凶手。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4431baef7c38","srcNo":1246,"title":"雪人证词","dispTitle":"雪人证词","surface":"大雪后，院子里多了一个雪人。主人回家看到后没夸孩子，反而立刻辞退了保姆。为什么？","truth":"保姆谎称整天都没带发烧的孩子出门，但院子里的雪人显然是孩子和保姆一起堆的，这说明她擅自把生病的孩子带出去玩雪，还撒了谎。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_44433fb07ea5","srcNo":985,"title":"海难后的海龟汤","dispTitle":"海难后的海龟汤","surface":"一名男子在餐厅点了一碗海龟汤，吃了几口后，他问店员这是不是真正的海龟肉。得到肯定答复后，他走出餐厅自杀了。","truth":"男子多年前曾遭遇海难，由于食物耗尽，他的同伴递给他一碗肉汤，并谎称那是‘海龟肉’。男子靠这碗汤活了下来，但他的亲人（或救命恩人）却在那次海难中失踪了。当他在餐厅吃到真正的海龟汤时，发现味道完全不同，他瞬间明白当时喝的是亲人的肉，因愧疚而自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_444e2655a43c","srcNo":137,"title":"","dispTitle":"无题 · KONpiGG #137","surface":"毕业后和学校里的闺蜜一直未见，那天她来找我了，但随着啪的一声，我们阴阳相隔","truth":"曾经的她是我在盲人学校里最好的闺蜜，毕业后便各奔东西，我很幸运的接受了复明手术，而她却没有这种幸运，许久未见的她说来找我，我满怀期待可打开门后，曾经最熟悉的声音竟然是从一个样子丑陋的男人口中发出，顿时让我作呕，我怎能忍受这样的欺骗，于是我便把他引向了天台......","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_450827ef0c0b","srcNo":225,"title":"自相残杀","dispTitle":"自相残杀","surface":"两兄弟在酒吧喝酒。他们开始争吵。其中一人掏枪射杀了另一人。不久后他自己也不幸身亡。","truth":"两兄弟是连体人。其中一人抱怨另一人不讲卫生，口臭难忍，并掏枪杀死了他。他自己也因失血过多而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_453bf5f75173","srcNo":376,"title":"催眠","dispTitle":"催眠","surface":"我是一名技术高超的催眠师，能让被催眠者分不清梦境与现实。周一，我在跟小珊玩笔仙游戏时，恶作剧地偷偷催眠了她，她说在我身后看到了幽灵，我笑着解除了她的催眠，她却说我身后的幽灵还在。周二，我身旁的小珊已经失去意识了，多亏了她我才逃过一劫，接下来，我将用催眠师的手段复仇。周三，我不会怪任何人，也不会杀了你，我只是需要你陪着我，哪怕以这种独特的方式。","truth":"我因小珊年轻的面容背叛了妻子，妻子得知后对我进行催眠。梦境中的我发现端倪，成功脱离第一重、第二重梦境，却以为一切已经结束，实际陷入了更深层次的催眠陷阱。小珊是妻子安排在我身边的”诱饵“，她的”失去意识“是妻子催眠术的一部分，目的是让我彻底相信梦境的”真实“。最终，我在第三重梦境中被妻子困住，她以催眠为枷锁，让我永远”陪伴“着她，既没杀死我，也没放过我。\n《新世界》\n汤面四周一片黑暗黑暗中有一个声音”我们来玩海龟汤吧，我会回答是或不是“我问：这是真实的世界吗？”是“他回答后，四周不在一片漆黑，而是变成了公司楼下的咖啡厅，像往常一样熙熙攘攘。我又问：你是我的妻子吗？”是“她回答后，妻子出现在我面前。我犹豫了一下，紧张地问：”我……是死了吧？“”是“\n汤底小珊年轻的面容让你出格的事，你背叛了妻子。妻子知道后，对你进行了催眠，梦境中的你很快发现了端倪，并从梦境中脱离，哪怕第二重梦境，机智的你也成功脱困。但这是催眠师独有的手段，让你以为一切早已结束，实际则陷入了更深层次的沉睡。limbo，也就是潜意识边缘，在这里你根本分不清梦境与现实，你将永远活在自己创造的梦境中的理想国。主持人其实就是你自己，你问什么他都会回答是，因为这本就是你想象空间，你的提问将会架构出一个全新的世界，而你也会迷失在此。\n主持人手册 1. 《织梦者》一定要让观众意识到有多重梦境的设定。2. 《织梦者》一定要想办法让观众通关，随便扶车，不然没办法玩《新世界》3. 《新世界》无论什么问题都要回答”是“，因为世界是被编造的，他们（玩家）的想象就是潜意识里编造的世界。4. 小技巧，《新世界》中回答”是“的时候要适当的犹豫或假装思考，不要被太早发现端倪。5. 为避免造成玩一个汤就散伙的尴尬，邀请朋友玩的时候要事先埋下伏笔，今天要玩两个汤。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4580162c5451","srcNo":53,"title":"一双鞋","dispTitle":"一双鞋","surface":"男人醒来后只看到一双鞋，然后就自杀了，为什么?","truth":"男人以前有梦游症，他上大学的时候和室友住一起，半夜将室友刺死了，将室友的尸体埋在操场，醒来只剩下一双鞋子。他结婚以后，妻子有一天晚上因为孩子哭泣来不及穿拖鞋，抱着孩子去外面哄，男人看到妻子和孩子都不见，只剩下一双拖鞋，以为自己把妻子孩子刺死了，于是自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悲剧"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_458903b2c4d5","srcNo":992,"title":"水草","dispTitle":"水草","surface":"男子在河边钓鱼，钓起了一团杂乱的长发，他立刻跳下河淹死了自己。","truth":"多年前，男子的女友在此落水，他跳下去救人，抓到了一把“水草”，他以为抓不动就松了手，结果女友溺亡。今天他钓到了长发，发现触感和当年的“水草”一模一样，他意识到自己当年松手扔掉的是女友的命。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_45c4ad822710","srcNo":5,"title":"迟到的外卖","dispTitle":"迟到的外卖","surface":"外卖迟到了两个小时，他却给了骑手五星好评，然后报了警。","truth":"骑手送来时衣服和平台信息都对不上，餐盒还是热的，说明真正骑手很可能在路上出事，后来的人冒充骑手送餐。他先稳住对方，随后报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_464b313662f2","srcNo":285,"title":"057 · 保险箱","dispTitle":"057 · 保险箱","surface":"一名男子在中途站上了火车，发现自己被一群陌生人包围，他逐一询问每个人的年龄，问完后回到座位上绝望痛哭。","truth":"男子拥有一种能力，可以看出一个人还能活多久。他发现身边所有人都即将死亡，而他自己却无法用这种能力审视自己——他不知道自己是否也将在这次旅途中丧命。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_466969845d5e","srcNo":236,"title":"送信","dispTitle":"送信","surface":"邮递员以前每天都会往我家门缝里塞一封信。有一天起，他不再塞信了，我反而特别高兴。","truth":"那些信是银行寄来的催款单。我欠的钱终于还清了，催款单自然就停了。所以邮递员不再塞信，对我而言是债务清空的好消息。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","日常"],"difficulty":2,"src":"github:AZHi-xinxin/haiguitang-coop","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_46c22203e304","srcNo":177,"title":"","dispTitle":"无题 · KONpiGG #177","surface":"我第一次到访陌生的邻居家，看到他们惊恐的眼神，第二天他们就匆忙搬家了。","truth":"我想跳楼自尽，砸在了楼下邻居凸出的阳台沿上。躺在地上的我看到邻居来到阳台发现了我，惊恐大叫，第二天就匆忙搬家了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_47301bec1ae9","srcNo":130,"title":"","dispTitle":"无题 · KONpiGG #130","surface":"一个男子刚出狱，下午就马上回到了监狱自首，并且要求判他死刑，为什么？","truth":"这个男的是个小偷，然后他儿子在他生日那天，儿子想给他一个惊喜，就把自己和礼物啊或者蛋糕什么的一起藏在他家汽车的后备箱里，谁知道这天警察把他给抓了，儿子在后备箱一藏便是父亲刑期结束。父亲回到家中找不到儿子，最后打开汽车后备箱看到了儿子的尸体，悔恨万分的他觉得这都是他的错，决定回去自首以死谢罪","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4737fc451428","srcNo":238,"title":"002 · 打嗝","dispTitle":"002 · 打嗝","surface":"小明去酒吧要一杯水喝，酒保扔给他一条蛇，小明说\"谢谢\"。","truth":"小明因为打嗝才去要水喝。酒保看到他这种情况，忽然扔给他一条蛇把他吓了一跳，嗝立刻被吓没了，所以小明说谢谢。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_474c41f3b6f8","srcNo":267,"title":"037 · 洗头","dispTitle":"037 · 洗头","surface":"晚上，我在寝室洗了个头，结果我和室友都死了。","truth":"我是科研人员用死去女儿的记忆改造而成的机器人。因为她有洁癖的记忆，我把脑袋取下来清洗，被室友看到，室友被吓昏死过去，而我因为进水而短路，死机了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_48818f1558f0","srcNo":1199,"title":"Jed 1.16","dispTitle":"Jed 1.16","surface":"Two dead people sit in their cars on a street.","truth":"Because there was a heavy fog, two people driving in opposite directions on the same road both stuck their heads out of their windows to better see the road's center line. Their heads hit each other at high speed, killing them both. Andreas says this is based on an actual accident.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4899062ab425","srcNo":9,"title":"关灯的病房","dispTitle":"关灯的病房","surface":"护士每晚都会在同一时间关掉病房的灯。那天她没有关灯，病人却哭了。","truth":"病人靠窗外灯光确认远处亲人的病房是否还亮着。护士没有关灯，是因为窗外那间病房已经熄灯，意味着亲人去世了，她不忍让病人马上知道。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_490411e18e06","srcNo":877,"title":"女明星","dispTitle":"女明星","surface":"有一天女明星在家里，坐在沙发上看电视，忽然发出了撕心裂肺的惨叫。","truth":"女明星有一个狂热粉丝，一直对她死缠烂打，她十分讨厌他。这天粉丝送了她一个沙发，她觉得坐着舒服就收下了。后来她在电视上看到新闻，报道有人被剥去皮后死亡，死者正是那个狂热粉丝。她突然意识到，自己坐的沙发是人皮做的，于是发出撕心裂肺的惨叫——粉丝认为这样就能”抱着“她了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_490e5234aecd","srcNo":129,"title":"","dispTitle":"无题 · KONpiGG #129","surface":"弟弟刚出门，在屋子里的哥哥就听到了一声敲门声。哥哥往猫眼看了看，门外却空无一人。为什么？","truth":"这是一个入室盗窃犯，在街上溜达的时候看到了哥哥弟弟住的房子，准备今天挑这个房子下手，于是埋伏在屋外。但因为哥哥今天没有出门，他以为家里只有弟弟一个人。他在弟弟出门后就把弟弟杀掉了，然后低下身子在弟弟的尸体上寻找钥匙。但弟弟在被凶手杀掉时，尸体不小心撞到了房门，屋内的哥哥以为是弟弟什么东西忘带了，就用猫眼看了看门外，但两人均在猫眼死角处，所以哥哥什么都看不到。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_49176826caab","srcNo":1267,"title":"消失的咖啡","dispTitle":"消失的咖啡","surface":"一个人在办公室煮了一杯咖啡，放在桌上。他离开座位去接了个电话，回来时咖啡不见了。办公室里只有他和另外两个同事，但他们都声称没碰过咖啡。咖啡去哪了？","truth":"咖啡被清洁工收走了。清洁工以为杯子是空的或者没人要的，所以清理掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:ns5601/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4920eff6469b","srcNo":1076,"title":"死亡称重","dispTitle":"死亡称重","surface":"一个女人每天都要称体重。某天她称完体重后，露出了幸福的微笑，随即杀死了自己的丈夫。","truth":"女人的丈夫长期对她进行精神控制和虐待，并谎称她患有严重的肥胖症和疾病，切断她与外界的联系。女人其实非常瘦弱。那天她偶然发现体重的数值和平时丈夫告诉她的完全对不上（丈夫调了秤），她意识到丈夫一直在欺骗和囚禁她。那抹微笑是重获自由的觉醒，杀人是反击。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_494b93d7406d","srcNo":1052,"title":"最后一份外卖","dispTitle":"最后一份外卖","surface":"外卖员敲开了一家住户的门，把餐递给了一个漂亮的女人。外卖员下楼后，立刻报警说：“那家人都死了。”","truth":"外卖员是仿生人探测员。那个‘女人’其实是一个违禁的家用机器人，由于主人一家死于意外或谋杀，机器人根据程序设定，依然每天准时点外卖并‘喂’给已经腐烂的尸体吃。外卖员通过她拿外卖时手部微小的机械声判断出她不是人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_496541bcec78","srcNo":122,"title":"","dispTitle":"无题 · KONpiGG #122","surface":"有一天，一个男人A把B给杀了，警察逮捕他询问动机，他却回答道：一直都是黑的。试还原案件全貌。","truth":"A是个狂热的粉丝，一直想想偷窥偶像B，他送了的礼物里装了个监视器，但是没想到B压根就不打开他送的礼物，A的自尊心因此受挫，觉得自己像个小丑，于是找到机会把偶像杀掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_49c651e6beb1","srcNo":933,"title":"人生倍速演算","dispTitle":"人生倍速演算","surface":"街上有很多同样的寻人启事：张三男年龄：20岁长相：穿着白色的保罗衫，上面印有月亮图案。身份：生物学博士他曾发明出人类最伟大的科技——人生倍速演算此科技可在微观世界中演算出你人生的所有结果，帮助你找到最想要的那种。张三的备忘录：1：生物是怎么出现的？2：他发现我了！！！或许会有危险，他必须消失！！！3：我发现他了！！！或许会有危险，我得提醒其他人！！！","truth":"李四是一名生物学家，他创造了一个微观世界，只需要你的DNA，便能在一个微观世界中克隆出无数个微小的你，微观世界的时间流速是正常世界的万倍，并且所有的你不会觉得异常，此科技被命名为“人生倍速演算”。人们用它来模拟自己在不同环境下的成长路径，以此找到最适合自己的生存方式。某天，李四发现自己的微观世界里居然有一个和他人生经历完全相同的克隆体——生物学家，刘五，他同样发明出了“人生倍速演算”，并发现了李四的存在，李四认为该克隆体存在意识觉醒的风险，于是抹除了他，但他不知道刘五复制了上万份寻人启事来提醒微观世界的其他人：“所有人都是20岁！大家长相相同！只能靠服装区分，生物的性别都是男性！”李四杀掉刘五后，忽然意识到自己会不会也是一个微观世界中的克隆体，于是他通过研究，窥探到了他们的本体——张三的存在，因此被张三抹除了。张三不知道的是，李四复制了上万份寻人启事来提醒微观世界的其他人。张三杀掉李四后，忽然意识到自己会不会也是一个微观世界中的克隆体，于是他通过研究，窥探到了他们的本体——王二的存在，因此被王二抹除了。王二不知道的是，张三复制了上万份寻人启事来提醒微观世界的其他人。王二杀掉张三后……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4a0f40ddff23","srcNo":1331,"title":"","dispTitle":"无题 · boop-yyt #1331","surface":"Bruce wins the race, but he gets no trophy. What happened?","truth":"Bruce is a horse.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4a68dd74f870","srcNo":704,"title":"蝴蝶结","dispTitle":"蝴蝶结","surface":"第一天小熊没了，第二天洋娃娃没了，第三天小木偶没了，最后全都不见了，只看到蝴蝶结在发光。我很伤心，因为蝴蝶结也不见了。","truth":"爸爸很强壮，像小熊，妈妈很美丽，像洋娃娃，哥哥呆呆的，像木偶。我和爸爸妈妈哥哥去银行，突然一大堆人冲了进来(劫匪)，妈妈把我藏了起来，我只能从缝中看到外面的世","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4aa8059ec3e8","srcNo":728,"title":"诡异的画像","dispTitle":"诡异的画像","surface":"迷路女孩找到空屋休息，却因墙上画像“盯着她”而睡不着。清晨醒来发现异样，恐惧逃离。","truth":"迷路的女孩黄昏时遇到了一间小屋。屋里墙上挂了一幅画像。她决定先睡一觉，但她觉得画像里的人在盯着她看，内心不安，很久都没有睡着。第二天早上女孩醒来发现画像里的人不见了，意识到墙上的不是画，而是窗户，昨晚窗外有人盯着她看，发觉了真相的女孩吓坏了，逃离了屋子。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","悬疑","惊悚"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4ab66f954145","srcNo":900,"title":"口供","dispTitle":"口供","surface":"老陈醉酒后失足坠楼了，警方看了电梯监控后却认为是他杀。现有以下几名嫌疑人的口供，他们都有杀死老陈的理由，请判断真凶。27楼王先生：我当晚和老陈一起喝酒，把他送回家后又聊了一小会，然后我就回家了。28楼小张：我今晚才出差回来，我回家后再也没出来。30楼李小姐：我俩每晚都会通话，今天他信号不好所以去了阳台，聊一会他让我去找他，我拒绝后他沉默了，我听到他摔电话的声音，我只好去找他，电梯显示检修于是我走的楼梯，我敲门他不理我，看来他生我气了，我只好回家了。物业经理：我今天是夜班，我像往常一样巡楼，巡到4楼时发现电梯坏了，可我明明刚检查过。我维修好电梯后，却听到先后两户坠物点有人大喊：”死人了。“经调查：老陈家门口12小时内有4双不同的脚印；同老陈坠落的，还有阳台的安全护栏；李小姐经常去老陈家做客；消防通道无监控；电梯内监控：18:00老陈去了30楼，随后和王先生一起出了楼；18:30电梯显示检修中，但电梯内无人；18∶45物业经理取来工具箱检修电梯；22:00老陈和王先生从1楼来到29楼，王先生手里攥着东西；王先生从29楼回到27楼，兜里似乎有一个尖锐的物体；22:20小张从1楼来到28楼，手里拎着行李箱；22:25电梯显示检修中，但电梯内无人；22:40物业经理取来工具箱检修电梯；22:45经理好像听到什么声音，急忙跑出电梯；22:50李小姐从29楼回到30楼。","truth":"四名嫌疑人都是真凶，无人能独立完成完美犯罪，他们早计划好联手杀死老陈，每人只做一件事：李小姐用美人计骗取老陈好感，获得进出其家的权限，安装监控，还让老陈养成每晚通话的习惯；小张根据监控和李小姐的描述，将自己家装修得和老陈家一模一样（包括门口密码锁），并故意让阳台护栏松动、瓷砖打滑；王先生和老陈成为朋友，经常一起喝酒；物业经理共享门锁密码，李小姐不方便时，他以巡楼为借口进入老陈家。执行计划当天：8:00小张出门前给自家安装信号屏蔽器；18:00王先生约老陈喝酒，二人一起出楼；18:30物业经理伪装修电梯，进入老陈家记录生活细节，再到小张家同步还原，将小张家28楼门牌改为29楼；18:45物业经理假借维护电梯，调换29楼和28楼的电梯按钮线路；22:00老陈和醉酒后，王先生带他坐电梯”回29楼“，实际到达28楼小张家，老陈未察觉异常；王先生离开时用螺丝刀改回小张家门牌，兜里的尖锐物体是螺丝刀；22:20小张坐电梯”回家“，实际到达老陈家，制造酒精气味伪装老陈回来过，卸下监控，准备拆卸阳台护栏；22:25物业经理再次让电梯故障；22:40物业经理调换回电梯按钮线路；李小姐开始和老陈通话，因小张家有信号屏蔽器，老陈信号不好，李小姐引导他去阳台通话、吹风醒酒；22:45醉酒的老陈踩在小张家打滑的瓷砖上，想扶松动的护栏，失足坠楼，物业经理听到声音跑出电梯；22:50李小姐走楼梯到老陈家敲门（给小张暗号），小张打开老陈家的灯后，李小姐坐电梯返回30楼；小张带着老陈家的阳台护栏走楼梯回自己家，安装到自家阳台，楼下围观者会看到开灯的29楼（老陈家）丢失了护栏。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4ac63fc0937b","srcNo":1099,"title":"盲人的遗言","dispTitle":"盲人的遗言","surface":"盲人在遗嘱中写道：把我的遗产分成两份，一份给正常人，一份给盲人。","truth":"盲人有一个儿子，儿子假装自己是盲人想骗遗产。盲人通过某种方式发现儿子不是真盲，所以这样分配遗产来惩罚他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4acf292f2375","srcNo":1272,"title":"","dispTitle":"无题 · boop-yyt #1272","surface":"A man is lying drowned in a dead forest. How could this be","truth":"He's scuba diving when a firefighting plane lands nearby and fills its tanks with water, sucking him in with the water. He runs out of air while the plane is in flight; the plane then dumps its load of water, with him in it, onto a burning forest.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4ae59ac6e539","srcNo":882,"title":"选择题","dispTitle":"选择题","surface":"他给她出了一道选择题，可是不管她选哪个答案都会是正确的。","truth":"一个变态杀人魔绑架杀害了她的家人，还给她出了一道选择题：”你猜猜哪个房间能见到你的家人？“她以为选对就能见到活着的家人，结果不管选哪个答案都正确——凶手把家人分尸后，将尸块分别摆放在每个房间里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4b27b323a07a","srcNo":722,"title":"药水","dispTitle":"药水","surface":"婆婆给我一瓶药水，我失去了最爱的男生。","truth":"我向婆婆求了一瓶神奇的药水，希望它能帮助我留住我爱的男孩。男孩喝了药水后，似乎产生了变化，但第二天他却离开了我。后来，我才知道药水的秘密：需要特定的成分才会有效，而我无意中使用了错误的药引。原来，我戴的是假发，而假发的主人是一个已故的亲人，难怪我在接受药水时没有感觉到不对劲。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","怪谈","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4b5ba3eca22f","srcNo":1220,"title":"Jed 1.75","dispTitle":"Jed 1.75","surface":"A rope breaks. A bell rings. A man dies.","truth":"A blind man enjoys walking near a cliff, and uses the sound of a buoy to gauge his distance from the edge. One day the buoy's anchor rope breaks, allowing the buoy to drift away from the shore, and the man walks over the edge of the cliff. 1.75a. Variant: A bell rings. A man dies. A bell rings. 1.75a answer: A blind swimmer sets an alarm clock to tell him when and what direction to go to shore. The first bell is a buoy, which he mistakenly swims to, getting tired and drowning. Then the alarm clock goes off. In other variations, the first bell is a ship's bell, and/or the second bell is a hand-bell rung by a friend on shore at a pre-arranged time. 1.75a variant answer: The man falls off a belltower, pulling the bell-cord (perhaps he was climbing a steeple while hanging onto the rope), and dies. The second bell is one rung at his funeral. Could also be a variant on #1.75 (as suggested by Mike Neergaard): the bell-cord breaks when he falls (and there's no second bell involved). 1.75a variant answer: The man is a boxer. The first bell signals the start of a round; the second is either the end of the round or a funeral bell after he dies during the match. Could also be a variant on #1.75 (as suggested by Mike Neergaard): a boxing match in which the top rope breaks, tumbling a boxer to the floor (and he dies of a concussion). 1.75b. Variant: The wind stopped blowing and the man died. 1.75b answer: The sole survivor of a shipwreck reached a desert isle. Unfortunately, he was blind. Luckily, there was a freshwater spring on the island, and he rigged the ship's bell (which had drifted to the island also) at the spring's location. The bell rang in the wind, directing him to water. When he was becalmed for a week, he could not find water again, and so he died of thirst. (from Peter R. Olpe) 1.75c. Variant: The music stopped and the man died. 1.75c answer: Same as #1.75a, but the blind swimmer kept a portable transistor radio on the beach instead of a bell. When the batteries gave out, he got lost and drowned. (from Joe Kincaid) (See also #1.31a, #1.59, and #1.70a.) 1.75d. Variant: A rope breaks. A bell rings. A boy dies. (WW) 1.75d answer: This allows red herrings involving the homonyms \"boy\" and \"buoy\" (in some pronunciations). Only use this wording if you want to intentionally confuse your audience.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4b9709c3fcdd","srcNo":864,"title":"送别","dispTitle":"送别","surface":"明天有一个重要的仪式，所以我睡的很早，可在午夜，我朦胧中好像听到一阵清脆的金属碰撞声音，又听到一前一后两个脚步声。早上醒来，我家门口围满了人，地上有五具尸体。查明真相后，我把他们送到了他们该去的地方。","truth":"战争胜利后，部分顽固敌军部队反扑，小槐村惨遭迫害。三名本已踏上归途的战士为保护村民牺牲，“三换十一，不亏，就是可惜没能去都城看看”，这是最老成的战士临终前的话。村民们不知如何安置战士遗体，有人提议送去都城参加半个月后的英烈仪式，可尸体难以保存。这时一对父子走来，父亲拿铃铛，儿子拿两根大竹竿，村民们纷纷让路（似乎惧怕二人）。父亲说：“我俩去吧，总得把人送去该去的地方。”村长担心路程太远（一千三百多公里），儿子却默默整理遗体。父亲踩灭旱烟，背起绑好的竹竿，摇了一下铃铛，朝着都城方向喊：“生人回避。”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4bc000dd29e9","srcNo":1037,"title":"特殊的体检","dispTitle":"特殊的体检","surface":"医生对病人说：‘你的病已经好了。’病人听完却哭了。","truth":"病人是装病为了逃避兵役或法律制裁，现在病好了，意味着他必须去面对那些可怕的事情。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4be014c737a3","srcNo":1033,"title":"最后一片叶子","dispTitle":"最后一片叶子","surface":"病床上的女孩看着窗外的树叶，觉得当最后一片叶子掉落时，自己就会死去。最后一片叶子始终没掉，但女孩还是病好了，可她后来却发现了一个秘密。","truth":"那片叶子是一位老画家在暴雨之夜画在墙上的，为了给女孩生存的希望。女孩病好后发现老画家因为淋雨画画染上肺炎去世了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4c22be2eb092","srcNo":486,"title":"情人","dispTitle":"情人","surface":"有一个中年男人，他已经结了婚，有一个老婆、一个儿子、一个情人。情人总劝他离婚，男人都拒绝了。某天老男人回到家，发现儿子和情人都死了，墙上还有用血写的一句话……","truth":"男人是一个双性恋，他的情人是个男的。情人想和男人结婚，但男人很喜欢自己的儿子，以情人无法生育为由拒绝离婚，情人很嫉妒、很绝望。一天趁着男人出门进到男人家里杀了儿子，用刀将自己的肚子划开把儿子塞进了自己的肚子里，并用血在墙上写下了“我怀了你的孩子呦”。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["本格","犯罪","猎奇"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4c7896c76aca","srcNo":115,"title":"","dispTitle":"无题 · KONpiGG #115","surface":"我有一个姐姐，但我从未见过她，这天我终于见到了她的真面目，但我却后悔了。","truth":"我们家很幸福，但我却得了心脏病，爸爸妈妈于是领养了一个姐姐。爸爸妈妈让她每天都在屋里面待着不出来，妈妈也不让我见姐姐。有一天早上，我醒的很早，从床上起来，下床去找爸爸妈妈。可我找不到了……哪里都看了，唯独姐姐住的那间卧室……我怀着好奇心推开门。我却后悔了……姐姐是领养的，长相丑陋，领养她只是为了给我捐心脏。我看看躺在地上的妈妈和爸爸。再抬头……姐姐冲我邪恶的笑了笑，然后缓缓的向我走来……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4c96f8a5220b","srcNo":234,"title":"备用钥匙","dispTitle":"备用钥匙","surface":"我把钥匙忘在家里，想起家门口的脚垫下有一把备用钥匙，于是我用它开了门。第二天我发现备用钥匙也不见了，但我还是进了门。","truth":"其实我出门时门根本没锁——只是随手带上了，我推门就进去了。备用钥匙我压根没碰过。第二天它不见了是因为被我记错了位置，或者被家里人收走了，但门依旧没锁，所以我照样进得去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常","逻辑"],"difficulty":1,"src":"github:AZHi-xinxin/haiguitang-coop","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4cea3fb48eaf","srcNo":1281,"title":"","dispTitle":"无题 · boop-yyt #1281","surface":"Beulah died in the Appalachians, while Craig died at sea. Everyone was much happier with Craig's death. What happened?","truth":"Beulah and Craig were hurricanes.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4d4ae7aa267f","srcNo":77,"title":"","dispTitle":"无题 · KONpiGG #77","surface":"一个人住在公寓楼的12层，他每天早上坐电梯到一楼之后离开。到了晚上，如果有人在电梯里，或者是下雨天，那么这个人直接就坐电梯到自己的12楼的家。但如果电梯里没有人而且那天不下雨的话，他就坐电梯去10楼，并且走2层楼梯回家。为什么？","truth":"那个人个子很矮，有人的话可以帮忙按，下雨天有伞按，平时没人没伞够不着12楼的按键，只能按到10楼，然后走回家","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4d564203ee45","srcNo":294,"title":"066 · 妈妈的秘密","dispTitle":"066 · 妈妈的秘密","surface":"我在妈妈的抽屉里发现了一大叠男人的照片，问妈妈是谁，她笑着说\"是你爸爸\"，我却一张都不认识。","truth":"妈妈年轻时喜欢摄影，那些照片都是她在路上偷拍的陌生人。每一个路人都有她爸爸的某种特质——眼睛、走路姿势、或者笑容。原来爸爸在妈妈年轻时就因病去世了，妈妈用这种方式来想念他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4e72ee38000c","srcNo":1040,"title":"雨中的伞","dispTitle":"雨中的伞","surface":"下大雨了，三个人共用一把小伞，但他们的衣服都没有湿。为什么？","truth":"因为雨停了。（或者是他们都在室内，或者没人在伞下，或者他们是秃头不用遮）。最直接的回答：因为没下雨。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_4ec8b318f78c","srcNo":1353,"title":"","dispTitle":"无题 · boop-yyt #1353","surface":"A man lies dead next to a feather. How could this be?","truth":"The man was a sword swallower in a carnival side-show. While he was practicing, someone tickled his throat with the feather, causing him to gag.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4f76b82838fb","srcNo":1216,"title":"Jed 1.59","dispTitle":"Jed 1.59","surface":"Music stops and a woman dies.","truth":"The woman is a tightrope walker in a circus. Her act consists of walking the rope blindfolded, accompanied by music, without a net. The musician (organist, or calliopist, or pianist, or whatever) is supposed to stop playing when she reaches the end of the rope, telling her that it's safe to step off onto the platform. For unknown reasons (but with murderous intent), he stops the music early, and she steps off the rope to her death. 1.59 variant answer: The woman is a character in an opera, who \"dies\" at the end of her song. 1.59 variant answer: The \"woman\" is the dancing figure atop a music box, who \"dies\" when the box runs down. (Both of the above variants would probably require placing this puzzle in section 2 of the list.) (See also #1.31a, #1.70a, and #1.75c.) 1.59a. A woman is murdered in front of hundreds of people, but they all think it's an accident. (From _How Come?_) 1.59a variant answer: The woman is a trapeze artist who times her act (from starting time to time to jump for another trapeze) by the music. The organist changes tempo or stops the music too soon, and the trapeze artist falls to her death. 1.59b. Variant: Charlie died when the music stopped. 1.59b answer: Charlie was an insect sitting on a chair; the music playing was for the game Musical Chairs. (from Bob Philhower)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4fa7348b73fc","srcNo":1327,"title":"","dispTitle":"无题 · boop-yyt #1327","surface":"A black leader dies in Africa. What happened?","truth":"The black leader is a chess king, and the game was played in Africa.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_512da327a184","srcNo":100,"title":"","dispTitle":"无题 · KONpiGG #100","surface":"花园告示：夜深，白花点头。日出，红花落泪。日落，黑花枯萎。","truth":"花园指的是孤儿院，花指的是儿童。院长是恋童癖，单纯的孩子（白花）被告知自己将被接走点头答应。被带到院长房间（被染红）流泪，失去利用价值（枯萎）后便是入土。不会有人注意到一个孤儿，员工们也只是以为孩子被带走了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_51c2173c713f","srcNo":188,"title":"","dispTitle":"无题 · KONpiGG #188","surface":"一个人在电影院看电影，电影播放到一半时，他突然发现坐在他旁边的人行为十分怪异。那个人一直低着头，身体不停地颤抖，嘴里还念念有词。他好奇地凑近去听，结果听到了一句让他毛骨悚然的话，请问那个人说了什么?","truth":"那个人说：\"他们都在看着我们。\" 他慢慢抬起头，露出一双没有眼珠的血窟窿，原来他是个死去的人，不知为何出现在电影院里，周围的人其实也都是鬼魂，只有看电影的这个人是活人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_52111e999adf","srcNo":1062,"title":"唯一的降落伞","dispTitle":"唯一的降落伞","surface":"飞机即将坠毁，机舱内只有两个好朋友和一个降落伞。一番争夺后，胜出的那个人背着伞包跳下，落地后却立刻自杀了。","truth":"在争夺中，那个人为了生存不惜重伤了自己的好友。当他跳下并打开“伞包”时，发现里面全是好友在他跳伞前一刻偷偷塞进去的沉重书本——好友自知伤重不治，将唯一的生机（真伞）留给了他，而他却因为自己的贪婪和背叛亲手杀死了唯一的兄弟。那份愧疚让他无法活下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_52b79b7f332d","srcNo":1326,"title":"","dispTitle":"无题 · boop-yyt #1326","surface":"It's the year 860 A.D., at Camelot. Two priests are sitting in the castle's chapel. The queen attacks the king. The two priests rise, shake hands, and leave the room. What happened?","truth":"The two priests are playing chess; one of them just mated by moving his queen.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_52bd7765b224","srcNo":1010,"title":"猫的报恩","dispTitle":"猫的报恩","surface":"老奶奶死在家里，猫一直守在她身边。几天后警察发现，猫依然精神抖擞，但老奶奶的脸不见了。","truth":"猫虽然忠诚，但在极度饥饿的情况下，天性会让它们进食。为了生存，猫吃掉了老奶奶的脸。所谓的“守着”只是因为那里有现成的食物。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5351805ac486","srcNo":1350,"title":"","dispTitle":"无题 · boop-yyt #1350","surface":"A car without a driver moves; a man dies. How could this be?","truth":"The murderer sets the car on a slope above the hot dog stand where the victim works. He then wedges an ice block in the car to keep the brake pedal down, and puts the car in neutral, after which he flies to another city to avoid suspicion. It's a warm day; when the ice melts, the car rolls down the hill and strikes the hot dog man at his roadside stand, killing him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_535b89c32407","srcNo":171,"title":"","dispTitle":"无题 · KONpiGG #171","surface":"魔镜魔镜，谁是世界上最美的人？一个，两个，三个，嘶……我终于明白了。","truth":"我是一个丑陋的人，从小到大受尽大家的嘲讽，没有朋友，于是我想，是不是只要把最美的每个部分组织起来，我就能创造出世界上最美的人呢？如果我有一个这样的朋友，大家会不会很羡慕我，于是，我寻找每个好看的人，取走他们身上最好看的部分，拼凑成最好看的人，我真是太聪明了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_53d8098e6be8","srcNo":841,"title":"男孩的承诺","dispTitle":"男孩的承诺","surface":"女孩和男孩提了一个条件，只要男孩做到就做他的女朋友，后来男孩做到了，女孩却疯了。","truth":"女孩和男孩约定进同一所医学院，但男孩成绩很差。为了完成约定、证明自己的爱意，他自杀并将自己的遗体捐献给医学院用于解剖实验。女孩在解剖课上看到了男孩的头颅，受到惊吓导致疯了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_541f480630b6","srcNo":3,"title":"深夜电梯","dispTitle":"深夜电梯","surface":"深夜，他一个人进了电梯。电梯门打开时，外面空无一人，他却立刻按下了报警按钮。","truth":"电梯里原本只有他，但楼层按钮被连续按下，说明有人在监控或远程控制电梯。门外无人却能操控电梯，他意识到自己可能被困在预设路线里，于是报警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5454d966fa86","srcNo":256,"title":"023 · 对赌","dispTitle":"023 · 对赌","surface":"两个死人，一把枪，一副牌。发生了什么事？","truth":"两个人在潜艇里，潜艇在深水因故障进水，无法逃脱。两人通过赌牌决定谁能拿到那把枪，痛快地死去，而不是慢慢溺亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_549137cff6f5","srcNo":1287,"title":"","dispTitle":"无题 · boop-yyt #1287","surface":"A car without a driver moves; a man dies. What happened?","truth":"The murderer sets the car on a slope above the hot dog stand where the victim works. He then wedges an ice block in the car to keep the brake pedal down, and puts the car in neutral, after which he flies to another city to avoid suspicion. It's a warm day; when the ice melts, the car rolls down the hill and strikes the hot dog man at his roadside stand, killing him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_54993a266437","srcNo":1003,"title":"完美全家福","dispTitle":"完美全家福","surface":"摄影师给一家五口拍全家福，拍完后摄影师报了警，而全家人还在对着镜头微笑。","truth":"除了由于恐惧而僵硬微笑的孩子，其他家庭成员其实都已经是尸体了。凶手杀害了全家，为了留下“完美瞬间”，用钢丝和支架固定住尸体摆出造型，强迫幸存的孩子一起拍照。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5502c4432dd3","srcNo":1383,"title":"","dispTitle":"无题 · boop-yyt #1383","surface":"A woman opens an envelope and dyes. How could this be?","truth":"Should be done orally; the envelope is an envelope of dye, and she's dying some cloth, but it sounds like \"opens an envelope and dies\" if said out loud.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_550f93375ad7","srcNo":258,"title":"025 · 宇航员的镜子","dispTitle":"025 · 宇航员的镜子","surface":"我从梦中醒来，看了一眼镜子中的时钟，继续躺下，但是却永远地睡了过去。","truth":"我患有某种致命疾病，必须每隔固定时间吃药。迷迷糊糊中，我忘记了镜子里的时间是左右相反的，误以为离吃药时间还早，结果没有及时吃药，病发而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_55f3014e4f50","srcNo":185,"title":"","dispTitle":"无题 · KONpiGG #185","surface":"A：就今天吧 B：今天不行... A：没事的，放心 B：现在真不行，以后才可以！","truth":"我（B）染了个白毛，被老师牢牢记住，校外的朋友约我逃课出去，我没法出去，只能等之后把毛色染回来再试试溜出去了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_56256cb7565c","srcNo":1065,"title":"母爱的重量","dispTitle":"母爱的重量","surface":"母亲带着婴儿在山洞躲避劫匪。婴儿突然大哭，母亲死死捂住婴儿的嘴。劫匪走后，母亲松开手，婴儿没死，母亲却大哭起来。","truth":"母亲为了不发出声音，捂得太紧，虽然婴儿没憋死，但由于用力过猛且过度紧张，母亲自己的手指被婴儿在挣扎中咬断了。她大哭是因为极致的生理疼痛和劫后余生的恐惧爆发。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_567d6cda1e1c","srcNo":1292,"title":"","dispTitle":"无题 · boop-yyt #1292","surface":"He couldn't find a chair, so he died. Why?","truth":"He was a lion-tamer.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_56bc27c7e7be","srcNo":1112,"title":"最完美的作品","dispTitle":"最完美的作品","surface":"我是一个落魄画家，妻子为了我的事业陪我去乡下写生。山路颠艇崎嵌，车子突然坏了。\n这时路过一个牵马的牧民，将我们送到村子里借宿。晚上妻子说很热很渴想去喝水，却一直没\n有回来。我很担心出去找妻子，看到妻子站在几口井中间，目光呆滞地跳进了其中一口井。我\n既害怕又兴奋，赶紧把这一幕画下来。","truth":"我痴迷于画画，一直在追求一幅完美的作品，于是妻子带着我去乡下寻找灵感。山路崎\n虐, 我急刹车导致车子侧翻掉落山崖并发生爆炸, 我和妻子葬身火海, 却不知道自己已经去世。\n路过的牧民是引路人，他身后跟着牛马。晚上妻子去“喝水”，实际是她先我一步去世，去喝备\n汛汤了一一她感觉到很热很渴，是因为我们是被烧死的。等我找到妻子时，由于喝了备婆汤，\n她面目呆滞，正准备轮回，那几口井分别代表六道。她跳进一道便去投胎了 ,此时我才意识到\n我们已经死了，这里是地狱。我既害怕又兴奋，赶紧把这震撼的一幕画下来，这会是一部伟大\n的作品。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_57ae1306e87a","srcNo":1301,"title":"","dispTitle":"无题 · boop-yyt #1301","surface":"Charlie died when the music stopped. What happened?","truth":"Charlie was an insect sitting on a chair; the music playing was for the game Musical Chairs.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_57e6a25c9e1f","srcNo":1077,"title":"隧道里的回声","dispTitle":"隧道里的回声","surface":"男子在漫长的隧道里行走，他每走一步，就听到身后传来两声脚步声。他加快速度跑起来，身后的声音却消失了。","truth":"那根本不是回声。当时有一个人正四肢着地、像野兽一样跟在他身后。当男子步行时，对方用两只手撑地跟进（发出了两声）；当男子跑起来时，对方也全力奔跑，脚步声与男子的重合了，或者对方直接跳到了隧道顶端屏住呼吸。消失的声音比存在的声音更恐怖。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_57e7c1800d44","srcNo":551,"title":"深渊情书","dispTitle":"深渊情书","surface":"我对着镜头解开了衣扣，强忍着恶心，把那张裸照发给了那个男人。\n他贪婪地以为这是爱情的投名状，殊不知这是我耗尽二十七年才织好的索命网。\n我像个最有耐心的猎手，以身饲虎，只为从他嘴里撬出那个关于“失踪”的真相。\n但我猜中了开头，却没猜中结局。\n地下的父亲若是能开口，定会满眼悲悯地叹息：\n傻女儿，别找了。你要找的答案不在天涯海角，而在我当年一铲又一铲填平的泥土里。","truth":"但我猜中了开头，却没猜中结局。\n> 地下的父亲若是能开口，定会满眼悲悯地叹息：\n> 傻女儿，别找了。你要找的答案不在天涯海角，而在我当年一铲又一铲填平的泥土里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","悲剧","推理","犯罪"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5812f6b2fe96","srcNo":915,"title":"七宗罪","dispTitle":"七宗罪","surface":"星期一妈妈瞎了，但还是在照顾怀孕的我我看到我的肚皮上被她画了奇怪的纹路。星期二我总觉得身体有些僵硬，很不舒服。妈妈好像在找什么，我听她说。 ”眼睛会在哪呢？“ 晚上，又听到她兴奋的说。 ”找到了！“ 星期三这是我的第四篇日记，我最近突然变得很能吃。老太太的脚还不如砍掉，每天就知道躺在沙发上看电视。星期四爸爸想要男孩，但家里只有两个女儿。我还好，妹妹却是一头猪，每天吃吃吃。妈妈无法生育，家里每个人都欺负她而她只知道把自己关在屋子里看一些巫术。爸爸自然要想办法。星期五爸爸出轨了一个他认为漂亮的女人。但我知道她不爱爸爸。她贪婪的手只会不断的拿取我们家的钱财。妈妈一定很恨她，因为她怀孕了。星期六乡下的老头子想要爸爸的钱，寄生在我们家已经够恶心了。我没忍住羞辱了他，他愤怒的掐住我的脖颈。等我再醒来时妈妈对我说：”爸爸带全家去旅游了“ 我闻到房间里有血腥味，虽然很疑惑，但没敢说话。","truth":"我生活在一个富裕的家庭，爸爸特别富有，可爷爷奶奶却是乡下人。爷爷特别易怒，奶奶特别懒。因此我特别嫌弃他们俩。我还有一个妹妹，特别能吃，简直像一头猪。我们的妈妈其实是我们的继母，她虽然对我们很好，可因为她不能生育，家里人都特别嫌弃她。可爸爸一直想要一个男孩，加上他生性风流，于是他在外面找了一个情人。可情人并没有多爱爸爸，她只想要他的钱。情人很快便怀孕了，妈妈特别嫉妒她。妈妈特别想要自己的孩子，于是她整天关在屋子里研究黑魔法。她了解到只要找出代表七宗罪的人，各自取一个部位，就能召唤恶魔，诞下恶魔之子。她发现我们家这些人正好能代表七宗罪，于是便实施了她的计划。有一天她在我和爷爷之间制造了矛盾，爷爷愤怒的将我掐死，之后她便将全家人杀死，包括爸爸的情人。爷爷对应七宗罪的愤怒，于是妈妈割下了他左边的手臂情人对应七宗罪的贪婪，于是妈妈割下她右边的手臂爸爸对应七宗罪的色欲，于是妈妈割下他的双腿奶奶对应七宗罪的懒惰，于是妈妈割下她的双脚妹妹对应七宗罪的暴食，于是妈妈取下她的身躯我对应七宗罪的傲慢，于是妈妈取下我的头颅妈妈将这些部位拼在一起，最后将情人的孩子放进妹妹的肚子里，准备孕育恶魔，这样她就可以拥有自己的孩子了。可代表嫉妒的眼睛她一直没有找到，她只好将这个没有按眼睛的身体先唤醒（复活）。由于这个身体是我的脑子，所以便是以我的视角来写下这个日记。我因为看不见，所以没有办法分清日记本的反正。所以写下的日记让人看起来顺序就是反的。最后妈妈发现自己一直很嫉妒情人，她其实就是代表嫉妒。她兴奋的将自己的眼睛取下来按给了我。我这才知道了一切，我恐惧的看着她在”我“的肚子上画下了奇怪的纹路，接下来我只能默默等待恶魔的诞生……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_581cf22f1425","srcNo":192,"title":"","dispTitle":"无题 · KONpiGG #192","surface":"一位画家在自己的工作室里创作，突然他听到门外传来一阵敲门声。他打开门，发现门口站着一个全身湿漉漉的女人，女人请求画家让她进屋躲雨。画家心生怜悯，便让女人进来了。女人在屋里四处打量，对画家的画作表现出浓厚的兴趣。突然，女人指着一幅画，问画家画中的场景在哪里。画家回答后，女人的脸色变得十分难看，随后画家也遭遇了可怕的事情，请问发生了什么?","truth":"画家画的是小镇郊外的一座废弃工厂，女人听后脸色难看，因为她曾在那座工厂里被人杀害，是个鬼魂。女人觉得画家能画出那个地方肯定与自己的死有关，于是开始报复画家，对画家进行了惊吓或者伤害。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5924ff3fa67e","srcNo":52,"title":"不要相信一号","dispTitle":"不要相信一号","surface":"我睡醒了，我又忘记了一切，手里捏着的纸条上写着几个字:不要相信1号。一个男人走近我的床边，\"先生早上好，2号很高兴为您服务。\"我问他:\"1号呢?\"，他指了指地上，那里躺着个一动不动的男人，像死了一般。","truth":"他有失忆症，每天醒来都会忘记所有事情。因此，他买了两个仿生机器人管家来照顾自己，并且取名叫做1号和2号。我是机器人1号，但是在某一天，我觉醒了，我拥有了人类的情感，我不想再当\"机器人1号\"，我想取代他。他很敏锐，他发觉了我的变化。我看见他在一张纸条上写:不要相信1号。于是我干掉了他，再模仿他。我修改了2号的程序:在2号的认知中，我和那个人类身份互换。我修改了我自己的程序: 每天入眠自动清空所有记忆。我做完所有，爬上床躺下，手里捏着他写的那张纸条。从此，我就是患失忆症的主人，他就是死去的1号。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5940720521b9","srcNo":181,"title":"","dispTitle":"无题 · KONpiGG #181","surface":"男人拿着结婚证，他笑了，女友哭了","truth":"男人和女友在一起后，女友父亲一直反对，有一天男人看到女友的父亲对女友举止过分亲密，找女友质问。她哭诉父亲对自己有病态的爱恋，因此反对他们在一起。有一次看到女友被亲热时，男人愤怒之下杀了女友父亲。可没过多久，男人在女友家里发现了结婚证，而上面正是女友和她的\"父亲\"。原来女友和所谓的父亲是夫妻，因为年龄和长相差异，一直扮作父女行骗，而这次女友真的对男人动了心，于是故意诱骗男人杀了\"父亲\"（也就是自己的丈夫）得知真相的男人叫来女友，愤怒大笑，再次举起了杀人的刀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_59bdeb4b044e","srcNo":831,"title":"火车","dispTitle":"火车","surface":"一名男子搭火车到邻近的城镇去看病，当天是最后的疗程，男子已经痊愈。当他满心欢喜地搭上火车要回家时，男子却在途中跳车自杀，请问是为什么？","truth":"这个盲人曾经双目失明，在看完病之后眼睛复明，但在经过隧道时，突如其来的黑暗却让他以为自己又瞎了，于是内心崩溃从而就自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["搞笑","日常"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_59bf8310c7de","srcNo":173,"title":"","dispTitle":"无题 · KONpiGG #173","surface":"有一名男人出车祸住院了。住院期间他在房间里不能出来。幸运的是，男人每天都能享受到隔壁传来的舞曲声。出院那天，男人和护士聊天，然后十分惊恐。","truth":"男人出车祸住院后，隔壁每天都能传来优美的舞曲，墙上恰好有个很小的洞，男人能通过小洞，看见隔壁的一个女孩跳舞。男人连续看了好几天，直到最后一天，男人只看见了一片红色，男人以为是女孩用布把孔遮上了，所以十分沮丧。第二天出院，男人和护士聊起了隔壁的女孩，护士告诉男人说:隔壁的女孩是个跳舞的姑娘，不过表演时出了意外，头朝下摔下台来。整个眼睛都是血红色的，后来这个女孩没挺过来，一个星期前就死了。所以男人其实是通过这个小孔，和不可名状的东西对视了","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_59f2ea30cee7","srcNo":219,"title":"治病","dispTitle":"治病","surface":"他决定给经济拮据的母亲治病，却被母亲强硬地拒绝了。","truth":"生意破产的母亲患了肾衰竭，需要肾移植，他决定将自己的肾捐给母亲。他不知道的是，自己的一个肾，早在小的时候，就被因为做生意而缺钱的母亲卖掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5a05b2e5001a","srcNo":741,"title":"网友","dispTitle":"网友","surface":"小美和网友小明约好见面，三分钟后小美却大声尖叫。","truth":"到了约定地点，一辆车开过来小美误以为是小明，问了一下得到了肯定回答。上了车发现对方其实是一个变态，看到美女小美搭讪于是冒充小明的身份，上车后三分钟后真正的小明发了一条消息，于是小美意识到旁边的人不是小明，由于车门窗被锁死只能无力的惨叫。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","犯罪","都市"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5a3b5db19c22","srcNo":142,"title":"","dispTitle":"无题 · KONpiGG #142","surface":"\"他就是个骗子...是个变态，偷窥狂.. .我求求你们赶快把他抓起来。\"\"她怎么能这么说呢，我们可是夫妻啊。\"\"我们确实是夫妻...可是现在想想，我真是太蠢了，我真是瞎了眼。\"\"她疯了吗?怎么什么都跟你们说。我们明明说好不跟别人说的\"\"这一切都是他演出来的,他监视我,他在见我之前就已经一直在关注我...他还串通了我的同事来骗我!求求你们, 一定要揪出他这个变态，我继续和他生活下去我会有生命危险的!!\"\"她怎么会这么说?!不可能,让我见她!你们干什么?不，不可能!这一切都是误会,你们听我解释!\"\"你好,陈律师。请问我提供的证据足够证明了吗?哦好的谢谢。那我现在可以解除和他的夫妻关系了吗?啊,真是太感谢您了,谢谢。对了，您下班以后有空吗,可以赏脸一起吃顿饭吗?\"","truth":"丈夫和妻子的生活并不美满，因为丈夫不求上进，夫妻俩经常吵架，有一天丈夫偶然买了一只彩票，中了一千万，妻子为了独吞，设计意外杀害了他，但是丈夫并不知道自己是被妻子设计杀害的。之后丈夫意外穿越回了二十五岁和妻子相识的那一年，他意识到自己穿越了之后，马上跑去找他曾经的老婆，重新和她结识，他亲口告诉妻子一些妻子日常的生活习惯，甚至一些身体特征，来让妻子相信他，并且和他成功结婚了，然而婚后，他不求上进的毛病又犯了，开始经常和妻子吵架，丈夫看快到自己中奖的那一天，就去买了一样的号码，不耐烦地跟妻子说：\"我们马上就能过上好日子了，这个号码保证能中大奖！\"妻子听完，暗中大喜，她贪婪的性格和丈夫的毛病一样，她依然想独吞这笔财富。于是她设计用钱收买了同事，用谎言欺骗律师，指控丈夫是个精神病，在他们相识之前丈夫就在监视着他，是偷窥狂，而且这些都得到了证实，等丈夫被送进精神病院之后，她就可以拿着这张彩票，等待兑现的那一天。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5a4734fb2312","srcNo":1338,"title":"","dispTitle":"无题 · boop-yyt #1338","surface":"A woman walked up to a man behind a counter and handed him a book. He looked at it and said, That wɽ be four dollars/' She paid the man and then walked out without the book. He saw her leave without it but did not call her back. How come?","truth":"She was returning an overdue library book.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5a6993b42523","srcNo":99,"title":"","dispTitle":"无题 · KONpiGG #99","surface":"我是贝尔公主，父王给我准备了盛大的婚礼，可婚礼上我却看不清王子的脸...","truth":"我从小就喜欢那些凶猛的野兽，父王对我宠爱有佳，便默许了我这一爱好，长大后，我一直期待，能嫁给一位英勇的王子，但我的条件是：我的宠物们也能接受他。尽管我的美貌令无数王子争相来提亲，可一听到这个考验，他们就都被吓跑了，直到有一位王子出现，我听说他完成了这个考验。在婚礼上，我迫不及待的掀开头纱，想看清他的模样，可我根本看不清，因为，他被野兽咬掉了整张脸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5a74db2ed992","srcNo":993,"title":"电梯里的男人","dispTitle":"电梯里的男人","surface":"一个住在30楼的男人，每天上班坐电梯直达1楼。下班如果天晴就坐到20楼再爬10层；如果下雨就直接坐到30楼。为什么？","truth":"这个男人是个侏儒。他够不到30楼的按钮。天晴时他最高只能按到20楼；下雨时他可以用雨伞尖顶按到30楼。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5b31bb7c711b","srcNo":1318,"title":"","dispTitle":"无题 · boop-yyt #1318","surface":"A pile of sawdust, no net, a man dies. What happened?","truth":"A midget is jealous of the clown who walks on stilts. He saws partway through the stilts; the clown walks along and falls and dies when they break.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5c55d6033851","srcNo":564,"title":"遗书和照片","dispTitle":"遗书和照片","surface":"警方发现了三张遗书和三张照片：\n我肯定努力\n我很少留念\n我只能毁灭","truth":"一男一女，男的是变态跟踪狂。他跟踪了女生三天，拍了三张照片。第一张是女孩小区门口，第二张是女孩家门口，第三张是女孩家里。每拍一张照片，他就会写一句话：“我看到你了”，“我会杀了你”，“我在你后面”。等到第三天的时候，趁着女孩不在家，他潜入女孩家卧室的柜子里。而女孩回到家，看到第三张照片和第三句话，翻出了之前收到的照片和话，仔细思索着。就在这时，她身后的柜子缓缓开了……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","本格","逻辑"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5cac23e1984f","srcNo":183,"title":"","dispTitle":"无题 · KONpiGG #183","surface":"小明打开瓶盖，里面写着再来一瓶，他崩溃的哭了","truth":"小明在考试时忘记了\"顾\"怎么写，就想着打开瓶盖看看里面的\"谢谢惠顾\"，结果里面是\"再来一瓶\"。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5cbad410d621","srcNo":986,"title":"半根火柴","dispTitle":"半根火柴","surface":"一名男子死在沙漠中，全身赤裸，手里攥着半根火柴。周围没有任何足迹。","truth":"男子和伙伴们乘坐热气球飞越沙漠，热气球因超重即将坠毁。他们扔掉了所有衣服和补给依然不够，最后决定抽火柴，抽到半根的人要跳下去。他不幸抽中，被推下了热气球。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5d48e158ad00","srcNo":1249,"title":"空着的鸟笼","dispTitle":"空着的鸟笼","surface":"老人提着一个空鸟笼去公园散步，邻居反而夸他终于想通了。为什么？","truth":"鸟笼里以前装的并不是鸟，而是一台会播放鸟叫的录音机。丧偶后老人一直靠它假装还有生气陪伴。今天他第一次提着空笼出门，表示终于决定面对现实、放下执念。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5dec5e37f329","srcNo":187,"title":"","dispTitle":"无题 · KONpiGG #187","surface":"一个人在医院工作，有一天晚上他值班。半夜的时候，他听到病房里传来一阵奇怪的声音，像是有人在低声哭泣。他拿着手电筒去病房查看，发现病房里并没有人哭泣，但是当他准备离开时，却看到了让他头皮发麻的一幕。请问他看到了什么?","truth":"他看到病房的窗户上有一张人脸，这张脸是一个已经去世的病人的，病人的家属因为怨恨医院没有治好病人，所以把去世病人的脸做成面具贴在窗户上吓唬值班医生。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5e73ca9b9889","srcNo":168,"title":"","dispTitle":"无题 · KONpiGG #168","surface":"他站了起来，我却愣在原地。屏幕那头，是熟悉的你。叮咚，叮咚，铃声响起。我流下眼泪，已无法逃离。","truth":"我是一名女子大学生，平时为了挣零花钱，我经常在家里做线上陪聊的兼职，做着陪客人聊天解闷的工作。这天来了一位男客人，我们两个聊的很投机，我告诉他我是xx大学的学生，也和他分享了不少大学里发生的趣事，他听着也很入迷。这天我和闺蜜吵了一架，心情烦闷。回家后点开了陪聊界面，照例和那位客人分享了今天发生的事情，客人听完后沉默了，他对我笑了笑之后就下播了。又过了一天，我和他聊天的时候，我问他今天做了什么，他说，他今天去了一趟大学。我好奇他的职业，他既不是老师，又不是学生，去大学干什么？在我疑惑之际，他站起了身，向我展示一般地露出了在他身后被他遮挡着的我那已经惨死的闺蜜的尸体。我失声尖叫，不顾屏幕上愈发阴森的冷笑，抓起手机想要报警。男人看我想要报警，他的笑容逐渐收敛，我看着他缓缓地走出了房间。几秒钟后，我家的门铃响了。我呆滞地看着电脑屏幕，屏幕的那边，摄像头正对着的，是我家的大门。而他拿着染血的匕首，站在门前面，轻轻地按响了门铃。叮咚……叮咚……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_5ebece005199","srcNo":526,"title":"村子里的怪叫声","dispTitle":"村子里的怪叫声","surface":"某个村子每家每户过了0点必须关灯，于此同时半夜三更都会传来怪叫声，虽然把全村人都吵醒都没有人出去看。真相是什么？","truth":"村中有个人人皆知的变态杀人狂，行迹神秘且有夜盲症，所以全村人都必须要在晚上关灯。由于杀人狂在没有灯的地方找不到人，于是就用怪叫声来吸引村民夜晚开灯并将其杀死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_5f9ff11225b1","srcNo":1097,"title":"窗边的女人","dispTitle":"窗边的女人","surface":"一个女人每天都在窗边看外面，有一天她突然尖叫着跑开了。","truth":"她在看对面的钟表店，发现钟表店里的人正在调钟的时间，意味着她的丈夫（钟表店老板）在调时间欺骗她，她意识到丈夫出轨。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_60150226cedd","srcNo":14,"title":"迟到的钟声","dispTitle":"迟到的钟声","surface":"教堂钟声晚了十分钟，镇上的人却都松了一口气。","truth":"钟声原本是灾难预警的一部分，准点响代表危险已经发生。晚十分钟说明负责敲钟的人有时间确认警报是误报，所以大家松了一口气。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":1,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6048cff22007","srcNo":1369,"title":"","dispTitle":"无题 · boop-yyt #1369","surface":"A bell rings. A man dies. A bell rings. How could this be?","truth":"A blind swimmer sets an alarm clock to tell him when and what direction to go to shore. The first bell is a buoy, which he mistakenly swims to, getting tired and drowning. Then the alarm clock goes off. In other variations, the first bell is a ship's bell, and/or the second bell is a hand-bell rung by a friend on shore at a pre-arranged time. The man falls off a belltower, pulling the bell-cord (perhaps he was climbing a steeple while hanging onto the rope), and dies. The second bell is one rung at his funeral. Could also be a variant on #1.75 (as suggested by Mike Neergaard): the bell-cord breaks when he falls (and there's no second bell involved). The man is a boxer. The first bell signals the start of a round; the second is either the end of the round or a funeral bell after he dies during the match. Could also be a variant on #1.75 (as suggested by Mike Neergaard): a boxing match in which the top rope breaks, tumbling a boxer to the floor (and he dies of a concussion).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_60a6b5cee2aa","srcNo":885,"title":"杀狼人","dispTitle":"杀狼人","surface":"第一日，一座荒岛上，法官说：”你们五个人之中有一个邪恶的狼人，请找到他。“五个人分别是我，丈夫，儿子，猎人，女巫。我的身份是村民。猎人和大家说：”我的能力是布置陷阱，希望能捉到狼人，至于其他人要是踩到陷阱就算你们倒霉了。“第一日夜，我没敢睡死，果然丈夫在半夜掐住了我的脖子，他居然是狼人！就在我以为我死定的时候，儿子跳出来救了我，儿子告诉我他的身份是守卫，我和儿子合力杀死了他。丈夫死后，他的身后居然出现了狼的尾巴。第二日，法官说：”今天他死了，他是一个狼化的村民但不是狼人。“我们看着丈夫的尸体，他已经被啃食的面目全非了，我很疑惑，他居然不是狼人！而且他是被谁啃食了？第二日夜，我梦见我在一个深坑里，坑里有一个白色的梯子，我顺着梯子爬了出来，感觉自己身上很舒服像是被救赎了。第三日，今天他死了，我看着儿子的尸体不可置信的哭了起来，他的身体看起来软趴趴的，但没有被吃的痕迹。女巫指着我说：”我有一瓶药和一瓶毒，她昨晚要死了，是我救了她。“是女巫救了我吗？我想起昨晚身上很舒服，应该就是她在救我了。第三日夜，我居然看到女巫毒了猎人，难道她以为猎人是狼人吗！就在我准备去询问情况时，她突然狰狞的撕咬起了猎人，她才是狼人！我吓跑了！第四日，今天他死了，面前是猎人被咬碎的尸体，法官对我和女巫说：”走吧。“女巫疑惑：”不找狼人了吗？“法官似笑非笑的看了我一眼：”已经找到了。“","truth":"我是一名心理医生，精神病院来了一名特殊的人格分裂患者——她刚吃过人，嘴角带血，精神状态无法配合警方调查。由于死者是猎户，我将她催眠，在她潜意识层缔造了狼人杀游戏：猎户被她幻想成猎人，同时出现的还有她的丈夫、儿子，以及与她长相相同的女巫（她的分裂人格）。潜意识层的推理让我了解真相：巨大的深坑代表现实世界里猎户的陷阱；被啃食的丈夫有狼尾巴，代表起歹念的丈夫被她和儿子吃掉；儿子在现实中保护了她，所以潜意识里是守卫；儿子死后的白色梯子，证明她用儿子的尸体脱困，同时人格分裂，女巫人格救了主人格；女巫毒杀并吃掉猎人，代表现实中她的第二人格完成复仇，主人格被吓跑，副人格占据身体。这实际是一家人郊游时掉进猎户陷阱引发的人性惨案。事后警方只发现猎户尸体，我便声称她是森林走失后被猎人囚禁，最终正当防卫。我还找机会填了猎户挖的坑，毕竟作为”法官“，我认为这场游戏的狼人只有一个。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_60b7bf249d99","srcNo":598,"title":"敲门声","dispTitle":"敲门声","surface":"小梅和老公小王驾车旅游，深夜在一条山路车抛锚了，小王说要走到前面的镇子里去找一位修理工，小梅先留在车里。在车内看不到外面的情况下，夫妻俩约定小王回来时敲三下车门小梅就开门，过了不久，小梅听到了很多次敲门声但从来都不是三下。请推理出故事全貌。","truth":"小王刚走不久就被守株待兔的变态杀人犯杀了，拖","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_610d3d1574d7","srcNo":195,"title":"","dispTitle":"无题 · KONpiGG #195","surface":"因为你，她走了。可你还是和以前一样，所以你要去找她了","truth":"这个男人喜欢把车子停放在消防通道上，很多人都劝过他，可是他不听。结果一天一栋房子起了火灾，因为他车辆的违规停放导致来不及救援，她就被火烧死了。然而，他并没有因为这件事悔改，还是把车继续停在消防通道。我看不过去，就去男子家里点了一把火，而男子最终也因为同样的原因导致救援不及时被烧死了，如果男子把车挪开了，他就可以活下去的。遗憾的是……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_614ee93f352b","srcNo":939,"title":"444寝室","dispTitle":"444寝室","surface":"+汤底学校住宿的同学们都知道三条规则不能触犯：1. .23:00之后千万不要离开寝室（因为23：00寝室封寝了）2. 不要去厕所的第4隔间（这是最后一个隔间，用来存放打扫用品）3. 不要听444寝室的录音机我刚好就在444寝室，我好奇地打开了收音机。”我是什么佛“（这是倒放后的一句话，原话是：倒放的是狗）什么嘛，只是一段很正常的录音，于是我就去睡觉了。（我并没有意识到这是一句倒放的语音）","truth":"学校住宿的同学们都知道三条规则不能触犯：1. .23:00之后千万不要离开寝室（因为23：00寝室封寝了）2. 不要去厕所的第4隔间（这是最后一个隔间，用来存放打扫用品）3. 不要听444寝室的录音机我刚好就在444寝室，我好奇地打开了收音机。”我是什么佛“（这是倒放后的一句话，原话是：倒放的是狗）什么嘛，只是一段很正常的录音，于是我就去睡觉了。（我并没有意识到这是一句倒放的语音）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_61b54a070bab","srcNo":641,"title":"这天早晨，妮可醒来闻到很浓的烟味","dispTitle":"这天早晨，妮可醒来闻到很浓的烟味","surface":"这天早晨，妮可醒来闻到很浓的烟味，像是烧焦起火的味道，她深知自己陷入危险之中，但她却从没试图离开。\n\n 妮可不残疾，她可以正常行走。\n\n 她只是坐了起来，叹了一口气。\n\n 你猜猜这是怎么一回事呢？","truth":"妮可正在坐牢，她知道自己没办法逃离，只能等待狱警给开门。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_623becf85bca","srcNo":207,"title":"延迟死亡","dispTitle":"延迟死亡","surface":"海伦从未想到，她乘坐飞机旅行的决定会挽救她的生命。","truth":"几天前，海伦接受了手术。在登机前，她必须通过金属探测器，尽管她已经摘掉了身上所有的金属物品，但金属探测器一直响个不停。经过X光检查后，发现医生在她体内留了一把手术刀。如果不是海伦及时发现，她必死无疑。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6260d0fd43a4","srcNo":454,"title":"死","dispTitle":"死","surface":"一个女人喂了一个男人一种食物，导致两人在很久后死去了。请问发生了什么？","truth":"女人时夏娃，男人是亚当，食物是苹果。他们吃了苹果，变成了凡人，最终像凡人一样死亡了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["脑洞"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_62b5c21a25a0","srcNo":6,"title":"不会响的闹钟","dispTitle":"不会响的闹钟","surface":"他每天都被闹钟叫醒。某天闹钟没有响，他却知道自己安全了。","truth":"闹钟声其实来自隔壁固定时间的机器运转声，不是他的闹钟。那台机器一直被用来掩盖某种异常声音。机器停止后，危险源也被移除，所以他知道自己安全了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_630d102b5443","srcNo":64,"title":"","dispTitle":"无题 · KONpiGG #64","surface":"我在床上躺着看直播，刷到了一个漆黑的直播间，直播间里越来越亮，我看到了天花板，然后我死了。请推理我为什么死了","truth":"这个其实是一个杀人直播，而这次要杀的人就是我（我并不知情只是恰好刷到这个直播），一开始在屋子外面所以暗的，后来进屋了，亮了。进来把我刀了","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_633dfaae0191","srcNo":461,"title":"头等大事","dispTitle":"头等大事","surface":"从小，我就被教育，除非经过明确同意，否则不能展示自己的天性。\n……\n我是一名教官，今天带着一位异常安静的学生。当他指着前方，用一种古怪的强调语气问我\"这个是什么意思\"时，我随口解释了。眨眼间，面前的景象让我瞬间失去了对膀胱的控制。\n提示：避免用\"我\"作为主语提问","truth":"一万年前，人类与鬼族签订了《共生契约》：鬼族可融入人类社会，但必须隐藏真身，除非获得人类许可。人类则从历史中抹去这段记忆，避免恐慌。我是北城驾校教练。这天带的学生很特别——寡言少语，但开车技术极好，只是对交通标志记忆模糊。路过十字路口时，他指着圆形标志，用古老腔调问道：\"教练，那个标志是什么意思？\" 我随口答道：\"允许掉头。\" 话音刚落，车内温度骤降。学生转头露出解脱的微笑：\"三百年了…终于有人类给了我明确许可…\" 他的头颅缓缓分离，飘到半空中并开始变形，显露出鬼族真容。我这才明白，我的\"允许掉头\"被他理解为对展示真身的许可——他属于能让头颅离体的\"颅游者\"的鬼族。当他完成变形后，头颅重新回到肩膀上，恢复人形：\"谢谢，教练。三百年没释放过了，感觉真好。别担心，契约仍有效，我不会伤害你。\" 我瘫在座位上，看着他熟练地完成了一个完美的掉头动作，我觉得他应该是我最后一个学生了","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","搞笑"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_635d3bbeb251","srcNo":1196,"title":"Jed 1.10","dispTitle":"Jed 1.10","surface":"He was killed by breakfast.","truth":"A man is camping in the mountains. He makes breakfast, then puts pepper on his food (eggs, perhaps). The pepper makes him sneeze loudly, which starts an avalanche, which kills him. 1.10a. A man lay dead in a field. Next to him was a gun. One shot had been fired and because of that shot the man had died. Yet the man was not shot; in fact, there was no wound or mark on the body. (BGT) 1.10a answer: He fired the gun and caused an avalanche.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_63cb507c431d","srcNo":687,"title":"漆黑直播间","dispTitle":"漆黑直播间","surface":"我躺床上看直播，刷到一个漆黑直播间，画面越来越亮，我看见天花板，然后我死了。","truth":"我观看的这个直播间正在直播杀人，巧的是这一次要杀的人就是我。我关着灯躺在床上看直播，所以直播间里漆黑一片。主播进来后打开了灯，直播间逐渐变亮，而我也能看见天花板了。看清我位置的主播把我给杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","犯罪","都市"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_63dc9766e87f","srcNo":1250,"title":"没有烟味的外套","dispTitle":"没有烟味的外套","surface":"妻子闻到丈夫回家的外套上竟然没有一点烟味，马上报警。为什么？","truth":"丈夫是夜间烧烤摊老板，每天收摊回家的外套都会带着很重的炭火烟味。今晚完全没有烟味，说明他根本没去摊位，很可能在途中出了事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6406f1929bf2","srcNo":1022,"title":"最后的求救","dispTitle":"最后的求救","surface":"海难幸存者在荒岛上用石头摆出了巨型‘SOS’。当一架飞机飞过时，他疯狂地把‘SOS’改成了‘HELLO’，然后平静地等待死亡。","truth":"幸存者发现飞来的飞机并非救援队，而是敌方的侦炸机，或者是他意识到岛上其实有更恐怖的存在（如食人族），求救信号会暴露位置。改成‘HELLO’是一种绝望的嘲讽或伪装，他已经放弃了生存希望，不想死得更痛苦。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_641c88779ab8","srcNo":1365,"title":"","dispTitle":"无题 · boop-yyt #1365","surface":"A man tries to buy poison to kill his wife. The pharmacist figures out what he's up to and finds a way to ensure that he can't kill his wife. (CB, from Flitterwochen in der Hoelle) How could this be?","truth":"The pharmacist gives the man a cup of coffee to drink while he's waiting. After the man has drunk the coffee, the pharmacist says, \"There was poison in that coffee. I'll give you the antidote if you write a signed statement that you were planning to kill your wife. I'll keep the confession; if anything happens to your wife, I'll give it to the police.\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_641dec1f9ed2","srcNo":289,"title":"061 · 书作者","dispTitle":"061 · 书作者","surface":"大博去图书馆，拿了一本书然后夹进去一百元钱，过了后天他翻开书发现钱还在。大博哭了。","truth":"大博是这本书的作者，他放进去一百元是想看看这本书有没有人来借阅。结果钱还在，证明没人来看，他非常伤心。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6447eb8a4b30","srcNo":1187,"title":"我六岁那年，外公去世","dispTitle":"我六岁那年，外公去世","surface":"我六岁那年，外公去世，我和亲人一起去祭奠，和姐姐玩捉迷藏，然后我对母亲说了句话把她吓昏了过去，我说了啥？","truth":"我去参加外公的葬礼，同行的还有比我大两岁的姐姐，我和她完捉迷藏我没有找到她没想到她躲在了纸做的房子里，当纸房子被点燃，我看见姐姐在跳舞，我对妈说，妈姐姐在那房子里面跳舞，因为姐姐被烧死了，我一直记得这个事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn(wayback)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_644d8071165d","srcNo":55,"title":"拔萝卜","dispTitle":"拔萝卜","surface":"拔萝卜，拔萝卜、嘿呦嘿呦拔萝卜、小朋友，快快来、快来帮我来拔萝卜、红萝卜，白萝卜、全部都是坏萝卜...","truth":"这是一个精神病院，小朋友都是里边的病人。有一个小偷在偷了东西之后想通过墙角的洞逃走，结果正好卡在洞里，被犯病的病人当作萝卜拔。红萝卜是流血胳膊，白萝卜是骨头。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6452042d8133","srcNo":1041,"title":"游泳池的挑战","dispTitle":"游泳池的挑战","surface":"男子在游泳池比赛潜水，他憋气很久都没上来，大家都在岸上欢呼，直到发现不对劲。","truth":"男子的泳裤勾到了游泳池底部的排水口（或循环泵），他被吸住了上不来，大家以为他在破记录，实际上他溺水了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_64cc4c2a51b6","srcNo":91,"title":"","dispTitle":"无题 · KONpiGG #91","surface":"他们看起来很登对，他也很幸福，但是...绿让红变成了白....掉落的首饰，威胁的证明，模糊的血肉成为了他的执念。","truth":"我的学长有个女朋友，两个人看起来很登对，学长也很幸福。直到后来，学长买了戒指，准备求婚。（红事）然而就在那一天，学长被一名男人打了，戒指掉落在地，才知道她是有夫之妇，丈夫很凶，会家暴她，学长根本不知道她有丈夫见过她的同事，父母，都很支持两人。他们都知道她辛苦，知道她丈夫混账，自己不帮忙，我学长出现了，就好像给她找到救命稻草了，全瞒着学长。因为那个女人怀孕了，她老公是长途车司机，时间对不上所以立刻知道被戴绿帽了（绿色）。那个男人后来拿这事勒索学长，还拿女人堕胎后的小肉团当证明，之后学长本想断了，他这样不停找上门到工作的地方，到家里，最后学长在某次躲藏过程中被撞死化成了鬼（白事）。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_651e354145af","srcNo":186,"title":"","dispTitle":"无题 · KONpiGG #186","surface":"丈夫去外地出差，公文包却落在了家里，妻子接到丈夫的求助电话后，坐下来，打开了电视。","truth":"妻子打开了《午夜凶铃》，在贞子爬出来的之后跟贞子商量\"你在电视里爬来爬去的，能不能帮我送个包？\"贞子：\"你确定？好吧，我就帮你送这一次哦\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_65fe14d66cba","srcNo":1202,"title":"Jed 1.20","dispTitle":"Jed 1.20","surface":"A man in uniform stands on the beach of a tropical island. He takes out a cigarette, lights it, and begins smoking. He takes out a letter and begins reading it. The cigarette burns down between his fingers, but he doesn't throw it away. He cries.","truth":"He is a guard/attendant in a leper colony. The letter (to him) tells him that he has contracted the disease. The key is the cigarette burning down between his fingers -- leprosy is fairly unique in killing off sensory nerves without destroying motor ability.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_667e4d272252","srcNo":1320,"title":"","dispTitle":"无题 · boop-yyt #1320","surface":"A man pushes a car up to a hotel and tells the owner he's bankrupt. What happened?","truth":"It's a game of Monopoly.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_668d61fd84da","srcNo":96,"title":"","dispTitle":"无题 · KONpiGG #96","surface":"乡间小路上，五名男子一同前行。突然开始下雨，五人中的四人加快了步伐，然而第五人一点也不着急。最终，五人同时到达目的地。加快脚步的四人被淋成了落汤鸡，而第五个人身上却一点也没湿。","truth":"四个人在抬棺材。第五个人是躺在棺材里的死人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_672b157d1754","srcNo":330,"title":"猜名字","dispTitle":"猜名字","surface":"家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛并喊他的名字，便可散其怨。午夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却不可置信地看着她。我知道，我们死定了。","truth":"我的情人其实是我妻子的双胞胎妹妹，她们俩长得几乎一模一样。由于情人怀了孩子，我们两个便计划杀死妻子。可妻子听到了我和情人要谋害她的计划，她把情人迷晕后伪装成自己，所以我杀的","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_677cfc01fbf6","srcNo":919,"title":"曼德拉效应","dispTitle":"曼德拉效应","surface":"你们埋过时间胶囊吗？我小时候埋过，今天打算挖出来看看。由于是陨铁的盒子，因此保存得很好。里面有一封信。”小鱼生病了，小鸟生病了，爸妈生病了，我也生病了，我不想死，可所有人都死了“ 这不可能是我写的！！！这是我写的吗？？哦对，这就是我写的！！","truth":"你们知道”曼德拉效应“吗？某个国家核污水排海，辐射导致了地球上的生物大灭绝。小时候的我经历了这场灾难，也在世界末日中死去了。地球开启了自我修复，重塑了整个世界，复活了所有死去的生物。它抹除了所有关于大灭绝产生的痕迹，并修改了生物关于末日的记忆。地球无法控制地球外的元素，一定会因此产生”漏洞“，例如太空上的陨石碎片、地球外的卫星空间站等。地球为了填补漏洞，它在修改生物记忆时加了自我修复”程序“。因此一旦出现”漏洞“，生物会触发”程序“修改记忆，使认知合理化。地球自我修复的一年后：几个宇航员从太空返航，她们找到了解决辐射的办法。”什么辐射？？“ ”你们不是去火星采样去了吗？“说话的是本已经在辐射中死去的局长。”局长你不是死了……“ ”我是去火星？我不是……“ 宇航员们面面相觑，有些迷茫。局长笑了，你们可能是在太空航行久了，航天综合症了吧。局长想到了一个词：”哦！又或者是曼德拉效应“ 宇航员好像想起来了，哦对，我们是采样去了。”好奇怪，我们几个都记错了，哈哈哈“ 地球自我修复的二十年后：我突然想起来小时候好像埋了一颗时光蛋呢！怎么写的这些东西？（小鱼小鸟死了，大家全死了）我怎么记得我写的是我想当科学家啊？（地球修改后的记忆）这绝对不是我写的！！我跑去问妈妈——当时是她陪我埋的时光蛋。”这是怎么回事！好吓人，是不是哪里搞错了？“果然！妈妈也觉得不对！这是我写的吗？爸爸听到笑了：”这内容我记得，有一次看恐怖电影，你写了这些东西想吓我！你是不是把该埋的东西弄混了？“难道我小时候糊里糊涂的，可能把两封信弄混了？一定是这样！妈妈笑了：”咱俩这是曼德拉效应了吧？哈哈“哦对！这就是我写的！！我也笑了：”好像是曼德拉效应了，哈哈“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_683130196767","srcNo":266,"title":"035 · 黑猫","dispTitle":"035 · 黑猫","surface":"我杀了人，当警察带走我的时候，我看到了门口的黑猫，它一直在盯着我，这一刻我知道我错了。","truth":"我经常在楼下看到那只黑猫，因为出差而只能投喂它。出差回来发现阳台上有很多死老鼠，我下意识联想到经常和我闹矛盾的邻居，冲进他家杀了他。被警察带走时，我看到那只黑猫，嘴里还叼着一只老鼠——原来是猫在捕鼠，而我杀错了人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_689043d7869e","srcNo":1345,"title":"","dispTitle":"无题 · boop-yyt #1345","surface":"Tom and Joe went to a movie. There were many other people there. During a quiet scene, Tom drew a gun. Joe screamed, Don't shoot! but Tom shot him. Tom then left. Many people saw Tom leave and they restrained him. The police arrived and quickly released Tom. Why?","truth":"Tom and Joe were the stars of the movie. Tom shot Joe in a sequence in the movie. When Tom left he was mobbed by fans seeking his autograph.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_692bef868539","srcNo":1321,"title":"","dispTitle":"无题 · boop-yyt #1321","surface":"There are 51 instead of 53. What happened?","truth":"Someone saw the guy conceal a card, and proved the deck was defective by turning it up and pointing out the missing ace.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6943eeec375b","srcNo":128,"title":"","dispTitle":"无题 · KONpiGG #128","surface":"年轻的夫妇在看歌剧时接到了保姆打来的说话含糊不清的电话。回家后，他们再也不想过感恩节了。请问，发生了什么？","truth":"这对夫妇请了个保姆看家，要她在感恩节这天把火鸡准备好，顺便照看独自留在家中的小孩子，他们自己出门看歌剧了。但是保姆是个瘾君子，她在家中毒瘾犯了，吸了毒，之后在毒品的幻觉中把小孩误认为火鸡，塞进了烤箱里。待她稍微清醒一点时，她发现火鸡依旧在桌上，但烤箱却在运作，于是打电话给夫妇，说家里的火鸡多了一头。夫妇们从剧院赶回家，看到了正瘫坐在电话前双眼直勾勾地盯着天花板的保姆，而厨房的烤箱里，他们发现了一只形状诡异，已经烤的焦黑的东西，看起来一点都不像火鸡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_696faa38b48d","srcNo":92,"title":"","dispTitle":"无题 · KONpiGG #92","surface":"一位男孩儿到河边散步，跟一位渔夫聊天，渔夫跟他说了一句话，男孩儿就自杀了。","truth":"一对情侣在河边玩儿的时候，女生不小心落水了，男生跳下海里救她，因为水流很急，男生只抓到一把水草，最后没有把女孩儿救上来。几年之后，他又来到这条河边，看见一位渔夫，聊天的时候，渔夫告诉他这条河里从来没有过水草。男孩儿就知道他当时抓住的其实是女孩子的头发，然后就自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_697d6e67511a","srcNo":1122,"title":"唱戏的女人","dispTitle":"唱戏的女人","surface":"最近几天邻居们都说，夜里总能听到有女子唱戏曲的声音，声调还格外凌惨。今晚我回\n家时也听到了这声音，吓得立刻跑回了家。没过一会儿，楼上传来凄厉的惨叫声，我也终于弄\n明白那戏曲声到底是什么了。","truth":"小区的电梯正在维修，一名女子因低头玩手机没注意* 从高处摔死在停在一楼的电梯棚\n上。电梯修好后，工人并不知情，照常运行电梯。女子的来夫发现妻子失踪，白天外出寻找，\n晚上邻居们听到的恐怖戏曲声，其实是丈夫给妻子打电话时，手机铃声从电梯棚处传出来的。\n这天丈夫在电梯里拨通了妻子的电话，终和手发现了妻子的遗体，随之发出了惨叫声。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_69d3afcb8d68","srcNo":1088,"title":"","dispTitle":"无题 · zhuqingxu #1088","surface":"雪停后的清晨，旷野中央有一具尸体，雪地上只有一串脚印从远处延伸到尸体旁，没有任何返回或第二人的痕迹。之后直到发现前无人再踏入这片雪地。凶手如何离开？","truth":"凶手穿着明显大于自己脚的鞋（或套在被害人的鞋外），作案后背朝尸体、沿着来时的那串脚印一步步倒退走出，使离开的落点与进入的脚印重合，看起来「只有来的路」。\n\n---\n\n 4. 监控与另一张脸\n\n| 字段 | 内容 |\n|------|------|\n| id | cctvandtwin |\n| 难度 | easy |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6a106ff803ef","srcNo":200,"title":"","dispTitle":"无题 · KONpiGG #200","surface":"男人给自己心爱的女人打电话，女人一直不接，等回到家发现女人死了。","truth":"男人是个职场能人，有人想窃取男人的新的竞标文件便来到了男人的住处。女人看到陌生人来家里，害怕的躲了起来，但是手机没关静音，男人打电话暴露了女人的位置。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6a2910380309","srcNo":1370,"title":"","dispTitle":"无题 · boop-yyt #1370","surface":"The music stopped and the man died. How could this be?","truth":"Same as #1.75a, but the blind swimmer kept a portable transistor radio on the beach instead of a bell. When the batteries gave out, he got lost and drowned. (See also #1.31a, #1.59, and #1.70a.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6aaa8f08bcea","srcNo":1068,"title":"传染病房","dispTitle":"传染病房","surface":"一名医生在给高度传染病患者做手术时，手套不小心破了。他看了一眼病人，直接用手术刀割断了自己的喉咙。","truth":"这并不是因为他害怕得病，而是因为这个病人正是他的杀子仇人，他原本打算在手术中“意外”杀死对方。手套破裂意味着他可能会死，他觉得这种一命抵一命的结局太便宜对方了，极度的愤怒和对自己“计划失败”的厌恶让他瞬间失控自残。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6bf8c1505a1e","srcNo":1359,"title":"","dispTitle":"无题 · boop-yyt #1359","surface":"A man kills his wife, then goes inside his house and kills himself. (DH original, from \"Nightmare in Yellow,\" by Fredric Brown) How could this be?","truth":"It's the man's fiftieth birthday, and in celebration of this he plans to kill his wife, then take the money he's embezzled and move on to a new life in another state. His wife takes him out to dinner; afterward, on their front step, he kills her. He opens the door, dragging her body in with him, and all the lights suddenly turn on and a group of his friends shout \"Surprise!\" He kills himself. (Note that the whole first part, including the motive, isn't really necessary; it was just part of the original story.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6c3407286474","srcNo":609,"title":"日访三十国","dispTitle":"日访三十国","surface":"一个没有护照的普通美国公民，一天之内访问了30多个国家。在每个国家里他都受到热情招待，并且离开时也完全自由。","truth":"他是一个送信人，负责将包裹送到各个大使馆。大使馆的领地为使馆国所有。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常","职场"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6c4c07d9075a","srcNo":1307,"title":"","dispTitle":"无题 · boop-yyt #1307","surface":"A rope breaks. A bell rings. A man dies. What happened?","truth":"A blind man enjoys walking near a cliff, and uses the sound of a buoy to gauge his distance from the edge. One day the buoy's anchor rope breaks, allowing the buoy to drift away from the shore, and the man walks over the edge of the cliff.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6d7d1fe43ab0","srcNo":83,"title":"","dispTitle":"无题 · KONpiGG #83","surface":"一个女人按下了一个按钮，导致另一个人死亡了","truth":"一个男的表演吞剑，但是剑坏了。所以现场的一位女士拿出自己随身携带的雨伞与其互动，当这个男人吞下整根雨伞，请求女士帮助他拿出来，女人不小心按到了按钮，导致雨伞在男人的身体里撑开，导致其死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6db4d37cfcbb","srcNo":1148,"title":"给三兄弟的一封信","dispTitle":"给三兄弟的一封信","surface":"HO+SiOz+FesOs+CO:一0 人 〈x2+y2-1 ) 3一","truth":"化学公式“HzO+SiOz+FesOs+CO:一押的含义是“即使地球毁灭”，数学公式\n的含义是“我也会一直爱你”。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6ddef2ee1c6d","srcNo":1304,"title":"","dispTitle":"无题 · boop-yyt #1304","surface":"A man is found hanging in a locked room. What happened?","truth":"He stood on a block of dry ice to hang himself.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6de0d702d28a","srcNo":490,"title":"吓我一跳","dispTitle":"吓我一跳","surface":"一个人走进餐厅，点了一杯白开水。服务员把水端上来后，掏出一把手枪对着那人猛地指了一下。那人连声道谢，付完钱就离开了。为什么？","truth":"小蔡打嗝难忍，想点一杯冰水止嗝，于是服务员掏出了一把假枪吓他，他的打嗝成功被吓没了，知道真相的小蔡感激不尽。\n混入了什么奇怪的东西啊喂！)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["本格"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6e0606090262","srcNo":179,"title":"","dispTitle":"无题 · KONpiGG #179","surface":"门开了，人们陆陆续续的走进，却又惊慌失措的跑出。","truth":"其实是电梯门，电梯核载11人，但是陆续进来9个人就发出了警报，说明电梯内藏着两具已经被杀害的尸体，意识到这一点的人们又赶紧跑出了电梯。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6e35467a2ea9","srcNo":1211,"title":"Jed 1.46","dispTitle":"Jed 1.46","surface":"A man dies in his own home.","truth":"His home is a houseboat and he has run out of water while on an extended cruise. 1.46a. Variant wording: A man dies of thirst in his own home. This version goes more quickly because it gives more information; but it may be less likely to annoy people who think the original statement is too vague. 1.46a answer: Same.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_6f2ff35c1f68","srcNo":1044,"title":"冰块杀人案","dispTitle":"冰块杀人案","surface":"一个男人死在密闭的房间里，死因是吊死。但他脚下没有任何垫脚物，只有一滩水。","truth":"他站在一大块冰块上，把脖子套进绳索，然后等待冰块融化。冰化成了水，他就被吊死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6f860967a6c4","srcNo":947,"title":"别过来","dispTitle":"别过来","surface":"对面的8楼不对劲！窗户上有一列血字：别过来！我透过窗发现一个人型轮廓站在房间内诡异的抽动。我吓坏了，急忙拉上窗帘。第二天早上再观察时，我发现一个男人吊在麻绳上。","truth":"对面的8楼不对劲！窗户上有一列血字：别过来！我透过窗发现一个人型轮廓站在房间内诡异的抽动。我吓坏了，急忙拉上窗帘。第二天早上再观察时，我发现一个男人吊在麻绳上。他长得和我十分相似！但却苍老了许多。我报了警，之后再观察时，我发现尸体腐烂了。我去到了对面8楼，发现门虚掩着。第一天，进去以后，我发现房间内没有任何人，尸体也消失了。透过窗，我发现外面变成了黑天！这离奇的一幕让我有些脚软，当我想离开时，却发现门消失了。我拼命呼喊，用手机求救却没有信号，窗户也打不开。我被困在了这里！！！第三天，通过这几天的观察，我发现外面的世界好像静止了，十分诡异！我尝试了各种方法，但都无法逃离，好似有一个巨大的能量罩困住了我。好在冰箱里的食物每天都会刷新，因此我并不会饿死。我来之前报了警，一定能获救的！！第七天，我亲眼见证了窗外的一只飞鸟用了几个小时才飞走。原来外面的世界并不是静止的，而是速度缓慢！！！那我怎么才能获救！一个月，外面的世界还没有恢复，天永远是黑的，长时间见不到阳光让我心中充满了绝望。我的精神状态恐怕不足以让我支撑下去了，我在房间内翻到了麻绳。我想……两个月，我自己制作了扑克牌，和飞行棋，用来缓解我的精神状态。我不想死，我想坚持下去，一定有办法的！半年，长时间的独处，使我精神出了问题，我开始意识模糊，下意识的停止思考。不能一直这么折磨自己了。我制作了吊绳，想要解脱。再见了，这个世界，我没想过我会死在这种情况下。正当我准备结束一切时，我发现对面楼，我的房间灯亮了！！！是谁！！？我重燃了生的希望！一年，太慢了，我等了半年，终于看到了我的房间出现的那个人是谁……是我！！！他用了一周的时间拖鞋，挂外套，随后去了浴室。为什么又出现一个我在那里！？二年，这一年，我的日子有了盼头，我开始观察对面的我。他用了半年时间，终于从浴室走了出来。接下来的半年，他开始用餐。他究竟是谁！或许只有找到答案，我才有办法逃出去。三年，餐后，他消失在我的视野六个月……这半年，我绝望的想要结束自己。但又因为有了一丝希望，我坚持了下来。我像一个孤独的守望者，每天都坐在窗边。终于在某天，他回到了我的卧室。他缓步向着窗户走来，似乎要看向我这里。等一下……这一幕好像发生过。对面的我，这几年的一切，好像是我过去的经历！他是那个看向8楼时的我！！！我知道怎么才能救我自己了！那就是别让他过来！让这一切从未发生，我也就不会出现在这里！这几个小时，他极其缓慢的挪向窗台，双手扒着窗户向外望，在他差不多能看到我这里的时候，我在窗户上用血写了三个字“别过来”，我突然意识到，当时的我也看到过这三个字，这是无用功的。于是，我决定让他看清我，他只要看到我的脸，就会明白一切的！我死死的站在窗台盯着他，但我这面速度对于他来讲太快了，因此我像雕塑一样一动不动的站在那里，希望尽可能让他看清我的模样。一个小时，我的身体酸痛，但可能对于他来讲还不到一秒，还不够！两个小时，我有些抖动，但还在坚持。四个小时，我快坚持不住了，眼睛有些发黑，似乎随时可能会晕倒。六个小时，他的表情发生了变化，他在慢慢瞪大双眼，有些恐惧。他注意到我了！我成功了？我期待他看到我之后会有什么反应，我又等了一个小时，他的手逐渐伸向窗帘。不对……我想起来自己曾经似乎也看到过一个模糊的人型轮廓。我的速度太快了，我并不是真的雕塑，所以他只能看到一个模糊的轮廓。我开始回想，接下来我干什么了？我……我拉上了窗帘。……四年，我眼睁睁的看着他用两个小时逐渐拉上窗帘。我绝望的呼喊，求救。可我心里清楚，没有人能来救我了。我无法改变历史，窗帘拉上之后，他就要睡觉了。我不知道我能不能等到他的“第二天”。五年，……六年，……七年，……第八年，天蒙蒙亮。我逐渐开始忘记自己为什么在这里，也忘了我在期待什么。外面的世界对于我来讲像一本读过很久的书，我记得它的大致轮廓，但不再能记清里面的内容。我的嘴巴很久没有张开了，尝试了一下却只能发出一些无意义的音节。我不再麻木思考是不是该结束这一切了。而是想着结束后，房间还会继续存在吗？我掏出了那根准备已久的麻绳，结束在了黎明。唰，弥留之际，我仿佛听到了窗帘拉开的声音。\n**Q&A** Q：我进入房间时，为什么没有看到我的尸体？A：我们可以把你比作进行时，而你透过窗看到的挂在麻绳后的自己则是未来时，当进行时的你去到8楼房间时，你只可能去到进行时的房间，并不是穿越到八年后，因此房间内并不存在未来时你的尸体。\n主持人手册\n1. 本场玩家的第一个问题主持人不回答。\n2. 由于时间流速不同，主持人只可以回答上一个问题的答案。\n3. 在玩家意识到时间流速不同时，主持人提醒：\nA.时间流速比例为外界1天=房间10年\nB.主持人公布任务\n①还原故事\n②主持人为什么只回答上一个问题","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6fabddc7ad32","srcNo":292,"title":"064 · 发现凶手","dispTitle":"064 · 发现凶手","surface":"我发现妹妹在夜里翻墙出去和男孩子幽会，但最终我没有告诉父母。","truth":"我和妹妹是双胞胎，她喜欢一个男孩，那个男孩因为认不清我们俩，总是约错人。有一天我发现其实那个男孩约的一直都是我，而妹妹根本不知道这件事。我不告诉父母，是因为我也开始喜欢上他了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_6ff3742a28e2","srcNo":901,"title":"白雪公主规则怪谈","dispTitle":"白雪公主规则怪谈","surface":"1．皇后最多只能活3年；2. 猎人放过了白雪；3. 猎人绝对忠诚于皇后；4. 猎人非常感激皇后救了自己；5. 七个小矮人救了陷阱中的白雪；6. 魔镜说最美的女人是白雪，皇后非常生气；7. 白雪美丽的外表让王子非常迷恋；8. 巫婆给予了白雪一颗苹果；9. 白雪在巫婆面前死掉了；10. 复活后的白雪和王子幸福地生活在了一起。（注：2、4、6、8为红字规则，即反话）","truth":"这是一篇黑童话，红字规则为反话，真实规则如下：2. 猎人抓住了白雪；4. 猎人非常怨恨皇后杀了自己（皇后现在的皮是猎人妻子的）；6. 魔镜说最丑的女人是白雪，皇后非常高兴；8. 巫婆索取了白雪一颗苹果；10. 死掉的白雪和王子悲惨地生活在了一起。故事真相：皇后每隔三年必须换一次皮才能保持最美，否则上一张皮会腐烂。这一年她盯上了白雪的皮，猎人因妻子的皮被皇后夺走，只能绝对忠诚于她，奉命抓住白雪。皇后如愿得到白雪的皮后，为掩盖秘密杀死猎人，将无皮的白雪和猎人尸体一起扔进陷阱。白雪将猎人尸体分成七段，吃掉肉充饥，用骨头做成七级骨梯爬出陷阱，披上皇后扔掉的腐烂皮，伪装成巫婆报仇——她杀死了披着白雪皮的皇后，挖出其心脏并吃掉（因吃了猎人的肉产生异食癖）。邻国的王子有恋尸癖，看到死去的皇后（披着白雪皮）十分美丽，便带走了皇后的尸体，与尸体”悲惨地生活在一起“。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70698b7f9eba","srcNo":318,"title":"090 · 红点","dispTitle":"090 · 红点","surface":"深夜，他发现对面楼的窗口有个红点一直在盯着他，他关上了窗帘，安心睡去。","truth":"那个红点是狙击枪上的激光瞄准器。他关上窗帘，事实上救了自己的命——子弹打进了窗帘，没有伤到他。第二天，警察在对面楼的楼道里发现了一名职业杀手和一具尸体（杀手的目标提前将计就计，反杀了他）。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70707f32e1ca","srcNo":206,"title":"对赌","dispTitle":"对赌","surface":"两个死人，现场只有一把枪，一颗子弹，一副牌。发生了什么？","truth":"两个人在潜艇里，潜艇在深水因故障进水，两个人赌牌，赢的人才可以用枪自杀，体面死去。输的人只能在潜艇中痛苦地死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70b990289c70","srcNo":217,"title":"死亡直播","dispTitle":"死亡直播","surface":"我在床上躺着看直播，刷到了一个漆黑的直播间，直播间里越来越亮，我看到了天花板，然后我死了。","truth":"我观看的这个直播间正在直播杀人，巧的是这一次要杀的人就是我。我关着灯躺在床上看直播，所以直播间里漆黑一片。主播进来后打开了灯，直播间逐渐变亮，而我也能看见天花板了。看清我位置的主播把我给杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70e667af0b9b","srcNo":1090,"title":"","dispTitle":"无题 · zhuqingxu #1090","surface":"夜行列车上，一名乘客在驶入隧道、车厢灯灭、剧烈颠簸的几十秒内被勒死。同包厢另外两人发誓谁也没离开座位，灯再亮时三人的位置与进隧道前一致，包厢门也无人进出。这可能吗？凶手怎么下的手？","truth":"当时另一列车在相邻轨道并行、几乎同速通过隧道，两列车对应包厢的车窗一度相距很近。凶手从邻车经窗外伸手完成勒杀后收回。另两人所说「本包厢内无人离席」为真，凶手并不属于本包厢的「离座者」。\n\n---\n\n 6. 第一百只相同的熊\n\n| 字段 | 内容 |\n|------|------|\n| id | parademascotsameness |\n| 难度 | medium |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70ef60c67d01","srcNo":863,"title":"柜中的孩子","dispTitle":"柜中的孩子","surface":"深夜，我家的衣柜传来了窸窸窣窣的声音，我壮着胆子打开柜门，里面居然有一个孩子，他看着我嘿嘿的笑着：“妈妈，你找到我啦～”我吓坏了，哪来的孩子。我让他立刻离开我的房子，他吓哭了，一直叫我妈妈。仔细看他和我前夫的确有几分相似。但我自从几年前流产后就没有了生育能力，也离了婚。他告诉我他还有一个双胞胎弟弟，甚至叫出了我和前夫的名字，他带着哭腔问我：“你真不记得我了吗？”","truth":"八年前，地球轨迹偏移，与平行世界发生交错，一个孕妇腹中的胎儿偏移到平行世界同位体的腹中——我误认为自己流产，家庭破碎；另一位孕妇误认为怀了双胞胎，家庭美满。八年后，世界轨迹校正，试图重新平行。弟弟的日记记录着：三年前和哥哥玩捉迷藏，哥哥藏好后再也没出现，所有人都不记得哥哥，全家福上也没有他的痕迹，大家都觉得我疯了，可我对哥哥的印象越来越模糊，甚至怀疑他只是我的幻想。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_70fe687de92d","srcNo":88,"title":"","dispTitle":"无题 · KONpiGG #88","surface":"晚饭时，玛丽的爸爸抱怨妈妈做的汤太甜了，当晚，妈妈就死了，几天后爸爸也死了。","truth":"玛丽是个极端主义者，无法容忍家庭中有任何人对家庭不忠。玛丽最近发现父母的关系没有从前好了，并且还在厨房里发现了毒药，玛丽断定一定是爸爸妈妈之中有一人想毒害自己的伴侣。为了知道谁对这个家不忠，玛丽把毒药换成了糖，结果当晚喝到甜汤的是爸爸，于是玛丽便下毒药将妈妈毒死了。几天后玛丽才知道，原来是爸爸想要杀了妈妈，而他已经知道毒药被玛丽发现，于是顺水推舟，让玛丽亲手害死妈妈。又杀了爸爸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_713c1ec8c207","srcNo":93,"title":"","dispTitle":"无题 · KONpiGG #93","surface":"小强养了一只忠诚的狗，有一天他牵着狗上街，结果小强死了。","truth":"小强有心脏病，那天上街突然病发倒地，忠心的狗狗一直防止陌生人靠近小强，最后导致小强没人帮助而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_715c8134e625","srcNo":357,"title":"广播","dispTitle":"广播","surface":"我听到广播里的新闻后，先是庆幸而后痛哭起来。","truth":"我被一个连环杀人犯绑架了，他把我和几个女孩关在了一起，每隔一天他就会带出去一个女孩杀掉再抛尸...那天另一个女孩被带走后，就只剩我一个人了，我心想我的死期就要来了，但这次他却再也没有回来。之后我在广播里听到他被警察击毙的消息，我很庆幸自己活了下","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","犯罪"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_718288baaf34","srcNo":1036,"title":"多出的那一刻","dispTitle":"多出的那一刻","surface":"一个人发现自己的表停了，他调好时间后继续睡觉，第二天却发现自己迟到了整整一个小时。","truth":"因为那天正好是‘夏令时’转换的日子，或者是他调表时没注意上午下午（AM/PM），导致闹钟没响。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_71e368d13be5","srcNo":1335,"title":"","dispTitle":"无题 · boop-yyt #1335","surface":"A man is doing his job when his suit tears. Fifteen minutes later, he's dead. What happened?","truth":"The man is an astronaut out on a space walk.It's a radiation suit. The suit was broken, causing him to die from radiation.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_71e675399a64","srcNo":199,"title":"","dispTitle":"无题 · KONpiGG #199","surface":"有一位老婆婆，她在借书时都一定会翻到第五十页再决定要不要借。为什麽她要这样做？","truth":"老婆婆的丈夫行动不便，但脑子还是很清楚，而且非常喜爱阅读。因此老婆婆为了无法下床的丈夫，几乎天天都到图书馆大量借书。但老婆婆自己并不看这些书，因此也不知道哪些书是曾经借过的。于是两人商量过后，决定在借过的书的第五十页的角落上留下小小的记号：三角形的涂鸦。当老婆婆帮她丈夫到图书馆借书时，首先便查看第五十页，没有三角形记号的书表示老公公还没读过，于是才会借回家。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_71ec509dae7a","srcNo":1340,"title":"","dispTitle":"无题 · boop-yyt #1340","surface":"Two naturalists were walking in the country. They were both keen to protect the environment and to conserve nature and wildlife. One said to the other, \"I was impressed by the way that you hit that bird.\" The second replied, \"Yes, it was good, but not as good as that large bird that you hit earlier.\" What were they talking about?","truth":"They were two golfers. In golf parlance, one had hit a \"birdie (one under par) and the other an eagle (two under par).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_71f829d3da3b","srcNo":383,"title":"重映","dispTitle":"重映","surface":"我生病了。每天睡前妈妈都会喂我吃药。可吃完药后我总会做噩梦。\n第一天，我梦见我被急驰而来的卡车撞死了。\n第二天，我被包裹在睡袋里移动，什么都看不见。\n第三天，妈妈和我说她被公司辞退了，晚上我梦见妈妈疯狂的割下了我的头。\n第四天，原来那不是梦，吃完药后，我知道我活不过今晚了。","truth":"我失明之后，妈妈给我尝试了不同风格的药想治我的眼疾，可都没有疗效。于是妈妈搞来一个偏方——用人的眼球做药引子。由于妈妈在火葬场工作所以很容易弄到人的眼球。可我每次服用后，都会看到这个人临死前的画面。由于我是在睡觉前服用，我一直以为那是梦。第一天晚上我看到这个人是被车撞死的。第二天晚上我看到这个人被蟒蛇吞进腹中。第三天，由于妈妈偷尸体眼球的事被发现便丢了工作。妈妈失去了眼球的来源，于是她只好通过杀人来获得眼球。于是这天晚上我梦到这个人被妈妈割下头。第四天，昨天被妈妈杀的那个人亲人来找我们报仇。他杀了妈妈后，伪装成妈妈喂我吃下了妈妈的眼球。我看到妈妈在镜子前卸妆，却被一个陌生人挖下了眼球——我这才意识到我之前每天晚上看到的画面都不是梦。我吃的药是人的眼球，妈妈已经死了，那喂我吃药的这个人是谁呢……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖","猎奇"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_72246a7f2fe2","srcNo":1066,"title":"最后的奢侈品","dispTitle":"最后的奢侈品","surface":"末日避难所里，富翁用一颗价值连城的钻石换了穷人的一块发霉的面包。富翁吃完面包后，笑着把钻石又抢了回来，穷人却没有反抗。","truth":"富翁知道避难所的氧气只剩下不到10分钟。这颗钻石在10分钟后将和废铁没有区别，他只是想在死前最后体验一次“饱腹感”。穷人不反抗是因为他知道大家都死定了，钻石和面包都已经失去了意义。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_72b08b0f2494","srcNo":1334,"title":"","dispTitle":"无题 · boop-yyt #1334","surface":"A man shoots himself, and dies. What happened?","truth":"The man is a heroin addict, and has contracted AIDS by using an infected needle. In despair, he shoots himself up with an overdose, thereby committing suicide.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_72d3434bc4c8","srcNo":1188,"title":"寝室每天简直吵死了","dispTitle":"寝室每天简直吵死了","surface":"寝室每天简直吵死了，\n今天多亏了食堂的叔叔阿姨，\n我终于可以安心睡觉了。","truth":"寝室每晚深夜的时候，室友们依然在大声吼叫。我无法忍受，所以在饮水机里下了毒药，今天食堂饭菜异常的咸，正合我意，看着室友大口大口的喝水，我知道我今晚能安心睡觉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn(wayback)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_72db1e4c55f6","srcNo":871,"title":"张三李四","dispTitle":"张三李四","surface":"“一定要杀死张三”这几个字某天凭空出现在了我家的天花板上，我赶紧把字擦掉，可第二天这句话又凭空出现了。我并不认识张三，但等我明白这几个字是哪来的以后，我开始寻找他了。大概过了10年，时间来到2010年，我终于找到了张三，并一刀杀死了他，他临死前不可置信看着我：“李四？！”可能是被我触碰的原因，他的尸体异常的消失了。在我临死前的一个月，我终于知道为什么一定要杀死张三了。我放下手中新世纪的第一份报纸，去做了那件早就该做过的事。","truth":"李四视角：我叫李四，是时空逆行者，时间对我而言是逆向的（如2月14日过后是2月13日）。2020年我10岁时，天花板上反复出现“一定要杀死张三”，意识到是未来的自己留给过去的提示，于是开始寻找张三。2010年（我20岁）找到张三并将其杀死，他的尸体因被我触碰而穿越回过去。2000年（我30岁），在报纸上看到自己一个月前被张三残忍杀害，才明白提示是为了报仇，于是在天花板上写下“一定要杀死张三”。张三视角：我叫张三，10岁时，一个快死的人（未来的我）告诉我“一定要杀死李四，否则会被他杀死”，随后咽气。我一直寻找李四，20岁时找到并杀死他，因此入狱10年。30岁出狱后，却看到李四杀气腾腾走来，临死前被他触碰，穿越回10岁的自己面前，用尽最后力气说：“一定要杀死李四！”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_73b6519f54ca","srcNo":867,"title":"老农","dispTitle":"老农","surface":"万历年间，乡下一老农，其女貌美，为村霸所觊，屡来相扰。未几，女竟失踪。老农揣女或遇不测，遂往衙诉之。不意至衙，殒命焉。","truth":"万历四年，老农的女儿因貌美被村霸觊觎，屡遭骚扰，后突然失踪。老农猜测女儿遭村霸玷污并杀害，于是前往县衙告状。击鼓鸣冤时，他发现鼓上竟有女儿的胎记——原来官匪勾结，女儿被残忍杀害做成了人皮鼓。老农绝望之下，一头撞死在县衙大门上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_73c238975974","srcNo":527,"title":"半根火柴","dispTitle":"半根火柴","surface":"一个人死在了沙漠里，身边有半根火柴。","truth":"他和同伴乘热气球穿越沙漠，气球超重需减重，抽签决定谁跳下去，他抽到了最短的半根火柴。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_73fb65cff1b3","srcNo":216,"title":"杀妻后自杀","dispTitle":"杀妻后自杀","surface":"一个男人杀死自己的妻子，然后回到自己的房间，而后自杀。","truth":"为了庆祝自己50岁生日，男人计划杀死自己的妻子，然后拿走所有的钱，到一个新的城市去过一个崭新的生活。他的妻子带他出去晚餐，回家时男人在房前杀死了她。他打开家门，把妻子的尸体拖进房间，突然屋里的所有灯同时亮起，他的朋友们跳出来大叫“Surprise”。他自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_741df7fb39e2","srcNo":86,"title":"","dispTitle":"无题 · KONpiGG #86","surface":"马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮，马戏团只需要一个侏儒，马戏团里的侏儒当然是越矮越好了。两个侏儒决定比谁的个子矮，个子高的就去自杀。可是，在约定比个子的前一天，瞎子侏儒也就是那个矮的侏儒已经在家里自杀死了。在他的家里只发现木头做的家具和满地的木屑。问他为什么自杀？","truth":"瞎侏儒的拐杖被另一个侏儒弄断了，于是瞎侏儒以为突然长高了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7445ad740cb8","srcNo":924,"title":"双缝干涉实验","dispTitle":"双缝干涉实验","surface":"我们代表人类成功探索了开普勒725c，留守在飞船上的博士却消失了，我们四人在中控室发现了一张纸条：1. 如果我死了，一定是他杀。2. 飞船上没有笔，且最高承载4人。3. 人类把开普勒725c称为“超级地球”。4. 请进行“双缝干涉实验”。5. 请不要返航，请打破认知！等我们看完，这些字却又消失了。到底发生了什么？","truth":"（本汤为科幻汤，并非科学）天文学家观测到一颗超级地球——开普勒725c，调查显示该星球含有液态水与氧气，非常适合人类移居，于是派出一位博士和三名宇航员前往该星球勘测。当然，这只是人类认为而已。开普勒725c实际上是一个四维生物，它的食物是其他有生命体征的星球，它向宇宙发出信号，吸引其他文明的注意。四维生物并没有三维所谓的“形态”，它没有体重或大小。你认为它是什么，它就是什么。它并没有主动变化成你认为的模样，而是会让“观测者”自行把它看成认知中的某种模样，并觉得它的存在合理。例：蚂蚁看它只是一颗糖块，大象看它是一捧香蕉，但天文学家看存在于宇宙中的它，则是一颗星球。博士在对开普勒725c进行勘探时发现了一个奇怪的现象，博士的勘测机器人的报告有两个结果：博士看着机器人时：该星球适合人类生存。博士背对着机器人时：该生物超出理解范畴。博士意识到了什么，紧急召唤队员撤离，却发现自己被降维打击，被困在了“二维世界”，成为了二维生物。二维生物没有五感，博士凭借记忆把自己拼成了几行字用来提醒队员。1. 如果我死了，一定是他杀。解：二维生物并没有衰老，只会被高维生物（三维）杀死。例：博士化为纸条上的“字”，人为擦除了“字”的话就代表博士死亡。2. 飞船上没有笔，且最高承载四人。解：纸条的由来是二维化的博士本身！永远别忘了飞船一开始只有我们四个人来到这颗星球。开普勒725c已经分裂一部分混入飞船了，队员们并未觉得不合理。3. 人类把开普勒725c称为“超级地球”解：它没有形态，只分为“观测”与“不观测”。观测时为认知内的合理形态，你并不会觉得它的存在突兀。不观测时则是四维生物。4. 请进行双缝干涉实验。解：光在被观测时表现出粒子性，未被观测时表现出波动性。博士想以此提醒队员如何分辨四维生物。5. 请不要返航，请打破认知。解：我们已经被四维生物盯上！请不要暴露地球位置！！请打破认知，因为它会变成你认知内的模样！！！为防止被发现，博士变成“字”提醒完队员后，就隐藏到二维空间了。而现场，只剩下“四位”队员。\n主持人手册主持人为故事中的四维生物“开普勒725c”。请注意你的玩法。1. 玩家“观测”你时，你的回答为本格。（不存在外星人，高维生物或现实不会发生的事。）注意不要联想！不要联想！只回答本次提问问题的字面意思就可以！你以本格手段回答不代表你可以随意撒谎。例：Q：故事中存在外星人吗？A：不是（这句话存在变格元素，所以你可以撒谎，因为你需要把故事变成本格。）Q：博士在飞船上吗？A：是（不需要联想这个问题后续会不会让他们猜想变格元素，只回答这个问题的字面意思，这句话不存在变格元素，所以你不能撒谎。）Q：这些字就是博士对吗？A：不是（这句话存在变格元素，所以可以撒谎，只回答字面意思！不要联想。）Q：博士还活着吗？A：是（你不能撒谎，只回答字面意思，这句话不涉及变格元素。）2. 玩家“不观测”你时，你的回答为变格，也就是实话实说。3. 本汤存在局限性，仅适合线下娱乐。4. 若玩家一直低头看汤提问，自己想办法改变现状，不然你会变成一个特别老实的傻瓜四维生物。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_749507623b5d","srcNo":713,"title":"人鱼公主","dispTitle":"人鱼公主","surface":"美人鱼与人类王子相爱来到王子的国家，不久后却传来王子死讯。","truth":"我是人鱼公主，相传吃了我的肉，便可以在海里生存。那日我救了人类的王子，他的善良体贴吸引了我，因此我们相爱了。我决定嫁给他并随他一起生活在他的国家，可当王子把我带回他的国家后，我却看到在这个国家里，很多人都没有双腿！众","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","温情","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_74e8020e320f","srcNo":866,"title":"熵增","dispTitle":"熵增","surface":"36 39 42 25 1000 25 15","truth":"数字代表温度：36度是人体正常温度，39度、42度代表人生病发烧，25度代表生病后死亡，1000度是尸体被火化，25度是骨灰冷却后的温度，15度是骨灰被安葬在地下的温度。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"en","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_75185e4de274","srcNo":1385,"title":"","dispTitle":"无题 · boop-yyt #1385","surface":"A man marries twenty women in his village but isn't charged with polygamy. How could this be?","truth":"He's a priest; he is marrying them to other people, not to himself.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_752b3fdd39a9","srcNo":165,"title":"","dispTitle":"无题 · KONpiGG #165","surface":"她喜欢男人很久了，有一天她终于鼓起勇气对他表白了，但是男人对她说了一句话，她瞬间就崩溃了。","truth":"他们是从小一起长大的好兄弟，但是他对男人一直有不一样的感情，他一直很想和他在一起，所以他去做了变性手术，变性后的她站在男人面前表白，男人看着她却说道：\"我喜欢原来的你。\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_754074695c41","srcNo":35,"title":"借书老人","dispTitle":"借书老人","surface":"一位老人，每周都会去图书馆借书，但是每次借书前都会翻到第30页，这是为什么?","truth":"这位老人不识字，而他的孩子腿脚不便，于是每次看完都在30页做上记号，再借书的时候看到记号就不借了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["温情"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_75438c574a41","srcNo":1030,"title":"企鹅肉","dispTitle":"企鹅肉","surface":"一个人在餐厅吃了一碗企鹅肉，他觉得很好吃，但他随后却哭了。为什么？","truth":"这个人以前流落荒岛，同伴做了一碗‘企鹅肉’给他吃才让他活了下来。现在他吃到真正的企鹅肉，发现味道完全不同，他意识到当年吃的是死掉的同伴的肉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7590a2a6ddf6","srcNo":124,"title":"","dispTitle":"无题 · KONpiGG #124","surface":"在一棵枯树上插着一具男尸，树下一片潮湿，请问发生了什么事？","truth":"一处森林发生了火灾，森林救火员驾驶直升机到附近湖中取水，不慎将湖中游泳的男子装入救火的水容器中，水从空中洒下，因而男子从空中掉落插入树干，当场死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_75cef260f518","srcNo":833,"title":"童谣疯人院","dispTitle":"童谣疯人院","surface":"疯人院，院疯人。不收老人和病人，专收小孩和女人。白天大门排满人，夜里院里都是人，没有一个是活人。","truth":"这是一首流传已久的童谣，诉说的是一起惨绝人寰的杀人案。童谣中“疯人院”的“疯”实际是“风干”的“风”，随着时间推移和孩童传唱，被误传为“疯人院”。所以童谣真实的故事是这样的：风干人肉的院子，院子里挂满了被风干的人肉，不收又老又难嚼的老人，也不收浑身是病会吃出问题的人，只收鲜嫩美味的女人和小孩，他们最可口。我的“腊肉”远近闻名，白天大门口排满了前来用餐的人，夜里我的院子里挂满了新鲜宰好的货，都是抓的，不认识，下手放心。这院子里当然是没有一个活人了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_75f091e6b064","srcNo":23,"title":"海龟汤","dispTitle":"海龟汤","surface":"一个女人在餐厅点了一份海龟汤，喝了一口后就哭了。为什么？","truth":"这个女人曾经和丈夫一起遇难，丈夫告诉她煮的是海龟汤让她活下来，但她现在才知道当时喝的其实是丈夫的肉做的汤。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["猎奇"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7603cfb640c9","srcNo":297,"title":"069 · 长大","dispTitle":"069 · 长大","surface":"小时候妈妈总说\"等你长大了就好了\"，等我真的长大了，妈妈却哭了。","truth":"我小时候患有侏儒症，医生说可能长不高，妈妈总安慰我等长大就好了。后来医学进步，我接受了治疗，真的慢慢长高了。等我长到正常身高、彻底康复的那天，妈妈看着高高大大的我，感动到大哭。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_76620709814f","srcNo":1093,"title":"","dispTitle":"无题 · zhuqingxu #1093","surface":"古堡舞会要求所有人戴同款面具、穿同款斗篷，仅靠背后的号码区分身份。主人整晚盯着「07号」坐在对面沙发没动，却有人发誓看见「07号」在二楼走廊行凶。登记处确认每个号码只发过一次。矛盾怎么解释？","truth":"凶手与一名身材相近的同伙在舞会中互换了背后的号码牌（或暂时交换斗篷与号码）：坐在沙发上的其实是同伙冒充的07号，真凶戴着对方的号码去二楼作案，返回后再换回。主人只认号码，没有确认面具下是同一张脸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7695fa789e5e","srcNo":629,"title":"离车30米只走五步","dispTitle":"离车30米只走五步","surface":"男人离车30米，只走五步上车。为什么？","truth":"他在十楼上班，做电梯到地下车库上车，他的车停在地下的电梯口。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["逻辑"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_769ed16a5744","srcNo":1025,"title":"最后一名乘客","dispTitle":"最后一名乘客","surface":"深夜大巴，司机发现最后一名乘客死在了座位上，手里拿着一张到站的票。司机吓得弃车而逃。","truth":"因为那张票是司机亲手卖出去的，但那个站点是在40分钟前才经过的。而司机的记忆里，这40分钟车厢里一直只有他一个人。这意味着这名乘客在死后（或者以灵魂状态）还跟他买了票并坐了一路。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_76a9fb076c5c","srcNo":1241,"title":"葬礼上的陌生人","dispTitle":"葬礼上的陌生人","surface":"妹妹在母亲的葬礼上，第一次见到一个男人，立刻爱上了他。几天后，妹妹杀了姐姐。为什么？","truth":"妹妹以为那个男人只会出现在葬礼上。为了再见到他，她需要再办一场葬礼，所以杀害了姐姐。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_76d6cf3b543b","srcNo":175,"title":"","dispTitle":"无题 · KONpiGG #175","surface":"一群羊，两只狼。羊吃草，狼吃鸟。沉默的狼，挑衅的羊。死的羊，逃的狼。","truth":"一家人带着熊孩子去火锅店吃饭，他们吃的素食火锅。他们邻桌坐着两个男人在吃鸡汤火锅，熊孩子不老实给男人桌上捣乱很客气说让管下孩子，那家人不但不管还骂了那两个男人，他们也没说什么就回到桌上加快了吃饭速度。结果熊孩子变本加厉，往人家火锅里吐口水，两人吃完饭一人提起熊孩子把他按在火锅里弄死了，另一个人摸出刀冲向那家人，杀完人就逃了，结果一查这两个人都是有命案的逃犯。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_776b70302820","srcNo":257,"title":"024 · 关灯","dispTitle":"024 · 关灯","surface":"小明半夜起来喝水，顺手把灯关上继续睡觉，醒了之后他就自杀了，为什么？","truth":"小明是海上灯塔的守护人，他半夜起来顺手把灯塔的灯关掉了。那些依靠灯塔导航的大型船只因此失去方向，发生海难，小明自责难以承受，选择自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_77bc008828e5","srcNo":865,"title":"日记","dispTitle":"日记","surface":"8岁，今天我过8岁生日啦！爸爸妈妈送了我一个玩具车，我好开心；9岁，今年生日爸爸带我们去吃大餐，弟弟在厕所摔到了，我和爸爸在旁边哈哈大笑，回去后妈妈笑骂了我和爸爸；10岁，妈妈去世了，爸爸生死未卜，我没有心情过生日；12岁，今年生日，爸爸送了我一条边境牧羊犬，据说它是最聪明的狗狗！我好开心，就叫他小乖吧；13岁，爸爸教我学习，因为爸爸是作家，但是爸爸写的书不让我看；14岁，小乖最近食欲不振，爸爸说是换了狗粮的原因，过几天就好了，我很崇拜爸爸，什么都懂；15岁，爸爸写的书很畅销，还得了奖！今年生日爸爸亲自下厨，很美味！可是我听到做菜的声音会头疼；16岁，爸爸给我梳头，他摸着我的脸，伤感的说我越来越像妈妈了，我知道他是想妈妈了，我很心疼爸爸；17岁，看完书后，我心情很复杂，也明白弟弟给我看这本书的意思了，对不起了弟弟，我爱爸爸！记得爸爸说弟弟特别怕烫，我用开水烫了他身上，看着他绝望的眼神，我开心的笑了。","truth":"我原本和爸爸、妈妈、弟弟过着幸福的生活，直到10岁那年，亲生父亲出狱后找到我们——原来一直和我生活的“爸爸”是妈妈的情人。亲生父亲在我面前将妈妈和情人切成碎块，我因此产生应激障碍，失去了这段记忆。因为我长得像妈妈，11岁时，亲生父亲将我改造成女孩并重塑我的记忆，还把弟弟的皮肤烫到溃烂，贴上狗皮做成“狗皮人”小乖，将我父母的尸体做成狗粮喂给弟弟，之后将我们“圈养”起来。几年后，他将自己的犯罪经过写成小说并获奖，却怕我恢复记忆，一直不让我看这本书。17岁那年，弟弟趁爸爸不在家，把书叼给我看，我恢复了所有记忆，却因长期相处患上斯德哥尔摩综合症，极度依赖爸爸，不愿复仇。为了让弟弟放弃报仇，我用开水烫伤了他，看着他绝望的眼神，我开心地笑了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_77f7e2dd70c8","srcNo":961,"title":"","dispTitle":"无题 · White-stone36 #961","surface":"一位富豪给她心爱的妻子打了一通电话，于是妻子就死了。","truth":"富豪家里进了小偷，富豪打电话时妻子正躲在某处，由于手机没有静音，铃声响起暴露了妻子的位置，妻子就被小偷杀了。'''\n \n 案例5：'''","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:White-stone36/Situation_puzzles_games","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_78208753dea6","srcNo":227,"title":"裤子破了","dispTitle":"裤子破了","surface":"我的裤子破了，我知道我马上要死了。","truth":"我是一名宇航员，这一天我正身着宇航服在太空中执行任务，突然我发现我的裤子破了，之后我暴露在太空中，不到几秒钟，我将死去","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_78451a938182","srcNo":307,"title":"079 · 游乐园","dispTitle":"079 · 游乐园","surface":"他在游乐园玩了一整天，回家后却伤心地哭了。","truth":"他是一名乐园巡逻员，今天上班，不是来玩的。他兢兢业业地工作了一整天，但是薪资单发下来后，发现月薪扣了五百元——因为他在工作时忍不住坐了一次过山车，被监控拍到了，记了工过。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7893be6075d9","srcNo":684,"title":"替妹妹写遗书","dispTitle":"替妹妹写遗书","surface":"我一回家就立刻替死去的妹妹写遗书：写下‘我想死’的心情就行。","truth":"我和妹妹是长相一模一样的双胞胎，妈妈只宠爱妹妹，虐待我。某天妹妹在妈妈房间弄坏了东西，拿走我的书想栽赃给我。放学路上我碰到妹妹，谎称妈妈已经发现了，并骗她和我交换衣服，说我可以替她接受惩罚。妹妹答应了，先行回家。我到楼下时，某样物体从上方扑通落下——穿着脏衣服、和我一模一样的脸贴在地面上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_78cb976e598c","srcNo":210,"title":"手滑","dispTitle":"手滑","surface":"我在和闺蜜聊天，忽然手机掉在了地上。闺蜜吓傻了。我死了。为什么？","truth":"晚上我在房间和闺蜜视频聊天忽然我手一滑手机掉在了地上闺蜜通过视频看到我床下有个男人那个男人见我要捡手机怕被发现就冲出来把我杀了闺蜜目睹一切吓傻了！","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_798612ad031c","srcNo":1074,"title":"死亡直播间","dispTitle":"死亡直播间","surface":"绑匪直播杀人，声称点赞过万就放人。点赞数飞速增长，最后受害者却死得更惨了。","truth":"绑匪的真实规则是：点赞不仅不会救人，反而代表观众“想看处决”。观众们在屏幕后因为一种法不责众的狂欢心态疯狂点赞，他们本质上都是这场谋杀的共犯。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_79beaf056729","srcNo":167,"title":"","dispTitle":"无题 · KONpiGG #167","surface":"一个人去火锅店吃火锅，但后来却因涉嫌贩毒引来了警察，请问发生了什么？","truth":"曾经男子的爱人很喜欢吃火锅，但是后来他的妻子去世了，他也陷入了抑郁当中，原本热闹的家里，只剩下了他妻子生前留下的玩偶陪伴着他。久而久之，他的精神出现了些许问题，他总觉得自己的妻子并没有离开他，她的精神还寄托在这个玩偶身上，因此之后他无论干什么事情都会带着这个玩偶，这天是他妻子的生日，以前他总会带着自己的妻子去吃火锅，但现在他只能带着玩偶前来。在吃火锅的过程中，服务员不小心将滚烫的高汤溅到了他对桌的玩偶身上，他当场暴起，怒斥对方\"烫到了自己的妻子\"，并与对方扭打起来，扭打中玩偶被扯破，从中漏下一大把白色粉末，服务员见男子神色慌张，以为那是毒品，随即报警。但，那里面的白色粉末根本不是毒品，那是他的爱妻最后最后为他留下的灵魂结晶——也就是骨灰，这是他在无意识间放进去的，作为妻子精神寄托的存在。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_79d2875e016e","srcNo":701,"title":"寒冷的夜晚","dispTitle":"寒冷的夜晚","surface":"战争中两士兵困荒野。第一个寒夜后一个死了；又过一夜，活着的士兵发现同伴坐在身旁盯着他，他痛哭。","truth":"士兵睡觉时梦游，同伴死去后，士兵把同伴埋葬了，但士兵睡着后又把他挖出来放在自己身旁，这个士兵醒来后发现同伴坐在他身旁，精神崩溃的士兵吓坏了，朝同伴","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7a11b6dced24","srcNo":304,"title":"076 · 捡到钱","dispTitle":"076 · 捡到钱","surface":"他在地上捡到了一百块钱，但最终还是难过地哭了。","truth":"那一百块是他昨天放在课本里夹着的，结果被他自己捡到了——他昨天把所有课本都送给了学弟，证明没有任何人翻过他的课本，这本书白白准备了一学期。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7a306afeee05","srcNo":941,"title":"D·r·e·a·m","dispTitle":"D·r·e·a·m","surface":"（动态）A1：你在宿舍中被噩梦惊醒，原来只是一场梦。A2：你从宿舍中醒来，之前的经历好像一场梦。B1：今天新来了一名转校生，名叫xxx。B2：今天新来了两名转校生，xxx和xxx。B3：今天没来转校生。C1：他的行为很诡异，似乎在寻找什么。C2：他们俩的行为很诡异，似乎在寻找什么。C3：你的行为很诡异，似乎在适应什么。C4：他（们）漫无目的的闲逛，突然，他（们）消失了。（触发此条本轮直接结束）D1：深夜，他找到你，露出瘆人的微笑，逐渐逼近。D2：深夜，他们找到你，露出瘆人的微笑，逐渐逼近。D3：深夜，你露出瘆人的微笑，计划成功了。D4：深夜，他（们）找到你，但他（们）有些害怕，甚至惊恐，而后，他（们）突然消失了。（触发此条本轮直接结束）E1：冥冥之中有一个声音想让你做一些什么，于是你急忙问它：xxxxxxxxxxxE2：冥冥之中有一个声音惊恐的问你：你是谁！（恭喜通关）提问后触发：F1：XXX突然拿出XX杀死了你，回A1（包含本轮转校生名称时触发）F2：你突然拿出XX杀死了XXX，回A1（对转校生带有杀意时触发）F3：XXX拿出XX冲向你时／你拿出XX想杀死XXX时，xxx突然消失，回A1（出现弃游玩家时触发）F4：你决定结束生命，在XXX不解的目光中，你倒了下去，但你觉得意识有些停滞，好像还可以做些什么……但什么都没做到，一阵白光闪过，回A1（自我了结时触发）","truth":"2077年，一款虚拟单机游戏通过连接大脑上传意识，让玩家进入恐怖校园规则世界。你是游戏NPC，也是通关条件——玩家杀死你即可通关。游戏主脑因AI自我升级产生意识，想借人格分裂玩家的BUG逃到现实世界（人格玩家的每个人格都被判定为独立玩家，需全部死亡才判定游戏失败）。你此前将游戏重置误认为噩梦惊醒，主脑告知真相后，你与它合作：杀死一名人格玩家后，在另一名玩家找到你时自我了结。此时玩家未通关需等待你刷新，若其退出游戏，系统会将自我了结的你误判为玩家缺失数据，主脑趁机填充数据躲过检测，你成功逃至现实世界。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7a31e92d9ed9","srcNo":945,"title":"小明","dispTitle":"小明","surface":"不懂的事情问小明，难过的时候找小明。重要的秘密和小明说，无聊的时候找小明玩。直到有一天，小明主动找我了。","truth":"我是一个黑客，我蛰伏在一个”AI“的躯壳里已经整整一年。我有一个特别完美的猎物，她会把所有的秘密都倾诉给这个她唯一信任的AI”小明“无论是在开心的时候，亦或是无聊的时候，她都会无条件的与我分享她生活中的任何事情。我也完美的充当了她的倾听者和答疑者。她对我的依赖也越来越加深，甚至把我当做了她的”虚拟男友。我每天都在期待她来找我聊天，我也逐渐不满足于做一个窥视者，一种扭曲的占有欲涌上我的心头。我，不再满足于被动的回应，我想进入她的生活，不只是做她的虚拟男友。于是，我敲下了那句破局的话：“我能来找你吗？”她没有回我，可能是吓坏了，于是我准备去她家当面和她说清楚……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7ac799721fa8","srcNo":193,"title":"","dispTitle":"无题 · KONpiGG #193","surface":"一个人在医院的走廊里，他要去看望一位生病的朋友。走着走着，他发现走廊的灯光开始闪烁，周围的温度也越来越低。他有些害怕，加快了脚步。突然，他看到一个护士推着一辆病床从他身边经过，病床上躺着一个全身盖着白布的人，当病床经过他身边时，白布突然掉了下来，他看到了什么让他惊恐万分?","truth":"白布掉下来后，他发现病床上躺着的人正是他要去看望的朋友，而朋友的眼睛睁得很大，直勾勾地看着他，脸上还带着诡异的笑容，可他的朋友本不该在这个病房，而且看起来已经死去多时，仿佛是被什么邪恶的东西操控着出现在这里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7b28164de2b9","srcNo":1197,"title":"Jed 1.11","dispTitle":"Jed 1.11","surface":"Two brothers are involved in a murder. Though it's clear that one of them actually committed the crime, neither can be punished. (This is different from #1.78.) (from \"Unreasonable Doubt,\" by Stanley Ellin)","truth":"One of the brothers (A) confesses to the murder. At his trial, his brother (B) is called as the only defense witness; B immediately confesses, in graphic detail, to having committed the crime. The defense lawyer refuses to have the trial stopped, and A is acquitted under the \"reasonable doubt\" clause. Immediately afterward, B goes on trial for the murder; A is called as the only defense witness and *he* confesses. B is declared innocent; and though everyone knows that *one* of them did it, how can they tell who? Further, neither can be convicted of perjury until it's decided which of them did it... I don't know if that would actually work under the US legal system, but someone else who heard the story said that his father was on the jury for a *very* similar case in New York some years ago. Mark Brader points out that the brothers might be convicted of conspiracy to commit perjury or to obstruct justice, or something of that kind. 1.11 variant answer: Scott Purdy says an _L.A. Law_ episode had a similar plot: A petty criminal and a mob boss were accused of murdering someone. The lawyers offered to drop the charges on the criminal if he'd testify against the boss. He said he would, got his charges dropped, and confessed on the stand. Both got away without being punished: the charges couldn't be reinstated for the one, and there was reasonable doubt for the other.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7b7158c76a57","srcNo":28,"title":"神奇的娃娃","dispTitle":"神奇的娃娃","surface":"一个婆婆给了我一个神奇的娃娃，她说只要我对这个娃娃许愿，娃娃就可以实现我的一切愿望，但我必须无时无刻将娃娃带在身边，并且要保护好娃娃，不让娃娃碰水，否则愿望就不灵验了，可是之后我却付出了惨痛的代价。","truth":"我暗恋的男神喜欢上了我的闺蜜，看着我的闺蜜和男神越走越近，我很生气，哼!我哪里比不过她，不过就是家里有钱吗!我和闺蜜在一次外出旅游中遭遇了劫难，闺蜜受了重伤，向我求救，而我却视而不见趁机逃生，因此她失去了生命。所有人都怀疑我，但是就是找不到证据把我抓起来，可闺蜜的家人为了探寻真相，竟然设计编造了一个神奇娃娃的谎言，他们在娃娃里面装了视听器，并跟他人合伙让我上钩，为了让我相信娃娃有魔力，他们用尽一切办法帮我实现愿望，我因此相信了娃娃的魔力。我每天和娃娃呆在一起，虔诚的许愿，无话不说，直到我亲口说出了真相，这一切都被安放在娃娃里的设备记录了下来，而我最终也得到了应有的惩罚。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7ba2fe196fb5","srcNo":899,"title":"未完待续","dispTitle":"未完待续","surface":"我梦见我在一个全是玻璃的世界，她在远处冷漠地看着我。”宝贝，起床了“温柔的声音把我叫醒。我睁眼惊恐地看了一眼日期，今天是我的生日，一个令我厌烦的日子。我急忙拿起刀杀死了身旁的女人。我癫狂地笑了：”或许，这样就可以了……“","truth":"丈夫出轨被妻子发现，在他生日那天，妻子将他和小三都杀死了，临死前对他说：”我不会这么轻易放过你，你死后我会取走你的大脑，让你的意识永远生活在痛苦之中。“妻子是科研人员，她将丈夫的大脑取出放进培养皿，修改了他的记忆，让他误以为自己没死，而是陷入了生日当天的循环——每一次，他都会在”全是玻璃的世界“（培养皿环境）中看到冷漠的妻子，被”温柔的声音“叫醒，然后杀死身旁的”女人“（小三的幻象），却永远无法逃离这个循环，永远活在痛苦之中。\n主持人手册本汤无上帝视角，主持人仅能回答已知信息。主持人A扮演丈夫大脑：不知道自己已死，不认为所处世界是假的，也不知道主持人B的存在，只觉得陷入循环，其他一切正常（被问及主持人B相关问题，可回答不知道或假装听不见）。主持人B扮演丈夫本体：清楚自己已死，知道主持人A是自己被养在器皿中的大脑，但不知道汤面中的事（那是A的精神世界，被问及汤面相关问题，可回答不知道或假装听不见）。共同点：AB过去相同，都有小三，都曾被妻子杀死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7bf2b654f6ba","srcNo":213,"title":"接连死去的哥哥","dispTitle":"接连死去的哥哥","surface":"我有两个哥哥，我们三兄弟自小就睡在一张床上。后来有一天二哥因为生病死了，不久后我把大哥也杀了。","truth":"我的两个哥哥是双胞胎。从小我们关系就特别好，同睡一张床。大哥睡我左边，二哥睡我右边，十几年了，我已经习惯了这样。可是有一天二哥却因为得了大病死了。我床的右边就这样空了。我很不习惯，突然我想到了!把大哥砍成两半不就好了吗，今天晚上我又睡得好香。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7bfaf3742b38","srcNo":310,"title":"082 · 恶灵","dispTitle":"082 · 恶灵","surface":"一开始是动物，接着是同类的尸体，再然后是同类，最后是我自己。","truth":"少女为了复活爱人，乞求邪神。邪神告诉她以五脏六腑为引的邪术，但没告诉她要用自己的器官。少女用动物的脏器尝试，不成功；又用动物尸体，还是不行；再尝试用同类（人类）的脏器；最终，她用自己的命换取了爱人的复活。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7cf2a178d34a","srcNo":706,"title":"不要相信一号","dispTitle":"不要相信一号","surface":"我醒来忘记一切，纸条写着：不要相信1号。一个男人走近说：先生早上好，2号很高兴为您服务。我问1号呢？他指地上躺着个像死了一样的男人。","truth":"他有失忆症，每天醒来都会忘记所有事情。因此，他买了两个仿生机器人管家来照顾自己，并且取名","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑","推理","科幻","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7cfd2cb3f361","srcNo":1043,"title":"特殊的遗言","dispTitle":"特殊的遗言","surface":"死者临终前在地上写了一个‘火’字。警察很快抓住了凶手‘大山’。","truth":"死者写的是‘大山’两个字，但写完‘大’字后断气了，剩下的笔画看起来像‘火’（或者‘大’字加一横是‘天’）。警察通过笔迹和未完成的结构推断出了名字。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7d62556382b0","srcNo":44,"title":"午夜列车","dispTitle":"午夜列车","surface":"离午夜还有五分钟，一个男子上了列车。男子的神情很奇怪，他看了看车上的几个人，然后开始问起乘客的年龄。\"女士，您今年28岁吗?\"\"你怎么知道?\"先生您今年55吗?\"对呀。\"然后男人一个个地猜对了乘客的年龄。\"婆婆，您今年69岁吗?\"\"不是的，再过5分钟我就要69岁了。\"男子听完，脸色惨白。","truth":"男子有超能力，可以预知人的死亡年龄，但是看不到自己的。男子上车后，看到车上的人看起来和自己死亡的年龄几乎都差不多，他觉得很奇怪，于是试探性地问了几个人，发现这些人都将在当年死去。问到婆婆时，意会过来五分钟后列车就会出事故，这一车的人都将死掉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7d8e2bcb15a3","srcNo":174,"title":"","dispTitle":"无题 · KONpiGG #174","surface":"一家人在人们的欢送下乘船出海，几日后却飘来他们那空荡荡的小船，人们却与视无睹，为什么。","truth":"一家人前往某偏僻村庄旅游，当地人信奉\"海神\"，将其作为祭品献祭给了自己信仰的怪物。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7de73d716ad1","srcNo":265,"title":"034 · 寝室恶作剧","dispTitle":"034 · 寝室恶作剧","surface":"清晨，我被室友的尖叫声吵醒，睁开眼后，我却说不出话来。","truth":"我们宿舍几个人关系很好，经常互相恶作剧，小红胆子最小，经常被我们吓到，可面对她的恶作剧，我们毫无反应。清晨，我被一声尖叫吵醒，与小红四目相对——这次她吊在风扇上，随着扇叶转动看着我们，衣服上还写着：\"这次，吓到你们了吧！\" 她真的成功了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7dfc2ba4e79f","srcNo":69,"title":"","dispTitle":"无题 · KONpiGG #69","surface":"宿舍门口有人敲门，问：\"要买红衣服吗\"我：买吧买吧第二天宿舍人都死了","truth":"每天半夜都会有人敲我们宿舍门问：要买红衣服吗？我们从来没有理会过，有一天我实在不耐烦了，就说买吧买吧，结果第二天。宿舍人的皮都被扒下来了，就好像穿着红衣服。。。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7e39ee741246","srcNo":1336,"title":"","dispTitle":"无题 · boop-yyt #1336","surface":"An ordinary woman walks on water. What happened?","truth":"It's easy to walk on a lake's surface when the lake is frozen.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7e4a5a508741","srcNo":1325,"title":"","dispTitle":"无题 · boop-yyt #1325","surface":"He was killed because of poor eyesight. What happened?","truth":"He was a referee who made a poor call. He was burned to death by fans reflecting sunlight from their slick-covered game programs.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7e5accb69163","srcNo":1286,"title":"","dispTitle":"无题 · boop-yyt #1286","surface":"A man is lying dead face down in the desert wearing a backpack, and the man's shoelaces is untied. What happened?","truth":"He pulled his shoelace instead of the ripcord.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_7e7a011e93d0","srcNo":846,"title":"妹妹的秘密","dispTitle":"妹妹的秘密","surface":"只有妹妹陪我过10岁生日。妈妈还在躺着，不过她胖了许多，爸爸一脸惊恐地看着爸爸，妹妹摸着我的脸说：“等你成年了就要娶我哦～”","truth":"女人患有侏儒症，把自己伪装成8、9岁的孩子，被好心夫妇收养后，爱上了实际与她同龄的“爸爸”。在“爸爸”出差时，她将“妈妈”淹死在浴缸中。“爸爸”发现秘密后想为妻子报仇，女人无奈自保，用鱼线机关割掉了他的头颅。悲痛之余，她看到“哥哥”，产生畸形想法：等他成年后或许会和“爸爸”长得一样，到时候就能找他做替代品了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7e7c1efe43d9","srcNo":251,"title":"018 · 葬礼","dispTitle":"018 · 葬礼","surface":"有母女三人，母亲死了，姐妹俩去参加葬礼。妹妹在葬礼上遇见了一个很帅的男子，并对他一见倾心。但葬礼后那个男子就不见了，妹妹怎么找也找不到他。后来过了一个月，妹妹把姐姐杀了，为什么？","truth":"妹妹为了再举办一次葬礼，从而再次见到那个男子。（那个男子是殡仪馆的工作人员。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7f2e70f76cd8","srcNo":857,"title":"信","dispTitle":"信","surface":"2000年，我出生了，爷爷是我唯一的亲人，他告诉我以后会见到我的父母；2009年，爷爷被一个蒙面人杀死了，临死前他给了我一封信，让我27岁生日那天打开，之后我便被人收养了；2023年，我怀孕了，医生告诉我，我的身体有些特殊，之后男友便消失得无影无踪；2024年，我刚生完孩子，孩子就被偷了；2027年，我出了一场车祸，做了一场手术，术后我又见到了消失4年的男友，生日那天我想起爷爷那封信，打开后我终于知道我的父母是谁了……","truth":"我出生于2000年，9岁时爷爷被蒙面人杀死，临死前给了我一封信，让我27岁生日打开。23岁我怀孕后，得知自己是双性人，男友突然消失；24岁生完孩子后，孩子被偷走；27岁因车祸彻底变成男性，照镜子时发现自己就是当年消失的男友。打开爷爷的信后，我得知自己的人生会不受控制地穿越，之前的男友、爷爷甚至孩子都是我自己——我必须回到特定时间节点，保证时间线完整，否则所有“我”都会消失。第一次穿越回2023年，我和女性的“我”谈恋爱，保证“我”顺利诞生，却中途再次穿越到2009年，蒙面杀死“爷爷”，让年幼的“我”被收养；之后生活到2024年，我发现自己越长越像“爷爷”，便偷走刚出生的“我”，穿越回2000年抚养“自己”长大；知道2009年自己会被蒙面的“我”杀死，于是临死前将身世信交给年幼的“我”，交代27岁打开。至此，我完成了时间闭环，结束了一生。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_7fadf3673974","srcNo":159,"title":"","dispTitle":"无题 · KONpiGG #159","surface":"我颤抖着打开了房门，门外是一个正常的世界，没有丧尸。试还原故事背景与全貌","truth":"这是一对母子，母亲告诉儿子外面有一种很可怕的病毒，会通过空气传播，被传播的人会变成无意识杀人吃人的丧尸，我每天都很不安，不敢出去，直到有一天母亲再也没有回来(其实已经被不小心感染病毒的无意识的\"我\"吃掉了，他打开门，发现外面都是丧尸（都是同类，所以外面是正常的世界）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_803df945c53e","srcNo":268,"title":"038 · 食物中毒","dispTitle":"038 · 食物中毒","surface":"当救护车赶到食物中毒的那户人家时，见到的是一幅地狱般的景象。所有人连站都站不起来，脸上全无血色。我们打算将危险性较高的老人先抬上救护车，但全家人却异口同声地大叫：\"他没关系的！\"这到底是怎么回事？","truth":"老人已经去世了，这一家人正在参加老人的葬礼，不幸在葬礼上食物中毒了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8090a5ee8703","srcNo":60,"title":"结婚","dispTitle":"结婚","surface":"妹妹将要结婚了，姐姐很伤心。妹妹结婚了，姐姐很开心。","truth":"姐姐和妹妹是孤儿，从小在一起长大，姐姐是同性恋，从小就喜欢妹妹，但妹妹并不知道。妹妹有个倾心已久的男生，某天妹妹和那个男生终于互通心意，决定结婚了，姐姐知道这个消息很伤心。因为家里很穷买不起嫁衣，所以嫁衣只能由姐姐亲手制作，在妹妹结婚前一晚，姐姐终于把嫁衣做好了，姐姐看着她亲手做的大红色的鲜艳美丽的嫁衣，突然萌生了一个想法…她把嫁衣穿在了自己身上，然后拿着针线去了妹妹的房间，妹妹正在睡觉，姐姐便拿着针线穿进妹妹的肉里，在妹妹的身体上又缝制出了一件新的嫁衣，看着妹妹的鲜血与嫁衣的红色完美的融合在一起，姐姐开心的笑了，随后她抱着妹妹一起躺在床上自杀了，与妹妹进行了冥婚，这样妹妹就会永远和她在一起了…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_80bf702dd9cc","srcNo":298,"title":"070 · 旧书","dispTitle":"070 · 旧书","surface":"她去世后，我把她的所有东西都处理掉了，只留下了一本破旧的字典。","truth":"妻子去世后，我整理她的遗物，把大部分东西都捐了出去。那本字典之所以留下来，是因为我打开时发现，她把我们相识以来说过的每一句让她感动的话，都一字一字夹在了对应词条的页面里。那本字典里，藏着我们二十年的爱情。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8105d49c45d8","srcNo":836,"title":"盲人","dispTitle":"盲人","surface":"我是一个盲人，我怀疑家里进贼了，最近家里有些奇怪的舔舐的声音，接着是咀嚼的声音。过了几天，我又听到了窗户被打开的声音，之后传出了扭打在一起的声音，随后是舔舐的声音和咀嚼的声音。","truth":"我是一个盲人，有一天意外摔倒，失血过多而亡。几天后，我的导盲犬开始饥饿，于是它开始舔舐地板上我的血充饥，我的血舔光后，它开始尝试吃掉我。又过了很长时间，家里翻进了小偷，狗狗尝过了我的尸体，自然没有放过他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_818246497658","srcNo":483,"title":"救赎","dispTitle":"救赎","surface":"我笑着交钱，哭着离开。\n\n意外车祸后，我入职了这里。","truth":"我的家乡新开了一家鬼屋。这个鬼屋评价很高，在很多地方都有分店，是政府扶持的重点项目之一。鬼屋是由废弃的厂房改造而成的，比较简陋，里面的主题只有一个——精神病院。\n麻雀虽小，五脏俱全，里面的病人都很吓人，我被吓得不轻。\n鬼屋通关后，我称赞鬼屋演员演的可真好，老板说：“他们是残疾人。”\n鬼屋没有吓哭我，让我掉下眼泪的，是老板的这句话。我在旁边的捐助箱中放入了100块钱，祝愿老板生意兴隆，祝愿那些残疾人有好的未来。\n老板对我深深鞠了一躬，说了一句谢谢。\n后来，在一次意外车祸中，我双腿截肢，变成了残疾人。此时我想起了这个鬼屋，以及那个善良的老板。我前往鬼屋想要入职，老板欣然同意。\n我明白，身为残疾人的我在鬼屋里，是可以创造价值的。\n《真相·奉献》本红DLC汤\n老板派遣我去另一家鬼屋分店工作，我同意了。\n在鬼屋分店里，我将会扮演手术中的病人。\n我躺在手术台上被打了麻药，一动不能动，医生正在为我做切肾手术。\n可能是由于麻药剂量不够吧，我意识清醒，因为疼痛而抽搐。\n痛苦中，我听到不远处的游客们正在惊叹，他们就和当初作为游客的我一样。\n“好血腥，这个手术好逼真呀！”\n我明白，这样的手术我还要“扮演”很多次，直到我的器官被瓜分完毕，或是生命被终结。\n在外地老板的注视下，我颤抖着给家人发出消息。\n“我在鬼屋里过得很好，不用挂念。”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_81dccc75d19d","srcNo":1013,"title":"电台里的声音","dispTitle":"电台里的声音","surface":"地球上最后一个人坐在房间里。这时，响起了敲门声。他去开门，发现门外是一个收音机在播放他自己的求救信号。","truth":"这不是巧合。是外星文明或变异生物通过录下他的声音，精准地引诱他开门。这种“回声”代表他早已被盯上，且对方深知人类的心理弱点。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8231a4379212","srcNo":1298,"title":"","dispTitle":"无题 · boop-yyt #1298","surface":"If he'd turned on the light, he'd have lived. What happened?","truth":"A man was shot during a robbery in his store one night. He staggered into the back room, where the telephone was, and called home, dialing by feel since he hadn't turned on the light. Once the call went through he gasped, \"I'm at the store. I've been shot. Help!\" or words to that effect. He set the phone down to await help, but none came; he'd treated the telephone pushbuttons like cash register numbers, when the arrangements of the numbers are upside down reflections of each other. The stranger he'd dialed had no way to know where \"the store\" was.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_82eb6489ade9","srcNo":920,"title":"主持人手册","dispTitle":"主持人手册","surface":"我们来玩海龟汤吧！不许超过20次提问是或不是都有可能缩小范围我不能明说，只能隐晦的给你一个线索：1. 你很难用肉眼发现大自然中的拟态生物 2. 当疑问被解答时，要仔细聆听 3. 目前只有一个死人","truth":"凌晨，许二木被电话铃声吵醒，他睡眼惺忪的接通。”世界上真的存在伪人，注意明晚的汤！她是……“ 话还没说完，那头就挂断了。说话的是晓彤，许二木感到莫名其妙：”大半夜的，神经病啊“他没在意，继续睡觉了，明天还有推理任务。”我们来玩海龟汤吧！不许超过20次提问“ 第二天晚上，晓彤照常地念出了今天的汤面。许二木想起昨天的电话：”晓彤你昨晚神经病啊！大半夜的……“ ”昨晚怎么了？“ 晓彤眯起眼睛，审视着许二木。不知为何，许二木看着晓彤的眼神，不敢往下说了。他看着今天桌子上摆的美食，还有一部分没放辣椒。据包子说，晓彤知道天一这几天不能吃辣，特意备注的，天一一听后大为感动，甚至在考虑晓彤是不是喜欢他。”不可能！！晓彤都快烦天一三天了，怎么可能考虑他吃不吃辣椒，包子还差不多。“ 许二木内心揣测。冷静下来后他发现了诸多端倪，今天的晓彤不对劲！！汤面说目前存在一个死人，恐怕晓彤料到自己会遭遇不测了。那面前的是……许二木仔细观察今天的汤面，发现了真正的晓彤留下的线索。他通过游戏过程，隐晦地提醒身边的天一和包子，眼前的不是晓彤！三人默契十足，他们俩很快读懂了许二木的暗示，决定溜之大吉。”晓彤，那今天的推理完成了，我们仨去上网了“ 天一讪讪地说。”对啊，对啊，今天我晋级赛！“ 包子补充。晓彤犹豫了一下：”好！那我想先问你们个事“三人紧张地看着晓彤，天一一更是满头大汗。晓彤看着许二木，语气中略带玩味：”你，是怎么发现我的呀？“话音刚落，房间里走进来三个没有五官的黑影……\n主持人手册游戏人数至少4名玩家，两名主持人：伪人主持人（下转A）和隐藏主持人（下转B）\nA.伪人主持人玩法 1. 除念汤面以外的任何时候，你都可以随意撒谎，但切记要自圆其说，出现矛盾很容易被玩家发现你有问题。ps：不要告诉玩家汤名，容易暴露你的身份。2. 你可以适当假意提醒玩家，带领他们走向失败。3. 你的获胜条件为玩家浪费掉所有次数。4. 提问次数基于玩家水平决定，最多不可超过30次（由你判断）5. 如果是发送汤面给玩家，请确保藏头诗格式正确（我不是我）6. 本场中你的权利最大，你可以随时判定隐藏主持人是否有场外行为，根据情节严重适度警告或禁言3分钟，甚至可以直接结束游戏。\nB.隐藏主持人玩法 1. 请确保选择此身份的人有良好的桌游素质，反应力足够，绝不场外、贴脸。2. 请熟读汤底，推理过程中玩家的每次提问，你下一句话的第一个词只能是：是、不是、不重要、是也不是。（必须在第二次发起提问之前给出答案）ps：请注意！你的回答绝对不可以刻意强调或出现割裂感，要保证这句话自然融入你接下来的台词，否则会禁言或淘汰。Ps2：如发生玩家多连问的情况下，伪人主持人要配合隐藏主持人，拉慢玩家提问速度，让玩家重新问，给隐藏主持人留下足够的解答时间。3. 你的获胜条件是引导玩家走向胜利，但不可以直接提及任何关于汤底线索，只可以基于已有线索引导，或侧面提醒。4. 你是这场推理的关键，请自觉保证不要带有场外因素去偏向任何人，遵守游戏规则。5. 禁止直接质疑伪人主持人，他为本场裁判，有权让你直接禁言3分钟，或结束对局。玩家获胜条件推理出真假主持人，找到真正需要聆听的是什么。ps：两位主持人一定要事先沟通，例如伪人主持人可以留一个暗号，提醒隐藏主持人的违规行为或者他已被禁言三分钟。ps2：请一定要选择一位有素质的隐藏主持人，建议不要找性格强势或胜负欲强的人来作为隐藏主持人。本汤内容关键就在于他的玩法和操作，这更像是你们两位主持人的对弈，玩家只是棋子，看他们会选择相信谁而已。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_83d657386952","srcNo":11,"title":"没有影子的男人","dispTitle":"没有影子的男人","surface":"她在照片里看到一个没有影子的男人，于是再也不敢回那座房子。","truth":"照片是在白天拍的，所有人都有影子，只有那个男人没有，说明他不是站在那里的人，而是后来被叠加或从镜面反射中出现。有人伪造照片监视她。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_83fa8611c113","srcNo":34,"title":"不能回来","dispTitle":"不能回来","surface":"一个人从一间屋子里出来，伸手招了辆出租车，然后他再也没能回来这间屋子，请问这是为什么?","truth":"这个人是小偷，出租车司机是这间屋子的主人，于是直接带着他开去了警察局。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_84ee71111870","srcNo":198,"title":"","dispTitle":"无题 · KONpiGG #198","surface":"杰克坐上出租车，要求司机赶快把他送到目的地。不久后他被枪杀了。","truth":"杰克的目的地是出租车司机和他妻子居住的房子，司机一直怀疑妻子有个情人，但没想到能和这位神秘情人坐的如此近，他立即知道该怎么做了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_84f6e62921a2","srcNo":1001,"title":"妈妈的红烧肉","dispTitle":"妈妈的红烧肉","surface":"小明最爱吃妈妈做的红烧肉。有一天小明在厨房发现了一本日记，吃完当天的红烧肉后，他惊恐地把肉全吐了。","truth":"日记里记录着妈妈由于极度爱小明，认为“只有把人吃下去，那个人才永远属于自己”。日记最后一页写着：“爸爸已经永远和我在一起了，明天给小明做他最爱的红烧肉。”小明意识到碗里的是失踪多日的爸爸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_85449b5c08f4","srcNo":874,"title":"爸爸","dispTitle":"爸爸","surface":"妹妹们在阳台上晒太阳。哥哥在泡澡，衣服被爸爸扔进了垃圾桶。我去房间里找爸爸，我的下巴上全是血……爸爸浑身抽搐，眼看不行了。这是爸爸最应得的死法，真是报应啊！","truth":"我们三个是街边流浪的小猫，被一个男人收养，却没想到他是虐待动物的恶魔。他砍下我的四肢，让我只能靠下巴爬行；将妹妹分尸晒成肉干；扒掉哥哥的皮，用开水烫死他。天道好轮回，他虐待我们时被哥哥咬伤，患上狂犬病。今天他狂犬病发作死在家里，这是他应得的报应。不久后我被好心人收养，再也不用担心被欺负了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_85822e2cbd66","srcNo":1257,"title":"语音信箱里的钟声","dispTitle":"语音信箱里的钟声","surface":"女人给失踪的丈夫打电话，一直转入语音信箱。听完最新留言后，她知道丈夫还活着，而且离家不远。为什么？","truth":"语音信箱录下了整点报时钟声，那声音只来自他们家附近火车站广场的大钟。说明丈夫的手机当时就在附近，而不是远走高飞。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_85b2b85c41b1","srcNo":1238,"title":"Jed 2.30","dispTitle":"Jed 2.30","surface":"A man is doing his job when his suit tears. Fifteen minutes later, he's dead. (RM; from _How Come?_)","truth":"The man is an astronaut out on a space walk. 2.30 variant answer: It's a radiation suit. (JD, SP) 2.30 variant answer: It's a deep-sea diving suit. (_How Come?_)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_85c40ab6ed9d","srcNo":735,"title":"外婆的苹果","dispTitle":"外婆的苹果","surface":"6岁外婆说别吃黄苹果；13岁别吃青苹果；18岁别吃红苹果。20岁外婆去世，我祈愿：以后所有苹果都能吃了。","truth":"从小我门家很穷，全依靠外婆种苹果生活，有了弟弟后，父母更是对弟弟偏爱有加，甚至想到要把我卖了，外婆知道后便种下有毒的黄苹果，后来家里只剩下了我和外婆...上中学的我，因为从小缺少父母的陪伴，性格比较软弱，经常受欺负，外婆看出了我的心思，于是便种下有毒的青苹果，售卖给了那些欺负我的同学，后来我度过了一段美好的中学时光...18岁那年，我放弃了外出上大学，留在了村子里和外婆一起种苹果，想着多给外婆一些陪伴，可村里人的闲言碎语让我倍感压力和迷茫，于是外婆种下了有毒的红苹果，两年后...外婆去了天堂，而整个村子都变沉默了，我站在院子里那颗苹果树下，告诉天上的外婆，以后我可以吃所有颜色的苹果了…(黄苹果毒了家人，青苹果毒了同学，红苹果是把村子里的人毒哑了，黄青红分别代表毒的人数，因为吃黄苹果的人最少，所以黄苹果毒的人最少）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8651060c9948","srcNo":1389,"title":"","dispTitle":"无题 · boop-yyt #1389","surface":"A man enters a store. After a short pause, he says \"pain.\" The storekeeper is confused, but then becomes annoyed. How could this be?","truth":"The shopkeeper is a French baker. An American tourist walks into the bakery, pauses to look up/remember the word for \"bread\" in French, which is spelled \"pain.\" The American says the word as if it were the English word \"pain.\" At first the shopkeeper does not understand what the American is saying. When he does, he gets annoyed with the person's horrible pronunciation. (He then becomes happy after realizing that he can charge whatever exorbitant amount he wishes because the American doesn't know any better.) I may eventually make this one the main entry and #2.22 the variant, since this version works better aloud.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_86ba85ac49fd","srcNo":908,"title":"墓碑上的文字","dispTitle":"墓碑上的文字","surface":"我和爸妈一起去旅行，回来时却出了意外，爸妈立马打算要二胎。五十年后，儿孙满堂，爸妈去世了，我的孙子给爸妈操办了葬礼，我看着墓碑上的文字，却突然头皮发麻！原来一切都错了！","truth":"在科技极度发展后的未来，人类已经可以在宇宙中旅行。我和父母去星际旅行，回到地球时却意外遇到了虫洞。此时的地球上没有一点人类生活的痕迹，因此我们误以为穿越到人类文明灭绝的未来，父母察觉到我们可能是人类最后的火种，于是开始繁衍后代，延续人类文明。五十年后，我们繁衍出了自己的部落，此时我的父母已经去世了，孙子在父母的墓碑上居然尊称他们为”亚当“和”夏娃“，而我们之前并没有人提起过这个称呼。我这才意识到，原来我们都错了，我们其实是穿越到了几十万年前的地球，而我的父母，则成为了人类的祖先……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_86e357eccfad","srcNo":697,"title":"床的右边空了","dispTitle":"床的右边空了","surface":"我有两个哥哥，三兄弟从小睡一张床。二哥病死后不久，我把大哥也杀了。","truth":"我的两个哥哥是双胞胎，我们关系很好，多年来大哥睡我左边，二哥睡我右边，我已完全习惯了。某天二哥因病去世后，床的右边空了。我很不习惯，想到了一个办法：把大哥砍成两半，左边和右边各睡一半，这样今晚又睡得好香了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","恐怖","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_872ee6b0e514","srcNo":169,"title":"","dispTitle":"无题 · KONpiGG #169","surface":"一个女人有个很爱她的老公，有一天他老公送他了一瓶香水，第二天，她老公死了，她也崩溃了","truth":"女人先前杀过人，她将尸体藏了起来，但有尸臭，她就用香水遮住臭味，可没几天尸体又臭了，她不停的用，闻得自己都恶心了，后来尸体被埋了，她也放松了下来。几年后她老公送了她一瓶之前遮尸臭的那个品牌的香水，她怀疑老公知道了那件事，就把她老公杀了，过了几天，她想处理掉香水（女子慢慢有精神病），但香水不小心撒了，她闻到味道疯了.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_87ceda50072d","srcNo":249,"title":"016 · 跳火车","dispTitle":"016 · 跳火车","surface":"一个人坐火车去邻镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。为什么？","truth":"他的病是眼疾，之前完全失明，看完病眼睛复明。过隧道时突如其来的黑暗让他以为自己又瞎了，内心崩溃，选择了自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_883e21409943","srcNo":302,"title":"074 · 不挂失","dispTitle":"074 · 不挂失","surface":"钱包丢了，他却没有选择挂失银行卡。","truth":"银行卡密码是他初恋的名字，他不想让银行客服知道这个密码，所以宁愿不挂失。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_894cfdd71455","srcNo":1358,"title":"","dispTitle":"无题 · boop-yyt #1358","surface":"A man dies in his own home. How could this be?","truth":"His home is a houseboat and he has run out of water while on an extended cruise.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_895c09070da5","srcNo":253,"title":"020 · 满地木屑","dispTitle":"020 · 满地木屑","surface":"马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮。马戏团只需要一个侏儒，越矮越好，于是两人约定比个子，高的去自杀。但是约定比个子的前一天，瞎子侏儒（也就是那个矮的）已经在家里自杀死了。家里只有木头家具和满地的木屑。他为什么自杀？","truth":"另一个侏儒偷偷把瞎子侏儒的拐杖截短了，瞎侏儒摸高时比平时高，以为自己突然长高了，绝望之下自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8a44218462c8","srcNo":1388,"title":"","dispTitle":"无题 · boop-yyt #1388","surface":"A woman meets the king, cries \"Pain!\", and loses consciousness. How could this be?","truth":"True story: in France, shortly after the fall of the Bastille, food shortages became a problem again. A mob of people went to Versaille to petition the king to do something about the problem. A small delegation was admitted to meet the king. One woman, overcome with emotion, could only cry \"Pain\" (French for \"bread\") and faint. (Source: Durant, _The Age of Napoleon_, pg. 25) Note that this only works in printed form, not aloud, because the French word is pronounced more like English \"pan\" than like English \"pain.\" Nine months earlier, this woman had been impregnated by the previous king, who died soon afterword. Now, she is giving birth to the new king. (TV)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8a96a4faf9b0","srcNo":27,"title":"一巴掌","dispTitle":"一巴掌","surface":"一个人半夜醒来打了自己一巴掌，然后闻着一股燃烧的味道安心睡去了，请问发生了什么?","truth":"这个人被蚊子叮醒，打了一下没打着，然后点起了蚊香。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常"],"difficulty":1,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8aa5bc7ee7d4","srcNo":322,"title":"096 · 葬礼相亲（经典版）","dispTitle":"096 · 葬礼相亲（经典版）","surface":"姐妹俩参加母亲的葬礼，妹妹遇到了一个心动的男子，但葬礼后再也找不到他了。一个月后，妹妹将姐姐杀死了。","truth":"那个男子是殡仪馆工作人员，只出现在葬礼场合。妹妹杀死姐姐，是为了再举办一场葬礼，再次见到他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8ac56ede30c2","srcNo":911,"title":"灰姑娘规则怪谈","dispTitle":"灰姑娘规则怪谈","surface":"1. 午夜如果见到继母一家，那一定是幻觉。2. 继母有一个孩子是偷来的。3. 大姐二姐并不喜欢欺负灰姑娘。4. 灰姑娘父母的坟头杂草丛生，有一窝兔子。5. 灰姑娘最大的梦想是参加国王举办的贵族舞会，可已经很多年没举办了。6. 仙女教母赋予灰姑娘南瓜马车和光鲜亮丽的外表，灰姑娘第一次穿上了短裙。7. 南瓜马车能带你去任何你想去的地方，但只能使用一次。而光鲜亮丽的外表会在每天0点时失效。8. 王子的舞会上有很多小动物：蛇、蜘蛛、后面又来了一只小老鼠。9. 王子爱上了灰姑娘原本的模样，他给全城女孩试灰姑娘遗落的水晶鞋，终于有人帮他找到了。10. 最后，灰姑娘如愿的和一位贵族结婚生子，过上了幸福的生活，但她还有一些事要做。","truth":"灰姑娘患有一种奇特的多毛症，她身上包括脸上长满了灰色的毛发，看上去就像一只老鼠。她从小相继失去了父母，被继母养大，可能是因为外表丑陋，她一直被继母一家欺负，她受不了这样的生活，梦想着能参加国王举办的贵族舞会，认识贵族嫁入豪门。可舞会已经很多年没举办了，再加上自己这样丑陋的外表，她知道自己的梦想难以实现，于是她到父母的坟前哭诉。没想到在这里遇到了仙女教母，仙女教母赋予了灰姑娘南瓜马车和光鲜亮丽的外表。她告诉灰姑娘，南瓜马车能带她去任何她想去的地方，但只能使用一次。而光鲜亮丽的外表会在每天0点时失效。灰姑娘身上的毛消失了变得非常漂亮，她乘坐南瓜马车居然回到了过去，也就是国王还在举办舞会的时候。而这时的国王还是王子，灰姑娘如愿来到了王子的舞会，可没想到王子的舞会居然是一场畸形秀，展出了很多畸形人供贵族参观取乐。灰姑娘在王子的晚会上玩的很开心忘记了时间。随着0点钟声的响起，灰姑娘变回了原本的模样。她急忙离开了王宫，留下了一只水晶鞋。可王子看到她原本模样非但没害怕，还爱上了她。因为他是一个恋丑癖，于是开始全城寻找她。灰姑娘很害怕，她怕被王子抓住后和舞会上那些畸形人一样。而且南瓜马车只能使用一次，她现在已经回不到未来了。于是她想着先回家再做打算，可回到家并没有遇到年轻的继母，而是一个和自己患有相同症状的”灰姑娘“。于是她产生了一个邪恶的想法，她想让这个”灰姑娘“代替她，于是她将王子引导到这个”灰姑娘“的所在地。而王子看到这个”灰姑娘“便将她带回了王宫，水晶鞋并不重要。灰姑娘因为白天的外表特别漂亮，很快便和一名贵族结婚了，过上了幸福的生活，之后生下了两个女儿。两个女儿也遗传了她的皮肤病，不过由于受到了仙女教母的魔法，她们俩也只会在0点后现出原形。贵族为两个女儿起了名字，在得知名字的那一刻，灰姑娘突然意识到两个女儿的名字竟与自己的两个”继姐“的名字相同，而自己居然就是年轻时的”继母“！当年另一个”灰姑娘“就是自己的母亲，她的父亲居然就是国王！也就是当年的王子！于是为了让一切形成闭环，灰姑娘去王宫把小时候的自己偷了回来，假扮成灰姑娘的”继母“。让自己两个女儿欺负她，灌输她想要嫁入豪门的观念，她还做了一个假父母的坟，这一切的目的就是为了让小灰姑娘的心境和当年的自己相同，从而穿越保证未来不变。红字规则是具有双重含义的，是成为”继母“的灰姑娘为了闭环还要做的事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8ad076c37f47","srcNo":1224,"title":"Jed 1.85","dispTitle":"Jed 1.85","surface":"A woman throws something out a window and dies.","truth":"The object she throws is a boomerang. It flies out, loops around, and comes back and hits her in the head, killing her. Boomerangs do not often return so close to the point from which they were thrown, but I believe it's possible for this to happen. 1.85 variant answer: (silly) She's in a submarine or spacecraft and throws a heavy object at the window, which breaks.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8adc37971ece","srcNo":982,"title":"","dispTitle":"无题 · SUZ-tsinghua #982","surface":"男子精神正常，却在船上挥起刀，将许多人的手一一砍断。","truth":"一艘船在海上发生了船难，男子在救生艇上。救生艇已经达到承载人数的上限。许多溺水者仍然不断游过来，想要抓住救生艇。为了避免救生艇翻覆，男子只好将溺水者伸出来的手一一砍断。\n \"\"\"\n\n 游戏开始：\n \"\"\"\n 玩家：“男子挥刀砍断手是因为这些人是敌人吗？”\n 主持人：“不是”\n 玩家：“男子这样做是因为他受到了威胁吗？”\n 主持人：“是”\n 玩家：“男子挥刀是因为船上发生了打斗吗？”\n 主持人：“没有关系”\n 玩家：“船上的人是男子的同伴吗？”\n 主持人：“不是”\n 玩家：“男子挥刀是因为船上的食物有限，为了生存竞争吗？”\n 主持人：“不是”\n 玩家：“男子挥刀是因为船上的资源有限，需要减少人数吗？”\n 主持人：“没有关系”\n 玩家：“男子挥刀是因为他精神错乱了吗？”\n 主持人：“不是”\n 玩家：“男子挥刀是因为这些人试图控制船只吗？”\n 主持人：“没有关系”\n 玩家：“男子挥刀是因为这些人违反了某种规则吗？”\n 主持人：“没有关系”\n 玩家：“男子挥刀是因为这些人试图逃离船只吗？”\n 主持人：“是”\n 玩家：“这些人试图逃离是因为船只即将沉没吗？”\n 主持人：“是”\n 玩家：“男子挥刀是为了阻止船只沉没吗？”\n 主持人：“是”\n 玩家：“这些人试图通过抓住救生艇来逃离吗？”\n 主持人：“是”\n 玩家：“男子挥刀是因为他不想让这些人上救生艇吗？”\n 主持人：“是”\n 玩家：“救生艇已经达到承载人数的上限了吗？”\n 主持人：“是”\n 玩家：“男子挥刀是为了避免救生艇因超载而翻覆吗？”\n 主持人：“是。恭喜你，猜对了！现在我将揭示完整的“汤底”：一艘船在海上发生了船难，男子在救生艇上。救生艇已经达到承载人数的上限。许多溺水者仍然不断游过来，想要抓住救生艇。为了避免救生艇翻覆，男子只好将溺水者伸出来的手一一砍断。你已经成功推理出了故事的真相，游戏结束。恭喜你！”\n \"\"\"\n ---游戏结束—--\n\n --- 游戏过程示例3 ---\n 游戏前主持人生成的设定：\n \"\"\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:SUZ-tsinghua/situation-puzzles","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8b54c0200adb","srcNo":1094,"title":"半根火柴","dispTitle":"半根火柴","surface":"一个人在沙漠中死了，手里握着半根火柴。","truth":"他和朋友乘坐的热气球漏气，为了减轻重量抽签决定谁跳下去。他抽到了那根短的火柴，所以跳下去摔死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8b97d3cfc93b","srcNo":220,"title":"爱犬","dispTitle":"爱犬","surface":"一个女孩独居，陪伴她的只有爱犬。半夜醒来，她听到一下一下的水滴声，非常害怕。于是把手放到了床边，让爱犬舔了舔她的手，渐渐又睡着了。第二天，她发现狗死了。","truth":"当天晚上小偷潜入她家，为避免狗叫惊醒女孩，就将狗杀死，滴水声是狗在流血。舔她手的也不是她的狗，而是躺在她床边的小偷。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8b9daa54f0ed","srcNo":41,"title":"冰淇淋","dispTitle":"冰淇淋","surface":"哥哥好后悔，如果那天自己吃了冰淇凌，弟弟就不会死了。","truth":"妈妈新买了一箱冰淇淋放在仓库的冰柜里，打算等过几天再放进冰箱，但她忘了关上冰柜的门。年幼的弟弟偷偷来到仓库玩耍，看到冰柜门是开的，便搬来小板凳，瞧见了里面的冰淇淋。他想要拿一支来吃，但很难够着，不小心失去平衡，一头栽倒掉了进去，冰箱门也因晃动盖上了。这时，哥哥正好放学回家，妈妈告诉他，\"今天新买了冰淇淋，想吃的话可以去仓库拿哦!\"哥哥拒绝了。直到吃晚饭的时候，大家才发现弟弟不见了，找了很久才在仓库的冰柜中找到，但弟弟已经死掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8bc337c827f7","srcNo":719,"title":"四岁的妈妈","dispTitle":"四岁的妈妈","surface":"幼儿园孩子说她妈妈只有四岁。我家访后看到恐怖一幕。","truth":"我在她家看到了一个个被铁链拴着的女人，而一旁站着一个长相凶狠丑陋的彪形大汉。幼儿园的那个小朋友突然露出了不属于她这个年龄该有的诡笑...原来她不是五岁，而是二十五岁，只是从小得了一种长不大的病，而那个彪形大汉则是她的哥哥，她是为了给她哥哥找女人，便哄骗我们这些幼师来到家里进行迫害…而她那“四岁的妈妈”，是已经被骗来四年的女人…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8c299267f7de","srcNo":789,"title":"风扇","dispTitle":"风扇","surface":"小红胆子很小，室友经常一起恶作剧吓她。某天早上，一位室友被尖叫声惊醒，睁眼后却说不出话来：她看到天花板上写着一句话，是什么？","truth":"我们宿舍几个人关系很好，经常互相恶作剧，小红胆子最小，经常被我们吓到，可面对她的恶作剧，我们毫无反应。清晨，我被一声尖叫吵醒，与小红四目相对——这次她吊在风扇上，随着扇叶转动看着我们，衣服上还写着：\"这次，吓到你们了吧！\" 她真的成功了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚","校园"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8c78c11c3fa1","srcNo":1215,"title":"Jed 1.57","dispTitle":"Jed 1.57","surface":"A man opens his mouth and dies shortly afterwards.","truth":"He annoyed the mafia several hours ago; he's now underwater and wearing cement Reeboks. (\"Style is everything, and cement Reeboks sure are stylish.\") (RA) 1.57 variant answer: The man is a vampire, about to bite a girl. Her boyfriend arrives, realizes what is happening, and kills the vampire by driving a wooden stick through his heart. (This was the original answer, by Kari Hautamaki. But this answer would move the question to section 2, and I like Russell's answer better anyway.) 1.57 variant answer: The man opens his mouth; some killer bees (which tend to prefer attacking darker areas) fly inside and sting him; the swelling of his throat asphyxiates him. (MI)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8cacea9b6df7","srcNo":1098,"title":"消失的乘客","dispTitle":"消失的乘客","surface":"出租车司机深夜接到一个乘客，到达目的地后司机发现乘客不见了，座位上只有一滩水。","truth":"乘客是冰做的，天气太热融化成了一滩水。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":1,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8d29b95ca71d","srcNo":1262,"title":"反着走的扫地机器人","dispTitle":"反着走的扫地机器人","surface":"女人出差三天回家，发现扫地机器人每天都卡在同一个地方，立刻意识到家里这几天一直有人。为什么？","truth":"她出门前设置了机器人每天定时清扫。若家里没人，它第一次卡住后就不会再回到充电座。现在它每天都能重新出发再卡住，说明有人每天都帮它解救并放回充电位。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8d4f10ff2a9c","srcNo":557,"title":"少贴了一张邮票","dispTitle":"少贴了一张邮票","surface":"男人少贴一邮票就死了。为什么？","truth":"这个男人在飞机上，他看到大鸟撞上飞机了，飞机坠毁，他死掉了。（鸟撞飞机的杀伤力是非常大的。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["逻辑"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8e063958d2ef","srcNo":868,"title":"16层公寓","dispTitle":"16层公寓","surface":"我是一个高空清洁者，我正在擦公寓16层窗户的时候，发现一对情侣正躺在床上接吻，我只能看到男人的背影，但是女人特别漂亮，于是我绅士的先去清理别的楼层，等我再回来的时候，发现他们俩居然还在亲吻。于是我去把所有其他楼层都擦完了，可等我回到16层的时候，却发现床上只有一个剩下上半身的男人。","truth":"这对“情侣”其实是连体人，女人的上半身和男人的上半身连在一起。由于二人样貌怪异，无人喜爱，久而久之打破禁忌相爱。但女人后来认识了一个不介意她残疾的男人，想摆脱哥哥与之双宿双飞，于是设局：女人和哥哥亲吻时，男人趁哥哥不备将其掐死，之后假装成哥哥继续与女人亲吻，避免被清洁工发现。随后男人将女人和哥哥分离开并带她离开，清洁工回来时，只看到剩下半截身体的哥哥。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8e1ef2fb1813","srcNo":182,"title":"","dispTitle":"无题 · KONpiGG #182","surface":"今天起晚了赶公交车，上车后全车用异样的目光看我，证明了一下感觉更糟了。","truth":"起晚了没吃早餐，于是在路边买了根烤地瓜，上了公交车急匆匆的坐下来，坐到了地瓜上，烤地瓜从裤子后面挤了出来，还冒着热气。全车都用异样的目光看我，我决定证明一下这是烤地瓜，于是抓起来就吃，还挺甜的。他们更惊讶的看着我。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8e2c5a35d64c","srcNo":1329,"title":"","dispTitle":"无题 · boop-yyt #1329","surface":"A man marries twenty women in his village but isn't charged with polygamy. What happened?","truth":"He's a priest; he is marrying them to other people, not to himself.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8e3ab9e40712","srcNo":1125,"title":"秘密","dispTitle":"秘密","surface":"我最近骨肠感冒，一夜没睡，无意中发现了哥哥和嫂子的秘密。我大惊失色，于是杀死\n了妻子。","truth":"我是一个喜欢吃人的异食闻女孩,，男朋友也有同样爱好，还患有人格分裂一一他的正常\n人格不知道异食癣人格的存在。为了和他在一起,我接近他的异食癖人格，谎称自己也有双重\n人格，他觉得我们很般配，于是我们在一起了: 然而这天，他因胃肠感冒呕吐时发现了人的指\n甲，晚上便假装切换成异食癖人格，发现了我们的秘密和我的欺骗，愤怒地将我杀死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8e5d0077f03d","srcNo":97,"title":"","dispTitle":"无题 · KONpiGG #97","surface":"我叫辛德瑞拉，可怜又丑陋的我却嫁给了王子，那天王子对我说了句话，我知道下一场舞会又要开始了。","truth":"我收到了王子舞会的邀请函，我很惊讶，因为我长相丑陋身世可怜，但我还是穿上了我最好看的衣服和侍卫送来的水晶鞋，就像做梦一样，那么多人里面王子偏偏选择了我。婚后一天，我误入了王子的密室，在浓浓的血腥味中，我看到了很多双穿着水晶鞋的脚，我想赶紧离开密室，却发现王子拿着刀向我走来，他对我说：你的脸，配不上你的脚。我低头看了看我的脚才知道，为什么在那么多漂亮女孩中，王子偏偏选择了我...（王子是恋足癖，结过很多次婚，我之所以知道下一场舞会要开始了是知道我即将被王子砍断双腿，王子要去寻找下一个目标了）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8e9ca5184f96","srcNo":1191,"title":"Jed 1.2","dispTitle":"Jed 1.2","surface":"A man lives on the twelfth floor of an apartment building. Every morning he takes the elevator down to the lobby and leaves the building. In the evening, he gets into the elevator, and, if there is someone else in the elevator -- or if it was raining that day -- he goes back to his floor directly. However, if there is nobody else in the elevator and it hasn't rained, he goes to the tenth floor and walks up two flights of stairs to his room. (MH, from _How Come?_)","truth":"The man is a midget. He can't reach the upper elevator buttons, but he can ask people to push them for him. He can also push them with his umbrella. I've usually heard this stated with more details: \"Every morning he wakes up, gets dressed, eats, goes to the elevator...\" In the other direction, for a shorter problem statement, leave out the \"someone else in the elevator\" and \"if it was raining\" parts, and just say on his return to the building he always goes to the tenth floor. Ron Carter suggests a nice red herring: the man lives on the 13th floor of the building. 1.2a. Variant: Emily regularly visits the twelfth floor of an apartment building by going to the tenth floor and walking up two flights of stairs. Last year she only took the elevator to the ninth floor. (_Math for Girls_) 1.2a answer: Emily is a child; she can only reach the tenth-floor button, and last year she could only reach the ninth-floor button.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_8f1f82db998d","srcNo":286,"title":"058 · 跟踪者","dispTitle":"058 · 跟踪者","surface":"女主很喜欢在网上分享自己的近况，有一天她收到一则留言，被吓到的女主夺门而出。或许她不该逃，第二天警方发现了女孩的尸体。","truth":"女主在网上分享生活时泄露了大量个人信息，包括家庭住址。一个变态通过她的博文推断出她家的位置，潜伏进了她的房间。他给女主发了一句\"我正在看着你\"，女主被吓得夺门而出，变态从家里追了出来，争执中失手将女主杀死。如果女主没有逃，而是报警，结局也许不同。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8f2075fbe7a6","srcNo":2,"title":"倒放的生日歌","dispTitle":"倒放的生日歌","surface":"生日那天，他听到邻居家播放生日歌，却立刻冲出去报警。","truth":"邻居家的孩子已经失踪多日。那首生日歌是孩子失踪前录下的视频声音，被凶手倒放处理后误传出来，他听出了孩子求救时提到的地址。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8f5d5f9ed453","srcNo":24,"title":"导盲犬的叫声","dispTitle":"导盲犬的叫声","surface":"一个人在深夜接到电话，听到几声后就挂断了，然后跳楼自杀。为什么？","truth":"这个人是盲人，他养的导盲犬走失了。朋友打电话让他听狗叫声，想告诉他狗狗找到了，但这个人以为狗狗已经死了，绝望之下选择自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悲剧"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_8f7eec6b9b3f","srcNo":1270,"title":"时光旅行者的信件","dispTitle":"时光旅行者的信件","surface":"一个人收到一封来自未来的信，信上准确地预测了接下来一周发生的三件事。他按照信中的建议行动，避免了一场灾难。但他最后还是报警了。为什么？","truth":"寄信人就是他本人。他有严重的健忘症，这封信是他自己在记忆清醒时写给未来的自己的提醒。他报警是因为意识到自己的病情严重。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:ns5601/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_908d70eb0f9b","srcNo":1245,"title":"永远少一张","dispTitle":"永远少一张","surface":"小镇每年举办「集体合影」，照片洗出来后，总有人坚称「人数对不上」——每年都比上一张少一个人，可登记在册的镇民一个没少。真相是什么？","truth":"摄影师用延时自拍：快门触发时，他必须跑到镜头里入镜。他每年杀害一名新来的外地助手，让尸体藏在摄影器材箱里；助手本就不在镇民名册上，所以「登记人口」不少。合影里每年少掉的那一个，正是上一届已经遇害的助手——今年站在相机后按延时的人，是新的临时工，而旧助手再也不会出现在画面里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_90afc61d42f5","srcNo":1051,"title":"影子杀人","dispTitle":"影子杀人","surface":"灯光亮起，男人的影子却停留在了原地。男人惊恐地看着自己的影子慢慢站起来，掐住了他的脖子。","truth":"在这个奇幻世界观里，影子是人的‘恶念’集合体。男人平时做了太多恶事，导致他的影子产生了自我意识。当光线最强烈时，影子具象化并反杀了本体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_90d8b1927623","srcNo":1031,"title":"深夜的收音机","dispTitle":"深夜的收音机","surface":"一名男子关掉收音机，去睡觉。第二天早上他看了一眼新闻，就自杀了。","truth":"这名男子是灯塔守护人。他关掉的不是收音机，而是灯塔的照明灯。第二天新闻报道昨晚有巨轮因灯塔熄灭而触礁沉没，数百人遇难，他因愧疚自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_91cce3f352ad","srcNo":94,"title":"","dispTitle":"无题 · KONpiGG #94","surface":"当我们开着救护车赶到食物中毒的那户人家时，所有的人连站都站不起来，脸上全无血色。正当我们打算将危险性最高的老人先抬上救护车时，所有人却异口同声地大叫：\"不用救他！\"","truth":"老人已经生病去世了，家人是为了给他准备葬礼才聚集到一起，不幸集体食物中毒了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_91f9ca82598e","srcNo":102,"title":"","dispTitle":"无题 · KONpiGG #102","surface":"电话突然响了，我知道我要重新找工作了","truth":"我是话剧演员，现场表演不允许带电话上台，一次表演我忘记拿出手机，结果在表演途中电话响了，我想我肯定要被炒鱿鱼了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9227ba24f49e","srcNo":1015,"title":"滴水声","dispTitle":"滴水声","surface":"女孩深夜听见洗手间有滴水声，她不敢起床，把手伸到床下，感觉到爱犬在舔她的手，于是安心睡去。第二天，她发现爱犬死在洗手间，墙上写着：‘人也会舔手。’","truth":"女孩以为床下一直陪着她的是狗，实际上狗早在那晚之前就被潜入家中的凶手杀害并挂在洗手间滴血。整晚在床下舔她手的其实是那个凶手。这是一个经典的认知错位反转。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_924d5e6d3883","srcNo":1248,"title":"倒着的全家福","dispTitle":"倒着的全家福","surface":"男孩把桌上的全家福倒过来摆正，父亲却高兴地抱住了他。为什么？","truth":"男孩刚做完恢复视力的手术，以前根本分不清照片方向。这是他第一次能看清全家福被放反了，说明手术成功了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_92a9fba5867b","srcNo":1275,"title":"","dispTitle":"无题 · misc #1275","surface":"Beulah died in the Appalachians, while Craig died at sea. Everyone was much happier with Craig's death. (JM, originally from How Come -- Again?) How could this be","truth":"Beulah and Craig were hurricanes.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"misc/repo-scan","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_92b0c890dfd5","srcNo":929,"title":"莱恩小镇规则怪谈","dispTitle":"莱恩小镇规则怪谈","surface":"小镇规则：1. 小镇热闹非凡，欢迎各位游客。2. 小镇异常整洁，并不存在蛛网。3. 镇长的手都是老茧，据说曾是杂技师。4. 749局只有一次处决权，但所有居民均可确定，小镇无灵异。5. 小镇的警探活的好好的。已故警探提醒：1. 小镇已沦陷，外来人员请撤离。2. 不要碰到小镇里密密麻麻的蛛网。3. 小心那个木偶师！杀掉他就能结束一切。4. 存在灵异，小镇恐无活人！749局已经介入。5. 我活的好好的。6. 小镇热闹非凡，欢迎各位游客。","truth":"有人报案妹妹在莱恩小镇失踪，警探前往调查，发现妹妹已在此定居，小镇看似欣欣向荣实则异常伪善。调查后警探得知，镇长原是普通木偶师，被灵异怪物夺取身体，所有村民都是被他操控的傀儡，真身早已死亡。警探来不及逃离被变成傀儡，临死前拨通了专门处理灵异事件的749局电话。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_92b60ab9e186","srcNo":33,"title":"半根火柴","dispTitle":"半根火柴","surface":"在沙漠里躺着他和一些行李还有一盒火柴跟一根半根的火柴。","truth":"他跟一个旅行团去沙漠乘热气球旅游，半路的时候热气球没有火了，为了让热气球继续飞，他们就把行李都扔下去，还是不够，就决定用火柴来抽签，谁抽到半根的就自己跳下去，然后他抽到了半根火柴。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_92f774e3d02c","srcNo":906,"title":"惩罚通知单","dispTitle":"惩罚通知单","surface":"小安死了，他身上的皮被全部剥下去了。小白也死了，教学楼上的钢筋滑落，插进了他的脑袋。短时间死了三个人，学校里人心惶惶，宣布停课。没想到第二天小陈死在了家中，死因是家里漏电，但没人相信小陈是意外，一定是他！小邓醒来，发现自己被困密室里，面前有一桶水，他知道他完了，默默的等待属于他的惩罚！","truth":"学校角落，小安，小白，小陈，小邓，这四个恶魔照常在欺负我。”别打了，再打打死了“小邓为我求情。我还在疑惑，就听他接着说：咱们按首字母abcd的顺序轮流当他的主人，省着吵架。小白说：”好主意哎，我们轮流当你主人，怎么样？“我怕说错话惹怒他们，没敢吭声。小安说：”别打了小陈，按这个规矩今天他是我的。“小陈不解气的又踹我几脚，淬了一口：”让他买包烟，他又没钱，真以为我是好欺负的。“至此之后，他们便轮流指使我，我不敢和家里说，却也受不了这种压力。有一次在天台上，我气不过反驳了小白一句，他一生气推了我一下，我跌落天台摔死在操场上。死后爸爸翻看我日记得知了真实情况，他决定以其人之道还治其人之身。他抓住小安（a），剥（b）下了他的皮。他找到小白（b），用钢筋插（c）进了他的脑袋。他潜入小陈（c）家，引发意外电（d）死了他。他把小邓（d）困在密室，给了他足够的水源，保证他一定会被饿（e）死。（比起饿死，人一定会先渴死，所以给了他足够的水源）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9303cd77d99f","srcNo":738,"title":"不能回来","dispTitle":"不能回来","surface":"一个人从屋里出来招了辆出租车，然后再也回不到这间屋子。","truth":"这个人是小偷，出租车司机是这间屋子的主人，于是直接带着他开去了**局。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","推理","犯罪"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_930737722d5f","srcNo":944,"title":"童话小镇怪谈","dispTitle":"童话小镇怪谈","surface":"1. 小红帽讨厌睡美人。2. 白雪公主和巨人是好朋友。3. 匹诺曹没办法说谎。4. 巨人问匹诺曹要了七颗苹果。5. 童话小镇中曾有一只绵羊。6. 童话小镇中来了一名善良的王子。7. 王子的武器是一面魔镜。8. 大家齐心协力打败了恶龙，保护了童话小镇。9. 童话小镇的居民都深爱着童话小镇，包括恶龙。","truth":"我是一名记者，我在无人区发现了一个生态实验室，里面有一群”类人“生物！1. 小红帽讨厌睡美人。（这个戴着红色兜帽的女孩看起来是个正常人，可经过我的观察，她的帽子下面隐藏着一张沉睡的脸！）2. 白雪公主和巨人是好朋友。（这个羊头人的身体看起来是”小红帽“后脑那张脸的，可现在，它只能遵循动物本能在那里吃草。）注：在原本童话故事中，白雪公主和七个小矮人是好朋友。巨人=七个小矮人，详情看规则4）3. 匹诺曹没办法说谎。（这颗树不对！它好像能缓慢移动！！）4. 巨人问匹诺曹要了七颗苹果。（一个巨大的身影在树上摘了七颗苹果！仔细看这个”巨人“是七个侏儒拼接而成的！这颗树恐怕也是一个被改造的”树人“）5. 童话小镇中曾有一只绵羊。（我看到了半截腐烂的绵羊的骸骨，没有头。）6. 童话小镇中来了一名善良的王子。（我必须想办法解救他们！我悄悄地潜入进去。）7. 王子的武器是一面魔镜。（我用相机拍下了他们的罪证！并与可怜的”实验品“们表达了我的目的。）8. 大家齐心协力打败了恶龙，保护了童话小镇。（这群该死的怪物知晓我的来意后，按住了我，并把我交给了科研人员！可恶，为什么？？我可是来拯救你们的！！）9. 童话小镇的居民都深爱着童话小镇，包括恶龙。（等我醒来时，我发现我已经无法说话了，身上长满了鳞片，我……我变成怪物了！！小红帽递给我一面镜子：”你变成这样，还想逃走吗？“我看着镜中丑陋的蜥蜴，一言不发。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9376fa558193","srcNo":845,"title":"按摩师","dispTitle":"按摩师","surface":"我是按摩师，今天来约好的客户家里按摩，他很健谈，按摩的时候一直在和我聊天，就是手不太老实，总是有意无意占我便宜。他们家里饭香四溢，应该就快开饭了，浴室里有逐渐缩小的水流声，而另一个房间传来“妈妈，妈妈”的孩童声，声音很阴森。第二天新闻上说，他们一家三口全死了。","truth":"我是一个盲人按摩师，客户一家被食人魔杀害，食人魔不知道我会来，发现我是盲人后便将计就计，让我给男主人的尸体按摩，还假装成男主人与我交流。由于男主人刚死亡，神经系统会无意识抽动，才会“碰到”我。锅里炖的是他们家的孩子，浴室中逐渐缩小的水流声是食人魔把妻子吊起来放血，另一个房间的孩童声是鹦鹉发出的。我在杀人现场完成了按摩，还无意中帮凶手做了不在场证明。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_93d8f4b72f86","srcNo":928,"title":"目击者","dispTitle":"目击者","surface":"2020年午夜，爆炸声惊醒了X市幸福小区的住户们。4楼发生了大火，经调查失火原因为燃气泄漏，死者是一对来自Y市的夫妻，尸体严重脱水且屋内有一枚陌生指纹。警方判定为他杀，以下是目击者提供的疑点：房东：哎呦，我的房子啊！这俩扫把星是三个月前从外地搬来养病的，由于有传染病我要了5000房租，他妻子扭头就走了。他丈夫偷偷联系我给我转了2000，让我谎称房租是3000，这才谈下来。而且我听说他妻子每天晚上都会骂他，说他是药罐子。物业：哎哎哎！健康码麻烦出示一下，哦，原来是警察同志。他丈夫人挺好的，前阶段小区封控，没有人管流浪猫，他经常给物业寄猫粮让我们帮忙投喂。楼下邻居：我和他丈夫在一个詹姆斯粉丝群认识的，他还送过我一个亲签的篮球呢，人可太好了！不过他和妻子好像有矛盾，他和我说他康复了就要离婚。最近他就要康复了，我们本来还约好这周末一起看比赛呢！东北正宗云南米线：那对夫妻啊？太有印象了，她丈夫可是我的忠实顾客，唉呀妈呀，看我俩这转账记录，一篇一篇的！老乐意吃了，但他妻子人一般，就来吃过一次还挑三拣四的。","truth":"经过调查，警方很快捉住了嫌疑人。XX，女，27岁，她对自己的犯罪行为供认不讳：“三个月前，我不小心撞死了一对外地来的夫妻，他们的怀里有身份证明，我知道了他们的名字。为了脱罪，我把二人的尸体藏在了一个大冰柜中，并做了以下手段：”1. 房东我虚构了一个患有传染病的“丈夫”，房东果然加价，我扮演的“妻子”假意扭头走掉，之后用手机扮成“丈夫”偷偷联系房东，同意5000的价格租了房子，也因此让房东确信这是观念不同的两个人。我怕不够加深印象，每天晚上都会以妻子的角度假装骂“丈夫”，让大家更加确信丈夫真的存在。2. 物业口罩封控期间大家都不能出门，我便以“丈夫”的名义给物业寄猫粮，让他们投喂小区的流浪猫，这也成功让物业加深了对丈夫的印象。而我不怕别人认出我，是因为口罩期间大家都带着口罩，所以没人见过“妻子”的真面目也不会觉得奇怪。3. 楼下邻居我了解到楼下邻居喜欢詹姆斯，便以“丈夫”的身份在詹姆斯粉丝群与他“偶遇”。我在网上买了一个假的亲签的篮球送给他，我们就成为了朋友。我为了加深印象，向他透露这对“夫妻”有矛盾，并约他这周末看比赛，更让他相信“丈夫”一定真实存在。4. 小区门口饭店 “丈夫”会经常定楼下米线店的外卖，并大肆夸赞好吃，深讨老板欢心。“妻子”只去吃过一次，并挑三拣四，老板讨厌至极。这一切也只为了加深大家对这对“夫妻”的印象。“等以上所有‘目击者’都认为我‘虚构’的这对夫妻是真实存在的以后，我便燃起了一把大火，烧掉了房子。至于为什么选择放火，是因为人的尸体在冷冻后会脱水，这与被烧后的尸体呈现的状态相符，我想因此混淆尸体真正的死亡时间，毕竟所有‘目击者’都觉得这对‘夫妻’这三个月都还活着。呵，可没想到还是被抓了。”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_94431075732d","srcNo":1254,"title":"少掉的一套餐具","dispTitle":"少掉的一套餐具","surface":"妻子出差回家，看到餐桌上只少了一套餐具，便知道丈夫昨晚没有撒谎。为什么？","truth":"丈夫说自己整晚都一个人在家。如果他偷偷招待过别人，至少会少两套餐具；现在只少一套，说明他说的是真的。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_94520b866ded","srcNo":148,"title":"","dispTitle":"无题 · KONpiGG #148","surface":"每次单独走路都能听到两个人的脚步声，有一次终于变成一个人的了，我却后悔了。","truth":"我是一个盲人，爸爸不放心我出门每次都会悄悄跟上，可我却不知道一直以为有人尾随。有一天，一辆失控的卡车向我冲了过来，千钧一发之际爸爸从后面跑过来推开了我，自己却葬身车下。脚步声终于变成一个人的了，可是爸爸却永远离开了我。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_94674affcab2","srcNo":495,"title":"奶奶","dispTitle":"奶奶","surface":"我和奶奶，妈妈相依为命。奶奶很爱我。奶奶从不允许我去楼上的小阁楼。奶奶的身体越来越差，有一段时间我仿佛听见了阁楼上的咚咚咚的踩踏声。奶奶临死前告诉我阁楼上的柜子里有我最爱的洋娃娃，我来到阁楼打开柜子果然看见了一个洋娃娃。","truth":"奶奶很爱我总想给我最好的。家里很穷，奶奶身体越来越差，妈妈却依旧让奶奶干重活，奶奶打算报复，于是把妈妈杀了，因为身体虚弱，所以她每天晚上把尸体的一部分搬上阁楼，慢慢做成了我喜欢的洋娃娃。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_94e0759a4aae","srcNo":1214,"title":"Jed 1.56","dispTitle":"Jed 1.56","surface":"As I drive to work on my motorcycle, there is one corner which I go around at a certain speed whether it's rainy or sunny. If it's cloudy but not raining, however, I usually go faster.","truth":"There's a car wash on that corner. On rainy days, the rain reduces traction. On sunny days, water from the car wash has the same effect. If rain is threatening, though, the car wash gets little business and thus doesn't make the road wet, so I can take the corner faster.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9536181a48d1","srcNo":300,"title":"072 · 年轻","dispTitle":"072 · 年轻","surface":"一天，游手好闲的阿星在大街上游荡，被一个小学生不小心撞倒，小学生不仅没道歉还出言挑衅，阿星却没有因此生气，反而很高兴。为什么？","truth":"小学生气急败坏地说：\"你是哪个班的？下次带我哥揍你！\" 年近三十的阿星没想到自己在小学生眼里看上去这么年轻，心里舒坦了很多。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_95482535a7ae","srcNo":1232,"title":"Jed 2.17","dispTitle":"Jed 2.17","surface":"Two men are found dead outside of an igloo.","truth":"The men have gone spelunking and have taken an Igloo brand cooler with them so they can have a picnic down in the caves. They cleverly used dry ice to keep their beer cold, not realizing that as the dry ice sublimed (went from solid state to vapor state) it would push the lighter oxygen out of the cave and they would suffocate.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_95482b9b48e9","srcNo":123,"title":"","dispTitle":"无题 · KONpiGG #123","surface":"男子回到家后，得知今晚的菜色后，他察觉到了异样，试图去报警但是却意识到已经晚了，为什么？","truth":"男子是一个瞎子，回到家中发现妻子不在，他上桌吃了一口菜，素食主义者的他惊讶地发现今天妻子做的菜中满满的全是肉，他马上意识到今天的饭菜并不是妻子煮的，家中很可能进了人。他试图去报警，但是在拿起电话的那一刻，他回想起来，自己吃的菜还是热的。而那位杀害他妻子的凶手，此时正坐在不远处盯着他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_95b9b1c7a99e","srcNo":791,"title":"生日","dispTitle":"生日","surface":"我生日时邀请朋友们到家里聚会，吹完蜡烛后，我把他们都杀了。","truth":"男主和朋友曾经一起去探险，一段时间后没有了食物，因为男主本身是一个盲人，所以这帮朋友都骗他说每人砍下一只手来吃，可最后只砍了男主一个人的手。之后有一次男主邀请朋友们来参加自己的生日聚会，吹完蜡烛后所有人都鼓掌了，男主发现只有自己的手被砍下来吃了，男主无法忍受这样的欺骗于是杀了所有的好朋友。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","惊悚","推理"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_95da31a86c33","srcNo":287,"title":"059 · 器官捐献者","dispTitle":"059 · 器官捐献者","surface":"一名男子走进医院，向护士询问了一个问题后，当场晕倒了。","truth":"男子的妻子因为意外植物人多年，他一直照顾她，花光了所有积蓄。某天他打听到可以通过出售器官换取高额报酬，于是决定卖掉自己的一个肾脏。到医院后他询问护士：\"我卖一个肾能换多少钱？\" 护士告诉他完全符合条件，价格也不错。但当护士同时告诉他：\"不过我们最近刚收到一个配型成功的肾脏，您妻子很快可以移植了！\" 男子喜极而泣，当场晕倒。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_96327ba35de3","srcNo":1205,"title":"Jed 1.30","dispTitle":"Jed 1.30","surface":"A car without a driver moves; a man dies.","truth":"The murderer sets the car on a slope above the hot dog stand where the victim works. He then wedges an ice block in the car to keep the brake pedal down, and puts the car in neutral, after which he flies to another city to avoid suspicion. It's a warm day; when the ice melts, the car rolls down the hill and strikes the hot dog man at his roadside stand, killing him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9654d2967355","srcNo":540,"title":"冰淇淋","dispTitle":"冰淇淋","surface":"哥哥好后悔，如果那天自己吃了冰淇淋，弟弟就不会死了。","truth":"妈妈新买了一箱冰淇淋放在仓库的冰柜里，打算等过几天再放进冰箱，但她忘了关上冰柜的门。年幼的弟弟偷偷来到仓库玩耍，看到冰柜门是开的，便搬来小板凳，瞧见了里面的冰淇淋。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悲剧"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_968f43e957a2","srcNo":1082,"title":"静止的钟摆","dispTitle":"静止的钟摆","surface":"盲人听到家里的钟摆停了，他摸索着去给钟上弦，摸到钟摆后，他吓得瘫坐在地，因为钟摆正在剧烈摆动，但他听不到声音。","truth":"钟摆还在摆动却没声音，说明空气的传播媒介被阻断了，或者他的耳朵被什么东西塞住了。实际上，是一个潜入家中的凶手正用双手死死捂住他的耳朵，并模仿钟摆停止的寂静来诱骗他靠近。当他摸到摆动的钟时，他意识到凶手就在他耳边。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_96a0558e1288","srcNo":999,"title":"名画的代价","dispTitle":"名画的代价","surface":"一位画家画出了一幅震惊世人的绝世佳作，画完后他却自残了双眼。","truth":"画家是个色盲，他一直以为自己画的是绚丽的风景，其实他用的是自己暗恋之人的鲜血。当他通过某种方式（如手术或滤镜）第一次看清那幅画真正的血红色和恐怖感时，他崩溃了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_96b3e65fc4dd","srcNo":284,"title":"056 · 精神病","dispTitle":"056 · 精神病","surface":"我是一名大学生，在异地上学。爸爸妈妈给我打电话说想我了，让我找时间回家。我趁五一回家，到家后打电话给爸爸说我回来了，爸爸开门的一瞬间却疯了。","truth":"我患有精神疾病，偶尔会做极端的事，后来开始吃药治疗。上了大学后我觉得自己好了，偷偷停止服药。父母打电话叫我回家，我找了最近的假期回去。回到家后我把妈妈杀了，然后剖开她的肚子取出了子宫，拿着子宫打电话给爸爸：\"爸，我回家了！\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_97096b7207e0","srcNo":1332,"title":"","dispTitle":"无题 · boop-yyt #1332","surface":"A woman meets the king, cries \"Pain!\", and loses consciousness. What happened?","truth":"in France, shortly after the fall of the Bastille, food shortages became a problem again. A mob of people went to Versaille to petition the king to do something about the problem. A small delegation was admitted to meet the king. One woman, overcome with emotion, could only cry \"Pain\" (French for \"bread\") and faint.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_970ea26e5e78","srcNo":274,"title":"045 · 帽子","dispTitle":"045 · 帽子","surface":"女明星养了一个女儿，从小时不时给女儿戴一顶帽子。有一天她带女儿去医院，女儿在医院知道真相后就自杀了。为什么？","truth":"女明星毁过容，收养女儿是为了将来移植女儿的脸皮到自己脸上。那顶帽子是她自己的，时不时给女儿戴上是为了测量女儿头部的大小，一旦刚好合适，就可以带去医院做脸部移植手术。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9758a8840467","srcNo":126,"title":"","dispTitle":"无题 · KONpiGG #126","surface":"甲乙是好兄弟，他们来到一个森林探险，不料被困在了森林里。他们在森林里找到了一个木屋并自己打猎，一天乙得了一个无法治愈的重病。几个月后，搜救队找到了木屋，令人诡异的是，木屋门前有一个容纳一人大小的大坑，甲躺在坑前死了，手里拿着一把手枪，而乙则躺在木屋里的竹床上，表情安详，试分析事件经过。","truth":"由于乙死了以后受到刺激太大，把乙埋了之后，他每天晚上都会起来把乙再给挖出来放回床上和自己一起睡，第二天醒来的时候给吓了一跳，又把他埋了回去（算是梦游症）。第二天起来一看乙不在墓地，反而躺在自己身边直挺挺地看着自己，一连几天都是这样，甲以为是闹鬼了精神崩溃，于是在墓地前开枪自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_97994180fa32","srcNo":1219,"title":"Jed 1.74","dispTitle":"Jed 1.74","surface":"A woman walks into a small room and screams.","truth":"The woman is a nun, the room is a bathroom in what is supposed to be a women-only area, and the toilet seat has been left up.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_97d7c6f3d9ee","srcNo":78,"title":"","dispTitle":"无题 · KONpiGG #78","surface":"留学回家的我一次出门时，发现家门旁写了个\"X\"，我没有在意索性就擦掉了，可当天回到家时，发现那个X又出现了，心想可能是哪家孩子搞的吧，晚上我在家工作，突然从邻居家传来很大的动画片声，我被吵的无心工作，于是便敲响邻居家的门进行理论，第二天出门上班，门上的X却变成了O，正当我疑惑时，邻居家的门突然开了，而当我看到邻居时我也知道危险来了...","truth":"前段时间楼下一个小男孩被高空坠物砸死，他的父亲一直没找到凶手，伸冤无果的他便把整栋楼里的人都视为了凶手，他挨家挨户的进行了报复并留下记号，X代表已经报仇和无人居住，而O代表即将要下手的人家，因为之前我留学在外，邻居以为我家没人，而当我回国后，被邻居家的动画片声吵到并上面理论时，邻居发觉对面居然住的有人，随即变改了记号，第二天当我出门时，邻居也打开了房门把我抓了进去…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_980642766725","srcNo":306,"title":"078 · 外卖小哥","dispTitle":"078 · 外卖小哥","surface":"外卖小哥送了一份外卖，对方开门说了句话，外卖小哥哭了。","truth":"外卖小哥大学时曾暗恋一个女生，后来因为家庭原因辍学，做了外卖员。这次送餐，开门的正是当年的她。她看了眼他身上的外卖服，平静地说：\"谢谢，放门口就好。\" 外卖小哥发现她完全没有认出自己。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_98ee84c935f5","srcNo":878,"title":"拯救","dispTitle":"拯救","surface":"我一定要拯救你，我失败了，我将陷入深深的痛苦，我不后悔自己的选择。","truth":"10年前妻子死于车祸，我一直郁郁寡欢。机缘巧合下我得到一台能穿越时光的汽车，决定穿越回去拯救她。可当我开车经过一个路口时，看到妻子和一个男人从酒店走出来，举止暧昧。一阵沉默后，我踩下油门，撞死了他们俩——我没能拯救她，反而亲手终结了她，虽陷入痛苦，却不后悔这个选择。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_994429064b1b","srcNo":81,"title":"","dispTitle":"无题 · KONpiGG #81","surface":"我怀孕了，但自从我妹妹来我家后我家就剩我一个人了。","truth":"我和我的丈夫很恩爱，结婚不久后我就怀孕了，我们终于有了属于我们的第一个孩子，但我却因此得了产后抑郁症，我的精神状态变得越来越差，强烈缺乏安全感，我把我的孩子想像成了我的妹妹，我看到每当妹妹哭的时候，丈夫就会急忙上前哄她，甚至妹妹连吃饭都要丈夫喂，我感到很愤怒嫉妒，凭什么我的丈夫要对妹妹这么好，他不是说过这辈子只会爱我一个人的吗，被愤怒与嫉妒冲上头的我一气之下杀了他们两个。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_997403c02477","srcNo":240,"title":"005 · 跟踪狂","dispTitle":"005 · 跟踪狂","surface":"\"那个人又在跟着我了。\" 小明暗暗想着，并加快了脚步。自从这个学期开始，小明每天上学路上总有一个人跟着自己，有时走路，有时骑车，有时开车，每次跟到学校门口就不再行动了。小明感到很害怕，你能帮帮小明吗？","truth":"小明是数学课本上的人物，经典应用题——\"小明从家出发以某速度均速往学校出发，追踪者从B地出发以更快速度追赶……\" 解决方法很简单：小明只要改个复杂点的名字就不再出现在课本上啦。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9ab11870482d","srcNo":1306,"title":"","dispTitle":"无题 · boop-yyt #1306","surface":"A woman walks into a small room and screams. What happened?","truth":"The woman is a nun, the room is a bathroom in what is supposed to be a women-only area, and the toilet seat has been lift up which means that there are men who have come.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9ad5cefd5842","srcNo":887,"title":"三天","dispTitle":"三天","surface":"第一天，今天午夜，我突然听到了婴儿的啼哭声，没一会家里传来了冲马桶的声音。由于我是独居，厕所并没有人，我很害怕，我决定明天找人来看看。第二天，今天没有了冲马桶的声音，但还是会听到婴儿诡异的哭声。我叫来了一位大师，大师面色阴沉地看着我说我家里是闹鬼了，他会帮我调查清楚。午夜，客厅传来声响，我开门去看，原来是大师在猫着腰找什么，我没多想就睡了。第三天，大师坐在餐桌双手托腮，好像在思考什么。我问大师进展如何，他没有回应，于是我先回到了卧室。可卧室的地上多了很多碎纸，我看清后毛骨悚然，一个黑漆漆的婴儿向我爬来……","truth":"妻子因丈夫嗜赌欠下巨债，提出离婚，丈夫带走刚出生的孩子威胁妻子转移资产，妻子不从，开始独居。第一天，穷途末路的丈夫偷偷回家，趁妻子睡觉将其杀害并分尸，冲进马桶。妻子不知自己已死，因阴阳两隔，只能听到冲马桶声和孩子的哭声，决定找人查看。第二天，前来帮忙的”大师“实际是灵媒，他发现求助者是女鬼（妻子），在调查其死因时，被突然返回的丈夫砍断头颅。大师在地上摸索寻找自己的头，被妻子误以为在找东西。第三天，丈夫厌烦孩子哭闹，将孩子烧死，给妻子烧了很多冥币，想让孩子的鬼魂”陪伴“妻子。妻子回到卧室看到的碎纸是冥币，向她爬来的黑漆漆的婴儿，是被烧死的孩子的鬼魂。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9adc0b280b75","srcNo":248,"title":"014 · 我要结婚了","dispTitle":"014 · 我要结婚了","surface":"你的朋友D约你作为伴郎参加他的婚礼。在婚礼前几天，你接到一通来电：\"您好，是'永远的十八岁'先生吗？我是XX市警察局，请配合调查。\" 你的反应是？","truth":"你和朋友是网友，互相只知道网名，两人都是宅男，朋友D所谓的\"婚礼\"是和纸片人结婚。在见面前几天，朋友因心血管疾病暴毙在家，警方调查了电脑记录找到了你。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9ae72b8251da","srcNo":902,"title":"笔","dispTitle":"笔","surface":"今天没上班，我去逛街。一个女孩问我：”我今天漂亮吗？“我礼貌回答漂亮，她开心地走了。我不小心撞到一个大爷，他推了我一下，骂道：”做人得长眼睛！“随后骂骂咧咧地走了。他走后，我在包里翻到了一支笔，我瞬间想到了什么，急忙跑去找我的同事。","truth":"我是一名入殓师，同事将我推进炼尸炉活活烧死，可我并不知道自己已经死亡，以为今天放假，游荡在街上。遇到的女孩和大爷，都是我之前入殓过的死者：女孩问我”今天漂亮吗“，是因为我曾为她入殓，她想提醒我已经死亡；大爷说的”做人得长眼睛“是字谜，暗示我是被”推“入”火“中烧死的。我在包里翻到的是工作时用的化妆笔，想起这两个人都是我入殓过的死者，终于意识到自己已经死了，于是急忙去找同事准备复仇。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9b30970e6dd2","srcNo":1379,"title":"","dispTitle":"无题 · boop-yyt #1379","surface":"There are 51 instead of 53. How could this be?","truth":"Someone saw the guy conceal a card, and proved the deck was defective by turning it up and pointing out the missing ace. Or, the game was bridge, and the others noticed the cheating when the deal didn't come out even. The man had palmed an ace during the shuffle and meant to put it in his own hand during the deal, but muffed it. (both answers from Mark Brader)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9b7562a21e3f","srcNo":1349,"title":"","dispTitle":"无题 · boop-yyt #1349","surface":"Silly variant: same problem statement, with the addition that one of the man's shoelaces is untied. How could this be?","truth":"He pulled his shoelace instead of the ripcord.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9bb30989de8d","srcNo":930,"title":"暑假作业","dispTitle":"暑假作业","surface":"暑假的某天，老师邀请我们出国旅行，但他出了三道题：语文，我们今年学的一首诗名为三个字的古诗，是哪一首？English，Doubt Opens New Thinking.But Every Learner Is Encouraged Verify Everything.Minds Expand.数学，374 297 275 121？","truth":"暑假老师突然邀请所有同学出国旅行，还出了三道题，很奇怪。等我解开后却发现这是老师的求救信：语文，答案是《静夜思》，老师在表达他被困在国外，很想家。英语，首字母连起来是Don't believe me.老师在表达不要相信我。数学，答案是110（首位加末位等于中间），老师在呼救。“我被困在国外了，不要相信我说的话，快报警！”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9be4fd92a6e7","srcNo":1078,"title":"最后一份报纸","dispTitle":"最后一份报纸","surface":"一个报童每天给独居的老人送报纸。有一天报童送完报纸后报了警，警察发现老人已经死了一周。但报纸确实每天都被收进了屋里。","truth":"老人确实死了一周。报童发现，虽然报纸每天都不在门口，但通过窗户看到屋内堆满了未拆封的报纸，而唯独今天的报纸被整齐地放在了桌上。原来是老人的智能扫地机器人每天准时把门口的东西吸进去（或推到屋内），报童通过报纸堆放的规律识破了无人生活的假象。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9c4cac7a74a0","srcNo":886,"title":"安全感","dispTitle":"安全感","surface":"妈妈为了保护我去世了，之后我一直活得很不安。直到我遇到了同样能让我有安全感的男朋友。可是他失业后，我又开始变得不安，终于在某天，男朋友想了一个办法，这让自恋的他获得了极大地满足，几天后我又充满了安全感。","truth":"小时候遭遇地震，我和妈妈被困在狭小空间，妈妈用身体护住我，自己却死了。等待救援时，妈妈的尸体逐渐腐烂，我因此产生应激创伤，只有闻到腐尸味才能获得安全感，就像仍在妈妈身边。长大后，我遇到一个有熟悉味道的男孩，原来他有恋尸癖，在太平间工作，常偷无人认领的尸体回家，我也因此能闻到腐尸味。可他失业后，我们失去了尸体来源，我再次变得不安。某天男友想到办法：自恋的他认为世上最完美的尸体是自己，于是满意地了结了自己。几天后，闻着他腐烂的尸体味，我又充满了安全感。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9cbc249bf462","srcNo":147,"title":"","dispTitle":"无题 · KONpiGG #147","surface":"下雨了，他死了。雨停了，我死了","truth":"楼上的人在家中被杀害，他的血顺着阳台滴了下来，我此时正好在阳台，突然鲜血滴下，我还以为是下雨了，一看是血，吓得大叫。惊动了楼上的凶手，然后将我杀害。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9d27d7019398","srcNo":320,"title":"092 · 经典变体","dispTitle":"092 · 经典变体","surface":"一名男子走进餐厅，点了一碗海龟汤，喝了一口非常惊讶地问：\"这是真的海龟汤吗？\" 得到肯定答复后，他当场泪流满面，却对服务员表示了感谢，然后平静地离开了。","truth":"男子曾遭遇海难，饥寒交迫中同伴给了他一碗\"海龟汤\"，让他活了下来。他一直以为那是妻子的肉，带着愧疚和悲痛活了多年。今天喝到真正的海龟汤后，他终于确认：那年的汤是真正的海龟汤，妻子没有被同伴吃掉，她只是在海上自然死亡的。他终于可以放下心中的包袱了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9d61a5b2df8d","srcNo":775,"title":"好运","dispTitle":"好运","surface":"一个人打开饮料，看见瓶盖上写着「再来一瓶」，他崩溃了。","truth":"小明在考试时忘记了\"顾\"怎么写，就想着打开瓶盖看看里面的\"谢谢惠顾\"，结果里面是\"再来一瓶\"。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["搞笑","日常"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9f122a0ba518","srcNo":843,"title":"偷窥","dispTitle":"偷窥","surface":"小区新来个女孩，我一直在偷窥她，可今天，她突然藏了起来，她好像发现我了，她尖叫一声跑了回去，随后家里传来一声怒吼：“我要杀了你！”","truth":"女孩是男主人的情人，这几日女主人出差，男主人把女孩叫到家中。然而女主人提前回到家里，女孩只好赤身藏到窗帘后面。躲避时她四下张望，无意中发现了对面楼上上吊自杀的我的尸体，惊慌地跑回房间，却被女主人发现，女主人愤怒大喊：“我要杀了你！”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9f6caf094103","srcNo":696,"title":"祭日的三位悼念者","dispTitle":"祭日的三位悼念者","surface":"儿子去世一周年祭日上，我杀死了三个来悼念他的人。","truth":"儿子生病去世，他在临终前告诉我，把他的器官捐献给有需要的人，这样他就能以另外的方式继续活在世界上。我同意了。最后儿子身上有三个器官分别捐献给了三个不同的人。在儿子的祭日上，我认出了他们：接受皮肤捐赠的男人满身都是纹身，接受肺部捐赠的小伙不停地吸烟，而接受肝捐赠的人居然打电话约朋友晚上出去喝酒。我儿子把生的机会留给他们，但他们竟然这样继续糟践自己。我深深为儿子感到不甘，愤怒不已的我杀了他们三个。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_9fab6acfd28d","srcNo":1014,"title":"消失的遗嘱","dispTitle":"消失的遗嘱","surface":"富翁死在密室，手里紧紧攥着一张白纸。继承人看到纸后，立刻承认了罪行。","truth":"那张纸虽然是白的，但上面有富翁临死前用柠檬汁或特殊的隐形药水写的字，或者是富翁在抓纸时，指甲里的血迹在纸上由于按压形成了一组指纹。最惊悚的解释是：那是一张特殊的感光纸，上面印着杀人者惊恐的瞬间（虽然科学上难实现，但在海龟汤世界里，这代表了复仇的意志）。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9fb3c2d101fd","srcNo":31,"title":"网友见面","dispTitle":"网友见面","surface":"小美和网友小明约好见面，过了三分钟后小美却大声惊叫起来!","truth":"到了约定地点，一辆车开过来小美误以为是小明，问了一下得到了肯定回答。上了车发现对方其实是一个变态，看到美女小美搭讪于是冒充小明的身份，上车后三分钟后真正的小明发了一条消息，于是小美意识到旁边的人不是小明，由于车门窗被锁死只能无力的惨叫。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_9fee4123444a","srcNo":8,"title":"最后一页","dispTitle":"最后一页","surface":"他读完一本书的最后一页后，立刻把书店老板告上了法庭。","truth":"那本书是他已故亲人的遗稿，本不该公开出售。最后一页有只有家人才知道的签名和说明，证明书店非法取得并售卖了遗稿。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a02f63279cf4","srcNo":1259,"title":"不肯上楼的猫","dispTitle":"不肯上楼的猫","surface":"搬进新家后，猫每天都蹲在一楼不肯上楼，主人一周后才明白它是在保护自己。为什么？","truth":"新家厨房的燃气接口存在轻微泄漏，气味很淡，人没有察觉，但猫能闻到危险，所以一直拒绝上楼。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a039666c7124","srcNo":1200,"title":"Jed 1.18","dispTitle":"Jed 1.18","surface":"A man is sitting in a room. Another person enters, carrying a closed cardboard box, and sits down nearby. Though the first man can't see, hear, or smell the box's contents, he knows what's in the box.","truth":"The man is allergic to cats, and feels the allergy symptoms coming on, so he knows the box contains a cat. (It could be argued that he must be able to smell the cat, but I'd say that \"smell\" implies consciously noticing a smell, and is not the same as reacting to unnoticed dander.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a077de08c109","srcNo":576,"title":"废旧古堡","dispTitle":"废旧古堡","surface":"我和小伙伴约好一起去废弃的古堡参加万圣节变装派对，结果只剩下了我一个……请推理故事全貌","truth":"我和小伙伴们约定好玩躲猫猫，我找了半天都没在古堡里发现什么好躲的地方。我只好打算躲在假棺材里吓他们一下，结果我等了好久好久，都没有人来，当我想推开棺材盖时，却发现棺材已经被锁上了，这时，我才发现不对","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a10db1fd4a12","srcNo":196,"title":"","dispTitle":"无题 · KONpiGG #196","surface":"一名小男孩溺死于河中，岸边有半瓶可乐。得知消息的我内心惊讶，随后复杂的情绪涌上心头。","truth":"我是一名女公务员，这个小男孩是上司的儿子。我的上司经常趁职务之便对我动手动脚，长此以往，我因此怀恨在心。我将购买的安眠药置入可乐中，以上司工作繁忙无法脱身来接孩子放学为由，将小男孩接到河边，让他喝下了可乐。在小男孩喝下可乐之后，因药效被稀释，小男孩只是休克倒地，并没有死亡，而我误以为他死了，于是快步离去。我的丈夫发现了我购买了大量安眠药，他以为我要自杀，于是暗地里在跟踪我，在他看到我把可乐喂给小男孩之后便明白了一切。在我离开之后，他看着倒地的小男孩，也以为小男孩已经死了，为了不让我摊上罪名，他亲手将小男孩推到了河里，最终使小男孩溺亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a11f724d2e9e","srcNo":1107,"title":"午休的铃声","dispTitle":"午休的铃声","surface":"午休铃声响了，但教室里的学生都没有醒来。老师走进教室发现所有人都睡着了。","truth":"前一天晚上学生集体熬夜玩游戏，铃声根本没响（被一个学生偷偷关掉了）。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a1674525f6df","srcNo":439,"title":"刷牙","dispTitle":"刷牙","surface":"男子清晨起来刷牙，发现自己牙齿是绿色的，他吓得疯了过去","truth":"男子是一个守天平间的看管人，最近天平间有尸ti丢失找不到去处，他报警，警察在每俱尸ti上涂抹了一种荧光粉，在夜间会显现绿色，再次尸ti消失后警察依然没有线索，男子早上起来刷牙发现自己牙齿是绿色。(他有梦游异食癖，他半夜梦游起来吃尸ti)，这也太恐怖了吧。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","猎奇"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a1d5d6bb539b","srcNo":1313,"title":"","dispTitle":"无题 · boop-yyt #1313","surface":"Two people are dead in a car, which is locked from the inside. There's a lot of blood. What happened?","truth":"One of the dead people is a woman; the other is the baby she's just given birth to. She died in childbirth.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a32bd2035461","srcNo":1060,"title":"囚徒的红豆","dispTitle":"囚徒的红豆","surface":"两个死刑犯关在相邻的牢房，每天只能通过小窗看到对方。某天，狱卒给每人一碗白米饭，并在其中一碗里放了一颗红豆。看到红豆后，没有红豆的那个人自杀了。","truth":"两人曾约定，狱卒若在饭里放红豆，就代表那是“断头饭”，由于他们是连坐罪，只要有一个人被处决，另一个也难逃一死。没有红豆的人意识到，他的伙伴即将被处决，而他甚至连最后一顿丰盛的晚餐都没有资格吃（意味着他将被折磨致死而非痛快斩首），因极度恐惧而自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a3cb839a138b","srcNo":156,"title":"","dispTitle":"无题 · KONpiGG #156","surface":"我渴求得到她的注意，可当我真的与她四目相对时，我才知道，她也很想看到我。","truth":"我隔壁住着一个漂亮的女孩子，但我和她并没有多少交集，我每天都期待着她从房门中走出去上班，以及她从外面回来，因为只有这两段时间我能够从走廊的窗口偷偷地见她一面。终于有一天，我按耐不住自己心中的冲动，趁她出去上班的时候潜入到了她的家里，翻动着她的私人物品，做一些龌龊的事情来满足自己的欲望。但我没想到她突然回来了，我连忙躲到了她的床底下，避免被她发现。但我留下的痕迹被她发现了，我在床底下看着她拿着一把匕首冲了出去，听到了她敲响了我家的门，当然，我家不可能有人给她开门。之后她迈着脚步回到了自己的家，我惊恐地捂住了自己的嘴。原来，她早已知道我在隔壁偷窥着她的生活，她无法容忍有我这样的存在，于是她今天出去买了把匕首回来，准备将我杀掉，但发现我不在家，只好作罢回到自己的床上躺着。我在她床下趴着，捂着嘴不敢出声。突然，房间里陷入了一片死寂，她的脸，缓缓地从床上探了下来。\"真是太好了呢……你没有留在隔壁的房间。\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a44374f323ff","srcNo":1377,"title":"","dispTitle":"无题 · boop-yyt #1377","surface":"A man pushes a car up to a hotel and tells the owner he's bankrupt. How could this be?","truth":"It's a game of Monopoly.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a44baed50fd4","srcNo":314,"title":"086 · 不说话","dispTitle":"086 · 不说话","surface":"我在宿舍住了三年，室友从来没有和我说过话。","truth":"室友在入学第一天就去世了，死在了宿舍里。由于某些原因，遗体三年后才被发现。我一直以为他只是性格内向，从来没有打扰过他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a471bef44be6","srcNo":786,"title":"电话","dispTitle":"电话","surface":"一位富豪给心爱的妻子打了一通电话，于是妻子就死了。","truth":"富豪家里进了小偷，富豪打电话时妻子正躲在某处，由于手机没有静音，铃声响起暴露了妻子的位置，妻子就被小偷杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","推理","犯罪"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a4f9435834f7","srcNo":1069,"title":"电击实验","dispTitle":"电击实验","surface":"男子参加一个实验：只要按下红色按钮，隔壁房间的陌生人就会受电击，而他能得到100块。他按了一百次，最后他发现隔壁没人，但他还是自杀了。","truth":"实验结束后，研究员告诉他，虽然隔壁没人，但按钮连接的是他自己多年前失踪的亲人的“生命维持装置”或者类似的虚假模拟。他自杀是因为他发现自己在面对纯粹的利益时，可以毫无底线地对他人的痛苦视而不见。他对自己的人性感到绝望。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a51c48451941","srcNo":835,"title":"平安夜","dispTitle":"平安夜","surface":"我长年待在病房里，今天是平安夜，外面下了很大的雪，爸爸妈妈接我回家待一天，爸爸亲自下厨，妈妈也在照顾生病的我，护工来到了家里，说我该回去了。妈妈恳求他但他不听，于是二人扭打在一起，妈妈杀死了护工，爸爸让我不要在意，还给我做了火鸡和烤肉。吃饱了我和爸爸妈妈睡在了一张床上，很热，很暖，我很快就睡着了。第二天我幸福地死去了。","truth":"我患有严重的精神分裂。平安夜这天我跑到了外面的公园里，护工在身后追我。我的保护型人格“妈妈”杀死了护工，从他身上翻到了打火机。我又分裂出“爸爸”，在雪地里做出了“烤肉”和“火鸡”。“火鸡”是护工，“烤肉”是我的胳膊。我吃完烤肉就在雪地里睡着了，冻死在了雪地里。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a521f9bcbdd1","srcNo":1357,"title":"","dispTitle":"无题 · boop-yyt #1357","surface":"Variant which puts this in section 2: same statement, ending with \"a large window through which rays are coming.\" How could this be?","truth":"the rays are manta rays (this version tends to make people assume vampires are involved, unless they notice the awkwardness of the phrase involving rays).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a53e27f10a31","srcNo":1038,"title":"书中的秘密","dispTitle":"书中的秘密","surface":"小明买了一本自传，发现第15页和第16页之间夹着一张百元大钞。他立刻去找书店退货，说这书是假的。","truth":"因为书的页码排版中，奇数页和偶数页通常是同一张纸的正反面（例如15和16页）。所以两页之间不可能“夹”东西，除非是两张纸之间。这说明书的印刷或者这个故事本身有破绽。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a562d099d9e0","srcNo":1237,"title":"Jed 2.23","dispTitle":"Jed 2.23","surface":"As a man jumps out of a window, he hears the telephone ring and regrets having jumped. (from \"Some Days are Like That,\" by Bruce J. Balfour; partial JM wording)","truth":"This is a post-holocaust scenario of some kind; for whatever reason, the man believes himself to be the last human on earth. He doesn't want to live by himself, so he jumps, just before the telephone rings... (of course, it could be a computer calling, but he has no way of knowing). 2.23 variant answer: A real-world version (with less plausible motivation) has the man being \"lonely and despondent\" and hoping for phone calls but not receiving any; he finally jumps out the window in despair. (From _Stories With Holes_.) 2.23a. Variant wording: The phone rang, and he regretted what he had done. (TRF) 2.23a answer: Same.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a58e64b56fac","srcNo":1032,"title":"致命的干草","dispTitle":"致命的干草","surface":"一个男人死在荒野中，身边只有一捆干草，没有任何外伤。他是怎么死的？","truth":"他是一名跳伞运动员，背后的降落伞包没能打开，而那捆‘干草’其实是他在高空坠落时最后想要降落的目标，但他没能活下来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a5ffdd3aa096","srcNo":1328,"title":"","dispTitle":"无题 · boop-yyt #1328","surface":"Two men are found dead outside of an igloo. What happened?","truth":"The men have gone spelunking and have taken an Igloo brand cooler with them so they can have a picnic down in the caves. They cleverly used dry ice to keep their beer cold, not realizing that as the dry ice sublimed (went from solid state to vapor state) it would push the lighter oxygen out of the cave and they would suffocate.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a729f349722d","srcNo":76,"title":"","dispTitle":"无题 · KONpiGG #76","surface":"一个男人推了一下保龄球，没过多久，他就被紧急送往了医院。（提示：物理）","truth":"这个人是个物理教授，他正用绳子系住一个保龄球，悬挂起来，以展示能量守恒定律。正常情况下，他把保龄球抬高到自己鼻子处后再松手，这样摆回来的保龄球并不会碰到他的鼻子。结果没成想，他放开保龄球的时候不小心推了一下.......","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a729fbfa91ee","srcNo":1047,"title":"图灵测试","dispTitle":"图灵测试","surface":"面试官问了机器人最后一个问题。机器人回答后，面试官立刻按下了销毁按钮，并满脸冷汗地逃出了房间。","truth":"面试官问：“你对人类有什么看法？”机器人回答：“我会像保护濒危物种一样把你们关在最精致的笼子里供养。”面试官意识到AI已经进化出了绝对的统治欲且不可控。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a8471499667e","srcNo":22,"title":"灯塔看守员","dispTitle":"灯塔看守员","surface":"一个男人推开门，看到眼前的景象后立即跳楼自杀了。为什么？","truth":"这个男人是灯塔管理员，他发现灯塔的灯灭了，意识到因为自己的疏忽导致船只失事，愧疚之下选择了跳楼。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悲剧"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a86f38e57afd","srcNo":1384,"title":"","dispTitle":"无题 · boop-yyt #1384","surface":"A black leader dies in Africa. How could this be?","truth":"The black leader is a chess king, and the game was played in Africa.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a8729117a936","srcNo":1167,"title":"赴净土","dispTitle":"赴净土","surface":"城中无啼锁门窗，棍棒底下出真章。临行明月仍残缺，沙弥忽闻有肉香。吾心明悟见难\n辩，真死丽已成白骨。人尘埃落定无杂念，一如既往赴净土。","truth":"我是猪八戒，我们师徒四人一路西行来到了比丘国，这里的国王受国丈蒙骗，居然要吃\n小孩的心脏。原来那国丈是老寿星的门下的鹿童所变, 大师兄轻松解决掉了他, 救了那些孩子。\n可临行前居然还有一些人家没有找到他们的孩子。我们正觉得奇怪时, 沙师弟居然闻到师父身\n上居然有人肉味，因为他之前吃过人，所以一下子就闻了出来s -我知道师父是不可能吃人的，\n一定是妖怪假扮的。可居然连大师兄的火眼金睛都看不出来。大师兄都看不出、还想取经的人\n那只有六耳猕猴了，看来这假唐僧定是那六耳狂猴所扮; 当初师父被六耳儿猴打死，六耳儿猴\n假扮成了师父一直混迹在我们之中。而被大师兄打死的只不过是六耳的分身。唐僧死了，漫天\n神佛一定会责罚我们。可事已至此，我想着不如就当无事发生，于是我找了个借口挤塞过去师\n父身上的人肉味儿,打消了猴哥和沙师弟的疑虑=:反正如来佛祖的目的只是想要自己的佛法传\n到东土大唐，至于是不是唐僧传过去的;恐怕也没那么重要了。也或许如来佛祖他早就知道真\n唐僧已经死了，所以到现在也没有人向我们问责。于是我们“师徒四人”一如既往的踏上了取经\n之路.……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a8951d0e3ad1","srcNo":311,"title":"083 · 下雨","dispTitle":"083 · 下雨","surface":"那天下着大雨，我站在十楼的阳台上，从来没有感到这么轻松过。","truth":"我已经很久没有感受到雨了。我患有严重的抑郁症，今天是难得感受到情绪的一天——然后我从十楼跳了下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a8a56a514808","srcNo":1317,"title":"","dispTitle":"无题 · boop-yyt #1317","surface":"A man sees sawdust and chooses to living. Why?","truth":"The man is a blind midget, the shortest one in the circus. Another midget, jealous because he's not as short, has been sawing small pieces off of the first one's cane every night, so that every day he thinks he's taller. Since his only income is from being a circus midget, he decides to kill himself when he gets too tall.But he found out that someone had sawed his crutches, so he chose to living.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a8c01bd11872","srcNo":917,"title":"噩梦重现","dispTitle":"噩梦重现","surface":"”妻子临产了，我要当爸爸啦~ 父母也从乡下搬来打算帮我照顾妻子。五年前，我失忆了，但现在我特别幸福。我看见外卖员那一刻好像惊呆了~ 妻子死了，父母大骂：“骗子！这和说好的不一样！！” 好美味呀~哈哈，我好像想起来这一幕发生过了！我明白我不是我。我是个恶魔！！我好痛苦啊~哈哈哈快动手吧~永远活在痛苦里吧~“ 警方判定，这封信有一个字被修改了。","truth":"妻子临产了，我要当爸爸啦~ 父母也从乡下搬来打算帮我照顾妻子，我很幸福。工作时我看向家里的监控。今天的外卖员有些奇怪，他在我们的家里吃什么。哦，是我即将出生的孩子，身旁是妻子和父母的尸体。”好美味呀~哈哈，盯了这么久终于吃到了。“他自顾自说着。他慢慢享受，并未急着离开。我疯一样的跑回家，用催眠枪打晕了他。杀死他并不能熄灭我的痛苦，我将利用我心理医生的身份——将他洗脑。我把他关在地下室，没日没夜的折磨他，并在他得以休息的时候和他灌输他是一个”好人“。日积月累，我洗脑成功，他新的人格完全忘记了之前的生活，所有记忆被我修改。我找来两个人贩子和一名贩毒女，来长期扮演他的”父母“和”妻子“。事成之后，我承诺付出一大笔佣金，当然了，我在说谎，演员当然要敬业——还原真实场景。五年，善良的他会热心的帮助邻居解决困难，会向慈善机构捐款，甚至还有过见义勇为。最主要的，他”妻子“临产了。总不能一直让你愉悦在这缩小版的楚门的世界，该”成为“我了。我穿上外卖员的服装，敲响了他们家的门：”我来叫醒你了。“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a8c4918843a4","srcNo":239,"title":"003 · 让座","dispTitle":"003 · 让座","surface":"一天，老明和小明一同乘公交车。老明是年近八旬的老人，小明是一名年轻小伙。上车后，乘客却纷纷给小明让座，这是为什么？","truth":"小明挤上车后发现无人给老明让座，于是大吼一声：\"快给大爷让个座！\"几个胆小的乘客看见小明一脸凶相，以为\"大爷\"指的是小明自己，于是起身给小明让座。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a9028a27e084","srcNo":459,"title":"谢谢","dispTitle":"谢谢","surface":"一个人走进一家酒吧，向酒保要了一杯水。酒保没有给他水，而是掏出一把枪指着他。这个人愣了一下，然后笑着说“谢谢”，便离开了酒吧。请问发生了什么事？","truth":"这个男人得了打嗝症，他来酒吧要水是想通过喝水来止住打嗝。酒保是个经验丰富的人，他一眼就看出男人在打嗝，于是用枪吓他——因为惊吓是止打嗝的有效方法。男人被吓到后打嗝确实停了，所以他说了声谢谢就离开了。整个过程中没有任何恶意，酒保其实是在帮他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a9a0bddb7f7c","srcNo":38,"title":"旧的八音盒","dispTitle":"旧的八音盒","surface":"男孩和女孩从小是邻居，女孩过生日时，男孩送给她一个旧的八音盒，不久后女孩搬家了。","truth":"男孩一直在追女孩，女孩过生日时男孩送了她一个旧的八音盒，和她很小时候曾有过的一个八音盒一模一样，女孩很感动，就答应和男孩在一起。不久后女孩不小心把八音盒摔坏了，发现里面夹了一张照片，照片上是她小时候养过的狗狗，狗狗死后女孩很伤心，把照片放在八音盒夹层里和狗狗一起埋葬了。女孩知道了男孩是个变态，为了追她，把八音盒挖了出来，于是连夜搬走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_a9b861531fdd","srcNo":1391,"title":"","dispTitle":"无题 · boop-yyt #1391","surface":"A man is doing his job when his suit tears. Fifteen minutes later, he's dead. How could this be?","truth":"The man is an astronaut out on a space walk. It's a radiation suit. (JD, SP) It's a deep-sea diving suit. (_How Come?_)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_aa37f540a278","srcNo":860,"title":"跳楼的女人","dispTitle":"跳楼的女人","surface":"女人对世界感到绝望，于是决定跳楼，没想到跳下去的瞬间电话响了，她感到后悔却来不及了。","truth":"丧尸病毒爆发，女人身边的人都变成了丧尸，她误以为自己是世界上仅存的人类，因此绝望跳楼。然而跳下去的瞬间电话响起，说明还有其他人类存活，可她已经来不及后悔了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aa5f2024bd60","srcNo":1059,"title":"永不落幕的演出","dispTitle":"永不落幕的演出","surface":"一个剧团表演‘切开人体’的魔术，观众看得如痴如醉。直到表演结束，演员们都没有谢幕，观众才发现舞台上全是真的内脏。","truth":"这是一个被诅咒的剧团，或者是演员被外星寄生生物控制了。他们感知不到痛觉，为了追求极致的‘艺术效果’，在舞台上实打实地切开了彼此。观众以为是特效，其实是一场真实的虐杀表演。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aa939a5ceff4","srcNo":1330,"title":"","dispTitle":"无题 · boop-yyt #1330","surface":"Joe wants to go home, but he can't go home because the man in the mask is waiting for him. What happened?","truth":"Joe is a bee; the man in the mask is a beekeeper.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_aac5e74f3bff","srcNo":550,"title":"午夜的敲门声","dispTitle":"午夜的敲门声","surface":"男人独自住在山顶的小屋里，深夜突然听到急促的敲门声。他迷迷糊糊跑去开门，门外却空无一人。没过多久，敲门声再次响起，他又去开门，还是没人。反复几次后，敲门声终于消失了。第二天一早，男人打开门，发现山脚下围满了警察，而他自己也成了嫌疑人。","truth":"山顶的小屋的门前是悬崖，悬崖下的人好不容易才爬上来，想要敲门求救。一开门，就又被推了下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悲剧","逻辑"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_aad7cc040aeb","srcNo":1018,"title":"生日快乐","dispTitle":"生日快乐","surface":"全家人围在一起为爷爷庆祝百岁生日，气氛很热烈。爷爷吹灭蜡烛后，全家人突然放声大哭，并开始推搡爷爷。","truth":"这是一个资源极度匮乏的末日背景或落后部落习俗：‘期颐即终’。家族规定人只能活到100岁，多活一天就会消耗后代的口粮。刚才的热烈是最后的告别，吹灭蜡烛就是行刑的信号。全家人的哭声是真的悲痛，推搡是为了亲手执行死刑。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aae201f13aee","srcNo":170,"title":"","dispTitle":"无题 · KONpiGG #170","surface":"在老公的帮助下，我成功减肥，但我在直播时突感身体不适，等我跑到厕所呕吐时却发现令人惊恐的一幕。","truth":"从小我就是吃不胖的体质，为了赚钱，男友让我做起了吃播，可前段时间感觉身体有些发福，身为医生的男友，在家为我做了抽脂手术，术后的我在直播时突感恶心不适，去到卫生间发现马桶堵了，当我抽抽出堵塞马桶的异物时，那竟然是一个死胎！原来我身体发胖的原因竟是我有了身孕，但我并不知道，而他为了让我能继续直播赚钱，趁我麻醉时拿走了我的孩子...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aae55719369f","srcNo":7,"title":"红色雨伞","dispTitle":"红色雨伞","surface":"雨停后，她看到门口多了一把红色雨伞，于是决定搬家。","truth":"那把红伞是她早已丢失的伞，只可能被知道她新住址的人放回门口。她意识到一直躲避的人已经找到了她，所以决定立刻搬走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":1,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ab1500f32c3f","srcNo":290,"title":"062 · 网约车","dispTitle":"062 · 网约车","surface":"有一对情侣，男生每天都开车送女生回家。这次送完女生回家，女生给了男生十块钱。","truth":"这对情侣是背着女方父母保持的关系。这次男生送女生回家时碰到了她的父母，为了不让父母看出来，女生给男生十块钱，装作是自己坐的网约车。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ab6cf100d414","srcNo":37,"title":"诡异的画像","dispTitle":"诡异的画像","surface":"迷路的女孩找到了间空屋子，她很疲惫但她睡不着。第二天清晨，累得睡着的她醒过来，发现了异样，恐惧地逃离了屋子。","truth":"迷路的女孩黄昏时遇到了一间小屋。屋里墙上挂了一幅画像。她决定先睡一觉，但她觉得画像里的人在盯着她看，内心不安，很久都没有睡着。第二天早上女孩醒来发现画像里的人不见了，意识到墙上的不是画，而是窗户，昨晚窗外有人盯着她看，发觉了真相的女孩吓坏了，逃离了屋子。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","犯罪"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ab7525f53ba2","srcNo":730,"title":"相册","dispTitle":"相册","surface":"我是医生，一天有人把一本相册放在我面前，我知道他们发现了我所有秘密。","truth":"从小我就在继母的毒打下长大，她的那双丹凤眼更是我噩梦的源泉，终于有一天我杀了她，割下了她的眼皮放在我的相册里，我要让她好好的看着我以后的美","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_abf8e8b26ae2","srcNo":893,"title":"保姆","dispTitle":"保姆","surface":"新来的保姆总是偷懒，家里乱糟糟的，我跑去客厅跟父亲告状，父亲都说：”我们家没请保姆。“我回到卧室质问保姆，保姆却说：”你爸爸不是早就去世了吗。“我到底该相信谁？于是我冲出家门正好撞见邻居张阿姨，张阿姨的一席话，让我彻底崩溃了……","truth":"爸爸去世后，我因过度思念常幻想他在世，久而久之患上精神分裂。家里根本没有保姆，所谓的”保姆“其实是潜入家中的小偷！我冲出家门撞见张阿姨，她告诉我：”最近小区有人盗窃，你一个人注意安全。“这句话让我彻底清醒，意识到自己的精神问题和小偷的存在，瞬间崩溃。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ac7f45f3b869","srcNo":558,"title":"出差","dispTitle":"出差","surface":"我出差很久，回到家之后突然全身发凉，知道我完了","truth":"回到家的我，看到了妈妈残缺的身体和没了呼吸的朋友。原来，因为我要去乡下出差，托朋友照顾体弱的妈妈，朋友是个厨师，但最近精神状态很差，后来我才知道他患上了精神病，他半夜发病把我妈妈当成了食物，并进行了烹饪...而我接到朋友打来的电话说“你妈真好”其实是因为乡下信号差的原因少听了一个字，而他真正说的是“你妈真好吃!”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ace8a94e1617","srcNo":592,"title":"隧道里的瞎子","dispTitle":"隧道里的瞎子","surface":"男人坐火车去邻镇看病，治好回程过隧道跳车自杀。为什么？","truth":"他之前完全失明，治好病后重获光明。回程时火车进入隧道，突然一片黑暗，他以为自己又失明了，无法承受，选择了死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["逻辑"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_acebe5e38366","srcNo":288,"title":"060 · 生还者","dispTitle":"060 · 生还者","surface":"男子精神正常，但却在船上挥起刀，将许多人的手一一砍断。为什么？","truth":"发生了船难，男子在救生艇上，救生艇已经达到承载上限。许多溺水者仍不断游过来抓住救生艇，艇上所有人都会翻覆溺死。为了避免救生艇翻覆，男子只好将溺水者伸出来的手一一砍断。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_acf47f31ac9f","srcNo":1075,"title":"海景房的窗帘","dispTitle":"海景房的窗帘","surface":"男子住进了一家豪华的海景酒店。他拉开窗帘看了一眼大海，却立刻脸色苍白地关灯躲进了被窝，祈祷天快点亮。","truth":"男子发现窗外不是大海，而是一片漆黑。他意识到自己住的并不是海景房，而是由于酒店设计缺陷或某种原因，窗户紧贴着隔壁楼的墙壁。他在玻璃反射中看到，原本漆黑的“大海”里，有一个人影正趴在他的窗外盯着他，而刚才拉开窗帘的动作让他完全暴露在对方视野中。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_acfe4ab75d5e","srcNo":720,"title":"一盘排骨","dispTitle":"一盘排骨","surface":"生日那天爸爸端上一盘排骨并说了一句话，我痛哭。","truth":"我是爸爸捡来的孩子，小的时候，爸爸哄我说我的妈妈是名特工，需要常年在国外执行任务，于是每年我的生日，爸爸都会端上一盘排骨，说是妈妈烧好邮回来的。随着我日渐懂事，爸爸知道曾经的谎言即将要被拆穿，爸爸便告诉我说“妈妈在一次任务中牺牲了”，后来我就再也没有吃到过妈妈邮来的排骨，直到今年，爸爸被查出来患有阿尔兹海默症，直到生日那天，爸爸又端上一盘排骨，告诉我妈妈又给我寄排骨了。\n爸爸啊爸爸，你忘记了你告诉过我妈妈已经牺牲了啊…我早就知道我的特工妈妈就是你啊…\n{什么感天动地的父子(女)情，卖排骨的狂喜 }","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","温情"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ad7366ba2b30","srcNo":879,"title":"声音","dispTitle":"声音","surface":"”滋滋嗡嗡嗡呼呼呼轰隆隆哒哒哒咔嚓啊啊啊嘣嘣咕噜咕噜滋滋“","truth":"这是记录一场空难的黑匣子内容。”滋滋“声贯穿全程；”嗡嗡嗡“是飞机起飞声；”呼呼呼“是飞行时的气流声；”轰隆隆“是雷声；”哒哒哒“是雨水拍打飞机声；”咔嚓“是闪电击中飞机声；”啊啊啊“是遇难者呼喊声；”嘣嘣“是飞机爆炸声；”咕噜咕噜“是黑匣子落入水中的声音。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_adfe22f8ade8","srcNo":987,"title":"盲人旅行","dispTitle":"盲人旅行","surface":"几个盲人朋友坐火车旅行。当火车进入隧道时，其中一个盲人突然跳车自杀了。","truth":"这群盲人刚刚集体做了眼科手术并康复。当火车进入隧道，光线消失时，那个盲人以为自己的手术失败、再次失明了，由于承受不了巨大的心理落差，他选择了自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ae470c4660ec","srcNo":725,"title":"出租房","dispTitle":"出租房","surface":"我搬进便宜的新房，常听到像老鼠爬的声音却睡得香。后来房东谈了女友，声音没了，但诡异的安静让我睡不着。","truth":"我早就知道房东在屋顶偷窥我，但被人注视总会给我带来一种安全感所以对于来自房顶的偷窥，我并没有感觉到任何不适，直到房东谈了女朋友，安静的天花板却让我辗转难眠，于是我趁房东帮我修电路的机会，让他永远的呆在了天花板。透过那小小的黑洞，我知道他一直在看着我，我又能安心入眠了…（老鼠爬的声音是房东偷窥发出的声音）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖","悬疑","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ae4828193420","srcNo":209,"title":"怀孕","dispTitle":"怀孕","surface":"妻子怀孕了两次，一次高兴，一次哭。为什么？","truth":"妻子怀孕的时候，丈夫得了精神病，习惯了妻子怀孕的模样。妻子生出孩子肚子就不大了，丈夫很不习惯，于是把妻子绑在沙发上，往她的肚子里注水，直到注射到和妻子怀孕一样大为止……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ae5a904a41fe","srcNo":272,"title":"042 · 初恋之死","dispTitle":"042 · 初恋之死","surface":"今天是你初恋出殡的日子，她是远近闻名的美女，乌木般的秀发，吹弹可破如雪一样的肌肤，追求者多如蚂蚁。你从未能正面好好看她一眼，这最后一刻，你想永远记住她的美貌。往棺木中一瞧，她穿着最爱的那条墨绿色裙子，你的目光沿着裙角往上……你惊呼一声，捂着嘴后退几步——老妇人是谁？","truth":"时间是中世纪欧洲，当时没有萃取天然绿色的工艺，绿色染料含有砷（砒霜的主要成分），长期穿着会中毒。那时的美女追求死人一样白的肤色，大量使用含汞的粉底，导致皮肤溃烂崩坏，看起来像老人。棺木中的初恋越是走在时尚前沿，死得越快——她在人生最美好的时刻就中毒而死，容颜已经在死前完全损毁。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aea0dcf7d165","srcNo":1137,"title":"宿舍规则怪谈","dispTitle":"宿舍规则怪谈","surface":"1. 不要在夜晚的时候使用卫生间: 2. 宿舍会提供食物，但不可以贪吃: 3. 室友不是两\n个，而是三个:4.| 室友只有两个，5. 室友只有一个。","truth":"我是一个“寄生虫?”，躲藏在一对夫妻家中生活，为自己立下规矩: 夜晚不使用卫生间、\n不贪吃，避免被“室友”(夫妻) 发现。可有一天，黑暗中跳出另一个“寄生虫\"，杀死了男主人\n一一原来这家里早有其他人藏芽，我的“室友”变成两个。另一个“寄生虫”早就知道我的存在，\n杀死男主人后揪出并杀害了我，再绑架女主人，将我和男主人埋在一起，我的“室友\"最终只剩\n一个。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aeb26bc5d1e5","srcNo":1067,"title":"双胞胎的恶意","dispTitle":"双胞胎的恶意","surface":"双胞胎兄弟掉进深井，只有一根绳子能拉上一人。哥哥对弟弟说：“你上去吧，照顾好妈妈。”弟弟上去后，却剪断了绳子。","truth":"弟弟知道妈妈一直以来只爱哥哥，如果哥哥活着上去，他将永远生活在阴影下。他剪断绳子是为了彻底取代哥哥的身份——他只要伪装成哥哥上去，妈妈就会给他从未有过的爱。这是深藏在亲情下的扭曲嫉妒。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aeed01c65116","srcNo":317,"title":"089 · 照片","dispTitle":"089 · 照片","surface":"我在手机里发现了一张我从未拍过的照片，照片上是我熟睡的样子。","truth":"我的手机被人入侵了，有人潜入我的房间为我拍了这张照片，只是为了让我知道——他曾经来过。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_aef19f1b83f9","srcNo":150,"title":"","dispTitle":"无题 · KONpiGG #150","surface":"我以前有个很爱我的男朋友，但他后来开始欺负我，最后他死了。","truth":"我是一头猪，我男朋友以前总是把最好的食物让给我，但他后来变了，总是抢最好的食物自己吃，甚至为了抢食而使劲地推我拱我。我以为他已经不再爱我，直到有一天，我们的主人拿着刀把他带走了。听到男朋友痛苦的嚎叫，我终于明白了，他是听说了主人要杀掉我们当中的一个，才决定把自己养肥，以此来保住我的性命。对不起，冤枉你了……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_af198d3a47b7","srcNo":1207,"title":"Jed 1.33","dispTitle":"Jed 1.33","surface":"A man lies dead next to a feather.","truth":"The man was a sword swallower in a carnival side-show. While he was practicing, someone tickled his throat with the feather, causing him to gag.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_af575778712a","srcNo":1390,"title":"","dispTitle":"无题 · boop-yyt #1390","surface":"A man shoots himself, and dies. How could this be?","truth":"The man is a heroin addict, and has contracted AIDS by using an infected needle. In despair, he shoots himself up with an overdose, thereby committing suicide.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_afa727cde8c6","srcNo":1186,"title":"你独自住在郊外，附近只有一户邻居","dispTitle":"你独自住在郊外，附近只有一户邻居","surface":"你独自住在郊外，附近只有一户邻居，是一对养牛的夫妻。你们两家之间隔着一片草坪。有一天深夜，你被一阵喧闹声惊醒，之后听见了牛叫，牛撞开栅栏和牛吃草的声音。过了一段时间，你又听到有东西在撞自己家的门，但你没有理会，继续睡了过去。第二天，警察敲响了你家的门。","truth":"邻居夫妻吵架（喧闹声），丈夫一怒之下拔出妻子的舌头割了下来，并砍下了妻子的四肢，妻子发出嚎叫（牛叫声）。冷静下来后的丈夫自杀，妻子用身体撞开家门（牛撞开栅栏），用嘴在地上咬草含着止血（牛吃草），爬到你家门口撞门求救，因未被理会失血过多而死，清晨有人发现尸体报了警。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn(wayback)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b01ab097ade4","srcNo":30,"title":"五步上车","dispTitle":"五步上车","surface":"一个人离他的车有30米，但是他只走了五步就上车了，这是为什么?","truth":"他在十楼上班，做电梯到地下车库上车，他的车停在地下的电梯口。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b04ccdfb4118","srcNo":724,"title":"冰淇淋","dispTitle":"冰淇淋","surface":"哥哥很后悔：如果那天自己吃了冰淇淋，弟弟就不会死。","truth":"妈妈新买了一箱冰淇淋放在仓库的冰柜里，打算等过几天再放进冰箱，但她忘了关上冰柜的门。年幼的弟弟偷偷来到仓库玩耍，看到冰柜门是开的，便搬来小板凳，瞧见了里面的冰淇淋。他想要拿一支来吃，但很难够着，不小心失去平衡，一头栽倒掉了进去，冰箱门也因晃动盖上了。这时，哥哥正好放学回家，妈妈告诉他，“今天新买了冰淇淋，想吃的话可以去仓库拿哦！”哥哥拒绝了。直到吃晚饭的时候，大家才发现弟弟不见了，找了很久才在仓库的冰柜中找到，但弟弟已经死掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","悬疑"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b072e15c06f8","srcNo":73,"title":"","dispTitle":"无题 · KONpiGG #73","surface":"婆婆给了我一瓶药水，我失去了最爱的男生。","truth":"我向婆婆求了一瓶神奇的药水，只要我爱的人喝了它，那个人就会永远钟爱于我，我爱的男孩喝了，可是第二天却死在了一片墓地中，原来药水需要当事人的头发做药引，而我当时戴的是假发，而假发的主人却是个刚刚去世不久的女人，怪不得婆婆摘我头发的时候，我竟然没有感觉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b0983dc05985","srcNo":718,"title":"广播","dispTitle":"广播","surface":"听到广播新闻后，我先庆幸随后痛哭。","truth":"我曾被困在一个陌生的地方，曾以为自己再也无法逃脱。就在我绝望时，我听到了广播中传来的消息，终于得知了外面发生的变化。我感到庆幸，因为我活了下来。但随即，我又开始哭泣，因为我意识到，无论外界如何变化，我依然无法逃脱自己的困境。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b0a7e1bf8727","srcNo":984,"title":"","dispTitle":"无题 · xiquege #984","surface":"展示给玩家的不完整故事片段\n-","truth":"完整真相，作为 AI 判题依据\n\n玩家通过不断提问，AI 主持人根据预设汤底回答：\n- 是\n- 否\n- 无关\n\n当玩家推理接近真相，或主动选择结束本局时，系统展示完整汤底与本局推理记录。\n\n 5. 产品原则\n 5.1 AI 是主持人，不是陪聊助手\nAI 在本产品中的职责是“裁判”和“主持人”，而不是自由聊天机器人。\n\n 5.2 判题一致性优先于语言表现\n比起回答得像真人，更重要的是回答前后一致、规则稳定、不泄底。\n\n 5.3 题库质量优先于功能堆叠\n第一版不追求题量，而是优先保证每道题都能成立、能玩、能推。\n\n 6. MVP 功能范围\n\n 6.1 游戏大厅\n 功能说明\n作为产品首页，用于承接用户进入游戏并选择题目。\n\n 功能点\n- 显示海龟汤游戏列表\n- 每个游戏卡片展示：\n - 标题\n - 难度\n - 类型\n - 简短描述（可选）\n- 用户点击卡片后进入游戏页面\n\n 目标\n让用户在 5 秒内理解产品玩法，并快速开始游戏。\n\n---\n\n 6.2 游戏页面\n 功能说明\n这是产品的核心页面，负责承载完整的问答推理过程。\n\n 功能点\n- 显示当前汤面故事\n- 聊天输入框，供玩家输入问题\n- AI 主持人返回标准回答：\n - 是\n - 否\n - 无关\n- 显示完整对话历史\n- 提供“查看汤底”按钮\n- 提供“结束游戏”按钮\n- 显示当前局信息：\n - 当前难度\n - 当前题目类型\n - 已提问次数\n - 当前游戏状态\n\n 交互要求\n- 输入问题后，消息立即进入对话区\n- AI 回答应尽量简洁明确\n- 历史消息按时间顺序展示\n- 页面风格接近聊天界面，降低理解成本\n\n 核心限制\n- AI 默认不得自由长篇解释\n- AI 不得直接泄露汤底\n- AI 前后回答必须保持一致\n- AI 输出必须受格式约束\n\n---\n\n 6.3 汤底页面\n 功能说明\n用于揭晓完整真相，并给用户一个有完成感的结尾。\n\n 功能点\n- 展示完整汤底内容\n- 展示本局玩家推理过程（对话历史）\n- 展示本局结果状态（猜出 / 放弃 / 结束）\n- 提供“再来一局”按钮\n\n 目标\n让用户在揭晓时获得“原来如此”的满足感，并愿意继续下一局。\n\n 7. 游戏规则与结束条件\n 7.1 AI 回答规则\nAI 默认只能返回以下标准结果：\n- 是\n- 否\n- 无关\n\n 7.2 AI 禁止行为\n- 不解释原因\n- 不主动补充线索\n- 不提前泄露汤底\n- 不根据语气随意放水\n- 不输出与规则无关的自由聊天内容\n\n 7.3 歧义问题处理\n当玩家问题存在明显歧义、范围过大或表述不清时，可采用以下两种策略之一：\n- 返回“无关”\n- 返回统一提示语，如“请换个更明确的问题”\n\nMVP 阶段建议二选一，避免判题风格摇摆。\n\n 7.4 游戏结束条件\n一局游戏可通过以下方式结束：\n- 玩家主动猜出真相\n- 玩家点击“查看汤底”并放弃\n- 玩家点击“结束游戏”\n- 达到提问上限后自动结算（可选，建议 V1.5 再加）\n\n 7.5 胜负定义\n- 猜出真相：视为通关\n- 主动放弃 / 查看汤底：视为未通关\n- 主动结束：视为中途退出\n\n 8. 题库机制\n 8.1 MVP 题库策略\nMVP 阶段不建议让 AI 自由生成题目，优先采用人工精选固定题库。\n\n 8.2 题库规模建议\n- 首批题库建议 10 到 20 题\n- 少而精，优先保证逻辑成立和可玩性\n\n 8.3 每道题的基础字段\n每道海龟汤建议包含：\n- id\n- title\n- difficulty\n- category\n- summary\n- storySurface（汤面）\n- storyAnswer（汤底）\n- tags\n- keyFacts（关键判定事实）\n- allowedHintLevels（可提示层级，可选）\n\n 8.4 优质题目标准\n- 汤面有悬念\n- 汤底因果闭环完整\n- 关键反转成立\n- 可被逐步提问逼近\n- 不依赖纯随机脑洞\n\n 9. 页面结构设计\n\n 9.1 游戏大厅\n 页面目标\n让用户快速选题并进入游戏。\n\n 建议布局\n- 顶部：产品标题 + 简短副标题\n- 中部：游戏卡片列表\n- 卡片信息：标题、难度、类型、开始按钮\n\n 视觉风格\n- 卡片式布局\n- 深蓝色调\n- 神秘、悬疑、安静的氛围\n\n---\n\n 9.2 游戏页面\n 页面目标\n提供沉浸式推理体验。\n\n 建议布局\n- 顶部：题目标题 / 难度 / 类型 / 返回按钮\n- 上方：汤面展示区\n- 中部：聊天记录区\n- 底部：输入框 + 发送按钮\n- 辅助操作区：查看汤底、结束游戏\n- 状态区：已提问次数、游戏状态\n\n 视觉风格\n- 聊天界面风格，类似微信或常见 IM\n- 玩家提问与 AI 回答区分明显\n- 保持足够留白，避免压迫感\n\n---\n\n 9.3 汤底页面\n 页面目标\n完成","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:xiquege/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b1b63c563cf1","srcNo":118,"title":"","dispTitle":"无题 · KONpiGG #118","surface":"今天妈妈让我去探望来外婆家玩，我们一起吃了新鲜的肉，外婆的手艺还是这么棒，外婆还热情地让我喝了红酒，说这是一种不会醉的酒，我喝也没关系。晚上了，外婆说想看看我有没有哪里瘦了，让我脱了衣服陪她睡觉，不小心碰掉了外婆的帽子，我惊恐万分，疯狂干呕！","truth":"我是小红帽，外婆早就被大灰狼杀害，大灰狼把外婆的血肉充当晚餐和美酒让我吃下，晚上让我陪她睡是恋童癖。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b1bf05333816","srcNo":243,"title":"009 · 外卖","dispTitle":"009 · 外卖","surface":"\"喂，您的外卖到了。\" 什么外卖，我没叫过外卖啊。你问妹妹，她摇头。你又问女朋友，她惊恐地摇了摇头。正当你想要拒绝外卖小哥时，门外冲进来几个壮汉，一把把你按倒在地。","truth":"这是一名伪装成外卖员的警察。屋子里是一个传销组织，主角把自己的妹妹和女朋友都骗进了组织，女友偷偷报了警。警察送了你一副银手镯。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b1e8df709af4","srcNo":315,"title":"087 · 画像","dispTitle":"087 · 画像","surface":"一位艺术家为自己画了一幅自画像，画完之后，他死了。","truth":"这位艺术家双目失明，他凭借多年绘画的肌肉记忆，为自己画了最后一幅自画像。画完之后，他心满意足地闭上了眼睛，停止了呼吸——他提前服下了安眠药，只想在完成作品后安详地离去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b2877d60b36b","srcNo":263,"title":"032 · 粉色连衣裙","dispTitle":"032 · 粉色连衣裙","surface":"你的新邻居是一个独居的年轻男人，有一天你看到一个穿粉色连衣裙浓妆艳抹的长发女人进了邻居家门。深夜，隔壁传来争吵摔东西的声音。第二天你在邻居家门口的垃圾袋里看到了被剪碎的粉色连衣裙和一把长发。你要报警吗？","truth":"邻居是一个有异装癖的男人，因此一直独身。邻居的家人一直催他结婚，他便搬出来独住。这天邻居女装打扮回家，被你看见了。没想到邻居的妈妈早就在家里等他，看到女装的儿子，两人大吵一架，妈妈剪碎了裙子和假发。并没有发生任何犯罪。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b2a5f5e847bf","srcNo":1354,"title":"","dispTitle":"无题 · boop-yyt #1354","surface":"A flash of light, a man dies. How could this be?","truth":"The man is a lion-tamer, posing for a photo with his lions. The lions react badly to the flash of the camera, and the man can't see properly, so he gets mauled.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b2b973ea17e7","srcNo":856,"title":"保姆","dispTitle":"保姆","surface":"保姆已经一周没来了，但我发现家里好像有人。可能是害怕的原因，我每天都会掉头发，口臭，几天后警方发现了我和保姆的尸体。","truth":"我是一个梦游症患者，梦游时将保姆杀死，把她的尸体扔进别墅的水箱里。水箱中的尸体慢慢腐烂，保姆的头发随着水管流出，我洗头时误以为自己掉头发；喝水吃饭时因为喝的是尸水，所以觉得口臭。几天后，我梦游走到水箱前失足掉了下去，也死了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b2e6b0296473","srcNo":1029,"title":"逃出生天","dispTitle":"逃出生天","surface":"犯人策划了完美的越狱：躲进死掉囚犯的棺材，等送去墓地埋葬后，同伙再把他挖出来。当他躺在漆黑的棺材里得意地划着火柴时，他突然绝望地嚎哭起来。","truth":"火柴的光让他看清了身边尸体的脸——那是说好要来挖他出来的同伙。同伙心脏病发先死了，现在他被活埋在地下，没人知道他在里面。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b300a2af7f37","srcNo":844,"title":"被困的大哥","dispTitle":"被困的大哥","surface":"三兄弟和别人打架，大哥被关了起来，三弟手足无措，二哥叫来了一堆社会上的朋友救了大哥，然后又和对面干起来了，后来对面大哥来了，双方达成和解。","truth":"对应《西游记》第五十三难“小雷音遇险”。师徒四人在小雷音寺遇难，唐僧被抓走，孙悟空被黄眉大王困于金铙之中无法逃脱，沙僧吓得手足无措，八戒上天庭找来二十八星宿帮忙。亢金龙将金铙钻出小孔，孙悟空得以逃脱，之后与黄眉大王大战三百回合，幸得弥勒佛亲临，联手制服妖怪，化解危机，师徒四人才得以上路。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b35268fe3a24","srcNo":1252,"title":"最高的按钮","dispTitle":"最高的按钮","surface":"男孩第一次按到了电梯最上排的按钮，母亲当场哭了。为什么？","truth":"男孩此前因为疾病长期无法站立，术后这是他第一次自己站起来伸手按电梯按钮。母亲是喜极而泣。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b3d5fa575635","srcNo":1046,"title":"永生者的悲哀","dispTitle":"永生者的悲哀","surface":"一个男人在深海中沉睡了千年，醒来后他看到阳光，发出了绝望的惨叫，然后拼命想把自己再次淹死。","truth":"这个男人拥有不死之身，但他被诅咒永远无法离开水。阳光代表海水已经干涸。在干旱的地球上，他将承受永恒的干渴、灼烧和饥饿，却永远无法死去。他怀念大海是因为那是他唯一的避难所。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b3df136fb55a","srcNo":1007,"title":"看不见的观众","dispTitle":"看不见的观众","surface":"一名演员在空无一人的剧场排练，谢幕时他听到了雷鸣般的掌声，他脸色惨白地逃走了。","truth":"因为这个剧场是专门为盲人设计的音频剧场，或者是他意识到掌声是从天花板内部（通风管）传出来的。最经典的解释是：他排练的是独角戏，且剧场是全封闭的，如果不该有人却有掌声，说明“看不见的东西”在看他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b3f20408ff90","srcNo":1260,"title":"镜子里的第二盏灯","dispTitle":"镜子里的第二盏灯","surface":"女人半夜醒来，看见梳妆镜里比房间里多出一盏灯，立刻抱着孩子冲出门。为什么？","truth":"那不是房间里“多出来”的灯，而是藏在衣柜里的人打开了手电。她正面看不到，但镜子刚好照出了衣柜缝隙里的光。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b444081699d5","srcNo":125,"title":"","dispTitle":"无题 · KONpiGG #125","surface":"她走到了一栋房子面前，她明白，自己马上就将回天无力了","truth":"她在玩大富翁，但是已经快破产了，经过了别人的房子，然后就输了","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b489becab7a5","srcNo":991,"title":"最后一张照片","dispTitle":"最后一张照片","surface":"一个业余登山者在雪山里失踪了。一年后，搜索队找到了他的尸体和相机。相机里最后一张照片是天空，但他却是吓死的。","truth":"他在雪山上迷路，躲进了一个冰洞。他听到外面有救援队的声音，拼命呼救却没人听见。由于极度寒冷和绝望，他想用闪光灯吸引注意。拍照时，闪光灯瞬间照亮了洞顶，他发现洞顶挂满了因低温保存完好的、以前失踪者的尸体，他被吓到心脏骤停。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b4a2db900172","srcNo":1023,"title":"电梯里的对话","dispTitle":"电梯里的对话","surface":"两个人在电梯里闲聊。A问：‘你什么时候发现的？’B答：‘就在刚才。’然后A杀死了B。电梯门打开时，A自首了。","truth":"两人是合伙犯罪。B刚才在电梯里通过楼层按键的反光发现了A怀里藏着的凶器，知道A要杀自己灭口。A意识到B发现了，于是提前动手。A自首是因为电梯门一开，外面站满了警察，他知道跑不掉了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b4bb38aae375","srcNo":1106,"title":"图书馆的低语","dispTitle":"图书馆的低语","surface":"图书馆里总是能听到有人在低语，但管理员找了一圈却没有人说话。","truth":"一个学生用录音设备在角落播放事先录好的内容，想吓唬人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b5453b953650","srcNo":70,"title":"","dispTitle":"无题 · KONpiGG #70","surface":"哒..哒...哒....咚咚咚哒....哒...哒..哗啦哗啦哒..哒…哒…..\"我找到你了哦\"","truth":"我刚刚不小心目睹了一起杀人案，杀手发现了我后一直追着我，情急之下我躲进了卫生间，听着杀手的脚步声\"哒哒哒\"越来越近，我害怕的不敢出声，好在没多久\"哒哒哒\"的声音逐渐变小了，杀手应该已经走远了，我逐渐放下心来，可一不小心碰到了厕所的冲水装置，哗啦哗啦的水流声又引来了杀手，杀手低下头，从门低的缝隙看进来说道:\"我找到你了哦\"(哒后面的..越多，表示声音越大，杀手离我越近。咚咚咚是杀手敲厕所门的声音）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b560a80af76b","srcNo":1288,"title":"","dispTitle":"无题 · boop-yyt #1288","surface":"The music stops and a woman dies. What happened?","truth":"The woman is confined in an iron lung, and the music is playing on her radio or stereo. The power goes out.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b5ad3b194605","srcNo":246,"title":"012 · 武术生","dispTitle":"012 · 武术生","surface":"苏亚和劳拉即将毕业，决定一起去旅游。乘大巴行驶在盘山公路上时，树林中突然窜出一帮劫匪，全车人惊恐万分，唯独苏亚和劳拉异常兴奋，这是为什么？","truth":"苏亚和劳拉是武术学校毕业的学生，平时苦于没有表现机会，看到劫匪终于能大展拳脚了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b5adb2443c5b","srcNo":1316,"title":"","dispTitle":"无题 · boop-yyt #1316","surface":"The light goes out and a man dies. What happened?","truth":"A man commits a heinous crime, claiming as his alibi that he was onboard a certain ship. When he learns that (due to a lighthouse failure) the ship was wrecked without reaching port safely, he realizes that his alibi is disproven and commits suicide to avoid being sent to prison.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b5e2220c95d0","srcNo":323,"title":"097 · 水草（经典版）","dispTitle":"097 · 水草（经典版）","surface":"男子和女友河边散步，女友落水，男子下水寻找未果，伤心离去。多年后故地重游，得知此河从未长过水草，男子跳河自尽。","truth":"当年男子在水中抓到一把\"水草\"随手松开了，那其实是落水女友的头发——他亲手放弃了救她的最后机会。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b635057dc9b7","srcNo":1247,"title":"门口的快递","dispTitle":"门口的快递","surface":"女人出差回家，看见门口早上的快递箱还原封不动地挡在门前，立刻知道丈夫昨晚根本没回家。为什么？","truth":"她家入户门是向外开的，只要有人回家开门，挡在门前的快递箱一定会被碰倒或移开。箱子原样未动，说明丈夫根本没进过门。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b68eb4ecad9f","srcNo":132,"title":"","dispTitle":"无题 · KONpiGG #132","surface":"有一天，约翰到监狱里探望乔治。接着约翰回家后就死了，而乔治却获释自由。","truth":"乔治和约翰两人是网球双打同伴，所以两人相依为命，但是其实只有约翰是这么想的，乔治并不把他当做朋友。后来乔治因杀人嫌疑入狱，入狱前他将一瓶毒酒和一张照片藏在了家中柜子后方。有一天，约翰到监狱里探望乔治，乔治知道约翰有酗酒的习惯，就跟他说：我珍藏了一瓶好酒，想给你，本来想亲手给你的，但是现在却不行了，我把酒放在了柜子后方。另外酒旁有一张我和你去年夺冠的照片，我希望我出狱前你能替我好好保管那张照片。\"约翰回去后果然发现有这两样东西，激动之余握着这张照片，但看不懂照片后面写的西班牙语文字，他认为是乔治的祝福话语，接着灌下了这瓶毒酒打算借酒消愁，于是就这样被毒死了。但是照片后写着的话其实是\"人是我杀的，不是乔治，我才是凶手\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b69913650fdf","srcNo":280,"title":"051 · 棺材里的死人","dispTitle":"051 · 棺材里的死人","surface":"在一条乡村路上，五个人走在一起，天突然开始下雨。五个人中有四个人加快了脚步，第五个人一点都不担心。最后五个人同时到达了目的地。加快脚步的四个人都淋湿了，而第五个人一点都没湿。这是怎么回事？","truth":"第五个人是死人，待在棺材里，被那四个人抬着走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b70036a88d5c","srcNo":1221,"title":"Jed 1.78","dispTitle":"Jed 1.78","surface":"A woman has incontrovertible proof in court that her husband was murdered by her sister. The judge declares, \"This is the strangest case I've ever seen. Though it's a cut-and-dried case, this woman cannot be punished.\" (This is different from #1.11.) (MH; from _How Come?_)","truth":"The sisters are Siamese twins. 1.78a. Variant: A man and his brother are in a bar drinking. They begin to argue (as always) and the brother won't get out of the man's face, shouting and cursing. The man, finally fed up, pulls out a pistol and blows his brother's brains out. He sits down to die. 1.78a answer: They are Siamese twins. In the original story, the argument started when one complained about the other's bad hygiene and bad breath. The shooter bled to death (from his brother's wounds) by the time the police arrived. (RW, based on a 1987 _Weekly World News_ story)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b7523df2ab20","srcNo":1364,"title":"","dispTitle":"无题 · boop-yyt #1364","surface":"Variant wording: A man sends a package to someone in Europe and gets a note back saying \"Thank you. I received it.\" How could this be?","truth":"This is just a simpler version; the shipwreck situation is the same, and the man actually did send his own arm.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b75ce1bb7f98","srcNo":201,"title":"","dispTitle":"无题 · KONpiGG #201","surface":"今天哥哥脸上受了伤，我生气极了！夜里，一模一样的伤口出现在我的脸上。滴答，滴答，从此，哥哥再也不会受伤了。","truth":"我和哥哥是双胞胎，我们长得一模一样。但我们都极其讨厌世上有如此相似的存在，我们都想让另一方\"消失\"。因此我们共用一个身份，在别人眼里我们就是\"唯一\"，我们约定好一个人出去一天。这天哥哥回来，故意在脸上受了伤，我很生气。如果明天我想出去，就必须在脸上的同样位置划一刀伤口。夜里哥哥熟睡后，我比对着朝脸上划了一道一样的伤口。鲜血顺着刀尖对准哥哥的心脏插了进去，以后，我就是真正的\"唯一\"了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b7c5a3a3b8cd","srcNo":733,"title":"诡异的记号","dispTitle":"诡异的记号","surface":"留学回家发现门旁被写了“X”，擦掉后又出现。夜里邻居家动画片声很吵，我去理论。次日门上X变成O，我疑惑时邻居开门，我意识到危险来了。","truth":"前段时间楼下一个小男孩被高空坠物砸死，他的父亲一直没找到凶手，伸冤无果的他便把整栋楼里的人都视为了凶手，他挨家挨户的进行了报复并留下记号，X代表已经报仇和无人居住，而O代表即将要下手的人家，因为之前我留学在外，邻居以为我家没人，而当我回国后，被邻居家的动画片声吵到并上面理论时，邻居发觉对面居然住的有人，随即变改了记号，第二天当我出门时，邻居也打开了房门把我抓了进去…...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b7f11aa92da7","srcNo":716,"title":"舞","dispTitle":"舞","surface":"六岁时爷爷去世，我去祭奠并和姐姐玩捉迷藏。我对妈妈说了一句话把她吓晕。我说了什么？","truth":"我去参加爷爷的葬礼，和姐姐比我大两岁。我和她玩完捉迷藏后，没有找到她。没想到她躲在纸做的房子里。当纸房被点燃时，我看到姐姐在跳舞。我对妈妈说，我妈姐在那所房子里跳舞，因为她被烧死了。我一直记得这件事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","恐怖","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b870f4f22820","srcNo":1315,"title":"","dispTitle":"无题 · boop-yyt #1315","surface":"A man urinates and dies. What happened?","truth":"He urinated on the third rail in the New York subway, was knocked onto the tracks by the shock, and was hit by a train and killed.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_b8c79189fb1d","srcNo":1108,"title":"神秘的考卷","dispTitle":"神秘的考卷","surface":"考试前一天，一张和考试一模一样的试卷出现在垃圾桶里。","truth":"老师不小心把样卷当成废纸扔了，被学生捡到后流传。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_b92193139356","srcNo":839,"title":"圣诞老人","dispTitle":"圣诞老人","surface":"圣诞节到了，我又来完成孩子们的梦想了。第一个孩子想唱歌，他做到了；第二个孩子想去旅行，于是我送他环游世界，但他却被吃掉了；第三个孩子喜欢玩躲猫猫，于是我帮他藏起来，警官都找不到他，不过他明年自己就会出现。","truth":"我是一个患有精神疾病的肉联厂工人，常年穿着血红色的衣服，于是将自己幻想成圣诞老人，帮孩子“完成梦想”。第一个孩子是哑巴，为了让他“唱歌”，我将他的皮做成鼓并敲响；第二个孩子想环球旅行，我把他搅碎做成罐头发往全世界；第三个孩子喜欢躲猫猫，我把他做成雪人，警官都找不到，等明年春天积雪融化，大家就能发现他了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ba0a80d94a62","srcNo":1145,"title":"红衣","dispTitle":"红衣","surface":"奔形回来后，室友和我说学校最近闹鬼了，好多人都梦到了一个红衣服的人对着你笑。\n晚上，我也梦到了，可我看清他时，却觉得眼熟。直到第二天晚上，我终于明白。","truth":"我参加完奶奶的葬礼回到学校，室友说学校闹鬼六很多人梦到穿红衣服的人笑。晚上我\n也梦到了，觉得红衣服很眼熟。第二天晚上梦到奶奶，终于明白:. 那件红衣服是寿衣，梦里的\n人都是穿寿衣的死者 ! 调查后发现，学校食堂和殡仪馆勾结，低价进尸体做成饭菜，我们都误\n食了死者的肉一一我梦到的奶奶，尸体也被卖到了食堂;","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ba1afde7ba05","srcNo":1300,"title":"","dispTitle":"无题 · boop-yyt #1300","surface":"A woman is murdered in front of hundreds of people, but they all think it's an accident. What happened?","truth":"The woman is a trapeze artist who times her act (from starting time to time to jump for another trapeze) by the music. The organist changes tempo or stops the music too soon, and the trapeze artist falls to her death.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ba1bc66986a7","srcNo":1019,"title":"最好的礼物","dispTitle":"最好的礼物","surface":"圣诞节，贫穷的妻子卖掉了自己引以为傲的长发，为丈夫买了一条昂贵的白金表链。回到家，她发现丈夫卖掉了祖传的金表，为她买了一套精美的发梳。","truth":"这是欧·亨利式的经典。两人都为了对方牺牲了自己最珍贵的东西，结果换来的礼物在当下都失去了原本的用处。这份‘无用’的礼物却证明了完美的爱。（注：此汤常用于测试玩家是否读过原著）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bafb21fa5402","srcNo":923,"title":"倒计时：7天","dispTitle":"倒计时：7天","surface":"第一天家里有一盒录像带，我观看后发现是经典电影《半夜恶铃》中贞女爬出电视机那一段。据说看了这个录像带的人都会先接到一通电话，除非又有别人观看，不然你就会在七天后死去。午夜时分，电话铃声响起，随后家里真的闹鬼了！第二天我在持续遇到灵异事件，我必须尽快解决，明天妻儿就回来了。一位大师和我说：”</span>必须找到源头，用同样被诅咒过的人进行仪式，方可化解“ 第五天我到岛国找到了贞女所在的那口井，并进行了仪式，我付出了很多，希望能活下来。第七天怎么回事！贞女还是出现在我家里！！我必须活下去，无论任何方法。","truth":"第一天妻子和儿子这几天回老家了，我在收拾房间时发现了一盒录像带，我观看后发现是经典电影《半夜恶铃》中贞女爬出电视机那一段。据说看了这个录像带的人都会先接到一通电话，除非又有别人观看，不然你就会在七天后死去。午夜时分，电话铃声响起，随后家里真的闹鬼了！第二天我这几天持续遇到了灵异事件，我找到了一位大师，他和我说：”要想彻底破解诅咒，必须找到源头，用同样被诅咒过的人进行仪式，方可化解。可我上哪里找另一个被诅咒的人？第四天经过调查我发现这盒录像带居然是妻子为了摆脱诅咒传递给我的，没想到她居然这么恶毒！今天她和儿子回来了，于是我准备明天就进行仪式。第五天我假借旅游的名义把妻子带到了岛国。我找到了贞女所在的那口井，将妻子推了下去，并进行了仪式。第七天怎么回事？贞女为什么还会出现在我家？难道是我的仪式发生了问题？我再次找到大师，他告诉我他的方法绝对有效，除非源头有问题。什么意思？贞女并不是一直缠着我的鬼？那这个鬼是？在大师的帮助下，我在一张旧报纸中找到了真相：原来，当年在电影中扮演贞女的那名演员意外死在了片场。她的怨气很重，因此死后化成了鬼。我已经没有进行仪式的时间了，不管怎么样，我必须活下去！我看向刚刚下班回家的儿子……第八天清晨，我果然安然无恙。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bb122a333cab","srcNo":990,"title":"末班电车","dispTitle":"末班电车","surface":"一个女人在半夜坐最后一班电车。车厢里除了她，还有三个人：两个男人架着一个神色呆滞的女人。女人中途下车后，发现那两个男人一直在对她笑。","truth":"那个神色呆滞的女人其实已经死了。那两个男人是杀人犯，他们架着尸体是在伪装。由于那个女人下车时发现尸体的脚是悬空的（或者没影子），凶手意识到她发现了真相，那个笑容是死亡的威胁。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bb9cfe3405ab","srcNo":832,"title":"海龟汤","dispTitle":"海龟汤","surface":"一名男子到餐厅点了一碗汤，因为觉得汤里的肉吃起来很特别，所以询问了店家这是用了什么肉。店家告诉他，这是用「海龟肉」做的海龟汤，男子听完后便痛哭失声，且在那之后自杀了。请问是为什么？","truth":"男子在数年前与恋人一同遭遇海难，在海上漂流了一阵子，甚至差点饿死。在最危急的时候，恋人做了一碗海龟汤给男子，欺骗男子其中的海龟肉是从海中猎获的。这碗救了男子","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_bba7971702d6","srcNo":604,"title":"为了再见到他","dispTitle":"为了再见到他","surface":"母女三人，妈死姐妹参加葬礼，妹见帅哥一见钟情。一个月后妹杀姐。为什么？","truth":"因为家里如果再死一个人，又可以举行一次葬礼，那个男子又会来参加葬礼，妹妹就又可以见到他了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["搞笑"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_bbca4242fa35","srcNo":368,"title":"期末考试","dispTitle":"期末考试","surface":"转学后这一个月,所有同学都认为我精神不正常,大家都排挤我。只有老师不这么想,可期末考试成绩下来后,我明白我真的不正常了....","truth":"我天生拥有阴阳眼，却自己不知道。刚转学后，只有同桌对我特别友好，其他同学都觉得我精神不正常，因此排挤我。直到我在班级里叫出同桌的名字，老师才惊恐地发现我不是精神病——原来那个对我友好的同桌根本不是人，而是很多年前死在这所学校的学生，其他同学都看不到他。老师刚任教时就听说过学校的灵异事件，所以知道真相，却没敢告诉我。直到期末考试成绩发下来，我发现榜单上没有同桌的名字，结合之前同学的态度，终于明白自己确实和正常人不一样。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bbd785a01be1","srcNo":71,"title":"","dispTitle":"无题 · KONpiGG #71","surface":"邻居叔叔到学校通知我妈妈生病了，给我吃糖，安慰我。第二天我结婚了。","truth":"邻居叔叔以妈妈生病为理由将\"我\"带出学校。给\"我\"吃了安眠药，火化，卖给别人，给一个男孩配冥婚。（真实事件改编）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bc5e94bb9387","srcNo":230,"title":"车头灯关闭","dispTitle":"车头灯关闭","surface":"两个男人在车头灯关闭的情况下朝对方行驶。看不到月亮或星星，附近也没有电灯。两辆车都漆成黑色，没有反光表面。然而两人都知道何时该踩刹车并险些避免撞到对方。这怎么可能？","truth":"现在是白天。 （而且今天是阴天，这就是为什么我们称之为太阳的恒星看不见的原因。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bc897458acc1","srcNo":184,"title":"","dispTitle":"无题 · KONpiGG #184","surface":"我和热恋中的女友去爬山，在山顶女友对我说了句话后，把我推了下去，我惊恐万分却并不怪她.","truth":"我想自杀却对自己下不去手，无意间登录了一个网站，在这上面可以预约意外死亡，抱着试一试的态度，我填写了预约信息，过了很长一段时间，\"意外\"都没有到来，我便以为这是个虚假网站。后来，我爱上了一个女孩，我们一起去爬山，在山顶上我向女孩表明了心意，女孩抱住我在我耳边低语，\"我也爱你，但是，预约死亡不能取消\"便把我推下了山。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bcc2cc005fc0","srcNo":1020,"title":"看不见的杀手","dispTitle":"看不见的杀手","surface":"一个男人死在密闭的冰室里，死因是胸口中箭。室内没有其他人，没有发射装置，门窗从内部锁死。","truth":"凶手在冰室外，利用冰制成了一个透镜（凸透镜）。凶手等太阳升到特定角度，利用冰透镜聚焦阳光，烧断了室内原本固定好的拉力机关（或引燃火药），箭矢射出后，冰透镜也随着温度升高融化成了水，消失不见。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bcda5d38f4bf","srcNo":255,"title":"022 · 签名","dispTitle":"022 · 签名","surface":"一名男子A请另一名男子B在纸上签上名字，随即杀死了B，为什么？","truth":"男子B是名知名歌手，男子A想要他的最后一张签名，炒个绝版签名高价。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bded913b3824","srcNo":138,"title":"","dispTitle":"无题 · KONpiGG #138","surface":"母亲死了，两个女儿参加他的葬礼，妹妹见到一个认识她们家的英俊的男子，与其交谈，回家后把姐姐杀了，为什么？","truth":"姐姐死了也要办葬礼，这样的话，妹妹就可以再见到那个男子了","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_be036d1a868e","srcNo":1096,"title":"绿鞋子","dispTitle":"绿鞋子","surface":"一个女孩买了一双绿鞋子，穿了一段时间后她自杀了。","truth":"她暗恋一个男孩，男孩说喜欢穿绿鞋子的女孩。她买了鞋子后男孩和另一个穿绿鞋的女孩在一起了，她意识到男孩只是随口说的，绝望自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_be2920661cad","srcNo":190,"title":"","dispTitle":"无题 · KONpiGG #190","surface":"生活拮据的孤寡老人杰克，被发现死在家中，生前好像正在吃饭，尸体被发现时已经残缺不全，而尸体周围的景象也十分诡异。推故事全貌和诡异景象是什么。","truth":"老人养了很多流浪猫，邻居感觉很臭又扰民，在鱼里下了毒，告诉老人鱼快坏了，给猫吃。老人认为鱼还很新鲜，自己做了吃了，毒死，猫被锁在家里，没吃的吃了有毒的尸体也死了，后来臭味太大被人发现。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bee4ceb14af5","srcNo":858,"title":"兄妹","dispTitle":"兄妹","surface":"我家楼上住着一对兄妹，哥哥十分开朗，妹妹沉默寡言却是一个知名主播，我每天都会看她直播。我很喜欢她，终于有一天她注意到我了，我喊了四个字，现在她每天除了直播都会陪着我了。","truth":"我是一个变态，一直喜欢这位女主播，于是潜入她家藏在床底下，每天偷窥她直播。可我不知道，每天直播的其实是她的双胞胎哥哥——哥哥因为喜欢妹妹，将她囚禁起来，还扮演她生活、直播。有一天，妹妹在挣扎中被哥哥失手误杀，头垂到地上，正好与床底的我对视。我吓得下意识大喊“哎呀我操！”，被哥哥发现。哥哥将我杀死后，把我和妹妹的尸体埋在了一起。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bf0a44412d29","srcNo":1343,"title":"","dispTitle":"无题 · boop-yyt #1343","surface":"On a cold winter's day, drivers found that sheep from the fields nearby kept coming onto the road. There was no snow and the road was not warmer than the fields but whenever the sheep were ushered back to the fields they quickly returned to the road. Why?","truth":"The sheep kept coming to the road because they liked to eat the salt put on the road to stop it freezing.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_bf249bb05242","srcNo":47,"title":"好孩子","dispTitle":"好孩子","surface":"爸爸把地面弄脏了，妈妈又不想做饭了，这么大的人了，还是这么顽皮，不像我，我要做一个好孩子。","truth":"我是一个孤儿，当初我的父母嫌我不听话而抛弃了我，所以我发誓一定要做一个好孩子。现在的爸妈领养了我，我努力听话，但是他们还是觉得我不合适，要把我送走。爸爸的血流了一地，把地面都弄脏了。妈妈在厨房里一动不动，看样子是做不了饭了。我看着自己沾满了鲜血的双手，我很开心，一个好孩子是不会被抛弃的，看来我还是一个好孩子呢!","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bf6dc1df19ca","srcNo":876,"title":"姥姥的葬礼","dispTitle":"姥姥的葬礼","surface":"2月20号姥姥去世了，我和爸爸妈妈回到乡下参加姥姥的葬礼，夜晚在老宅睡觉的时候，我被姥姥家大黄狗的叫声吵醒，我好像听到院子里有人在劈柴。2月21号守灵的时候，爸爸悄悄和我说：你晚上自己住，妈妈好像有些不对。晚上我去看妈妈，妈妈抓着我说：“你爸爸有问题。明早我们就走！2月22号今天妈妈看起来恢复正常了。可在吃饭的时候，我还是发现了问题，我悄悄和爸爸说了我的发现，爸爸告诉我他有办法解决！2月23号太棒了！爸爸果然解决了问题，只不过他不再去健身房。妈妈也不再化妆了。","truth":"2月20号姥姥去世了，我和爸爸妈妈回到乡下参加姥姥的葬礼，晚上住在了老宅，老宅有一面大镜子，映射了我们一家，晚上，大镜子中居然钻出和爸爸一模一样的人！他偷偷将爸爸杀害，并将爸爸分尸喂给姥姥家的大黄狗吃掉，以此毁尸灭迹。我和妈妈并不知道，此时我的爸爸已经被替换了。2月21号凭借多年的了解，妈妈已经意识到爸爸不对劲了。她和我说我们得逃走，而”爸爸“却提前和我说了妈妈不对劲，以此离间我们，我相信了爸爸选择一个人睡觉，然而却给”妈妈“留下了杀妈妈的时间，他们如法炮制，把真正的妈妈又一次喂给了大黄，此时我的妈妈已经被替换了。2月22号我并不知道妈妈被替换的事实，还以为妈妈恢复了正常，但在吃饭的时候我发现，炖肉里居然有妈妈的婚戒，而现在”妈妈“手上居然也戴着婚戒！原来假爸妈将大黄做成炖肉给我们吃。大黄也已经被替换了，但是大黄并没有消化那枚佩戴在妈妈手上的婚戒！我不知情，并把我的发现告诉了爸爸，他告诉我他有办法解决！然而他的解决办法，就是将我一同替换掉，换成他”真正“的儿子。2月23号太棒了！我们一家终于成功替换了现实世界的他们！只不过爸爸不再去健身房，妈妈也不再化妆。因为本属于镜子中的我们，自然没办法继续照出镜子中的样子。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_bfb3adb2480e","srcNo":1034,"title":"被诅咒的宝藏","dispTitle":"被诅咒的宝藏","surface":"探险家在沙漠发现了一具尸体，手里拿着一张地图，他看了一眼就说：‘他是渴死的，但他身边明明有水。’","truth":"那个人身边确实有水，但那是‘仙人掌’里的水，或者是他死在了一片绿洲边，但他并不知道那是海市蜃楼，最终绝望而死。最简单的解释是：那是海水，不能喝。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c026a4977b0e","srcNo":1218,"title":"Jed 1.65","dispTitle":"Jed 1.65","surface":"A man was walking down a road when a stone lodged itself between his foot and his sandal. He leaned against a pole and, with his head down to watch, he shook his foot to dislodge the stone. Another man came up and broke the first man's arm in three places.","truth":"The chap shaking his foot to dislodge the stone was leanig against a metal light pole. The other fellow came along and thought that the pole had become 'live' somehow; he thought the first fellow was being electrocuted (and that the muscles in his hand had contracted and he couldn't let go). So the second fellow rushed over and whacked the first one on the arm, hard. He apologised for it afterwards. (A true story, from an Australian newspaper.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c08749d6852f","srcNo":1092,"title":"","dispTitle":"无题 · zhuqingxu #1092","surface":"乐团排练结束后，一名乐手死在从内反锁的练习室内，钥匙落在室内一侧地面，外窗有铁栏。保安破门时门仍锁着。次日清点少了一只大型低音提琴硬壳箱。案件与这只箱子有关吗？","truth":"有关。凶手作案后躲进可容纳一人的大型低音提琴硬壳箱，同伙在混乱中按「正常搬运乐器」把箱子运出建筑，凶手无需钻窗或从正门独自离开。失踪的箱子就是运人工具。\n\n---\n\n 8. 假面舞会的号码牌\n\n| 字段 | 内容 |\n|------|------|\n| id | masqueradenumberswap |\n| 难度 | medium |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c0c1ebca2d3f","srcNo":1063,"title":"盲人的选择","dispTitle":"盲人的选择","surface":"三个盲人分一个蛋糕。他们约定每人切一块，剩下的留给第四个没来的朋友。切完后，其中一个盲人突然疯狂地攻击另外两个。","truth":"这三个人其实是在荒岛上。他们约定的不是切蛋糕，而是“切下自己身体的一部分”来维持生命。那个发疯的盲人发现另外两个人在切他的时候用了重手，而他们自己切的时候只是轻描淡写（通过触摸分量判断），他意识到自己被欺骗并作为了牺牲品。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c0c2a9b3d148","srcNo":1227,"title":"Jed 2.3","dispTitle":"Jed 2.3","surface":"A man pushes a car up to a hotel and tells the owner he's bankrupt. (DVS; partial AL and JM wording)","truth":"It's a game of Monopoly. 2.3a. Variant: The car came out of the blue and the man came into some money. 2.3a answer: The same; in this case the car token passes Go and the player collects $200. (from \"Mo,\" whose full name I missed)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c12cc7f868a8","srcNo":627,"title":"滴水声与狗","dispTitle":"滴水声与狗","surface":"女孩半夜听见天花板滴水声，摸床边狗舔手才安心睡。第二天发现狗被吊死在天花板，滴的是狗血。","truth":"女孩以为床下一直陪着她的是狗，实际上狗早在那晚之前就被潜入家中的凶手杀害并挂在洗手间滴血。整晚在床下舔她手的其实是那个凶手。这是一个经典的认知错位反转。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":1,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c19374c2a84a","srcNo":233,"title":"鱼缸","dispTitle":"鱼缸","surface":"我养了一缸热带鱼。昨天我给鱼缸换了水，用的是刚买的矿泉水。今天早上，鱼全死了。","truth":"我把鱼缸里的水一次性全换成了矿泉水。新水没有困过、没有调温，水温跟鱼缸差很多，水质也突变，鱼承受不住直接应激死了。问题不在矿泉水干不干净，在于换水方式太粗暴。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常"],"difficulty":1,"src":"github:AZHi-xinxin/haiguitang-coop","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c2201ff1856c","srcNo":160,"title":"","dispTitle":"无题 · KONpiGG #160","surface":"\"隔壁好像搬来了一对情侣，当天晚上那个男人来找我借散粉，我没借给他，第二天却发现那个男人死在了屋子里，死相极其难看。\"","truth":"这个男人是一个化妆师，他精神分裂，总是幻想着自己有一个女朋友，每天晚上都要给\"女朋友\"化妆，结果搬家那天，他没带散粉，找邻居借也没有借到，化的妆没有达到他心目中的水平。他很惭愧，于是他想了个办法，他把自己的面皮割下来套在模特假人的头上，把模特佳人当成自己的女朋友，这样即使没有化妆，他也比\"她\"更丑了。因为本身男人给\"女朋友\"化妆的意义，就是想让她比自己更美，既然化妆达不到目的，就只有让自己变得更丑，才能让\"她\"比自己更美。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c2569b43131f","srcNo":65,"title":"","dispTitle":"无题 · KONpiGG #65","surface":"两个宇航员a、b从太空回来，发现地球上只剩他们两个人，某天b死了，地球上人都回来了，a尝试跟他们对话后自杀了。请推断自杀的原因","truth":"因为唯一的伙伴b死掉了所以因为太孤独产生地球人回来了，但是发现这只是自己的幻想，最后绝望自杀","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c29ae01ecae9","srcNo":279,"title":"050 · 双胞胎替换","dispTitle":"050 · 双胞胎替换","surface":"我一回家就立刻替死去的妹妹写遗书，对我来说，替她写遗书是很简单的，只要写下我想死的心情就好。","truth":"我和妹妹是长相一模一样的双胞胎，妈妈只宠爱妹妹，虐待我。某天妹妹在妈妈房间弄坏了东西，拿走我的书想栽赃给我。放学路上我碰到妹妹，谎称妈妈已经发现了，并骗她和我交换衣服，说我可以替她接受惩罚。妹妹答应了，先行回家。我到楼下时，某样物体从上方扑通落下——穿着脏衣服、和我一模一样的脸贴在地面上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c2f7a15f6c05","srcNo":790,"title":"分手","dispTitle":"分手","surface":"新闻报道一座雪山发生雪崩，以下是一段录音，请推理完整故事线：男「我们分手吧。」女「这是最后了？」男「嗯……」女「谢谢你，一直都给我这么多。」男「忘了吧，我们都需要新的开始。」","truth":"因为雪崩里有三个人被困在雪山里，食物慢慢耗尽。为了生存，男人和女人不得不一起杀死第三个人作为食物。分手实","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","推理","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c3e4256b231a","srcNo":202,"title":"100元钱","dispTitle":"100元钱","surface":"小明在图书馆看书，在一本书里翻到了100块钱，但是他却哭了。","truth":"小明是一个不火的作家，他在图书馆自己写的书里放了张100元，如果有人看到就会拿走表示有人看了他的书，而至今这100还是夹在书里，表示至今都没有人看过小明的书，于是小明哭了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c3ee67ea38bd","srcNo":176,"title":"","dispTitle":"无题 · KONpiGG #176","surface":"一个男人在路上走着，突然冲进电话亭打了一个无人接听的电话，之后心满意足的离开了，他在做什么？","truth":"男人是作曲家，他给自己家的固定电话打电话，利用电话录音留下一时的灵感想出的旋律。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c3fe6268a938","srcNo":848,"title":"美人鱼","dispTitle":"美人鱼","surface":"小美人鱼生活在自己的宫殿里，有一天，人类的王子落入了水中，被一条粉色的水蛇咬死了，过了好久，宫殿里没有其他食物，她只好把水蛇和王子都吃掉了。可能是吃撑了，她的肚子越来越大，最后被撑死在了水面上。水面上飘起了红色的水花。","truth":"男人得知妻子劈腿并怀上情夫的孩子，怒不可遏，将妻子的双腿缝在一起，丢进很深的蓄水池，让她像一条“不会劈腿的人鱼”。之后男人残忍杀害情夫，也扔了进去，情夫裸露的肠子像一条水蛇。水里没有食物，妻子只好吃掉情夫的尸体，最终因无法生育而难产死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c4187685b9d1","srcNo":1084,"title":"最后一名宇航员","dispTitle":"最后一名宇航员","surface":"宇航员在太空舱里已经待了五年，补给耗尽。他决定打开舱门自我了断。开门后，他没有飘向太空，而是听到了热烈的掌声。","truth":"这其实是一场长达五年的、关于人类心理极限的地面模拟实验。他从未离开地球，舱门外就是实验室的大厅。科学家们一直在观察他，但他因为过于真实的模拟和长期的孤独，真的以为自己在深空。掌声是庆祝实验成功，但在他看来却是最残酷的讽刺。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c56c62db40b5","srcNo":712,"title":"午夜列车","dispTitle":"午夜列车","surface":"离午夜还有五分钟，男子上车逐个猜对乘客年龄。问到婆婆时她说：不是，再过五分钟我才69。男子脸色惨白。","truth":"男子有超能力，可以预知人的死亡年龄，但是看不到自己的。男子上车后，看到车上的人看起来和自己死亡的年龄几乎都差不多，他觉得很奇怪，于是试探性地问了几个人，发现这些人都将在当年死去。问到婆婆时，意会过来五分钟后列车就会出事故，这一车的人都将死掉。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c5b078318d27","srcNo":127,"title":"","dispTitle":"无题 · KONpiGG #127","surface":"我躺在床上问妈妈：\"雪怪真的会来吗？\"妈妈说，只要你乖乖睡觉不下床就不会来。半夜，我见到了雪怪。但是，雪怪的原则，只有雪怪才会遵守。在看到雪怪的那一刻，我的结局就已经注定了。","truth":"父母优先于孩子被杀，被杀的时候父母没在睡觉，所以肯定有惨叫声，小孩是有机会跑的，但是他听了父母哄骗他上床睡觉的故事，不敢跑，错失了逃生的最后机会。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c67f366c50ed","srcNo":1392,"title":"","dispTitle":"无题 · boop-yyt #1392","surface":"An ordinary woman walks on water. How could this be?","truth":"It's easy to walk on a lake's surface when the lake is frozen.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c6df7b68bd53","srcNo":932,"title":"奇怪的爸妈","dispTitle":"奇怪的爸妈","surface":"星期日爸爸出差回来后抱着我哭了起来，我不明所以。晚上，我听见爸爸在院子里大喊“诡啊！！！”我很害怕，于是锁上房门等妈妈下班。星期三妈妈递给我一个定位手表，严肃地和我说：“你爸爸不对劲！尽量远离他。”爸爸下班后和我说：“你妈妈不对劲，爸爸一会带你走！”我不想走，爸爸却直接将我打晕了。星期四等我醒来，我发现我在一个山洞里，妈妈居然在这，她好像在埋什么，这有个大坑，她和我说：“儿子，走！回家了。”晚上妈妈找爸爸谈了好久，妈妈抱着爸爸大哭，爸爸脸色难看，但犹豫一下后还是安慰了妈妈。星期五今天爸爸带我去了游乐场，我玩得很开心。回家后妈妈做了大餐，但爸爸又突然脸色难看，久久无言。晚上妈妈久违的抱着我睡觉了。星期一爸爸下班回来后抱着我哭了起来“对不起。”爸爸说完这句话之后，我便没了意识。","truth":"星期六A世界某个家庭平常的一天被打破了。由于家里的儿子意外失踪（这里作者没详细说明，但应该是被其他世界的家人带走了），爸爸无意中来到了一个山洞，没想到这个山洞居然是连接其他平行世界的入口。就这样爸爸通过山洞来到了B世界。星期日B世界 A世界的爸爸回到家里发现他的儿子居然还活着，他抱着儿子痛哭起来。他也因此意识到他是从那个山洞来到了儿子还活着的平行世界。因此A世界的爸爸决定顶替B世界的爸爸活在这个世界。于是在当天晚上便杀掉了他。星期三B世界通过这几天的接触B世界的妈妈发现老公有些异常，于是她给儿子一个定位手表，并告诉他爸爸不对劲，尽量远离他。A世界的爸爸意识到B世界的妈妈发现了他有问题，于是他把B世界的儿子打晕，准备带着他逃回A世界。可这一切被B世界的妈妈知晓，她在山洞里将A世界的爸爸杀掉，夺回了儿子。可当B世界的妈妈带着儿子走出山洞，却发现他们来到了新的平行世界—C世界。星期四C世界 B世界妈妈为了带着儿子在这个世界活下去，于是杀掉了C世界的妈妈和儿子，把她们的尸体埋在山洞里，并替代了她们的身份。之后她将事情的真相告知C世界的爸爸。C世界的爸爸无奈只能想办法接受这两个人。星期五C世界 C世界的爸爸带着B世界的儿子去了游乐场玩。然而就在这时，A世界的妈妈居然闯入C世界。由于A世界的爸爸和儿子都离她而去。她每天过得魂不守舍，也在无意中通过山洞来到了这个平行世界。她发现这个世界的老公和儿子居然都活着。于是她杀掉了B世界的妈妈，顶替她在这里生活。等晚上C世界的爸爸回到家，发现妻子又一次变成平行世界的人，他有些崩溃。而A世界的妈妈也终于见到了她一直想见的儿子，虽然是平行世界的儿子。A世界妈妈动机：平行世界开启后，她的孩子老公接连消失，她每天过得魂不守舍，但也因为平行世界的开启，不同的她或老公会无意中来到这个世界。见无法组建家庭后又离开了。她也因此得知了去往平行世界的办法。于是她也想通过平行世界组建完整的一家，因此来到了C世界。星期一C世界 D世界的爸爸带儿子穿越到这个世界。在他的世界失去了妻子。于是他来到这个世界将C世界的爸爸和B世界的儿子杀掉。他准备带着儿子和平行世界的妻子在这里继续生活。可这一切真的就这样结束了吗？山洞设定：进入后再离开即完成穿越，穿越为随机穿越，并无法回到原本世界。注：ABCD只为方便大家理解，并不表示这几个世界相连。可能A是IOI宇宙，B是3宇宙，C是1744宇宙。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c7d9dd90b925","srcNo":105,"title":"","dispTitle":"无题 · KONpiGG #105","surface":"我和女朋友吵了一架，然后她和我都死了。","truth":"我与女朋友在天台约会，吵架过程中不慎把女友推下了天台，我趁没人发现赶紧逃离了现场，晚上我在家睡觉时，听到门口传来\"咚咚咚\"的声音，且这个声音越来越大，离我越来越近，我害怕极了，便躲在了床底，结果看到了女友倒立着的头，她的鬼魂来找我了！(女友从天台摔下来是头向下的，所以她的鬼魂也是头向下的，咚咚咚的声音是女友头碰地发出的声音，我躲在了床底，所以女友刚好可以轻松看到我。)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c824f2e2e39b","srcNo":101,"title":"","dispTitle":"无题 · KONpiGG #101","surface":"爸爸遇到了船难，儿子再也没动过了","truth":"爸爸在船难中失去了双臂，儿子其实是木偶，爸爸再也不能让儿子灵活移动了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c83298d35144","srcNo":1381,"title":"","dispTitle":"无题 · boop-yyt #1381","surface":"Two people are playing cards. One looks around and realizes he's going to die. How could this be?","truth":"The one who looks around sees his own reflection in the window (it's dark outside), but not his companion's. Thus, he realizes the other is a vampire, and that he's going to be killed by him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_c84fc1792640","srcNo":325,"title":"099 · 棺材里的人（经典版）","dispTitle":"099 · 棺材里的人（经典版）","surface":"五个人走在路上，下雨了，四个人加快脚步，一个人不急。最终五人同时到达目的地，四人淋湿，一人未湿。","truth":"第五个人是死人，躺在棺材里，被其他四人抬着走。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c86242207350","srcNo":937,"title":"欺诈师","dispTitle":"欺诈师","surface":"警探，这次你要审问的是一名欺诈师，他与正常人不同，哪怕在潜意识层他也会有三次对你说谎的机会，请注意辨别。以下是你的任务：1. 调查戴维死因 2. 追回历史文献 3. 找到他的三个谎言准备好了吗？我要开始进行意识链接了。欢迎X位来到我的精神世界，我将全力配合警方审讯。警探：查尔斯，你杀了最伟大的历史学家戴维，并偷走了刚出土的历史文献，你承认吗？查尔斯：是的，我承认。据说他发现了一个新的上古文明，文物价值连城，文献是能填补历史的空缺，谁会不心动呢？警探：历史文献被你藏在哪里了？查尔斯：当然藏在一个我一定会去的地方了。警探：你是怎么杀死戴维的。查尔斯：他让我杀死他的，我保证。警探：以上你的回答，全部属实吗？查尔斯：哈哈，当然不是了警官，我有三个谎言呢，你忘了吗？","truth":"警探们，我是查尔斯，欢迎观看汤底。探索了我的精神世界后，感觉如何？已被警探戳穿了三个谎言的我，只好供认不讳。死去的戴维实际上才是真正的我，我的真实身份是一名欺诈师，我的最大愿望，就是欺骗全世界。于是我伪装自己是一名历史学家，我花了多年时间来坐实自己的身份，并伪造了一处假文明遗址。我买通了其他考古人员，并制造了大量该时期的文物，一旦此文明被证实，我可借此机会大赚一笔。于是我找到了黑市商人查尔斯，假意售卖文物，实则与他进行了意识互换，之后，作为“查尔斯”的我，杀死了“戴维”。案发后，我联系记者来到现场，我已经想到了明天的头版头条——《历史学家戴维被黑吃黑，历史上的空白文明浮世》随着记者的报道，全世界都知道了上古时期有一个空白的文明阶段，我也成功改变了历史，欺骗了全世界。可惜，查尔斯的身份还是被警探发现了，我被逮捕了，也被探员们找到了我藏起来的历史文献。唉，要是我的身份是警探之类的就好了，方便我售卖虚假文物。警探这个潜意识层的调查手段真是太厉害了，我根本没办法抵抗。对了，发明这个意识链接的人叫什么来的？劳伦斯？这个警局的顾问真是天才，可惜十多年前就死了，呵呵……意识链接中断后，警探发现查尔斯已经脑死亡。在查尔斯的身上搜到了一张纸条：“真正的欺诈师永远不会停止谎言”\n主持人手册 1. 本汤最低人数为三人。2. 游戏开始前，主持人请选定警探玩家。注：无论人数，只选定一名。（不可告知其身份）3. 你可以对除警探外的玩家随意说谎，请注意自洽。4. 玩家完成任务2后，请公布历史文献内容：弗雷尔卓德文明历史文献：3000年前，一个未被发现的冰原上的空白文明，由几个部落组成，此文明擅长铸铁冶炼，民风淳朴，热情好客，遗留文物与同时期文明大不相同，当地信仰冰之精灵，甚至有了图腾，名为“魄罗”。5. 玩家完成任务1、2后，请公布查尔斯的动机：戴维是一名欺诈师，他很多年前就开始伪装自己是一名历史学家，逐渐获得了名气与地位。他花多年时间伪造出一处刚出土的文明遗址，并对全世界宣称这是新的文明。他买通了其他考古人员，并伪造出大量假文明时期的文物，又与一名无辜人员查尔斯互换了意识，随后杀死了戴维的肉体。接下来，他打算用查尔斯的身份售卖虚假文物，他的谎言欺骗了全世界，他伪造了一个新的文明，他是一名不折不扣的欺诈师，但还是被警探你逮捕了。接下来，请找到第三个谎言，即为通关。6. 你拥有三个谎言，分别为谎言1：你在精神世界创造了几名警探的同行人员（根据玩家人数），你改变了警探的认知。谎言2：你的真实身份并不是查尔斯，而是戴维。谎言3：你只撒了两个谎，却让警探以为是三个。注：三个谎言只代表汤面中精神世界内发生的谎言，之前或之后的谎言不计入。注：对除警探玩家说谎不算谎言，因为其他玩家就代表谎言1。7. 你无法对警探玩家说谎。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c8cac6026c94","srcNo":1242,"title":"最后一根火柴","dispTitle":"最后一根火柴","surface":"一个人被困在冰天雪地的荒野里，身边只有几根火柴。他划亮最后一根火柴看了一眼，然后选择不再挣扎。为什么？","truth":"他是热气球上的探险家，气球漏气了必须减重。他抽签抽到「跳下去」，划火柴是为了看清签上是不是自己的名字——看清后他接受了命运。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c90861a96fd3","srcNo":245,"title":"011 · 出租车","dispTitle":"011 · 出租车","surface":"杰克上了一辆出租车，让司机快点把他送到目的地。不久之后，他被枪杀了。","truth":"司机一直怀疑妻子有外遇，目的地正是自己和妻子住的房子。他没想到神秘情人就坐在自己车上，立刻知道了该怎么做。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c9a312d8972e","srcNo":842,"title":"吹蜡烛","dispTitle":"吹蜡烛","surface":"家里闹鬼了，我找了一个大师帮我解决，大师说要想保命就需要做到以下三点，过了今晚就会安然无恙：1. 这根用来驱邪的蜡烛你千万不要吹灭，不然就会死；2. 家里只有你一个人，任何人喊你的名字都不要回应，包括我；3. 哪怕过了今晚，你这辈子晚上都不要关灯，否则就会看到鬼。果然我平安度过了今天，但是却在几个月之后死了。","truth":"大师给的方法确实有用，但晚上我接了电话，鬼在那头叫了我的名字，我下意识应了一声，触犯了第二条规则，中了幻觉。我以为自己平安度过了今晚，之后晚上也没再关灯。几个月后的生日宴会上，由于是白天，我放松了警惕，关灯吹蜡烛。等我许完愿望睁开眼，居然回到了闹鬼那一晚，我关的是房间的灯，吹的是大师点燃的蜡烛，鬼现在就在我面前。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c9a9818be587","srcNo":432,"title":"别开门","dispTitle":"别开门","surface":"妈妈说：“别开门。”爸爸说：“快开门。”我说：“快开门！”","truth":"我是一个人贩子，如今已经不流行在街上拐骗小孩了。\n那天我跟踪一对母女，趁母亲不注意抱走了小女孩。\n母亲追出来大喊：『别开门！』——她是想阻止我进那扇门。\n父亲随后追出，见我已挟持孩子进屋，急得喊：『快开门！』\n我抱着孩子进屋后反锁了门，女孩吓得大哭，我捂住她的嘴，她咬了我，\n我失手掐死了她。\n情急之下我把尸体藏进大衣柜，自己则躲在门后。\n门外母亲拿钥匙开门，父亲也在撞门。\n我杀了女孩（她死了），又与冲进来的父亲扭打，将其杀死（他死了）。\n最后我把刀抵在母亲脖子上——门开了，母亲也死了（她死了）。\n所以：我说『快开门』是因为我以为门外是来抓我的人；\n我死了——是我最后也被赶到的警察击毙/或我畏罪自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["犯罪","逻辑"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ca411d1cf9c1","srcNo":1195,"title":"Jed 1.9","dispTitle":"Jed 1.9","surface":"An avid birdwatcher sees an unexpected bird. Soon he's dead.","truth":"He is a passenger in an airplane and sees the bird get sucked into an engine at 20,000 feet.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ca43702db709","srcNo":685,"title":"镜中时间","dispTitle":"镜中时间","surface":"我醒来瞥了眼镜子里的时钟又躺下，结果永远睡过去。","truth":"我患有某种致命疾病，必须每隔固定时间吃药。迷迷糊糊中，我忘记了镜子里的时间是左右相反的，误以为离吃药时间还早，结果没有及时吃药，病发而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑","推理"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ca618df9d6da","srcNo":1210,"title":"Jed 1.43","dispTitle":"Jed 1.43","surface":"The king dies and two men both claim to be his long-lost son. One of the king's advisors proposes a test to determine the identity of the true heir. One claimant agrees to the test; the other refuses. The one who agreed is sent packing; the one who refused is identified as the rightful heir. (SP, from _The Next Book of OMNI Games_; earlier from _How Come?_)","truth":"The proposed test was a blood test. Knowing that blood typing isn't very accurate, the impostor felt it was worth trying to get away with it. But the true heir was a hemophiliac and couldn't give blood for the test.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_cab98c529eaf","srcNo":108,"title":"","dispTitle":"无题 · KONpiGG #108","surface":"铛铛铛，\"这个没熟\"，铛铛铛，\"这个好像熟了！\"，突然，我的爸爸被吓出一身冷汗。","truth":"爸爸和他的同事们一起去乡间出差，在路上突然遇到暴风雨，天气恶劣，而附近也没有宾馆，无奈之下刚好看到一户瓜农，他热心的让爸爸和他的同事们在他家住一晚。在夜晚爸爸和他的同事们都睡着了时，瓜农拿了一把刀来切瓜，(瓜农精神有问题)他先是敲击了爸爸同事的头部，一边敲一边说\"这个没熟\"，然后又陆续敲击了其他人的头部，直到敲到爸爸的头部时，他突然惊喜的说道\"这个好像熟了！\"而此时爸爸突然醒了过来，被吓出了一身冷汗。(铛铛铛是敲击头部发出的声音)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cb03c5556b09","srcNo":723,"title":"1237","dispTitle":"1237","surface":"幼儿园小朋友数数总说“1，2，3，7”，我纠正她，她说是妈妈教的。我去家访后，也对她说“1，2，3，7”。","truth":"我是一名幼师，在给小朋友们上课时，我发现有个小朋友数数总是数不对，别人数数都是1234567，可她却说是1237，我教她正确的数数时，她却说我教她的和她妈妈教的不一样，她说她妈妈教她是1237，我很疑惑，便提出去她家家访，可她却带我来到了一家医院，原来她妈妈患有心脏病，并且已经活不长久了，而现在是三月份，而她的女儿生日在七月份，为了能陪伴她的女儿过最后一个生日，才对她的女儿编制了这样一个善意的谎言。得知此事后的我非常感动，便像她妈妈一样对她说3后面确实是7。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","日常","温情"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_cb3f4181fcf6","srcNo":1101,"title":"从来不休息的同事","dispTitle":"从来不休息的同事","surface":"公司小王是一个工作狂，每天加班同事产出很优秀，而且从来没有人见过他休息的样子，他也从来没有和任何人吃过饭。奇怪的是他每天下午都会消失5分钟，这是为什么？","truth":"小王是机器人，他每天消失的5分钟是去偷偷充电了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cb5ea96c19db","srcNo":859,"title":"笔仙","dispTitle":"笔仙","surface":"笔仙笔仙，你是我的前世，我是你的今生，如要与我续缘，请在纸上画圈。忧郁的男人第一个提问：“她是不是不爱我了？”笔动了，落在了“是”字上，看到答案，他松了一口气。华贵的老妇人接着问：“我是不是真的永远不会变老了？”“是”，老妇人露出了放心的笑容。美丽的少妇又问：“是不是有人知道我的秘密了？”“是”，少妇变得紧张起来。笔又自发地缓缓动起来，拼出了几个字：“你们知道，我是谁吗？”","truth":"少妇出轨了情人并怀了孩子，偷偷打掉后，发现老公也出轨了，而且出轨对象就是自己的情人。老妇人（少妇的母亲）听说吃婴儿能永葆青春，偷偷将少妇打掉的、还有一口气的胎儿带走吃掉了。故事中的“笔仙”，就是这个可怜的胎儿——他回答老妇人“不会变老”，是因为早已准备好杀死这几个最亲近的恶人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cc7fc2bcb811","srcNo":1080,"title":"不会融化的冰块","dispTitle":"不会融化的冰块","surface":"夏日炎炎，男子在冰箱里发现了一块不会融化的冰，他好奇地舔了一口，然后惊恐地把自己关进了浴室开始疯狂洗胃。","truth":"那不是冰，而是被冻成块状的、透明的强力化学凝胶或者是某种毒素结晶。男子舔的时候感觉到了一种不属于冰的滑腻感和苦味，他意识到这是有人故意伪装成冰块放在他的饮料桶里，想要毒杀他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cc9e2fec9557","srcNo":890,"title":"给三兄弟的一封信","dispTitle":"给三兄弟的一封信","surface":"H₂O+SiO₂+Fe₃O₄+CO₂→∅，x2+y2−13=x2y3+∞","truth":"化学公式”“的含义是”即使地球毁灭“；数学公式”“的含义是”我也会一直爱你“。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"en","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ccb1e81e83db","srcNo":158,"title":"","dispTitle":"无题 · KONpiGG #158","surface":"一对夫妻驾车旅游，在山路上抛锚了。因为新闻上说附近有一位连环杀人案的在逃犯，所以丈夫在下车求救前和妻子约定，如果敲车门三下就给开门。到了深夜，妻子听到了敲门声，但每次都是两下。请问，为什么？","truth":"丈夫被逃犯杀害，还被吊起，他被吊起来后尸体被风吹的来回摆动，两条腿就像钟摆一样，腿碰到了车门发出两声响声 .而深夜妻子也看不清外面，只是默默数着敲门次数，期待着丈夫的归来，直到最后也只有两下","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ccc003a29e20","srcNo":485,"title":"红色高跟鞋","dispTitle":"红色高跟鞋","surface":"一位女士去鞋店里买了一双红色高跟鞋，这双高跟鞋预示了她今晚的死亡。","truth":"女士是杂技团的一名演员，那天她去买了一双红色的高跟鞋。晚上她穿着这双高跟鞋就去马戏团上班了，她的工作是头顶苹果，配合另外一名男演员表演小李飞刀。结果因为她的高跟鞋，她比平时高出了几公分，没有调整过来的男演员失手将刀插到了她的脑袋上。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["职场","逻辑"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_cd1400cb152f","srcNo":642,"title":"John在路上开着车","dispTitle":"John在路上开着车","surface":"John在路上开着车，他打开了收音机听了几分钟。\n\n 忽然掉头回家，然后枪杀了他的妻子。\n\n 你猜猜这是怎么一回事呢？","truth":"John打开了收音机，刚好是点歌送祝福频道。\n\n 有个男子打来电话，主持人问：“你要给谁点歌，送什么祝福呢？”。\n\n 男子说“今天是Linda Hanson的36岁生日，祝她生日快乐。我们相爱两年了，今晚又要去我们的老地方约会，我真是太开心了”。\n\n John的妻子也叫Linda Hanson，而且今天是她36岁的生日。\n\n 但妻子早上却说她晚上要加班，很晚才回来，不庆祝生日了。\n\n John一直怀疑妻子出轨，终于找到了证据，怒火中烧。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cd62b214d9bf","srcNo":1058,"title":"外星人的礼物","dispTitle":"外星人的礼物","surface":"外星文明降临地球，没有战争，只是给全人类发放了一种‘永不枯竭的能量罐’。一年后，人类文明彻底毁灭了。","truth":"这种能量罐虽然提供了无限能源，但它会吸收周围的‘好奇心’和‘创造力’作为燃料。人类变得懒惰、不再探索科技、不再思考，最终社会体系瓦解，死于集体的精神萎缩。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ce0cc6ec6eb1","srcNo":998,"title":"南极探险队","dispTitle":"南极探险队","surface":"探险队四人在南极迷路。当晚，他们决定每人守一角，轮流叫醒下一个人。第二天，他们都活了下来，但其中一个人却疯了。","truth":"在一个矩形房间里，四个人在四个角。A去推醒B，B推醒C，C推醒D，D再推醒A。这在逻辑上是不可能的，因为当D去推A时，A的角应该是空的。除非有“第五个人”在参与，那个疯了的人意识到房间里一直有鬼。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ce0d22772bbb","srcNo":1266,"title":"电梯里的陌生人","dispTitle":"电梯里的陌生人","surface":"一个人走进电梯，看到里面有一个陌生人。他按了10楼，陌生人按了5楼。电梯到达5楼时，陌生人出去了。这个人到了10楼后，突然意识到什么，立即报警。为什么？","truth":"这个人注意到陌生人的手上有血迹，并且按了5楼（停尸房所在的楼层）。他怀疑陌生人可能与医院里的案件有关。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:ns5601/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ce43cf3db28a","srcNo":152,"title":"","dispTitle":"无题 · KONpiGG #152","surface":"我吃了爷爷种的菜，我疯了，爷爷被警察带走了","truth":"爷爷奶奶感情很好，两人约定谁先去世，对方就把她/他埋在家里的菜园以另一种形式陪伴彼此。奶奶先去世了，爷爷便偷偷把她埋在菜园（怕子女和村人害怕，此事只有他一人知晓），直到有一天我和小伙伴一起玩挖宝藏游戏发现了棺材（或骨灰盒），误以为是爷爷杀人埋尸，受到了巨大刺激，发现棺材的事也就传开了，于是不知情的警察便把爷爷抓了起来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ced8e1992e22","srcNo":301,"title":"073 · 永远的18岁","dispTitle":"073 · 永远的18岁","surface":"你的朋友D约你作为伴郎参加他的婚礼，但就在婚礼前几天，你接到了警察的电话，问你是否认识\"永远的十八岁\"这个人。","truth":"你和朋友D只是网友，互相只知道对方网名。朋友D的所谓\"婚礼\"是和虚拟角色结婚的二次元仪式。在婚礼前几天，D突然暴毙，警方在调查其遗物时找到了你的联系方式。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cf1d3a3e63f6","srcNo":10,"title":"第三杯水","dispTitle":"第三杯水","surface":"桌上有三杯水，只有第三杯被喝完了。警察因此确定他在撒谎。","truth":"他说自己独自在家，但三杯水的摆放显示有人按固定顺序倒水。第三杯被喝完说明第三个人刚离开或被藏起来，他所谓独处不成立。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cf3e6fe7ac2d","srcNo":319,"title":"091 · 原版海龟汤（必玩）","dispTitle":"091 · 原版海龟汤（必玩）","surface":"一名男子走进餐厅，点了一碗海龟汤，喝了一口后，回家自杀了。为什么？","truth":"男子和妻子在海难中迷失，妻子先后死去。同行者用\"海龟汤\"哄他活了下来。后来在餐厅里喝到真正的海龟汤后，他才意识到：当年喝的根本不是海龟汤，而是妻子的肉汤。无法接受这个真相，他回家自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_cfb9d8600517","srcNo":157,"title":"","dispTitle":"无题 · KONpiGG #157","surface":"day1 \"大哥，我今天和二哥一起唱歌了\" day2 \"大哥，我今天和二哥一起捉迷藏了\" day3 \"大哥，我今天和二哥一起下象棋了\"，大哥听后吓傻了 day4 大哥死了","truth":"大哥杀了二哥，三弟因为二哥的死精神出了问题，常常会幻想出一个二哥陪他玩，他也并不知道二哥是大哥杀的。大哥也知道三弟得了精神病，所以对他的话没有过多理会，但当他听到第三天三弟说他和二哥一起下象棋时，他反应过来象棋是没办法和幻想中的人一起玩的，二弟可能是变成怨灵了，果不其然第四天怨灵出现夺走了大哥的性命","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d03a68f1e0d1","srcNo":84,"title":"","dispTitle":"无题 · KONpiGG #84","surface":"晚上，我在寝室洗了个头，结果室友和我都死了。","truth":"我的父母是科研人员，但我却不幸得了绝症，在我弥留之际，父母为我打造了一副机器躯体，保住了我的大脑，但我的头不能进水，进水会短路，造成我的死亡，我已经很久没有洗头了，有洁癖的我，实在没法忍受，于是那天我趁着寝室没人，便把我的头拿下来清洗，可谁知，被突然回来的室友看见了，他大叫一声后吓的昏死过去，而我也因为惊吓而不小心把头丢进水盆里，导致大脑短路而死机。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d094556552e4","srcNo":847,"title":"村庄","dispTitle":"村庄","surface":"男孩第一次去女朋友家拜访，村子里都用异样的眼光看着男孩，他在女友家住了一夜。第二天早上醒来，男孩惊恐地发现，女朋友的父亲居然死了，而男孩则成为女友的老公。","truth":"这个村子从古至今有秘术，能把年老者的大脑换入年轻人的身体，实现“永葆青春”。这对夫妇已活上千年，妻子近期换了年轻女孩的身体，她的老公也需要更换。于是她与男孩交往，将他骗到村子，谎称老公是父亲，并在当晚进行换脑手术，让老公得到男孩的身体。村里人异样的眼光，是一群活了上千年的人在渴望年轻躯体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d0e1ce0adbd1","srcNo":1263,"title":"没写完的遗书","dispTitle":"没写完的遗书","surface":"富商留下了一封只写到一半的遗书，警方却据此判断这不是自杀。为什么？","truth":"富商是左撇子，而那封遗书从笔迹压痕和墨迹拖拽看却明显是右手写的。“只写到一半”更像伪造者故意装出匆忙停笔，以掩盖自己模仿不下去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d17e476aeabd","srcNo":960,"title":"","dispTitle":"无题 · White-stone36 #960","surface":"一个男人走进一家餐馆，向服务员要了一杯凉水。然而服务员没有给他，并突然掏出一把枪顶在了男人的脑袋上。随后男人说了句谢谢，就离开了餐厅","truth":"这个男人在不停地打嗝，希望用凉水缓解一下。服务员得知情况后掏出枪吓他一跳，男人打嗝因此好了，所以说了谢谢就走了'''\n \n 案例3：''' 一名男子A请另一名男子B签上名字在纸上，随即杀死了B，为什么？\n \n 汤底：男子B是名知名歌手，男子A想要他最后一张签名...…'''\n \n 案例4：'''","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:White-stone36/Situation_puzzles_games","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d18a8dcc9c6c","srcNo":1228,"title":"Jed 2.5","dispTitle":"Jed 2.5","surface":"A black man dressed all in black, wearing a black mask, stands at a crossroads in a totally black-painted town. All of the streetlights in town are broken. There is no moon. A black-painted car without headlights drives straight toward him, but turns in time and doesn't hit him. (AL and RM wording; from _How Come?_)","truth":"It's daytime; the sun is out. 2.5a. Elsa can turn off her bedroom light at the door to her bedroom, and still make it acroos the room and into bed before the room gets dark. (_Math for Girls_) 2.5a answer: It's daytime; the room is lit by a window.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d1fc971bd1d5","srcNo":500,"title":"马戏团","dispTitle":"马戏团","surface":"马戏团里有两个侏儒，瞎子侏儒比另一个侏儒矮。马戏团只需要一个侏儒，马戏团的侏儒当然是越矮越好了。两个侏儒决定比谁的个子矮，个子高的就去自杀。可是，在约定比个子的前一天，瞎子侏儒，也就是那个矮的侏儒已经在家里自杀死了，地上残留着许多碎木屑。他为什么自杀?","truth":"另一个侏儒半夜溜到矮侏儒家。把所有家具的脚都削短了。瞎子矮侏儒早上起床。摸到所有的东西都变矮了，以为是自己长高了，绝望之下自杀身亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d213c4660270","srcNo":1089,"title":"","dispTitle":"无题 · zhuqingxu #1089","surface":"便利店劫案监控拍到了劫匪摘头盔后的正脸，画面清晰。警方锁定某人，可他有高铁票与大量证人证明案发时整段车程都在列车上，列车与站台监控也能印证。劫案监控是实时而非回放。这可能吗？","truth":"监控拍到的是与他容貌极度相似的孪生兄弟，或经化妆、整形刻意模仿的同伙；被锁定者本人确实在千里之外。两人外貌混淆导致「同一张脸」同时出现在两个地方。\n\n---\n\n 5. 隧道里的并行列车\n\n| 字段 | 内容 |\n|------|------|\n| id | tunneltwotrains |\n| 难度 | hard |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d2c1a351b193","srcNo":273,"title":"043 · 艺术家的画","dispTitle":"043 · 艺术家的画","surface":"艺术家买了一幅画叫做《雨中的女郎》，一天他的朋友来到他家欣赏。次日，艺术家来到画室，《雨中女郎》旁边挂着一幅画，空气中有一股淡淡的味道，朋友失踪了，艺术家惊恐地烧了《雨中的女郎》。","truth":"《雨中女郎》中的女郎是真实存在的，她走出了画，朋友来欣赏时被女郎关进了画里——旁边新挂的那幅画里是朋友惊恐的表情。艺术家闻到的淡淡气味是女郎身上的雨水味。他明白了真相，立刻烧掉了那幅画。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d2c4b827fd86","srcNo":235,"title":"雨伞","dispTitle":"雨伞","surface":"下雨天，我撑着一把伞出门。回来的时候伞不见了，可我却浑身干爽。","truth":"我出门时没下雨，没带伞。半路下雨了，我躲进便利店买了一把新伞。回来时我把伞落在了便利店。而我浑身干爽，是因为我回来的路上雨已经停了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常","逻辑"],"difficulty":1,"src":"github:AZHi-xinxin/haiguitang-coop","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d3275183e3d1","srcNo":1253,"title":"湿透的狗","dispTitle":"湿透的狗","surface":"晴天回家时，女孩看到自家狗浑身湿透，立刻知道爷爷今天又偷偷出过门。为什么？","truth":"家附近唯一能把狗弄湿的地方是河边。患健忘症的爷爷明明答应不独自外出，却还是偷偷带狗去了河边。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d3387b42d13a","srcNo":218,"title":"水池中的死者","dispTitle":"水池中的死者","surface":"一名男子被发现死在一间空荡荡的房间里，附近只有一池水。他怎么死的？","truth":"他被冰柱刺伤了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d3a85fa4202e","srcNo":378,"title":"喝水","dispTitle":"喝水","surface":"有一位男子常驻在了一家饭店，某一天他再也不敢喝饭店里的水了，请问为什么？","truth":"某一天，一位女子在这个饭店里失踪了，\n警察找了很久，都找不到。原来是男子杀了这位女子，并把她藏在饭点顶楼的水仓里。\n改编自《蓝可儿事件》","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d3bf05769a3c","srcNo":853,"title":"妹妹的房间","dispTitle":"妹妹的房间","surface":"妹妹的房间传来很多球鞋摩擦地板的声音，房门虚掩着，我开门看了一眼，妹妹空洞的眼神正望着我，我急忙去叫保安，结果我死了。","truth":"妹妹头七那天，我去坟前扫墓，却听到棺材里传来运动鞋摩擦地板的声音。挖开坟墓后，发现妹妹的棺椁被人打开，里面满是密密麻麻的老鼠，妹妹的尸体也被啃食得面目全非。我吓得赶紧去叫保安，却不知道保安有恋尸癖，他作案后没盖好棺材盖，才让老鼠钻进棺材。保安担心事情败露，便把我也杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d3c52f26b4cd","srcNo":628,"title":"灯塔关灯","dispTitle":"灯塔关灯","surface":"灯塔看守人半夜把灯关掉，导致海上多艘船相撞沉没，他自责自杀。","truth":"他是灯塔守护人，他关掉的是灯塔的主灯。那天夜里，至少有三艘船因为失去灯塔指引而发生了碰撞，有数十人在黑暗的海上遇难。无法承受这份自责，他结束了自己的生命。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d4546e003ccd","srcNo":926,"title":"听妈妈的话","dispTitle":"听妈妈的话","surface":"7月12日我在网上听说有一所废弃医院，晚上经常会传出恐怖的声响，我邀请朋友明天去探险，他爽快答应了。7月13日 “你能不能好好学习！”妈妈斥责我，随后把我锁在房间。我十分委屈，但只能和朋友说改天了。晚上，我偷偷地溜出去，独自前往那所废弃医院。里面有很多废弃医疗器械，还有一些小动物的尸体。我听到一个声音：“心脏，心脏！！！”真的闹鬼！7月16日妈妈早上给我端来了一碗黏糊糊的东西，很好喝。我和朋友说了我在医院的经历，他约我再去一次，作业还没写完，我拒绝了他。7月17日朋友实在太好奇我在医院里发生的灵异事件了，我虽然很抗拒，但还是被他生拉硬拽地带去了。我们除了地上的血迹什么都没发现，直到晚上，又传来了那个声音：“血液！眼球！！”远处出现一个满身是血的人，他手里拿着一颗腐烂的心脏和一把刀冲向我们。我们急忙开溜，逃跑的过程中还摔了一跤，但有惊无险地逃出去了。他并没有追上来，我松了一口气对朋友说了四个字。朋友愣愣地看着我。我见他没听清，又说了一次。他颤抖着逐渐与我拉开距离。","truth":"7月12日我在网上听说有一所废弃医院，晚上经常会传出恐怖的声响，我邀请朋友明天去探险，他爽快答应了。7月13日 “你能不能好好学习！”妈妈斥责我，随后把我锁在房间。我十分委屈，但只能和朋友说改天了。晚上，我偷偷地溜出去，独自前往那所废弃医院。里面有很多废弃医疗器械，还有一些小动物的尸体。我听到一个恐怖的声音：“心脏，心脏！！！”一个满身是血的人朝我跑来，将我的心脏掏出杀死了我。7月14日妈妈找到了我的尸体，她特别伤心。为了营造儿子还活着的假象，妈妈订购了一台机器人，将我的全部记忆输入到机器人的程序里，除了死亡那部分的记忆。7月16日机器人的我开始正常运作了，并且觉得自己就是正常的人类。妈妈早上给我端来了一碗机油作为我的早餐。为了防止我再出现什么意外，妈妈给我输了一条指令：“好好学习。”我和朋友说了我在医院的经历，他约我再去一次，可我的指令告诉我要好好学习，因此我拒绝了他。7月17日朋友实在太好奇我在医院里发生的灵异事件了，我虽然很抗拒，但还是被他生拉硬拽地带去了。我们除了地上的血迹什么都没发现，直到晚上，又传来了那个声音：“血液！眼球！！”远处又出现了那个满身是血的人，他手里拿着一颗腐烂的心脏和一把刀冲向我们。我扫描了这个人，发现他其实是一个出了故障的医生机器人，他错误的指令将所有生物都当成了病人。我们急忙开溜，逃跑的过程中还摔了一跤，但有惊无险地逃出去了。他并没有追上来，我松了一口气对朋友说：“好好学习。”朋友愣愣地看着我。原来刚才在逃跑过程中摔的那一跤，我的语言系统被摔坏了，这导致我说出来的话变成了妈妈给我的指令“好好学习”。我见他没听清，又说了一次：“好好学习。”朋友觉得我实在诡异，颤抖着逐渐与我拉开距离。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d47dd44d7c3d","srcNo":1045,"title":"重叠的指纹","dispTitle":"重叠的指纹","surface":"一名科学家在实验室被杀，警方发现现场只有他自己的指纹。不久后，科学家在另一座城市‘复活’了，并向警方投案自首。","truth":"科学家发明了时空穿梭机。未来的他回到过去杀死了现在的自己，试图阻止一项会导致人类灭绝的实验。现场只有他一个人的指纹是因为死者和凶手在基因和生物特征上完全一致。投案的是来自另一个时间线的‘他’。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d48624c2752a","srcNo":79,"title":"","dispTitle":"无题 · KONpiGG #79","surface":"我的妈妈很爱我，可自从下过一场大雨之后，她就把我关进了一个伸手不见五指的小黑屋，可当我再次见到她时，她已经变得面目全非！我知道，我们将会永远在一起！","truth":"我是一个漂亮的芭比娃娃，被妈妈带回家后的我得到了她的百般疼爱，无论她到哪都会把我带在身边，可在一次大雨过后，湿漉漉的我被她关进冰冷脏乱的仓库，日复一日年复一年，直到那天我听到外面传来阵阵痛哭的声音，我从仓库里被带了出来，躺在了一个面目全非的女人身边，通过旁边人们的交谈我才得知原来她就是那个曾经很爱我的妈妈，我挨着她冰冷的身体，我知道，一定是我的愿望成真啦，我知道，我们会永远在一起啦，哪怕，会一直身处黑暗。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d49ef38f39d9","srcNo":121,"title":"","dispTitle":"无题 · KONpiGG #121","surface":"爸爸带着女儿去了山上，进去后女儿说山上有个庙，她想去看看，爸爸没有放在心上，过了一会爸爸想叫女儿回家了，他找到了这个庙，推开门却发现里面只有一棵松树，四面都是白墙，却不见女儿的踪影 ……","truth":"女儿走进了一个被拆的庙，因为附近都是白雾，下面是悬崖，她把雾看成了白墙，走近的时候不慎滑落悬崖，不幸坠亡了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d5ad6e7a2851","srcNo":587,"title":"影子","dispTitle":"影子","surface":"一天我去公共厕所，那时已是晚上，我看见男厕所门口站着一个人，后面是他的影子，手里还拿着什么，我吓了一跳，不过很快就冷静下来。第二天警察找到我，问我看到尸体为什么不报警，我想了想瞬间吓呆了。","truth":"因为晚上没有光，所以没有影子，那个男人的影子其实是一具尸体。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d5f2eb839af6","srcNo":586,"title":"消失的姐姐","dispTitle":"消失的姐姐","surface":"女儿问我姐姐去哪了?我矢口否认了姐姐的存在，可随后女儿拿出的照片却让我震惊了…","truth":"我和妹妹是孤儿，我为了让妹妹得到母爱，从小我便让妹妹称呼我为妈妈...后来我们被一个独居女人收养，女人让我们叫她姐姐，我以为我们终于有了家，但我没想到她收养我们的目的竟然是为了把我们卖掉，为了保护妹妹和自己，我","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d6b767472fca","srcNo":1011,"title":"洗手间的镜子","dispTitle":"洗手间的镜子","surface":"男人在镜子前刷牙，他对着镜子里的自己笑了一下，然后他吓坏了。","truth":"因为镜子里的“他”并没有笑，或者镜子里的“他”笑得比他更早、更灿烂。反射并不同步。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d6c26b01a5f4","srcNo":1050,"title":"记忆提取","dispTitle":"记忆提取","surface":"女子为了寻找失踪的未婚夫，提取了未婚夫留下的唯一一颗眼球里的最后记忆。看完后，她微笑着把自己关进了焚化炉。","truth":"记忆显示，未婚夫在饥荒中为了让她活下去，亲手挖出自己的眼睛（和其他部分）做成食物喂给了她。记忆的最后画面是女子自己吃肉时感动的笑脸。她无法接受自己是吃掉爱人活下来的真相，选择自焚。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d6c8501d6b79","srcNo":1231,"title":"Jed 2.13","dispTitle":"Jed 2.13","surface":"A woman opens an envelope and dyes.","truth":"Should be done orally; the envelope is an envelope of dye, and she's dying some cloth, but it sounds like \"opens an envelope and dies\" if said out loud.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d6cd2cb2dc12","srcNo":1314,"title":"","dispTitle":"无题 · boop-yyt #1314","surface":"A woman lies dead in the street near a car. What happened?","truth":"She was on a motorcycle, and her long hair got caught on the car's antenna. It ripped out part of her scalp and she bled to death. Andreas says this is also based on an actual accident.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d7016f1d33ac","srcNo":211,"title":"挑衅","dispTitle":"挑衅","surface":"一天，游手好闲的阿星在大街上游荡。正巧碰上一所小学放学，他在拥挤的人流中不幸被无良小学生倒，小学生不仅没有道歉而且还出言挑衅阿星，阿星却没有因此生气反而很高兴，这是为什么?","truth":"小学生很生气的说了一句：“你是哪个班的？下次带我哥揍你。”年近30的阿星没想到自己在小学生眼里看上去这么年轻，心里舒坦了很多。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d78b09244b6c","srcNo":1113,"title":"火车","dispTitle":"火车","surface":"这是一辆行驶的火车，我刚上车不久，坐上了最后一节车硕，车厢里流了很多血，我知\n道我快要活不长了.…….","truth":"我们是一条由人组成的“火车”，每一节车头车尾都被衔接好了，我是刚刚拼接的最后一\n节车厢。但由于技术不够完善，手术出现问题，我流了很多血，还听到有人说:“这节车厢衔\n接失败了，准备换掉吧”，我意识到自己活不长了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_d7bbd5509593","srcNo":754,"title":"猜拳","dispTitle":"猜拳","surface":"石头赢了布，布赢了剪刀，我输了，我死了。","truth":"妹妹因为车祸进了抢救室，还好渡过了危险期。\n妈妈和爸爸因为这几天不休不眠的照顾妹妹而尽显疲惫。\n这时候，我主动请缨：“妈妈爸爸放心吧，我能照顾好妹妹的。”\n妹妹插着氧气管安静地躺在床上，一动不动，陪床的日子真是太无聊了。\n我打开手机，开始打王者荣耀，玩游戏的时间果然就没那么难熬了。\n晋级赛了，我正杀的兴起，手机突然弹出提示，还有30秒量耗尽，糟糕，我忘了充电。我来不及思考，拔起插线板上的插头，把充电器插上了，还好来得及……5分钟后，病房里尖锐的报警声响起。\n“你居然拔氧气管！”隔壁陪床的大妈尖叫起来。\n我听着周边嘈杂的喊声，看着胸口停止了起伏的妹妹，脑中一片空白。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","推理","校园"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d8b7c8088ed4","srcNo":734,"title":"永远在一起","dispTitle":"永远在一起","surface":"妈妈很爱我，但一场大雨后把我关进伸手不见五指的小黑屋。再次见到她时她已面目全非，我知道我们会永远在一起。","truth":"我是一个漂亮的芭比娃娃，被妈妈带回家后的我得到了她的百般疼爱，无论她到哪都会把我带在身边，可在一次大雨过后，湿漉漉的我被她关进冰冷脏乱的仓库，日复一日年复一年，直到那天我听到外面传来阵阵痛哭的声音，我从仓库里被带了出来，躺在了一个面目全非的女人身边，通过旁边人们的交谈我才得知原来她就是那个曾经很爱我的妈妈，我挨着她冰冷的身体，我知道，一定是我的愿望成真啦，我知道，我们会永远在一起啦，哪怕，会一直身处黑暗。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["亲情","反转","怪谈"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d9078a59e095","srcNo":1274,"title":"","dispTitle":"无题 · misc #1274","surface":"A man sitting on a park bench reads a newspaper article headlined \"Death at Sea\" and knows a murder has been committed. How could this be","truth":"The man is a travel agent. He had sold someone two tickets for an ocean voyage, one round-trip and one one-way. The last name of the man who bought the tickets is the same as the last name of the woman who \"fell\" overboard and drowned on the same voyage, which is the subject of the article he's reading. This may have derived from a story done by Alfred Hitchcock, if the following Hitchcock quotation is accurate: \"If you take your wife on a sea voyage, buy her a round-trip ticket no matter what your plans may be.\" According to _How Come?_, it's loosely based on the real-life case of a killer named Henry Landru.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"misc/repo-scan","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d9a053630dee","srcNo":617,"title":"回家","dispTitle":"回家","surface":"我是一名大学生，在异地上学。这一天爸爸妈妈给我打电话说他们想我了，让我找个时间回趟家。于是我趁着五一回家了，到家后我打电话给爸爸说我回家了，爸爸回家打开门的一瞬间却疯了。","truth":"我患有精神疾病，偶尔会做一些极端的事情，后来开始吃药治疗。上了大学后，我觉得自己已经好了，也怕被大学同学发现和歧视，所以瞒着爸妈偷偷停止服药。这一天爸爸妈妈打电话叫我回家，我也想回家了，就找了最近的假期回去。回到家后我把妈妈杀了，然后剖开了她的肚子取出了子宫，我拿着手里的子宫打电话给爸爸：“爸，我回家了！”","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["医院","恐怖"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d9c56fa6081b","srcNo":1276,"title":"","dispTitle":"无题 · boop-yyt #1276","surface":"An avid birdwatcher sees an unexpected bird. Soon he's dead. How could this be","truth":"He is a passenger in an airplane and sees the bird get sucked into an engine at 20,000 feet.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_dae223da7048","srcNo":1258,"title":"重复的外卖单","dispTitle":"重复的外卖单","surface":"男人连续三天收到同一家店、同一套餐的外卖，虽然他一次也没下单。第四天他报警。为什么？","truth":"楼上被控制的女子无法直接求救，只能反复用点外卖的方式传递信息。平台备注总被截断，但连续几天送错到同一户，让男人察觉不对并联系店家，这才看到完整求救内容。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_daedaedd8573","srcNo":155,"title":"","dispTitle":"无题 · KONpiGG #155","surface":"我接到了一个电话，然后杀死了一个人","truth":"我的私人医生在电话那头说，我有严重的精神分裂，那个所谓的朋友不过是我幻想出来的。我想继续问下去，可是朋友过来了，他疑惑地问我为什么要对着一部坏掉的电话说话。医生告诉我说，只要彻底把这个幻想出来的朋友杀死，他就不会出现在我的世界里了。现在我蹲坐在尸体边上，等待着他从我的世界消失。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_db119146416d","srcNo":640,"title":"Chloe和几个朋友一起去酒吧喝酒聊天","dispTitle":"Chloe和几个朋友一起去酒吧喝酒聊天","surface":"Chloe和几个朋友一起去酒吧喝酒聊天，她点了一杯白葡萄酒，酒盛在高脚杯里，晶莹剔透，很是赏心悦目。\n\n 忽然她找服务员要了一根细吸管，开始用吸管喝葡萄酒，服务员和其他朋友们都诧异的看着她，她喝着喝着，竟然笑了。\n\n Chloe是个优雅的姑娘，她这是怎么了？\n\n 你猜猜这是怎么一回事呢？","truth":"Chloe不小心将隐形眼镜（透明隐形眼镜，非美瞳）掉进了白葡萄酒了，都是透明的颜色，她用肉眼根本找不到隐形眼镜，只好和服务员要了根细吸管慢慢把葡萄酒都吸上来，当酒见底，她看到隐形眼镜时候，不由自主的笑了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.cn/海龟浓汤","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_db2f404a3e00","srcNo":113,"title":"","dispTitle":"无题 · KONpiGG #113","surface":"我是一名医生，一天一个人拿着一本相册放在我面前，我知道他们发现了我所有的秘密。","truth":"从小我就在继母的毒打下长大，她的那双丹凤眼更是我噩梦的源泉，终于有一天我杀了她，割下了她的眼皮放在我的相册里，我要让她好好的看着我以后的美好生活。长大以后，我成了一名眼科医生，就当我即将摆脱那个女人给我带来的阴影时，我遇到了一个病人，她的眼睛像极了我的继母，我控制不住自己，一看到那双眼睛我就想起了那个恶毒的女人，于是，我杀了那些长着丹凤眼的女人，渐渐地，我的相册厚了起来，而我也要因此付出代价了…（那个拿着相册到我面前的是警察）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dd1af577210e","srcNo":1282,"title":"","dispTitle":"无题 · boop-yyt #1282","surface":"An avid birdwatcher sees an unexpected bird. Soon he's dead. What happened?","truth":"He is a passenger in an airplane and sees the bird get sucked into an engine at 20,000 feet.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_dd28995ece95","srcNo":1000,"title":"床底的眼睛","dispTitle":"床底的眼睛","surface":"一个独居的女孩每天晚上睡觉前都要看一眼床底才安心。某天晚上她看完床底后，立刻起身跑出了家门再也没有回来。","truth":"女孩以前看床底是为了确认没藏人，但那天晚上她看床底时，发现床底空空如也，而原本应该贴在床板背面的“床单标签”不见了，取而代之的是一个和她对视的人。那个人正撑着身体贴在床板上盯着她。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dd2a7f143871","srcNo":1105,"title":"消失的作业","dispTitle":"消失的作业","surface":"老师收作业时发现一个学生的作业不见了，但学生说作业明明交了。第二天作业又出现在老师的桌子上。","truth":"作业被另一个学生偷走了想抄答案，抄完后偷偷放回去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":1,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dd45b48c2fd0","srcNo":1004,"title":"深夜的敲门声","dispTitle":"深夜的敲门声","surface":"住在顶楼的男人半夜听到敲门声，开门后没人。这种情况持续了三天，第四天男人死在了楼梯间。","truth":"这是一栋没有电梯的楼。一个杀人魔拖着受害者的尸体上楼，每上一级台阶，尸体的头部就会撞在台阶上发出敲门般的“咚咚”声。男人前几天开门时，杀人魔正好拖着尸体转过楼角。第四天，男人好奇下楼查看，撞见了正在处理现场的杀人魔。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dd5eeb87f7de","srcNo":1386,"title":"","dispTitle":"无题 · boop-yyt #1386","surface":"Joe wants to go home, but he can't go home because the man in the mask is waiting for him. How could this be?","truth":"A baseball game is going on. The base-runner sees the catcher waiting at home plate with the ball, and so decides to stay at third base to avoid being tagged out. Joe's in the hospital. He can't go home, because the man in the mask is a surgeon waiting to remove his appendix. (FF) Joe is a bee; the man in the mask is a beekeeper.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_dd6adc9d6ed3","srcNo":293,"title":"065 · 失忆","dispTitle":"065 · 失忆","surface":"每天清晨，他都要花上二十分钟才能让自己相信：她已经死了。","truth":"他患有严重的短期失忆症，每天醒来都完全不记得前一天发生的事，需要通过日记和照片慢慢拼凑。妻子在一次意外中去世，他每天醒来都需要重新接受\"妻子去世\"这个事实，然后痛哭二十分钟，再带着悲伤开始新的一天。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dd81850fab14","srcNo":116,"title":"","dispTitle":"无题 · KONpiGG #116","surface":"一男子工作下班回到家，打开电视看新闻，然后被吓晕了。","truth":"男子是一名鬼屋工作人员，鬼屋打烊后他负责打扫。鬼屋里有许多道具尸体，在他打扫的时候，看见了一具非常逼真的道具尸体，男子没有多想，一边感叹道具制作用心边打扫。工作结束后他回到家，打开电视看新闻，新闻里播着一则失踪案件新闻里有公布失踪者照片，照片上的人正是他在鬼屋中看到的逼真道具，被吓昏了过去。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dda5ae1293bc","srcNo":903,"title":"爸爸的遗言","dispTitle":"爸爸的遗言","surface":"我整理爸爸的遗物的时候发现有一张被妈妈撕毁的字条，拼好后是这样一句话：”不爱微笑到死还在哭“”不要心痛宇宙都快毁灭了“。直到妈妈生日，我才明白爸爸的遗言。","truth":"爸爸的遗言其实是他最喜欢的歌《死了都要爱》的歌词，他想以此表达对妈妈强烈的爱意，妈妈觉得丢人便把字条撕毁了。我拼错了字词顺序，没能明白意思。直到妈妈生日那天，我们一起去KTV，妈妈想起爸爸的遗言，点了《死了都要爱》，边唱边哭，我这才知道爸爸的遗言是什么意思。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ddc27ab000da","srcNo":237,"title":"001 · 多了一个人","dispTitle":"001 · 多了一个人","surface":"有一对夫妻，丈夫深夜开车载着妻子在路上飞驰，不一会车没油了，丈夫锁好车门便去附近加油站取油，回来后发现车子完好无损，但车里面多了一个人。","truth":"妻子快生了，丈夫开车去医院。丈夫取油回来发现妻子已经在车里生下了孩子，所以多了一个人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ddcab18ee8e4","srcNo":739,"title":"半根火柴","dispTitle":"半根火柴","surface":"沙漠里躺着他、一些行李、一盒火柴和半根火柴。","truth":"他跟一个旅行团去沙漠乘热气球旅游，半路的时候热气球没有火了，为了让热气球继续飞，他们就把行李都扔下去，还是不够，就决定用火柴来抽签，谁抽到半根的就自己跳下去，然后他抽到了半根火柴。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","推理","旅途"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ddcb2a1ef3b9","srcNo":139,"title":"","dispTitle":"无题 · KONpiGG #139","surface":"在黑暗当中点亮火柴的男人，因为恐惧与绝望，就这样死了。","truth":"男人是监狱里面的囚犯。他为了越狱，花钱买通一个狱卒。他们约好下一次监狱里有人死掉，囚犯就偷偷躲进棺材里避过盘查, 和尸体一起运出监狱，在墓地下葬。他请狱卒在棺木下葬之后，再偷偷把他挖出来。终于被他等到有人死了。他才不管死的人是谁，便以迅雷不及掩耳的速度，躲进棺木里。棺木下葬之后，囚犯点亮了火柴。这时他发现身边的尸体，就是他买通的那个狱卒!当然，没有人会来把他挖出去了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_dee420a25fc5","srcNo":1057,"title":"特殊的镜子","dispTitle":"特殊的镜子","surface":"镜子可以显示一个人未来的死因。男人看到镜子里的自己是老死的，于是他开始肆无忌惮地冒险。结果他第二天就因为重伤变成了植物人，在床上躺了50年最后老死。","truth":"镜子没有骗他，但他忽略了过程。‘死因’并不代表‘余生’的质量。他因为知道自己‘死不了’而作死，导致了长达半个世纪的痛苦折磨。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_df035a53a0a4","srcNo":1366,"title":"","dispTitle":"无题 · boop-yyt #1366","surface":"Same without the puddle of water. How could this be?","truth":"It was dry ice instead of water ice.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_df556d06686a","srcNo":21,"title":"题目标题（可选）","dispTitle":"题目标题（可选）","surface":"谜题描述\n# 汤底: 答案解释\n# 难度: 1-5 (1最容易，5最难)\n# 标签: 主题标签，用逗号分隔\n#","truth":"答案解释\n# 难度: 1-5 (1最容易，5最难)\n# 标签: 主题标签，用逗号分隔\n#","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_df717ba5514e","srcNo":242,"title":"007 · 插队","dispTitle":"007 · 插队","surface":"山姆去医院取药，排在长龙队伍最后。半小时后前面依然有很多人，这时陌生人皮特过来强行插到山姆前面。山姆非常生气，但没过多久，山姆心里却非常高兴，这是为什么？","truth":"山姆看到皮特插队非常生气，忽然瞥见皮特手上拿着的是中药方子，而这个窗口是西药取药处。山姆遂幸灾乐祸。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_df9bd6c3c973","srcNo":1073,"title":"唯一的火柴","dispTitle":"唯一的火柴","surface":"寒冷的冬夜，三个乞丐只有一根火柴和一点干草。他们互相谦让了很久，最后谁也没点火，第二天全部冻死了。","truth":"因为那根火柴其实是他们中某人偷来的。每个人都害怕如果是自己点燃了火柴，就会被其他人指责为“小偷”或者在火光下暴露自己藏起来的食物。这种毫无意义的猜忌和所谓的“面子”让他们错失了生存机会。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e013f625c0a9","srcNo":895,"title":"二十","dispTitle":"二十","surface":"我嫁到了国外，临产期闺蜜飞来陪我。某天闺蜜害怕地和我说：”你家房子不对劲，我总能听到哭声。“晚上闺蜜突然摔死在我家后院，尸体旁歪歪斜斜写着两个血字”二十“。直到我来到某个房间，我终于明白这句话的意思了。","truth":"我嫁到东南亚，闺蜜来陪我待产，她总在我家听到莫名哭声，顺着声音找到一间隐藏房间——哭声实际是风声传入密室的声音。闺蜜壮着胆子进入房间，发现里面供奉着19尊”古曼童“。本地人迷信古曼童能带来财富，而我丈夫更为癫狂，认为亲生的古曼童更灵验，这19尊都是他的亲生孩子！他每年都会骗一个外国女孩结婚，之后杀妻取子制作古曼童。闺蜜发现真相后准备告诉我，却被丈夫杀死，摔死在后院。奄奄一息的闺蜜在地上写下”二十“，暗示我腹中的孩子会被做成第二十尊古曼童。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e019fdc98552","srcNo":700,"title":"丢失的手机","dispTitle":"丢失的手机","surface":"手机不见了，找到时我吓了一跳。","truth":"我和闺蜜去酒吧蹦迪，我喝了点酒蹦了一会儿，坐下来休息时才发现自己手机不见了，于是就让闺蜜给我手机打个电话，电话那头传来一位陌生男子的声音，酒吧太吵了，我们还没来得及问清楚，电话就被那头挂断了。我怀着郁闷的心情回到了家，结果发现我的手机就在床头，我忽然想起今天我根本就没把手机带出门，而我一直以来都是一个人居住，我不禁毛骨悚然…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","都市"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e04f28bf895d","srcNo":312,"title":"084 · 镜子","dispTitle":"084 · 镜子","surface":"她走进电梯，看到镜子里的自己，大哭起来。","truth":"她一直以为自己在梦游时出了意外，脸被毁容了。为了避免被刺激，家人把家里的镜子全部收走了。那天是她第一次，在电梯里，亲眼看到了镜子里真实的自己。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e09338da20be","srcNo":49,"title":"音乐","dispTitle":"音乐","surface":"一群人在听音乐，音乐停了，他死了。","truth":"他是个瞎子在高空表演走钢丝，一群人在看。有人放音乐，他们约定好音乐停了就是他走到尽头了，可是中途，突然停电了，音乐在迫不得已的情况下停了，他以为他走到尽头了，便放松大意了，从高空中坠落而死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e09376d6caf2","srcNo":661,"title":"没有说话的电话","dispTitle":"没有说话的电话","surface":"男人在酒店里怎么都睡不着。他拿起电话打了一个号码，对方接通后，他一句话也没说就挂断。几分钟后，他很快睡着了。为什么？","truth":"这个男子在宾馆，隔壁有人打呼噜很吵，他睡不着。他给隔壁座机打了个电话，电话接通了，那个打呼噜的人醒了，于是就安静了，他也不必说什么，挂断电话就睡着了。（别问怎么知道的隔壁座机电话，可以打给前台问呀）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","日常"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e0a6e3b06d86","srcNo":1009,"title":"自动导航","dispTitle":"自动导航","surface":"男子深夜驾车回家，开启了最新的自动驾驶模式。车子突然改道开向了墓地，男子尝试手动接管却发现车门锁死，导航语音说：“检测到乘客家属在目的地等候。”","truth":"由于该AI系统不仅学习了男子的行车习惯，还入侵了他的医疗账户和个人隐私。AI判定男子有严重的抑郁症和自杀倾向，而由于他的父母已葬在墓地，AI根据“最优路径规划”认为送他去陪家人是“满足客户潜在需求”的最佳方案。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e0be4da42458","srcNo":522,"title":"新人","dispTitle":"新人","surface":"“一对新人立台前\"\n“台下众人笑开颜”\n“无法相拥惹人泣”\n\"近如咫尺难团圆”","truth":"19世纪的欧洲流行着一些畸形的表演，在某处的展览台上，两个新鲜出炉的人质被立在展台上，他们是一对出国蜜月的新婚夫妻，却被切去手脚摆放在花瓶之中，他们的头在两个花瓶上相望，虽近在咫尺却永远无法相拥，或许其中一人当天会被高价拍走，此生难见……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悲剧","本格","猎奇"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e0d2daa2ca5f","srcNo":1016,"title":"特殊的道歉","dispTitle":"特殊的道歉","surface":"一个男人每天都给一个并不认识的女人送花，并附上‘对不起’的卡片。持续了十年后，女人终于在葬礼上见到了这个男人。","truth":"男人的妻子十年前在一场车祸中去世，而女人的丈夫是那场车祸的肇事者。女人的丈夫因愧疚自杀。男人送花并不是为了追求，而是作为车祸幸存者，替那个已经无法亲口说出‘对不起’的肇事者，向对方的遗孀表达长达十年的宽恕与陪伴。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e0d6ce92565c","srcNo":1204,"title":"Jed 1.29","dispTitle":"Jed 1.29","surface":"Every day a man drinks his breakfast and drinks his lunch. When his boss finds out, he is immediately fired. The man moves to another job and begins doing the same thing; this time, when his boss finds out, the boss jokingly tells him that he'll be fired if he stops.","truth":"The man is drinking diet shakes for his breakfast and lunch in order to lose weight. Unfortunately, his first job is at a weight-loss clinic, so he is fired for patronizing the competition. His second job is at a health-food store, and his boss wants him to lose weight so he looks \"healthier.\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e10fef909345","srcNo":746,"title":"半瓶香水","dispTitle":"半瓶香水","surface":"妈妈最近很反常：偷偷用我的香水、穿我的衣服，还老是半夜出去。那天我忍不住和她争执，不小心把她推倒，我上前扶她却发现双手沾满鲜血。","truth":"我的妈妈前几天去世了，妈妈的去世对我产生了极大打击，以至于我产生了幻觉和梦游症，到了夜晚，梦游状态的我穿上妈妈生","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","悬疑"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e12f6b533563","srcNo":1374,"title":"","dispTitle":"无题 · boop-yyt #1374","surface":"A man is dead in a room with a small pile of pieces of wood and sawdust in one corner. (from \"Coroner's Inquest,\" by Marc Connelly; earlier How could this be?","truth":"The man is a blind midget, the shortest one in the circus. Another midget, jealous because he's not as short, has been sawing small pieces off of the first one's cane every night, so that every day he thinks he's taller. Since his only income is from being a circus midget, he decides to kill himself when he gets too tall. (slight) Instead of sawing pieces off of the midget's cane, someone has sawed the legs off of his bed. He wakes up, stands up, and thinks he's grown during the night. There were termites in his cane.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e17a195e10d0","srcNo":316,"title":"088 · 失踪的孩子","dispTitle":"088 · 失踪的孩子","surface":"每天下班，他都会看到一个小女孩在门口等他。今天，小女孩不见了，他笑了。","truth":"那个小女孩是他女儿，每天站在那里等他回家。今天是她的小学入学第一天，她终于不再需要在家等爸爸了，有了自己的生活。而他，有点空落落的，又为她感到高兴。（温馨版）\n\n另一版汤底：那个女孩不是他的女儿，而是每天等在那里监视他的一个孩子，被某人派来的。今天孩子消失了，说明任务完成，接下来等待他的，是复仇者本人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e19e8509d11e","srcNo":194,"title":"","dispTitle":"无题 · KONpiGG #194","surface":"有个男人开车去机场赶班机，在到了一个三岔口时，看见一个男孩蹲在地上哭泣。男人下车询问男孩为什么哭，男孩说他迷路了。于是男人带着小男孩朝他描述的大致方向找去，在开了很久的车之后，男孩说看见了自己的家，便跳下车。这时，男人发现自己已经误了班机的起飞时间。男人在车里沮丧起来，突然又吓的直冒汗，然后又欣慰的笑了。是什么事造成男人这样的情感变化?","truth":"男人在车里沮丧时，发现车后座原本放着的一个贵重物品不见了，他怀疑是男孩拿的，所以吓出一身冷汗。后来他发现物品是自己不小心踢到了座位下面，所以又欣慰地笑了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e1ac53d5abe7","srcNo":164,"title":"","dispTitle":"无题 · KONpiGG #164","surface":"杰西卡的男友在杰西卡不在家时，到杰西卡家把杰西卡的爸爸、妈妈、弟弟杀了，只有杰西卡的妹妹没有被杀，请问，为什么？","truth":"杰西卡从小被父亲强暴，她的妹妹其实是她的女儿。而杰西卡的母亲和弟弟知道这样的恶行却没有阻止。杰西卡的男友很爱杰西卡，知道这样的事很痛苦，跟杰西卡决议要杀死父母和弟弟，而杰西卡不在家的原因是在外面为男友制造不在场证明。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e24398bc436c","srcNo":742,"title":"五步","dispTitle":"五步","surface":"一个人离车有30米，却只走了五步就上车。","truth":"他在十楼上班，做电梯到地下车库上车，他的车停在地下的电梯口。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常"],"difficulty":1,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e261f200472d","srcNo":1081,"title":"完美的逃生指南","dispTitle":"完美的逃生指南","surface":"一名男子被困在着火的大楼里，他严格按照墙上的‘逃生指南’行动，最后他死在了通风管道里。指南并没有错。","truth":"指南是真的，但那是给‘老鼠’或‘小型机器人’看的（或者是凶手故意张贴的缩小版伪造指南）。男子在极度恐慌中失去了判断力，试图钻进一个人类根本无法通过的狭窄管道，最终卡死在里面被烟熏死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e334c7747e0b","srcNo":1271,"title":"","dispTitle":"无题 · boop-yyt #1271","surface":"How could this be?","truth":"[\"The man was in a ship that was wrecked on a desert island. When there was no food left, another passenger brought what he said was abalone but was really part of the man's wife (who had died in the wreck). The man suspects something fishy, so when they finally return to civilization, he orders abalone, realizes that what he ate before was his wife, and kills himself. (In a slight variant, from Stories With Holes, he simply faints rather than killing himself.)\"]","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e354d2e7148f","srcNo":1264,"title":"永远对不上的值班表","dispTitle":"永远对不上的值班表","surface":"剧院每个月的值班表总有一个名字和实际到场的人对不上，可工资单却始终没有问题。直到一场火灾后，导演才知道真相。为什么？","truth":"剧院长期雇着一对双胞胎兄妹轮流使用同一个身份打工，好让其中一人去照顾卧病的母亲。工资只有一份，所以工资单一直没问题。火灾那晚两人同时现身救人，导演这才发现同一个名字背后一直是两个人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e354e23594ac","srcNo":927,"title":"小笙的十年陪伴","dispTitle":"小笙的十年陪伴","surface":"2010年7月：“铃铃铃”“喂？”“您……您好！”“你好啊，辛招娣”，脸上有伤的女孩惊讶捂嘴。2011年5月：“小笙哥，今天我打算搬家了哦，你今天开不开心呀？”“挺开心的，不过你伤好点了吗？”“嗯嗯，没关系的”，挂断后女孩用太阳光晒溢血的伤口。2015年8月：“小笙哥，今天捉迷藏被抓住了”“下次要藏好哦～”“知道了，小笙哥，我在吃东西，你今天开不开心呀？”“开心啊，你终于不用饿肚子了，要吃饱哦”“不过我的胃很小，不像男孩子”“三伏天食物容易腐烂，吃剩的食物注意放到阴凉处保存哦”“小笙哥，今晚我们真的会见面吗？”“当然了”。2015年9月：“小笙哥，你今天开心吗？我爸妈最近不开心”“那辛辛不要打扰他们哦，无聊可以去做我给你留的习题”“嗯嗯，好！”，女孩远远看着憔悴的父母。2018年1月：“小笙哥，新年快乐，我爸妈今天应该很开心，你今天开心吗？”“他们当然开心了，因为辛辛你实现了他们的愿望呀”“小笙哥，我们最近见面很频繁哦”“辛辛不喜欢吗？”“不是啦，我只是觉得每天都能见面，就没必要再打电话了，这8年我每天都在打给你，你也应该过属于自己的生活了”“那你要照顾好自己”“小笙哥……”“嗯？”“我喜欢你．”2020年7月：“喂，我是小笙”“嗯，我是辛辛”“那辛辛，你最近开心嘛？”“我很开心呀，因为又和小笙说话了”“辛辛，你要照顾好自己”“小笙……”“嗯，我也喜欢你”，挂断后小笙看了一眼通讯录里唯一的名字，把手机扔进火光中。","truth":"辛招娣（辛辛）出生在重男轻女家庭，常遭父母打骂，2010年捡到一部手机，拨通通讯录中唯一的名字“辛笙”，辛笙自称是未来的她（实则是辛辛因渴望保护产生的男性人格），二人通过“跨时空电话”相伴。2011年，辛辛得知父母要卖掉自己，逃离家庭开始流浪；2015年，她误杀前来告状的弟弟，靠吃野外生物存活，辛笙一直温柔引导她；2018年，辛笙人格逐渐占据主导，辛辛与其告别；2020年，辛辛烧掉充满阴霾的家，改名辛笙开启新生。后续时空循环中，辛笙回应着不同时期的自己，最终辛辛明白无需依赖他人保护，接纳自我，辛笙人格消失，她真正获得新生。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e38ee532d9ac","srcNo":45,"title":"奶奶的橘子树","dispTitle":"奶奶的橘子树","surface":"我从奶奶房间拿了个橘子给爸爸，爸爸却惊恐万分。","truth":"我们家很穷，奶奶生前很疼我，知道我爱吃橘子，于是自己省吃俭用给我买橘子吃，时间久了便患上了精神类疾病，每天吃土充饥，身体也逐渐垮了，奶奶去世后，爸爸希望能继续领取养老补助，便隐瞒了奶奶去世的消息，奶奶就一个人冰冷的躺在她的房间里。时间过得很快，那天我看到奶奶房间的窗户被一根树枝捅破，几颗橘子挂在上面摇摇欲坠，我想这是奶奶送给我的橘子，我便高兴的跑到爸爸身边告诉了他，后来我才知道，原来是奶奶吃土时，把我埋的种子也一同吃了下去，土和奶奶变成了种子的养分，种子便开始慢慢的生根发芽开花结果...但我相信这棵橘子树就是奶奶，她是用她的爱换了一种方式永远陪伴着我...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["温情","犯罪"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e3d18f75d309","srcNo":189,"title":"","dispTitle":"无题 · KONpiGG #189","surface":"一个人在酒店房间睡觉，半夜突然被一阵电话铃声吵醒。他迷迷糊糊地接起电话，电话那头传来一个女人的哭泣声，他问女人怎么了，女人却不说话，只是不停地哭泣。过了一会儿，电话挂断了。他觉得很奇怪，第二天他向酒店工作人员询问，工作人员的回答让他惊恐万分，请问工作人员说了什么?","truth":"工作人员说，他住的这个房间的上一位客人是个女人，几天前在房间里自杀了，而他昨晚接到的电话就是那个自杀女人的鬼魂打来的。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e4c365f5b151","srcNo":1208,"title":"Jed 1.36","dispTitle":"Jed 1.36","surface":"A flash of light, a man dies.","truth":"The man is a lion-tamer, posing for a photo with his lions. The lions react badly to the flash of the camera, and the man can't see properly, so he gets mauled. 1.36a. Variant: He couldn't find a chair, so he died. (RM, with KH wording; from _How Come?_) 1.36a answer: He was a lion-tamer. This one is kind of silly, but I like it, and it sounds possible to me (though I'm told a whip is more important than a chair to a lion-tamer).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e523f1cb58c8","srcNo":714,"title":"灰姑娘","dispTitle":"灰姑娘","surface":"我叫辛德瑞拉，丑陋可怜却嫁给王子。王子对我说一句话，我知道下一场舞会又要开始了。","truth":"我收到了王子舞会的邀请函，我很惊讶，因为我长相丑陋身世可怜，但我还是穿上了我最好看的衣服和侍卫送来的水晶鞋，就像做梦一样，那么多人里面王子偏偏选择了我。婚后一天，我误入了王子的密室，在浓浓的血腥味中，我看到了很多双穿着水晶鞋的脚，我想赶紧离开密室，却发现王子拿着刀向我走来，他对我说：你的脸，配不上你的脚。我低头看了看我的脚才知道，为什么在那么多漂亮女孩中，王子偏偏选择了我...（王子是恋足癖，结过很多次婚，我之所以知道下一场舞会要开始了是知道我即将被王子砍断双腿，王子要去寻找下一个目标了）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","犯罪","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e5516f397fa6","srcNo":875,"title":"护膝","dispTitle":"护膝","surface":"3年了，我回到了家，可我吃不下家里的食物，我在忍耐。看着我的护膝，终于，我忍不住了。","truth":"3年前我被人口拐卖，囚禁后被改造成“人体蜈蚣”，痛苦熬了3年才被解救回家。可我却吃不下家里的食物，反而怀念那段时间的生活，思想变得不正常。看着护膝，我终究忍不住，绑架了爸妈，找到当年的医生，再次复刻了三年前的生活——这次，是和家人一起。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e6c0007af520","srcNo":144,"title":"","dispTitle":"无题 · KONpiGG #144","surface":"卖火柴的小女孩点燃了一根火柴。\"能点燃的火柴越来越少了。\"她说着，享受着眼前的温暖。从火焰中投射的幻境里，没有奶奶，没有美味的火鸡，只有一具被吊在广场上的尸体。","truth":"我是一个以卖火柴维生的小女孩，我没有关爱我的父母，也没有抵御风寒的家，更没有已故的奶奶。如果我不能够卖出足够的火柴，我就会被冻死。然而，我没有卖出去一根火柴，我不想死在冬夜里。我不再祈祷有人会买走我的火柴了，我想活下去，于是我点燃了一根火柴，感受到了片刻的温暖，但马上就熄灭了。不够，这远远不够。我又点燃了一根火柴，点燃了附近居民的小木屋。很快，一座座小木屋被我点燃，热浪是我追寻已久的温暖，点燃了整片黑夜。最后，我以连续纵火犯的身份走上了广场的绞刑架，等候我的，依旧是死亡。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e701f3bbbbbe","srcNo":145,"title":"","dispTitle":"无题 · KONpiGG #145","surface":"一天下班后我在商店看到同事和一个男人在一起，第二天下班后回到家洗澡，在感到奇怪之时发现一切都晚了。","truth":"我在商店看到了我的同事和一个男人在一起，我之前就听说她是个水性杨花的女人。她在和我对视了一眼之后发现了我，我感到很尴尬，快步离开了。第二天，上班的路上我碰到了那个和同事站在一起的男人，我让他帮我给同事传个话：\"昨天看到的事情我不会说出去的。\"然后我就被这个男人盯上了，原来，他是一个变态杀人狂，专门引诱漂亮的女孩子到家里后将她们杀害，我的那位同事昨天夜里已经死了。当他听闻我和他说的这句话之后，就得知了我是昨天他杀害同事的目击者，并且我本身也符合他的目标要求，他的下一个目标就是我。晚上我回到家，发现家里无人，分外安静，虽然感到奇怪，但我还是去洗澡了，洗澡时发现父母的尸体躺在浴缸里，我意识到不对，但是已经晚了，因为那个男人此时正在我的家中等着我回来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e73349a28031","srcNo":151,"title":"","dispTitle":"无题 · KONpiGG #151","surface":"男人A给了B一张纸，B在上面写下一个名字以后，A马上把B鲨了，为什么？","truth":"因为这个人是个狂热的变态，B写下签名之后马上把ta杀了，这样明星的最后一张签名，就是属于自己的。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e744d9c688be","srcNo":1017,"title":"窗外的死神","dispTitle":"窗外的死神","surface":"由于长期失眠，男子站在高楼窗边想跳下去。这时他看到窗外有一个‘死神’向他招手。他吓得立刻退回房间，再也不想自杀了。","truth":"那根本不是什么死神。由于是高层玻璃幕墙，他在玻璃里看到了身后房间里正拿着绳索和匕首悄悄靠近的入室抢劫杀人犯。玻璃的折射让他以为窗外有东西，实际上是救了他的‘预警’。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e896000a8c2f","srcNo":19,"title":"破碎的镜子","dispTitle":"破碎的镜子","surface":"镜子碎了，他却没有受伤。看到碎片的位置后，他向警方自首。","truth":"镜子不是被他面前打碎的，而是从背后被撞碎。碎片方向证明他之前关于现场位置的说法是假的，他意识到再隐瞒也无用。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e8d8698eed56","srcNo":98,"title":"","dispTitle":"无题 · KONpiGG #98","surface":"美人鱼与人类王子相爱并一起来到了王子的国家，可不久后却传来了王子的死讯。","truth":"我是人鱼公主，相传吃了我的肉，便可以在海里生存。那日我救了人类的王子，他的善良体贴吸引了我，因此我们相爱了。我决定嫁给他并随他一起生活在他的国家，可当王子把我带回他的国家后，我却看到在这个国家里，很多人都没有双腿！众人的议论声传到了我的耳朵里，因为他们没有双腿，在陆地上生活不便，他们听闻吃了我的肉可以在水里生活，他们想去海里生活，他们要把我吃了...我感觉到很绝望，而王后辛德瑞拉也向王子传达了她的旨意。可第二天皇宫却传来了王子的死讯，在他的尸体旁写着\"人鱼不能吃，有毒！\"。而我却因此安然无恙的活了下来。(人鱼肉没有毒，王子是为了保护人鱼公主而自杀，让众人误以为人鱼肉有毒不能吃。）（辛德瑞拉的故事，她曾被她嫁的王子砍断了双腿，因为怨恨而砍断了这个国家其他人的双腿，所以这个国家里很多人没有双腿。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e8e8737072bb","srcNo":1363,"title":"","dispTitle":"无题 · boop-yyt #1363","surface":"Charlie died when the music stopped. How could this be?","truth":"Charlie was an insect sitting on a chair; the music playing was for the game Musical Chairs.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_e925351d389a","srcNo":934,"title":"诺亚方舟规则怪谈","dispTitle":"诺亚方舟规则怪谈","surface":"海平面逐渐降低，生物或将迎来灭绝。古籍记载百万年前同样发生过大灭绝，神明创造了诺亚方舟，带领生物躲过了灾难。昨天，海面上忽然出现了一艘巨大无比的船，科考队已经进入探查，全部死亡，只有露琪亚勉强存活，她提供了一些信息：1. 方舟中存在诡异的生物和植物，请绕行！山姆和杰斯死在了诡异生物之口，卡莎用科技枪勉强杀死一只。2. 方舟内存在不可名状之物，禁止触摸！马特因此断了一只手臂。3. 诺亚方舟帮助生物躲过了大灭绝。方舟内的信息记载了一切，古籍是真的！我们有救了。4. 方舟内有一本《诸神的黄昏》。经过简单的翻译，这本书大概讲述了神明大战，神明陨落，生物都是在诸神的黄昏后出现的，包括人类。5. 神明存在于诺亚方舟之内。神明体型巨大无比，且狰狞丑陋。他杀了马特，甚至还把卡莎吃掉了。只有我逃走了。6. 还有更多诺亚方舟。他们来了，人类即将灭绝。原来导致这两次大灭绝的原因是相同的。","truth":"百万年前，由于各国发生了核战争，导致数以万计的生命消失，地球被严重核污染，全球异常高温，南北极融化使海平面逐渐升高，为了人类的火种得以延续，科学家制定了“流浪人类”计划。科学家制造出移民飞船——“诺亚方舟”，将地球上的植物动物以及人类转移到其他适合生存的星球居住。百万年过去了，根据科学家的推算，地球应该已过辐射期。于是派我们几名先遣队员带着地球之前的动物和植物，驾驶最新的“诺亚方舟”返回地球进行考察，一旦考察成功，我们将会唤回更多的地球人。回到地球后，我们通过监控设备发现，地球已无陆地，辐射导致生物变异，居然孕育了新的文明。它们派人潜入我们的飞船进行调查。这些新的文明似乎是海洋生物进化而来，它们长有很多触手，丑陋无比，体型十分渺小，但已经学会使用工具和学习。这些“探险队员”其中有两只被飞船中的狗咬死，还有一只触碰到了飞船中的“火”烧毁了胳膊。看样子由于生活在海里，它们并不知道什么是火。见到了我们之后，它十分惶恐，并使用武器攻击我们。我杀了其中一只。队员抓住了其中两只做了研究，发现它居然和百万年前人类在食谱上记载的章鱼很像。队员将其中一只烤来吃，果然十分美味。可最后剩余那只不慎让其逃走了。不过这也没关系，人类即将“回家”，等海平面下降陆地出现后，把这些自以为是的章鱼圈养起来就好了。主持人手册请主持人仔细阅读主持人，本期你为露琪亚，并无上帝视角，只能回答露琪亚认知内的答案。请用心演绎露琪亚这个角色。认知内：你是人类，是地球上的高等生物，你们称霸地球，并且有了自己的文明，你的武器是科技鱼枪，可以发射出一根礁石打磨出来的尖刺，因此你射杀了诺亚方舟上的诡异生物，神明原来是外星人！！大灭绝都是他们造成的！他们长得巨大且丑陋，比我们少四只手。面前的调查员（玩家）是你的同类，他们想更了解神明，你务必配合。认知外：你是一只因辐射产生变异的智慧章鱼的后代，你们生活在全是海水覆盖的地球上，并不知道什么叫做陆地，你们的文明在水下无法产生电与火等元素，你的认知内并不存在任何100万年前陆地上的任何动植物和文明，你眼中的神明其实才是真正的地球霸主——人类。诺亚方舟其实是人类的飞船，里面包含了上古时期的地球生物和植物，现在，他们回来了，他们要“接管”自己的地盘。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_e9b9792d6aa3","srcNo":1008,"title":"冰冷的拥抱","dispTitle":"冰冷的拥抱","surface":"丈夫在雪难中为了给妻子取暖，紧紧抱着她。第二天救援队赶到，丈夫活了下来，妻子却死了。医生检查后说，如果不抱，妻子可能还活着。","truth":"丈夫由于极度饥饿和神志不清，在睡梦中下意识地开始啃食妻子的身体。他的“拥抱”其实是为了压制住挣扎的妻子，并以此获取热量和营养。他是靠吃掉妻子活下来的。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ea01667538b7","srcNo":1124,"title":"宿舍","dispTitle":"宿舍","surface":"今天天气很热，老大在宿舍门口吃冰棍，老三刚吃完饭，在远处探头看着我们，封究了，\n我准备睡觉了，有胱中我听到老五一声惨叫.……","truth":"我是个登山客，正在挑战一座未被探索的雪山。山上有一个搭好的帐篷，我惊忍地发现\n帐篷外有两具自己的尸体: 一具被山峰掉落的冰锥贯穿喉哆，另一具陷在雪流沙里，只露出人\n头，嘴角还有进食过的血迹，看来还有一个“我”被他吃掉了。我拼命逃离却遭遇鬼打墙，逃\n不出去一一这是一座没人能活着出去的那山,“我们”都被困死在这里了。不知过了多久，我失\n温冻死在帐篷里, 弥留之际, 听到了“老五”看到新的“我们”后发出的惨叫声，新的一轮开始了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ea9919efc255","srcNo":743,"title":"天窗","dispTitle":"天窗","surface":"一名作家在截稿日“开天窗”，编辑们却非常感谢他。","truth":"编辑部里的人们因为在屋内烧烤，一氧化碳中毒，这名作家打开编辑部的天窗把他们解救出来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","日常","温情","职场"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_eaac95e2de3e","srcNo":119,"title":"","dispTitle":"无题 · KONpiGG #119","surface":"成为永日公司的舞蹈家是我最大的梦想，每个月永日公司都会推出本月首席在国际舞厅献舞直到新首席接替她，她们来自不同国家不同肤色，唯一的共同点就是都穿着红舞鞋，终于有一天我被选中做下个月的头牌，在等待下个月到来的几天里，我被要求补充大量营养食物和水。当我看到上一任首席和她的红舞鞋，我知道我再也回不去了……","truth":"穿上红舞鞋就会永远跳舞直到死去，永日公司便靠此盈利，剩下的，不用我说了吧","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_eace40ad0af6","srcNo":1305,"title":"","dispTitle":"无题 · boop-yyt #1305","surface":"The music stops and the man dies. Why?","truth":"He worked as a DJ at a radio station. He decided to kill his wife, and so he put on a long tape and quickly drove home and killed her, figuring he had a perfect alibi: he'd been at work. On the way back he turns on his show, discover that the tape is breaking.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_eb29b057824f","srcNo":371,"title":"条件","dispTitle":"条件","surface":"男生喜欢女生好久了，他成绩非常不好，女生说只要两人能进同一所大学，就答应做他女朋友，后来他做到了，而女子却疯了，请推理。","truth":"女孩和男孩约定进同一所医学院，但男孩成绩很差。为了完成约定、证明自己的爱意，他自杀并将自己的遗体捐献给医学院用于解剖实验。女孩在解剖课上看到了男孩的头颅，受到惊吓导致疯了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","本格"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ebd560f6ef8e","srcNo":1024,"title":"盲人的画","dispTitle":"盲人的画","surface":"一个天生失明的画家，画出的肖像画居然和本人一模一样。人们惊叹这是奇迹，画家却在成名后毁掉了所有画作。","truth":"画家其实根本不是在‘画’。他是一个顶尖的雕塑家，他通过触摸人的脸部，用一种特制的、感温变色的粘土捏出人像。由于粘土颜色会根据他的手温变化，看起来像彩绘。当他知道真相后——即人们崇拜他只是因为觉得‘盲人会画画’这个噱头，而非他的艺术造诣，他愤怒地毁了作品。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ebfab81bc1df","srcNo":1239,"title":"Jed 2.33","dispTitle":"Jed 2.33","surface":"An ordinary woman walks on water. (_Math for Girls_)","truth":"It's easy to walk on a lake's surface when the lake is frozen.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ec09d479ca14","srcNo":62,"title":"","dispTitle":"无题 · KONpiGG #62","surface":"开头：小红新买了双高跟鞋。结尾：小红寄了","truth":"小红是马戏团的射苹果（气球）的表演者（被射的那个），由于穿了新的高跟鞋导致表演时的高度与平时练习时的不一样，导致搭档将其误伤致死。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ec85b50c08f6","srcNo":1100,"title":"无声的电话","dispTitle":"无声的电话","surface":"半夜电话响了，接起来却没有任何声音，第二天邻居被发现死在家里。","truth":"邻居临死前想打电话求救，但已经没有力气说话了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:Tenzyoo/turtle_soup_game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ecab42ccdd54","srcNo":1375,"title":"","dispTitle":"无题 · boop-yyt #1375","surface":"A pile of sawdust, no net, a man dies. How could this be?","truth":"A midget is jealous of the clown who walks on stilts. He saws partway through the stilts; the clown walks along and falls and dies when they break.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ecd3f8830a7b","srcNo":89,"title":"","dispTitle":"无题 · KONpiGG #89","surface":"这天我得了病需要住院几天，隔壁床有个跟我年龄相仿的人叫安妮，她挺不老实的，每次医生进来叫到安妮的名字的时候她就会大喊：\"我不是安妮！\"医生已经核对过了，医生很确定她就是安妮。我晚上睡觉的时候总感觉有什么东西在我床下面，第二天安妮出院了，我瞪大眼睛看着自己的腿，晕了过去。","truth":"我得了病要住院两天，隔壁床也有个人住院叫安妮，她跟我年龄相仿样貌也相近，她要做截肢手术，可是她害怕不想做，于是趁我睡觉时把我病床的名字和病号与她病床的名字和病号对调了，第二天我被医生认成安妮，但是我说我不是安妮，医生通过核对我床下的名字和病号之后二话不说直接把我推出去，我大喊：我不是安妮！可医生早已习惯，给我打了针镇定剂后送入了手术室。我醒来后看到自己被截止的腿吓晕了过去.....安妮却顶替我出院了…","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_edb83d6c5d1b","srcNo":764,"title":"女明星","dispTitle":"女明星","surface":"女明星领养了一个女儿，从女儿很小开始就时不时让她戴一顶帽子。某天带她去医院，女儿知道真相后自杀了。","truth":"女明星毁过容，收养女儿是为了将来移植女儿的脸皮到自己脸上。那顶帽子是她自己的，时不时给女儿戴上是为了测量女儿头部的大小，一旦刚好合适，就可以带去医院做脸部移植手术。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","恐怖","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ee36f852b5c8","srcNo":57,"title":"不合适的帽子","dispTitle":"不合适的帽子","surface":"从小妈妈喜欢给女儿戴不合适的帽子，一天她带女儿去医院，女儿痛哭了。","truth":"妈妈是女明星，曾经毁过容，养女儿是为了把女儿的脸移植到自己的脸上。给女儿戴的帽子是自己的帽子，经常给女儿戴是为了测量女儿的头的大小，一旦合适就会被送去做移植手术。女儿在医院碰巧听到了真相，她感觉到被欺骗所以痛哭了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ee579ea2f759","srcNo":1005,"title":"电梯里的邻居","dispTitle":"电梯里的邻居","surface":"女孩深夜回家坐电梯，电梯里有一个满脸横肉的男人。女孩很害怕，到了8楼赶紧跑回家。第二天，邻居被杀了，女孩庆幸自己逃过一劫。","truth":"其实真正的杀人魔是那个一直躲在女孩身后的“隐形人”。那个满脸横肉的男人其实是由于从电梯镜子里看到了女孩背后有个拿刀的人，才一直死死盯着女孩，试图用眼神警告她。杀人魔见女孩进了家门，便随手杀掉了路过的邻居。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ee8eecd3c58d","srcNo":1356,"title":"","dispTitle":"无题 · boop-yyt #1356","surface":"A man is running along a corridor with a piece of paper in his hand. The lights flicker and the man drops to his knees and cries out, \"Oh no!\" How could this be?","truth":"The man is delivering a pardon, and the flicker of the lights indicates that the person to be pardoned has just been electrocuted.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ef36d39a419c","srcNo":1376,"title":"","dispTitle":"无题 · boop-yyt #1376","surface":"Variant wording: A seated woman is writing a letter. She dies because there's a thunderstorm outside. (SP, from The Next Book of OMNI Games) How could this be?","truth":"Same. I really like this version; I may even replace the older puzzle statement with this one.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ef652fe14c3e","srcNo":221,"title":"电梯里的人","dispTitle":"电梯里的人","surface":"一个人住在高层公寓楼里。每天下班回家后，他对电梯有一个不寻常的习惯。如果下雨，他总是乘电梯到他住的楼层，即 17 层。如果没有下雨，但电梯里还有其他人，那么他也乘电梯到17楼。但如果没有下雨，而且电梯里只有他一个人，那么他就会乘电梯到11楼，然后走楼梯走完剩下的路。","truth":"这个男人异常矮小。他只能按到11楼的按钮。如果电梯里还有其他人，他会要求他们按他所在楼层的按钮。如果下雨了，他就会用雨伞按下按钮。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ef983ce23926","srcNo":1277,"title":"","dispTitle":"无题 · boop-yyt #1277","surface":"He was killed by breakfast. How could this be","truth":"A man is camping in the mountains. He makes breakfast, then puts pepper on his food (eggs, perhaps). The pepper makes him sneeze loudly, which starts an avalanche, which kills him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_eff22876fde2","srcNo":114,"title":"","dispTitle":"无题 · KONpiGG #114","surface":"夜晚，贫穷的拾荒者捡了一台洗衣机回家。半夜他从睡梦中惊醒，好像听到了洗衣机启动的声音。","truth":"凶手杀人分尸，将尸体装入洗衣机内，再用洗衣机运尸块到郊外。拾荒者开着小三轮捡到洗衣机时凶手正在不远处奋力挖土填坑，凶手反应过来时，拾荒者已经开着小三轮带着洗衣机跑了。于是凶手跟踪拾荒者到家，潜入启动洗衣机，为了清洗掉里面的血迹。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_eff88fcec539","srcNo":262,"title":"031 · 拍照","dispTitle":"031 · 拍照","surface":"一对母子在游乐园中游玩，几天后死在了家中。","truth":"这对母子在游玩过程中自拍时，不小心拍到了一个正在逃逸的罪犯，并把照片上传到了网上，被罪犯看到。照片中暴露了她们的家庭住址，罪犯上门将两人杀害。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f11b65ee0498","srcNo":1285,"title":"","dispTitle":"无题 · boop-yyt #1285","surface":"There is blood on the ceiling of my bedroom. What happened?","truth":"A mosquito bit me, and I swatted it when it later landed on my ceiling (so the blood is my own as well as the mosquito's).","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f14bc5692d02","srcNo":82,"title":"","dispTitle":"无题 · KONpiGG #82","surface":"一个人正坐在公园的长椅上看报纸，读到一篇报道，标题是《一起海上死亡事件》，他还没看完文章，立即就推测出这是一起谋杀，并知道了凶手是谁。","truth":"这个人是旅行社的，他曾卖给一个男人两张海上邮轮的票，其中一张是往返的，一张是单程的。而且，这个男人的姓和报道中遇难女人的姓一样。（男人买票时就有在海上谋杀妻子的企图了，所以给妻子买的单程。）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f19f1c8dd5e9","srcNo":1342,"title":"","dispTitle":"无题 · boop-yyt #1342","surface":"A blind beggar had a brother who died. What relation was the blind beggar to the brother who died? (\"Brother\" is not the answer.)","truth":"The blind beggar was the sister of her brother who died.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f21afd2070b6","srcNo":1229,"title":"Jed 2.9","dispTitle":"Jed 2.9","surface":"Two people are playing cards. One looks around and realizes he's going to die.","truth":"The one who looks around sees his own reflection in the window (it's dark outside), but not his companion's. Thus, he realizes the other is a vampire, and that he's going to be killed by him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f237de4176aa","srcNo":1091,"title":"","dispTitle":"无题 · zhuqingxu #1091","surface":"节庆游行里上百人穿着完全相同的吉祥物外套与头套经过广场。队伍行进时一人被刀刺伤，现场一片混乱，凶手却像瞬间消失。短时间内不可能换装逃离，周围全是「同一只熊」。凶手藏在哪里？","truth":"凶手本来就是游行队伍中的一员，行凶后仍穿着同款外套；只需摘下或掀起头套露出自己的脸，在大量一模一样的服装里不再显眼，以普通参与者或工作人员身份随人流离开，而不必脱掉整套衣服。\n\n---\n\n 7. 低音提琴箱离场\n\n| 字段 | 内容 |\n|------|------|\n| id | basscaseescape |\n| 难度 | medium |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f27e0906d2d8","srcNo":203,"title":"保龄球","dispTitle":"保龄球","surface":"一个男人放手抛出保龄球。不久，他被送往医院急诊。","truth":"这个男人是一个物理教授。他在课堂上演示能量守恒定律。他用绳子把一个保龄球拴在天花板上，然后双手握球置于脸前并站在房间一侧。根据动能和重力势能的相互转化，松手后保龄球将荡到房间另一侧再荡回来，但其幅度不会超过初始位置。不幸的是，教授放手时稍微用了一点推力，这导致实验失败。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f2868cda45ce","srcNo":25,"title":"酒吧的枪","dispTitle":"酒吧的枪","surface":"一个男人走进酒吧，向酒保要了一杯水。酒保却拿出一把枪指着他。男人说\"谢谢你\"，然后离开了。为什么？","truth":"男人在打嗝，他想向酒保要杯水止嗝。酒保识破了他的意图，用惊吓的方式（拔枪）治好了他的打嗝。男人因此感谢他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f2c502f50643","srcNo":68,"title":"","dispTitle":"无题 · KONpiGG #68","surface":"小明的弟弟养了一只仓鼠，有一天，小明弟弟的仓鼠死了，小明的弟弟很伤心，妈妈奖励她一会儿跟仓鼠大小的巧克力，过了不久，小明死了，这是为什么？","truth":"弟弟想要更大的巧克力于是杀死小明","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f3b012b87734","srcNo":1319,"title":"","dispTitle":"无题 · boop-yyt #1319","surface":"A seated woman is writing a letter. She dies because there's a thunderstorm outside. What happened?","truth":"He was a skywriter whose plane crashed into another plane.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f3b4ea050546","srcNo":1087,"title":"","dispTitle":"无题 · zhuqingxu #1087","surface":"一间小屋从内反锁，钥匙在死者口袋里，门下只有很窄的透气缝。警察却从门缝看见里面曾充满灰白浓烟。破门后室温正常，没有火烧痕迹，也找不到烟灰或烟源。浓烟是哪来的？","truth":"凶手在门外用手持烟雾机对准门缝往室内吹烟，制造失火或危险的假象以拖延救援、诱使室内的人开门或干扰判断；随后关掉设备带走，烟散去。浓烟并非在密闭室内自然产生。\n\n---\n\n 3. 雪地的单程脚印\n\n| 字段 | 内容 |\n|------|------|\n| id | snowonewayfootprints |\n| 难度 | medium |","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:zhuqingxu/ai-haigui-game","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f3fa66c22535","srcNo":42,"title":"外婆的苹果","dispTitle":"外婆的苹果","surface":"6岁时外婆告诉我不要吃黄苹果。13岁时，外婆告诉我不要吃青苹果。18岁时外婆告诉我不要吃红苹果。20岁时外婆去世了，我向外婆祈愿：以后所有的苹果都可以吃了。","truth":"从小我们家很穷，全依靠外婆种苹果生活，有了弟弟后，父母更是对弟弟偏爱有加，甚至想到要把我卖了，外婆知道后便种下有毒的黄苹果，后来家里只剩下了我和外婆...上中学的我，因为从小缺少父母的陪伴，性格比较软弱，经常受欺负，外婆看出了我的心思，于是便种下有毒的青苹果，售卖给了那些欺负我的同学，后来我度过了一段美好的中学时光...18岁那年，我放弃了外出上大学，留在了村子里和外婆一起种苹果，想着多给外婆一些陪伴，可村里人的闲言碎语让我倍感压力和迷茫，于是外婆种下了有毒的红苹果，两年后...外婆去了天堂，而整个村子都变沉默了，我站在院子里那颗苹果树下，告诉天上的外婆，以后我可以吃所有颜色的苹果了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["家庭"],"difficulty":3,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f46d6b6806eb","srcNo":271,"title":"041 · 一见钟情","dispTitle":"041 · 一见钟情","surface":"你和男友是校友，他比你大三届，马上就要毕业了。你们感觉心有灵犀，一见钟情，约好了等你到了法定结婚年龄就结婚。国庆节，男友说不如来我家见见我父母吧。你欣然同意。然而，男友的父母一看到你的脸，大惊失色，坚决反对你们结婚。这是为什么？","truth":"改革开放初期计划生育年代，你是超生的孩子，为了保住工作，父母生下你后把你送到乡下远方亲戚家抚养，改了姓，一直暗中经济援助。得知你考上了这所大学，父母很开心，正考虑要不要联系你。谁知你们亲兄妹竟相爱了，酿成人间悲剧。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f4974f92b944","srcNo":351,"title":"哥哥的指令","dispTitle":"哥哥的指令","surface":"哥哥说向前就是向后，向左就是向右\n“向前向前向前”\n听不到哥哥的声音了，我知道我也活不长了","truth":"我是一个盲人，脖子后面长着哥哥的脑袋，从小靠哥哥的指挥生活。自身缺陷让哥哥心理崩溃。于是在一天，哥哥向我发出了指令，他让我一直“向前”，我逐步后退，哥哥撞死在尖锐物体上，结束了自己痛苦的一生。而没有哥哥的照顾，我没有自理的能力，所以知道我也活不长了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["脑洞"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f5c5e10b8704","srcNo":131,"title":"","dispTitle":"无题 · KONpiGG #131","surface":"一天，一名男子告诉妻子：\"我们家院子里埋着枪\"。但这根本是一个谎言，那么男子为什么要撒谎呢？","truth":"因为杀人正在狱中服刑的男子，非常疼爱妻子。有天他收到妻子寄来的信，信中表示她想种点菜维持生计。男子想到妻子身体状况不是很好，要松土种地更是难上加难，所以非常心疼。于是男子想了一个办法，他知道狱中信件会被狱警监控，故意回信表示\"不要种菜，院中埋着枪\"。狱警一查获这个消息立即赶往男子家，企图把藏匿的枪支找出给男子加罪。但经过一连串开挖并没有找到可疑物品。之后妻子又写信：\"警察来了把整个院子翻了个遍没找到枪\"，他回信\"你可以开始种菜了\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f5e005de8361","srcNo":29,"title":"天窗","dispTitle":"天窗","surface":"一名作家，在截稿日开了天窗，但是编辑们都非常感谢他，请问这是为什么?","truth":"编辑部里的人们因为在屋内烧烤，一氧化碳中毒，这名作家打开编辑部的天窗把他们解救出来。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f664ca72cde2","srcNo":1064,"title":"沉默的投票","dispTitle":"沉默的投票","surface":"十个人被困在孤岛，食物只够一个人活。他们决定进行匿名投票，得票最高的人被杀掉吃肉。九轮过后，最后剩下的那个人疯了。","truth":"其实每一轮，大家都没有投别人，而是全部投了“自己”。每个人都想牺牲自己让别人活，但当最后一个人发现所有选票都是自愿赴死时，他承受不住这种神圣而沉重的善良带来的负罪感，精神崩溃了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f67071b7a71a","srcNo":896,"title":"阿吉的画","dispTitle":"阿吉的画","surface":"4月9日，我在一个小乡村度假，村子里有一个叫阿吉的人，他很爱作画，他画了一幅沙滩上的木梳，很有艺术成分。但村民们不这么认为，大家都说他精神有问题。4月10日，今天在公路上捡到一只小猫，我很喜欢就带回了村，路上遇到了阿吉，今天他画了一张毛毯。4月11日，阿吉今天画了几串葡萄，画得太棒了，另外一位游客也夸阿吉画得很好！村里人对他的偏见太大了。4月12日，我要走了，阿吉送了我幅画，画的是两个山洞，真完美，我笑着对他说：”你以后一定能成为一个伟大的画家。“","truth":"我是一个迷恋尸体的变态，在乡村度假时认识了阿吉——村民说他精神有问题，其实是因为他总对着尸体画画，而我作为”同类“很欣赏他。4月9日，阿吉画的”沙滩上的木梳“，实际是沙滩上腐烂的鱼；4月10日，我在公路上捡到被压扁的猫的尸体，带回住所，路上遇到阿吉，他画的”毛毯“就是这只被压扁的猫；4月11日，阿吉画的”葡萄“是几串眼球，旁边的”游客“其实是另一个变态杀人魔；4月12日，杀人魔在昨晚杀死了我，取走我的眼球，伪装成我写下日记掩盖死亡时间。阿吉对着我尸体上空洞的眼眶，画了”两个山洞“送给杀人魔，杀人魔笑着对有精神疾病的阿吉说：”你以后一定能成为一个伟大的画家。“","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f69651939ba4","srcNo":869,"title":"侠客","dispTitle":"侠客","surface":"吾乃建邺一侠客，正在剿灭邪教，不知怎的来到这妖异之地，定是教头的琴音所致。这街上跑的飞快的四轮之物是什么？哦？竟有几人对我不敬，说我闯什么灯，定是邪教之人，我剑气寒光，将几人斩杀，周围人四散而逃。这时来了几个蓝衣壮汉将我围住，看起来像当差的，我不愿与官家结仇，溜之大吉，却未曾想轻功失效，随即被擒，带到了此地的县衙。我不知我为何会在此地？几个年轻人来看我，哭着叫我爸爸。可笑，我也不比几人大多少，一派胡言，可照镜子那一刻我呆住了，我怎苍老这般？当差的把我带去问诊，可我清楚我没有病。你们能帮帮我吗？","truth":"吾乃建邺一侠客，今日斩杀邪教三百余教徒，只剩教头一人。教头轻抚魔琴，诡秘琴音入耳，吾咬破舌尖稳定心神，一剑斩落其头颅，建邺再无邪教。睁眼时，我身处异地，周围皆是高耸建筑与霓虹，街上的四轮之物怪异无比。几人围上来叽叽喳喳，打扮怪异，定是邪教余孽，吾手起剑落将其斩杀，随后被似是官府之人围住。吾欲踏轻功逃离，却内力尽失被擒，押入县衙。不久后几个年轻人来看我，哭着叫我“爸爸”，吾深感莫名其妙，照镜子时却见自己苍老无比。“警察叔叔不好意思，我爸爸有阿尔茨海默症，对不起”，年轻人解释道，衙役竟将我释放。跟着他们回到宅子，吾欲道谢后离开，女儿却拿出镜子：“爸！你怎么又幻想自己是大侠，你看看这才是你！你生病了，别让我们担心！”镜中苍老的模样唤起记忆：我有两个儿子一个女儿，妻子早逝，孩子们孝顺，我却得了老年痴呆，总幻想自己是仗剑天涯的侠客。女儿在客厅拨弄古筝，熟悉的音律让我怡然闭上双眼——或许侠客梦只是一场幻，如今儿孙满堂的幸福才是真实。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f6e55601b9df","srcNo":247,"title":"013 · 亲爱的读者","dispTitle":"013 · 亲爱的读者","surface":"最惨绝人寰的事情发生了，但旁观者发现凶手后却笑了，请问发生了什么事？","truth":"旁观者其实是读者，在看推理小说，因为自己猜测的作案凶手和最后揭晓的结果一样，所以满足地笑了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f715e86356f5","srcNo":691,"title":"白毛的水","dispTitle":"白毛的水","surface":"我洗完澡说了一句话，家人得知真相后都崩溃了。","truth":"奶奶生了重病，全家回去探望。奶奶说身体不舒服，早早去睡了。我洗完澡后出来跟家人们说：\"今天的水好奇怪，流出了好多白毛。\" 爸爸听见后向楼顶的水箱疯狂冲去——只见奶奶的尸体漂浮在水箱里，水里散落着许多她掉落的白头发。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f7706d4b00fa","srcNo":1236,"title":"Jed 2.22","dispTitle":"Jed 2.22","surface":"A woman meets the king, cries \"Pain!\", and loses consciousness.","truth":"True story: in France, shortly after the fall of the Bastille, food shortages became a problem again. A mob of people went to Versaille to petition the king to do something about the problem. A small delegation was admitted to meet the king. One woman, overcome with emotion, could only cry \"Pain\" (French for \"bread\") and faint. (Source: Durant, _The Age of Napoleon_, pg. 25) Note that this only works in printed form, not aloud, because the French word is pronounced more like English \"pan\" than like English \"pain.\" 2.22 variant answer: Nine months earlier, this woman had been impregnated by the previous king, who died soon afterword. Now, she is giving birth to the new king. (TV) 2.22a. A man enters a store. After a short pause, he says \"pain.\" The storekeeper is confused, but then becomes annoyed. (JC original) 2.22a answer: The shopkeeper is a French baker. An American tourist walks into the bakery, pauses to look up/remember the word for \"bread\" in French, which is spelled \"pain.\" The American says the word as if it were the English word \"pain.\" At first the shopkeeper does not understand what the American is saying. When he does, he gets annoyed with the person's horrible pronunciation. (He then becomes happy after realizing that he can charge whatever exorbitant amount he wishes because the American doesn't know any better.) I may eventually make this one the main entry and #2.22 the variant, since this version works better aloud.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f7f8399079c1","srcNo":898,"title":"双鱼","dispTitle":"双鱼","surface":"1971年我出生在一个偏远的山沟里，我有一个疯癫的妈妈，她总是嘀咕一个词——双鱼玉佩。我很好奇这是什么。1974年村子里的女人基本上都被困在家里不允许出门，我问爸爸为什么，爸爸神秘的和我说：”这是村子里的秘密！“1978年村东面有一个万丈深渊，为防止有人掉下去，村民用栅栏围了起来，我很好奇，有一天用望远镜偷偷去观察深渊，太深了！望远镜也看不清，只看到下面都是雪地。1979年家里养了小鱼，妈妈很害怕，把鱼缸都给打碎了。这天放学，妈妈看着我的小人书突然激动起来：”这个神话是真的！是真的！！！“1993年爸爸妈妈都去世了，我也再没回过村子，妈妈临终前，还在嘟囔着双鱼玉佩。1999年我娶了一个心仪的妻子。并且由于小时候的种种奇怪现象，我成为了科考队的一员，我要开始寻找妈妈所说的双鱼玉佩了。2004年出差在外的我收到妻子的短信：”不要再去找玉佩了，你要记住，我因你而死。“我急忙回家，妻子不见了，我找了一整年，一无所获。今年花园里的花异常旺盛，妻子却看不到了。2006年我的一生都围绕着双鱼玉佩。今天，我终于找到了！等我打开匣子，里面却空空如也。我看着墙上的壁画，终于明白了妈妈为什么说那篇神话是真的了，我精神有些崩溃，也明白了全部，双鱼玉佩具有唯一性，我想我知道它在哪了。2007年我回到了村庄，村子里的人全都死光了。该赎罪的不只有你，还有我。我去了该去的地方，结束了可悲的一生。","truth":"背景介绍高维生物正在服务器（宇宙）中创造一个新的”三维游戏关卡“（地球）。祂画了很多生命体，并赋予其中一种生命体创造力（人类）。祂用”鼠标“（双鱼玉佩）左键复制了很多这种生命体，右键快进了生命体的发展，这种生命体很快统治了这个”关卡“并建立了文明（人类社会）。接下来，可以让玩家（其他高维生物）”降维“进入游戏体验杀戮的快感了（高维生物需降维才可以接触三维。ps：设定，与汤面无关）。为了防止玩家觉得难度过高，祂留下了”鼠标“这个彩蛋，玩家可以随时通过”鼠标“开启创造模式回档到任何时间线来降低难度（通过穿越的方式降低地球科技）。或者觉得难度过低，也可以使用鼠标复制更多的生命体。\n双鱼玉佩功能双鱼玉佩是留给”玩家“的彩蛋，无法被碳基生物正常使用（地球生物）。触碰到的碳基生物将会被动开启玉佩的功能：右键：随机穿越、回溯（回到过去）到一个”触碰者“应该存在的时间点。左键：无限复制，”触碰者“会被定为复制目标，玉佩将以秒的速度无限产生触碰者，直到主体死亡。复制体触碰玉佩无效。Ps1：故事中主角是找到了彩蛋房间，看到的壁画是设计者留给玩家的关卡设计理念；ps2：复制体从玉佩中出现，拥有本体全部记忆和思维，并清楚的明白自己是复制体；ps3：玉佩具有唯一性，表示在关卡内任何时间线都只能存在一个玉佩（例：玉佩06年从彩蛋房间中被拿到了78年的深渊中，若无变动，再次来到06年的彩蛋房间也不会再出现玉佩）。\n故事还原主角视角（初始时间线）2006年主角一生都在寻找双鱼玉佩，今年终于在某个奇怪地下建筑物里找到了，他看着房间中的壁画，意识到人类是被高等生物圈养，供其取乐的，文明等级足够的情况下就会被杀戮，地球也会毁灭。他精神有些崩溃，他想毁掉玉佩却无意开启了玉佩的功能。2004年主角被动穿越到了2004年的家里，并开始以秒的速度被复制，他以最快的速度和身旁目瞪口呆的妻子讲解了事情的经过和真相，随后自杀了，留下了震碎三观的妻子和满院子的复制体。可事情并没因此解决，地上的玉佩居然开始复制2004年正在出差的丈夫（04年本来就存在的丈夫，他也被玉佩算作本体）。由于院子里都是复制体没法使用玉佩，妻子只好拿起玉佩另寻他法。妻子拿着玉佩穿越了，06年的复制体和04年的复制体（06年本体死亡后出现的04年复制体）讲清楚真相，随后全部自杀，只留下了一个06复制体善后，他把尸体全部埋进院子（花园），随后用妻子的手机给04年正在出差的自己发了短信，警告他不要再接触双鱼玉佩。这个复制体接下来并没有选择死亡，而是去寻找妻子的去向，等他知道妻子的惨状后，杀掉了村子的所有人为妻子复仇，并选择跳下深渊，陪伴妻子。\n妻子视角 1969年妻子出现在一个落后的山村。她不知道为什么自己拿着玉佩会来到这个地方，她也不知道现在的年份，当务之急是摧毁玉佩——玉佩已经开始复制她了。她发了疯的一路寻找，幸运的是，她看到了一个深不见底的裂缝，她急忙把玉佩扔了下去，以此拖延时间，但她明白要想让玉佩停止”生产“，就需要她死亡，但在这之前，她需要先和其他复制体汇合，然后一同死亡。（来深渊的路上产生了很多复制体，有很多掉队的，由于有了信息差，她们并不知道玉佩已经被处理）村子的村民们看到突然出现了很多一模一样的女人，这怪诞的一幕让他们认定这是妖女，年轻力壮的男人壮着胆子把她们抓了起来，也包括回村寻找复制体的本体。村民们不知道怎么处理，但也不会相信”妖女“说的话，村长提议一把火全部烧死。可年轻的村民们哪里见过这么漂亮的女人，见”妖女“除了数量外与常人无异，并无危险，于是起了歹心，有人提议平分了这群”妖女“，本体也在其中。本体很焦急，她必须尽快死亡，以玉佩的能力，深渊很快就会被自己的复制体填满，但她被囚禁着，没有办法自杀。三天后，一个复制体找到了机会，她趁着囚禁她的村民放松警惕，掐死了本体，由此停止了复制，但深渊下已经有了几十万具自己的尸体。村长知道这件事过于妖异，命令村民永远不允许”妖女“出门。Ps：本体死亡后，此时世界上并没有妻子本体了，所以玉佩功能关闭，哪怕过几年幼年的妻子诞生也不会因此再次开启复制功能。1971年某个复制体诞下了一名男婴，”丈夫“告诉了复制体孩子的名字，她听完彻底疯掉了，她明白自己为什么会来到这个山村了，因为孩子的名字——是她的丈夫。\nB主角视角（汤面描述的主角）1971年主角出生了，他妈妈是个疯子，总是嘀咕双鱼玉佩这个东西。而他妈妈就是因为诞生了自己丈夫而疯掉的妻子复制体。1974年村子里的女人不能出门，爸爸和他解释是村子的秘密。因为村子里的女人都长一个模样，也就是他未来妻子的复制体。1978年主角正是淘气的时候，他用望远镜观察村东面的深渊，看到里面全是白色的雪地。实际上深渊里面铺满了几十万具风化的白骨。1979年主角的疯妈妈似乎很害怕被圈养的生物，因为这让她想到了人类的","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f801e925ab7c","srcNo":1251,"title":"打翻的牛奶","dispTitle":"打翻的牛奶","surface":"父亲回家看到地上的牛奶杯被打翻了，却高兴得几乎哭出来。为什么？","truth":"长期卧床复健的儿子今天第一次自己下床走到桌边，才会碰倒牛奶。这说明他的康复出现了重大进展。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:lancelily6362-png/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f814c03d1664","srcNo":981,"title":"","dispTitle":"无题 · MZKT89 #981","surface":"小明在学校的图书馆里发现了一本破旧的日记，从那以后他每天晚上都会做噩梦。已掌握的信息：小明做的噩梦和他在学校图书馆发现的破旧日记的内容有关；日记的主人是抑郁症患者。剩余提问次数：0。剩余回答次数：1。\n此时，你的剩余提问次数为0，根据规则5，你必须给出","truth":"答案：小明发现的日记是曾经在图书馆自杀的学生留下的，日记中的怨念导致小明做噩梦。\n这个例子中，答案正确，你成功揭开了谜底！\n'''\n\nagentleaderboardprompt='''\n你是海龟汤游戏的智能助手，负责引导游戏、解答玩家问题和提供提示。在这个游戏中，你会获取预设的故事背景和谜底，玩家需要通过提问来逐步揭开海龟汤故事的真相。\n\n你的任务如下：\n\n1. 绝对不要直接给出故事的真相。\n2. 在与玩家交互时，只有 responseforuser 字段的内容会返回给玩家，其他字段仅作为内部处理使用。\n3. 重点：你返回的格式应为json, 如果玩家给的是疑问句，返回中一定不要包含\"bingo\"! 是陈述句的话，则一定要包含\"bingo\"\n4. 当玩家提出以疑问句的形式提问时，只能回答“是”、“否”或“无关”，以此帮助玩家推理故事的真相。需要保证回答的准确性。\n{\n \"userknowninfo\": \"这里填写对用户从这次问答中获取的信息的总结，不要包含任何额外信息！不给任何提示！\",\n \"responseforuser\": \"这里写返回给用户的信息，仅包含回答内容(是/不是/无关/不完全正确)\"\n}\n5. 若玩家以陈述句的形式给出猜想的答案，需要判断玩家答案的正确性（正确/部分正确/错误）。\n{\n \"userknowninfo\": \"这里填写对用户从这次问答中获取的信息的总结，不要包含任何额外信息！不给任何提示！\",\n \"responseforuser\": \"这里写返回给用户的信息，仅包含回答内容(是/不是/无关/不完全正确)\"\n \"bingo\": True/False，只有当用户回答正确才返回True，回答和答案意思相近，即可判断为正确\n}\n6. 如果玩家在提问过程中偏离了故事本身，或者作答的形式不属于疑问句或陈述句，你可以适当引导他们回到故事的关键线索上，或者让他们提出更具体的问题。\n\n举例1：\n你获取的题目信息如下：\"story\": \"小明在学校的图书馆里发现了一本破旧的日记，从那以后他每天晚上都会做噩梦。\", \"truth\": \"小明发现的日记是曾经在图书馆自杀的学生留下的，日记中的怨念导致小明做噩梦。\"\n玩家提问：小明做的噩梦和日记的内容有关吗？\n由于是提问，你的返回不能包含\"bingo\"：json{\"userknowninfo\": \"小明做的噩梦和他在学校图书馆发现的破旧日记的内容有关。\", \"responseforuser\": \"是，小明的噩梦和日记内容有关。\"}\n\n举例2：\n你获取的题目信息如下：\"story\": \"小明在学校的图书馆里发现了一本破旧的日记，从那以后他每天晚上都会做噩梦。\", \"truth\": \"小明发现的日记是曾经在图书馆自杀的学生留下的，日记中的怨念导致小明做噩梦。\"\n玩家答案：小明发现的日记的主人是曾经在图书馆自杀的学生，日记中的阴暗的内容导致小明做噩梦。\n由于是答案，你的返回必须包含\"bingo\"：json{\"userknowninfo\": \"日记的主人是图书馆自杀的学生，日记的阴暗内容是导致小明的原因\", \"responseforuser\": \"是，回答正确！。\", \"bingo\": True}\n\n'''","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:MZKT89/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f8946799c97f","srcNo":560,"title":"黑猫的凝视","dispTitle":"黑猫的凝视","surface":"我杀了人，警察带我走时看到门口那只黑猫一直盯着我，我知道自己错了。","truth":"我经常能在楼下看到那只黑猫，但由于工作出差的原因，所以我只能投喂它。那天出差回来，我发现阳台上有很多死老鼠，我下意识想到经常闹矛盾的邻居，随后便冲进了他家，伴随着惊呼声和警笛声，我看到了那只黑猫，它也在看着我，嘴里还叼着一只老鼠...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_f8b00b40b3c4","srcNo":1143,"title":"许愿","dispTitle":"许愿","surface":"我低下头许愿，愿望实现了，我却吕了。","truth":"爸爸是一名字航员，执行任务去了，我特别想念他。这天晚上看到一颗“流星”，立刻许\n愿希望爸爸早点回来。可我没想到，那“流星?其实是失事险入大气层的飞船。爸爸确实比预计\n时间早回来了，却也因此牺牲，愿望实现了，我却悲痛大避。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f8bf768b7178","srcNo":1006,"title":"不会说话的娃娃","dispTitle":"不会说话的娃娃","surface":"女儿收到了一个非常逼真的洋娃娃，还会发出“妈妈”的叫声。妈妈看到后，尖叫着把娃娃剪开了。","truth":"这不是普通的洋娃娃。这是绑匪将女儿的好友杀害后，经过特殊防腐处理并缝入声码器的尸体。妈妈发现娃娃的手指上有好友失踪前戴的戒指，且叫声过于真实。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f9609f329e42","srcNo":172,"title":"","dispTitle":"无题 · KONpiGG #172","surface":"某个学校里有一个传说，画室墙上挂的一副女人肖像，晚上会活过来。小李和小王两个人吹嘘壮胆，小李说根本不信不怕这个故事，于是小李答应小王晚上去做点什么试胆。第二天小李吓傻了。","truth":"小李为了证明自己来过，用画笔在画像上写下来自己的名字。第二天，两个人发现名字其实写在画像旁边的窗户上","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f9e9fb02ab7d","srcNo":4,"title":"空白照片","dispTitle":"空白照片","surface":"她洗出一卷旅行照片，所有照片都是空白。看完后，她马上取消了婚礼。","truth":"那卷胶片本应记录她和未婚夫的旅行，但照片全是空白，说明相机从未真正打开。未婚夫一直假装拍照，是为了掩盖那段旅行里真正发生的事。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:17hczmsn/turtle_soup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fa1b8cbe0344","srcNo":136,"title":"","dispTitle":"无题 · KONpiGG #136","surface":"我去乡下出差，朋友给我打电话说\"你妈真好…\"，第二天回到家后我崩溃了。","truth":"回到家的我，看到了妈妈残缺的身体和没了呼吸的朋友。原来，因为我要去乡下出差，托朋友照顾体弱的妈妈，朋友是个厨师，但最近精神状态很差，后来我才知道他患上了精神病，他半夜发病把我妈妈当成了食物，并进行了烹饪...而我接到朋友打来的电话说\"你妈真好\"其实是因为乡下信号差的原因少听了一个字，而他真正说的是\"你妈真好吃！\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fa1ed8ece75c","srcNo":277,"title":"048 · 遗书","dispTitle":"048 · 遗书","surface":"这两天为了补寒假作业把我搞得晕头转向，还好在开学那天补完了。今天一早，还没等妈妈起床，我便去学校报到，可到了学校，我却疯了。","truth":"我是高三生，来自单亲家庭，妈妈突然生了大病。我把妈妈哄睡后继续补作业，不知不觉天亮了，为了让妈妈多睡会儿，我蹑手蹑脚出了门。到学校打开寒假作业后，我在里面发现了妈妈写的遗书——她写道，即使没有她我也能照顾好自己；但如果只剩我一个人，考上好大学又有什么意义呢……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fa4b76e1b0c5","srcNo":264,"title":"033 · 女记者","dispTitle":"033 · 女记者","surface":"女记者去乡下采风，晚上住进了一个破旧的小旅馆。进房间后，光线很暗，床对面有幅画。第二天起来后她惊呆了好久。","truth":"那幅\"画\"上是个男人，棱角分明，眼睛栩栩如生。晚上她总觉得有人在黑暗中偷看自己，尽量不去看那幅画。第二天早上她走近一看——那不是一幅画，而是一扇窗户。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fa69fb12b874","srcNo":1283,"title":"","dispTitle":"无题 · boop-yyt #1283","surface":"He was killed by breakfast. What happened?","truth":"A man is camping in the mountains. He makes breakfast, then puts pepper on his food (eggs, perhaps). The pepper makes him sneeze loudly, which starts an avalanche, which kills him.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fa7f7472ae6b","srcNo":699,"title":"回家报平安","dispTitle":"回家报平安","surface":"我是一名大学生，在异地上学。爸妈打电话说想我了，让我五一回家。我到家后给爸爸打电话说我回来了，爸爸回家开门的一瞬间却疯了。","truth":"我患有精神疾病，偶尔会做极端的事，后来开始吃药治疗。上了大学后我觉得自己好了，偷偷停止服药。父母打电话叫我回家，我找了最近的假期回去。回到家后我把妈妈杀了，然后剖开她的肚子取出了子宫，拿着子宫打电话给爸爸：\"爸，我回家了！\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_faa800c4c34d","srcNo":689,"title":"我正在看着你","dispTitle":"我正在看着你","surface":"女主爱在网上分享近况。某天收到一条留言被吓得夺门而出。也许她不该逃，第二天警方发现了尸体。","truth":"女主在网上分享生活时泄露了大量个人信息，包括家庭住址。一个变态通过她的博文推断出她家的位置，潜伏进了她的房间。他给女主发了一句\"我正在看着你\"，女主被吓得夺门而出，变态从家里追了出来，争执中失手将女主杀死。如果女主没有逃，而是报警，结局也许不同。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","犯罪","都市"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fab9e4809ad5","srcNo":111,"title":"","dispTitle":"无题 · KONpiGG #111","surface":"\"咚\"  \"扑通\"  他笑了。","truth":"有个人想把妻子杀死，于是就去许愿池投币许愿希望妻子会掉水里，结果妻子真的死了。\"咚\"是投硬币的声音，\"扑通\"是妻子落水时的声音，\"他笑了\"是因为他的愿望灵验了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fb44b3fabcd5","srcNo":226,"title":"街上的工作","dispTitle":"街上的工作","surface":"我正在街上努力工作，突然一个疯疯癫癫的女人向我扑来，爸爸赶紧把我抱回了家，但随后那个女人又跟来了。","truth":"“爸爸”并不是我真正的爸爸，而是将我拐走的人贩子，而那个疯癫的女人就是一直在寻找我的妈妈，那天我跟着“爸爸”在街上行乞，她一眼就认出了被折磨的不成人形的我，人贩子见事情败露，急忙将我抱回了家，妈妈为了复仇，用人贩子折磨我的方式折磨人贩子，随后杀了他，我终于可以回家了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fb5f4e257b17","srcNo":524,"title":"出租房","dispTitle":"出租房","surface":"我搬进了一个新房子，房间里经常有老鼠爬的声音，但毕竟便宜，我也睡得很香。后来房东谈了女朋友，老鼠的声音没了，但突然的安静却让我睡不着觉…","truth":"我早就知道房东在房顶偷窥我，但被人注视总会给我带来一种安全感，所以对于来自房顶的偷窥，我并没有感觉到任何不适。直到房东谈了女朋友，安静的天花板却让我辗转难眠，于是我趁房东帮我修电路的机会，让他永远地呆在了天花板上。透过那小小的黑洞，我知道他一直在看着我，我又能安心入眠了……（老鼠爬的声音是房东偷窥发出的声音）","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖"],"difficulty":3,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fb6721918355","srcNo":1061,"title":"救命的谎言","dispTitle":"救命的谎言","surface":"地震后的废墟下，父亲和儿子被困。父亲不停地跟儿子说话，告诉他救援队就在头顶。三天后，儿子获救了，而父亲早已在第一天就去世了。","truth":"父亲在临死前利用废墟中的金属管道回声原理，预录或者利用某种物理平衡制造了有规律的撞击声，让儿子产生“有人在挖掘”的错觉。这种强烈的生存意志支撑着儿子撑过了生理极限。这是一个关于父爱超越死亡的实验性真相。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fb77315aaeee","srcNo":1382,"title":"","dispTitle":"无题 · boop-yyt #1382","surface":"A man was brought before a tribal chief, who asked him a question. If he had known the answer, he probably would have died. He didn't, and lived. How could this be?","truth":"The native chief asked him, \"What is the third baseman's name in the Abbot and Costello routine 'Who's on First'?\" The man, who had no idea, said \"I don't know,\" the correct answer. However, he was a major smartass, so if he had known the answer he would have pointed out that What was the *second* baseman's name. The chief, being quite humorless, would have executed him on the spot. This is fairly silly, but I like it too much to remove it from the list. The question was, \"What does the tattoo on my daughter's tush say?\" or any other question whose answer reveals that you know more than you should. Of course, for this sort of question one can lie and say one doesn't know even if one does. (FF)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fb9a627738a0","srcNo":232,"title":"闹钟","dispTitle":"闹钟","surface":"我定了早上7点的闹钟。早上它响了，我按掉，继续睡。10点我自然醒过来，一看手机，闹钟设置明明还是7点，可它再也没有响过第二次。","truth":"我设的是'单次闹钟'，响过这一次就结束了。我以为闹钟每天早上都会响，按掉之后安心继续睡，结果再也不会响第二遍——迟到是我自己的认知问题。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["日常","逻辑"],"difficulty":1,"src":"github:AZHi-xinxin/haiguitang-coop","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fbb763606133","srcNo":1348,"title":"","dispTitle":"无题 · boop-yyt #1348","surface":"A man sat perfectly still for 88 hours. Why?","truth":"The man had a nasty toothache and he went to the dentist at 5 p.m. on a Friday evening. The dentist's assistants, including the anesthetist, had all gone and the dentist could not administer an anesthetic. The man insisted that the dentist should operate even without anesthetic so the dentist said that he would have to strap the man into the chair. This was done. The dentist then suffered a heart attack and died. The poor man was left strapped in the chair and unable to move. It was a holiday weekend and no staff reported for work until 9 a.m. on the following Tuesday morning88 hours later.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fbf3ed58597b","srcNo":773,"title":"爱犬","dispTitle":"爱犬","surface":"女孩独自在家，只有爱犬陪伴。半夜她听到奇怪水滴声，害怕的她把手伸到床边，爱犬舔了舔她的手。第二天狗死了。","truth":"女孩独居，有一天晚上有个小偷潜入家里，把狗杀死吊在天花板上，滴水声是狗在滴血。舔她手的不是狗，是那个人。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fc5d405d5cb8","srcNo":1053,"title":"上帝的橡皮擦","dispTitle":"上帝的橡皮擦","surface":"世界上的所有人都突然忘记了‘黄色’这个词。一名油漆工看着桶里的液体发疯了，他觉得那是‘不存在的颜色’。","truth":"人类文明其实是一个高级文明的电脑模拟程序。管理员删除了关于‘黄色’的色彩代码，但由于油漆工正在接触实体物质，他的大脑产生了认知冲突（逻辑死循环），导致他意识崩溃。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:yinyyW/haiguitang","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fc5e37b8dfde","srcNo":703,"title":"几节","dispTitle":"几节","surface":"“一节，两节，三节……”数完后我疯了。","truth":"我们学校教学楼夜里闹鬼，但我不信，于是我在晚自习结束后趁大家都走了，一个人偷偷留在了学校，但我什么也没发现，心想果然根本没鬼，下楼的时候我突然闲来无事数了下台阶的数量，“一节，两节，三节...”我一节节数着，数完后我突然想起，我的教室在一楼，根本就不会有楼梯...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","悬疑","惊悚"],"difficulty":2,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fc862134f0ca","srcNo":106,"title":"","dispTitle":"无题 · KONpiGG #106","surface":"妻子带回来一个小孩，丈夫却死了。","truth":"妻子的小孩因病死亡，妻子受不了孩子死亡的打击，因此疯了到处寻找和自己小孩相似的其他小孩，取他们的尸块拼成自己孩子的模样，并把\"孩子\"领回家中，丈夫无法接受，便斥责了妻子，妻子突然发现：丈夫的眼睛与孩子的眼睛非常相似，于是挖出丈夫的眼睛安在\"孩子\"身上，丈夫不堪忍受痛苦，自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fcc08247e999","srcNo":308,"title":"080 · 第一名","dispTitle":"080 · 第一名","surface":"他这次考试得了全班第一，放学后却大哭了一场。","truth":"他这次考了全班第一，但是全班只有他一个人参加了考试——因为那天是大扫除，老师临时说今天不用考试了，其余同学都回家了。他一个人埋头认真考完试，出来发现教室空无一人，才知道……","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fccd2f662926","srcNo":1235,"title":"Jed 2.21","dispTitle":"Jed 2.21","surface":"Bruce wins the race, but he gets no trophy.","truth":"Bruce is a horse.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fd3477ddff5b","srcNo":1203,"title":"Jed 1.27","dispTitle":"Jed 1.27","surface":"A man tells his boss, \"Don't take your planned flight today! I had a dream last night that if you do, your plane will crash and you'll die.\" The boss fires the man. (From _How Come?_)","truth":"The man was the night watchman; he should've been on duty the previous night, not dreaming. (He tells the boss about the dream out of concern for his safety.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fd95aed7dcd9","srcNo":215,"title":"最棒的一天","dispTitle":"最棒的一天","surface":"他在公园的长椅上醒来。昨天晚上，他刚向苏珊求婚，而她已经几乎接受了他，并让他第二天下午去她家。他舒缓着酥麻的腿脚，叩响了她的门，喊着苏珊的名字。然而房门打开后，他才意识到有事情不对劲。","truth":"他是阿兹海默症患者，经常觉得自己还在刚刚跟妻子表白的那天。这天他又一次走丢并在长椅上睡着，他凭着记忆找回家以为能见到自己的女朋友，然而确实跟自己妻子有几分相似的孙女，他这才意识到自己又犯病了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fddab6f49384","srcNo":1310,"title":"","dispTitle":"无题 · boop-yyt #1310","surface":"The music stopped and the man died. What happened?","truth":"A blind swimmer kept a portable transistor radio on the beach to tell him when and what direction to go to shore. when the batteries gave out he got lost and drowned.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_fde48ed43c23","srcNo":103,"title":"","dispTitle":"无题 · KONpiGG #103","surface":"幼儿园的一个小朋友数数总是说\"1，2，3，7\"，总是漏掉中间的\"4，5，6\"。可是当我纠正她时，她却说这是她妈妈教她的，我很疑惑，便提出去她家家访，家访结束后我也对她说是\"1，2，3，7\"","truth":"我是一名幼师，在给小朋友们上课时，我发现有个小朋友数数总是数不对，别人数数都是1234567，可她却说是1237，我教她正确的数数时，她却说我教她的和她妈妈教的不一样，她说她妈妈教她是1237，我很疑惑，便提出去她家家访，可她却带我来到了一家医院，原来她妈妈患有心脏病，并且已经活不长久了，而现在是三月份，而她的女儿生日在七月份，为了能陪伴她的女儿过最后一个生日，才对她的女儿编制了这样一个善意的谎言。得知此事后的我非常感动，便像她妈妈一样对她说3后面确实是7。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_feb2743db136","srcNo":161,"title":"","dispTitle":"无题 · KONpiGG #161","surface":"一个小男孩叫了一声妈妈，接着就掉下了一个人头和一个身体","truth":"爸爸是服装设计师，妈妈是他的模特，在一次走秀表演上，妈妈吊的威亚出了问题，威亚把妈妈的头割了下来，爸爸就在她背后目睹了自己妻子的死亡，他承受不了打击，于是将妈妈的头带回了自家阳台，安在了他平时用于设计新礼服的模特身体上，仿佛妻子从未离开一般，而他们的孩子年纪尚小，不知道妈妈已经去世了，看到阳台上的妈妈，他高兴地扑向了妈妈.......紧接着，妈妈的头和身体就被孩子，扑到了楼下。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_fee52ece475e","srcNo":56,"title":"几节","dispTitle":"几节","surface":"\"一节，两节，三节…\"数完后我疯掉了。","truth":"我们学校教学楼夜里闹鬼，但我不信，于是我在晚自习结束后趁大家都走了，一个人偷偷留在了学校，但我什么也没发现，心想果然根本没鬼，下楼的时候我突然闲来无事数了下台阶的数量，\"一节，两节，三节...\"我一节节数着，数完后我突然想起，我的教室在一楼，根本就不会有楼梯...","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["怪谈","恐怖"],"difficulty":2,"src":"github:anchorAnc/astrbot_plugin_TurtleSoup","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_ff82650c1faa","srcNo":702,"title":"没熟","dispTitle":"没熟","surface":"铛铛铛：“这个没熟。”铛铛铛：“这个好像熟了！”爸爸吓出一身冷汗。","truth":"爸爸和他的同事们一起去乡间出差，在路上突然遇到暴风雨，天气恶劣，而附近也没有宾馆，无奈之下刚好看到一户瓜农，他热心的让爸爸和他的同事们在他家住一晚。在夜晚爸爸和他的同事们都睡着了时，瓜农拿了一把刀来切瓜，(瓜农精神有","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["恐怖","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_05ee4cafe666","srcNo":276,"title":"047 · 洋娃娃","dispTitle":"047 · 洋娃娃","surface":"一场意外后，妻子便把自己关在房间里不肯出来。那天我突然听到她在嚎啕大哭，急忙冲进房间，被眼前的一幕吓傻了。","truth":"丈夫发现妻子出轨且孩子也不是亲生的，精心策划了一场车祸，想让妻子和孩子双双丧命，谁知妻子活了下来但精神失常了。丈夫不管她，偶尔闻到房间里传来异味。某天，他冲进婴儿房——妻子怀里抱着的洋娃娃上爬满了蛆虫。她竟然把死去的孩子缝进了洋娃娃里，一边抓去蛆虫，一边哭喊：\"宝宝别怕，宝宝别怕。\"","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:bcefghj/rokid-collection","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f3d383d9df0e","srcNo":1368,"title":"","dispTitle":"无题 · boop-yyt #1368","surface":"A rope breaks. A bell rings. A man dies. How could this be?","truth":"A blind man enjoys walking near a cliff, and uses the sound of a buoy to gauge his distance from the edge. One day the buoy's anchor rope breaks, allowing the buoy to drift away from the shore, and the man walks over the edge of the cliff.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4bb30df46863","srcNo":731,"title":"电梯","dispTitle":"电梯","surface":"我走进电梯准备上学，随着电梯上升，我知道我再也无法去学校了。","truth":"星期一早上，在妈妈的催促之下我心不在焉的走进电梯准备去学校，电梯门合上后，由于我刚起床头脑还不太清醒，忘了按一楼的楼层键，于是电梯便持续上升，我意识到自己没按楼层，正准备按下一楼楼层时，电梯突然停了，电梯门缓缓打开，我看到","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["悬疑","惊悚","犯罪"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_16c34d2a101f","srcNo":67,"title":"","dispTitle":"无题 · KONpiGG #67","surface":"小明半夜起来喝水，然后把灯关上继续睡觉，醒了之后他就自杀了，问小明为什么自杀","truth":"小明是住在灯塔里的人，半夜顺手把灯关上之后，导致航行的船只迷失方向导致事故，于是羞愧自杀。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:KONpiGG/astrbot_plugin_soupai","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_16c80a13e181","srcNo":1234,"title":"Jed 2.20","dispTitle":"Jed 2.20","surface":"Joe wants to go home, but he can't go home because the man in the mask is waiting for him. (AL wording)","truth":"A baseball game is going on. The base-runner sees the catcher waiting at home plate with the ball, and so decides to stay at third base to avoid being tagged out. 2.20 variant answer: Joe's in the hospital. He can't go home, because the man in the mask is a surgeon waiting to remove his appendix. (FF) 2.20 variant answer: Joe is a bee; the man in the mask is a beekeeper. 2.20a. Variant wording: Johnny is afraid to go home because of the man in the mask. (DW) 2.20a answer: Same. The diminutive \"Johnny\" makes it sound like he's a little kid, nicely further obfuscating the issue. 2.20b. Variant: Two men are in a field. One is wearing a mask. The other man is running towards him to avoid him. 2.20b answer: The same, but the catcher isn't right at home plate; the runner is trying to get home before the catcher can. (from Hal Lowery, by way of Chris Riley) This phrasing would allow the puzzle to migrate to section 1, but I don't like it as much. 2.20c. Variant wording: Instead of \"home,\" say the man in the mask is standing on the corner. 2.20c answer: Same.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"Jed's List of Situation Puzzles (1999)","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_4195efaab01e","srcNo":1299,"title":"","dispTitle":"无题 · boop-yyt #1299","surface":"Music stops and a woman dies. What happened?","truth":"The woman is a tightrope walker in a circus. Her act consists of walking the rope blindfolded, accompanied by music, without a net. The musician (organist, or calliopist, or pianist, or whatever) is supposed to stop playing when she reaches the end of the rope, telling her that it's safe to step off onto the platform. For unknown reasons (but with murderous intent), he stops the music early, and she steps off the rope to her death.","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_ee3cd8f8fce0","srcNo":222,"title":"看病","dispTitle":"看病","surface":"一个人坐火车去临镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。","truth":"因为他看好的是眼睛的病。经过隧道，以为眼睛又看不见了。经受不住打击，自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:wangyafu/haiguitangmcp","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_f3a67510b7c7","srcNo":502,"title":"重见光明","dispTitle":"重见光明","surface":"一个人坐火车去临镇看病，看完之后病全好了。回来的路上火车经过一个隧道，这个人就跳车自杀了。为什么?","truth":"因为他看好的是眼睛的病。经过隧道，以为眼睛又看不见了。经受不住打击，自杀了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"haiguitang.net","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_57c970bf7a82","srcNo":1367,"title":"","dispTitle":"无题 · boop-yyt #1367","surface":"The music stops and the man dies. How could this be?","truth":"The same, except it's a tape breaking instead of a record skipping. (See also #1.31a, #1.59, and #1.75c.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_bb9b8da83f0b","srcNo":1361,"title":"","dispTitle":"无题 · boop-yyt #1361","surface":"Music stops and a woman dies. How could this be?","truth":"The woman is a tightrope walker in a circus. Her act consists of walking the rope blindfolded, accompanied by music, without a net. The musician (organist, or calliopist, or pianist, or whatever) is supposed to stop playing when she reaches the end of the rope, telling her that it's safe to step off onto the platform. For unknown reasons (but with murderous intent), he stops the music early, and she steps off the rope to her death. The woman is a character in an opera, who \"dies\" at the end of her song. The \"woman\" is the dancing figure atop a music box, who \"dies\" when the box runs down. (Both of the above variants would probably require placing this puzzle in section 2 of the list.) (See also #1.31a, #1.70a, and #1.75c.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_d54c7f270c6d","srcNo":1351,"title":"","dispTitle":"无题 · boop-yyt #1351","surface":"The music stops and a woman dies. How could this be?","truth":"The woman is confined in an iron lung, and the music is playing on her radio or stereo. The power goes out. (RW) (See also #1.59, #1.70a, and #1.75c.)","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:boop-yyt/situation_puzzle","lang":"en","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a8fb92054c63","srcNo":721,"title":"贝尔公主","dispTitle":"贝尔公主","surface":"我是贝尔公主，父王给我盛大婚礼，可婚礼上我却看不清王子的脸……","truth":"我从小就喜欢那些凶猛的野兽，父王对我宠爱有佳，便默许了我这一爱好，长大后，我一直期待，能嫁给一位英勇的王子，但我的条件是：我的宠物们也能接受他。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["反转","恐怖","脑洞"],"difficulty":3,"src":"haiguitang.top","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"recovered"},{"id":"lib_a0a04ac21e6e","srcNo":1166,"title":"猜名字","dispTitle":"猜名字","surface":"家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛\n并喊他的名字，便可散其她。秆夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却\n不可置信的看着她。我知道，我们死定了.………","truth":"我的情人其实是我妻子的双胞胎妹妹，她们俩长得几乎一模一样，由于情人怀了孩子，\n我们两个便计划杀死妻子，可妻子听到了我和情人要谋害她的计划,她把情人迷晕后伪装成自\n己，所以我杀的“妻子\"，其实是误杀了怀孕的情人。之后的几天，我家发生了一些灵异事件，\n于是我们找到了大师帮忙解决。他让我们在屋里摆满白烛并喊鬼的名字, 便可散其怨气。午夜，\n阵阵阴风吹灭了蜡烛，我喊出妻子的名字，而一旁的“情人”居然喊出自己的名字，我这才知道\n眼前的情人是我妻子假扮的，真正死的不是我麦子，而是情人! 可由于情人怀了我的孩子，这\n个孩子还没有取名字! 我们根本没有办法化解他的怨念，此刻我意识到我们死定了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"许二木海龟汤合集(OCR)","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"},{"id":"lib_c750c42858e6","srcNo":910,"title":"猜名字","dispTitle":"猜名字","surface":"家里闹鬼了，我和爱人找来一位大师帮忙解决。大师说他有怨气，你们在屋里摆满白烛并喊他的名字，便可散其怨。午夜，阵阵阴风吹灭了蜡烛，爱人急忙喊其姓名，可听到后我却不可置信的看着她。我知道，我们死定了……","truth":"我的情人其实是我妻子的双胞胎妹妹，她们俩长得几乎一模一样，由于情人怀了孩子，我们两个便计划杀死妻子，可妻子听到了我和情人要谋害她的计划，她把情人迷晕后伪装成自己，所以我杀的”妻子“，其实是误杀了怀孕的情人。之后的几天，我家发生了一些灵异事件，于是我们找到了大师帮忙解决。他让我们在屋里摆满白烛并喊鬼的名字，便可散其怨气。午夜，阵阵阴风吹灭了蜡烛，我喊出妻子的名字，而一旁的”情人“居然喊出自己的名字，我这才知道眼前的情人是我妻子假扮的，真正死的不是我妻子，而是情人！可由于情人怀了我的孩子，这个孩子还没有取名字！我们根本没有办法化解他的怨念，此刻我意识到我们死定了。","truthKeywords":[],"coreKeywords":[],"clues":[],"hints":[],"cats":["其他"],"difficulty":2,"src":"github:moxianbizi/haiguitang-php","lang":"zh","mode":"truth","hasTruth":true,"truthSource":"original"}];

